 * mode-switch or model-pick write-back racing a late-resolving GET — are directly assertable with
 * `renderHook` against a mocked `execution-settings.ts`, rather than only reachable indirectly
 * through a full dock mount. Same split rationale as Jini's `ConfirmDialog.hooks.tsx`: the JSX in
 * `AssistantDock.tsx` stays a thin render of whatever these hooks return.
 *
 * `shouldPublishOnMessagesChange`, `resolveRunContext`, and `resolveComposerDiscoveryOutcome`
 * below are not hooks — they are the pure decision/derivation halves of three of `AssistantDock`'s
 * own callbacks (`handleMessagesChange`'s settings-refresh dedup, the per-run `runContext` builder,
 * and the composer discovery selection resolver), pulled out for the same
 * directly-assertable-without-mounting reason. Each function's own doc comment explains why it, in
 * particular, is shaped this way; see `AssistantDock.tsx` for how each one is actually wired in.
 * `resolveComposerDiscoveryOutcome` is reached through `AssistantDock.tsx` rather than here
 * `.hooks.tsx`-only: per `INFO.md`'s Components rule 2 it is re-exported by name from the component
 * file, and that is the path its own suite
 * (`../__tests__/resolve-composer-discovery-outcome.unit.test.ts`) imports.
 *
 * Per `INFO.md`'s Components rule 3 (any hook touching the DOM, browser APIs, or IO is an
 * injectable prop, defaulted to the real hook), seven hooks below are exposed as injectable seams
 * on `AssistantDockProps` — the original four (`useExecutionConfig`, `useByokRuntime`,
 * `useLocalCliSelection`, `useComposerCapabilities`) plus three added in the 2026-08-18
 * inline-hook-extraction pass (`useAssistantTransport`, `useAttachmentUploader`,
 * `useRuntimeAccess` — each wraps a real network/service call: `createTovuAssistantTransport`,
 * `createDaemonAttachmentUploader`, and `fetch`-backed `listAgents`/`rescanAgents`/`daemonOnline`
 * respectively) — alongside `AssistantDock`'s own pre-existing `useChats` prop; see
 * `AssistantDock.tsx` for the wiring. (An earlier revision of this comment claimed none of the
 * three was seamed, on the reasoning that nothing in that day's brief called for it. That was stale
 * the moment rule 3 was applied here — corrected rather than left to mislead the next reader.)
 * `useComposerCapabilities` (2026-08-14) was the last of `AssistantDock.tsx`'s own raw
 * `useState`/`useEffect` pairs, moved here for the same reason. The existing component
 * test still exercises the config-load/discovery/mode-switch/model-pick paths through `renderHook`
 * against these exports directly for the hooks' OWN behavior; the seams exist so
 * `AssistantDock.tsx`'s own markup/wiring tests can fake them instead of driving the real ones.
 *
 * The remaining hooks added in the 2026-08-18 pass — `useChatI18n`, `useComposerDiscoverySelect`,
 * `useMessagesChangeHandler`, `useRunContext` — are pure derivations/local state with no I/O of
 * their own (their dependencies, e.g. `chats`/`publishSettingsRefresh`, are already wired
 * elsewhere), so per the same rule-3 reading they stay plain exports with no injectable seam; see
 * each hook's own doc comment for why.
 */

export interface UseExecutionConfig {
  executionConfig: ExecutionConfig;
  /** Same object as `executionConfig`, mirrored into a ref — see the field's own doc below for why. */
  executionConfigRef: React.MutableRefObject<ExecutionConfig>;
  setExecutionConfig: React.Dispatch<React.SetStateAction<ExecutionConfig>>;
  handleExecutionModeChange: (mode: "local" | "api") => void;
  /**
   * Whether this admin has a BYOK credential saved server-side (2026-08-05) — `null` until the
   * initial GET settles, then `true`/`false`. See {@link AssistantDock}'s `apiModeAvailable` for why
   * this exists: `executionConfig.byok.apiKey` alone is no longer enough to answer "is BYOK
   * usable", because the key is write-only and empty on every fresh load even when one is stored.
   */
  hasStoredAdminKey: boolean | null;
  /**
   * True once the initial ledger GET (`loadExecutionConfig()`) has settled — resolved OR
   * rejected — false only during that first in-flight load. Added (2026-08-05) for
   * {@link useLocalCliSelection}'s initial hydration: `executionConfig.localCli.agentId` starts
   * `null` in `DEFAULT_EXECUTION_CONFIG`, and a load that resolves to "nothing was ever saved"
   * ALSO leaves it `null` — those two states are indistinguishable from `executionConfig` alone,
   * so a separate "has the GET settled at all" signal is what lets that hook's hydration effect
   * fire after the first read instead of never (waiting on a non-null `agentId` that may never arrive) or
   * too early (before the load has had any chance to run).
   */
  configLoaded: boolean;
  /** Await the current refresh, or re-read a Local CLI config older than five seconds. */
  readExecutionConfigForSend?: () => Promise<ExecutionConfig>;
}

/** IO seam for the dock's existing ledger and credential adapters; tests provide fakes. */
export interface DockExecutionConfigPort {
  loadConfig: typeof loadExecutionConfig;
  loadCredential: () => Promise<{ isSet: boolean }>;
  now: () => number;
}

const defaultDockExecutionConfigPort: DockExecutionConfigPort = {
  loadConfig: loadExecutionConfig,
  loadCredential: loadAdminExecutionCredential,
  now: Date.now,
};

export const EXECUTION_CONFIG_MAX_AGE_MS = 5_000;

/**
 * Owns the runtime picker's Local CLI / API · BYOK state (ADR-049's picker, 2026-08-04 wiring) and
 * the mode-switch write-back. Split out of `AssistantDock` so the config-load failure path (the
 * `.catch()` below) and the mode-switch persistence path can be driven directly with `renderHook`
 * against a mocked `execution-settings.ts`, rather than only indirectly through a full dock mount.
 *
 * @returns `executionConfig` (the live value), `executionConfigRef` (read-fresh mirror for
 *   consumers that must not capture a stale closure), `setExecutionConfig`, and
 *   `handleExecutionModeChange` (persists a mode switch back through the ADR-028 chokepoint).
 * @param options.port - Ledger/credential IO; defaults to the existing host adapters.
 * @param options.persistWrite - Write seam for component tests; defaults to the shared dock writer.
 * @example
 * const { executionConfig, handleExecutionModeChange } = useExecutionConfig();
 */
export function useExecutionConfig(
  _requiredArgs: Record<string, never> = {},
  { port = defaultDockExecutionConfigPort, persistWrite = persistExecutionConfigWrite }: {
    port?: DockExecutionConfigPort;
    persistWrite?: typeof persistExecutionConfigWrite;
  } = {},
): UseExecutionConfig {
  const io = useRef(port);
  io.current = port;
  const { queryScope } = useAdminBootScope();
  const configKey = useMemo(() => ["settings", EXECUTION_NAMESPACE, queryScope, "dock"], [queryScope]);
  const credentialKey = useMemo(() => ["admin-execution-credential", queryScope, "presence"], [queryScope]);
  const loadConfig = useCallback(async () => ({ config: await io.current.loadConfig(), loadedAt: io.current.now() }), []);
  const loadCredential = useCallback(() => io.current.loadCredential(), []);
  // The provider retains reads across StrictMode replay and ordinary dock remounts. Explicit
  // refreshes revoke them; focus/pre-send reads keep the existing five-second freshness bound.
  const configLoader = useCachedLoader({ key: configKey, fetch: loadConfig }, { staleTime: Infinity });
  const credentialLoader = useCachedLoader({ key: credentialKey, fetch: loadCredential }, { staleTime: Infinity });
  const invalidate = useInvalidate();
  /**
   * Refreshed from `execution-settings.ts`'s ledger+localStorage-backed store — the SAME source
   * the Execution-mode settings tab reads/writes — so a mode chosen there is reflected here without
   * a page reload, and a mode picked directly from this dock persists back the same way.
   *
   * Held in a ref (kept in sync below) rather than read directly by the memoized `transport`: the
   * transport is built once (see its own comment) and reads this via `getExecutionConfig()` on every
   * `startRun` call, so a mode change mid-session takes effect on the NEXT message without forcing a
   * new transport instance — the same "read fresh, don't capture" pattern `runContext`'s
   * `frontendBindToken` already uses a few lines down.
   */
  const [executionConfig, setExecutionConfigState] = useState<ExecutionConfig>(DEFAULT_EXECUTION_CONFIG);
  const executionConfigRef = useRef(executionConfig);
  executionConfigRef.current = executionConfig;

  /**
   * Counts THIS mount's local writes — a mode switch from
   * `handleExecutionModeChange` below, or (through the wrapped `setExecutionConfig` this hook
   * exposes) a BYOK model pick from `useByokRuntime`'s `handleByokModelChange`. Each refresh samples
   * this count before reading: without it, an operator who switches modes before the initial
   * `loadExecutionConfig()` resolves would see the switch silently revert. The load starts on
   * mount and reads whatever the server held BEFORE the switch's own `saveExecutionConfig` call;
   * if it resolves after the switch (a real race — both are ordinary network calls with no
   * ordering guarantee), applying it unconditionally overwrites the operator's just-made,
   * already-persisted choice with the stale pre-switch value. That leaves the UI showing a
   * different mode than the server holds — exactly the disagreement
   * `handleExecutionModeChange`'s own doc comment says the ADR-028 chokepoint exists to prevent.
   *
   * A ref, not state: incrementing it must not itself trigger a render, and it needs to be readable
   * synchronously when deciding whether a refresh response is still current.
   */
  const localWriteRef = useRef(0);

  /** Backs {@link UseExecutionConfig.configLoaded} — see that field's own doc. */
  const [configLoaded, setConfigLoaded] = useState(false);

  /**
   * The `Dispatch` this hook exposes — to its own `handleExecutionModeChange` below, and to
   * `useByokRuntime`'s `handleByokModelChange` (passed `executionConfig`/`setExecutionConfig` as
   * an input pair). Wraps the raw state setter so any update that actually changes the value
   * marks {@link localWriteRef}.
   *
   * Relies on the "return `previous` unchanged to bail out" convention every updater passed
   * through here already follows (`handleExecutionModeChange`'s and `handleByokModelChange`'s own
   * `if (previous.… === next) return previous;` guards) rather than re-deriving no-op-ness itself:
   * comparing the updater's result to `previous` by reference is enough to tell a genuine write
   * apart from a no-op, so an operator re-picking the mode/model already active does not
   * permanently block a legitimate mount-load from applying.
   *
   * Runs an updater once, synchronously, against {@link executionConfigRef} (moved forward on every
   * write, so two picks before a re-render compose), and hands React the resulting value rather
   * than the updater. `applyExecutionConfigChange` (`../execution-config-write.ts`) relies on that
   * to read what a pick changed right after the call and save it outside the updater — StrictMode
   * runs updaters twice, and a save inside one wrote two revisions per pick (2026-09-23).
   */
  const setExecutionConfig = useCallback<React.Dispatch<React.SetStateAction<ExecutionConfig>>>((action) => {
    const previous = executionConfigRef.current;
    const next = typeof action === "function"
      ? (action as (current: ExecutionConfig) => ExecutionConfig)(previous)
      : action;
    if (next === previous) return;
    localWriteRef.current += 1;
    executionConfigRef.current = next;
    setExecutionConfigState(next);
  }, []);

  const lifecycleRef = useRef<AbortController | null>(null);
  const refreshGeneration = useRef(0);
  const lastLoadedAt = useRef<number | null>(null);
  const activeRefresh = useRef<Promise<ExecutionConfig> | null>(null);

  const refreshExecutionConfig = useCallback(() => {
    const controller = lifecycleRef.current!;
    refreshGeneration.current += 1;
    const generation = refreshGeneration.current;
    const writesAtStart = localWriteRef.current;
    // A refresh notification invalidates the old read even if this request fails. Otherwise Send
    // could reuse a recent cache entry after Settings told us its saved value had changed.
    lastLoadedAt.current = null;
    // Retried while the API is unreachable: the dock mounts once per session, so a load during
    // a dev-API restart must recover without a page reload. A local write or newer refresh makes
    // this response obsolete; unlike the old boolean guard, it does not block ALL future reads.
    const pending = retryWhileUnreachable({ load: () => configLoader.load(), signal: controller.signal })
      .then(({ config, loadedAt }) => {
        if (controller.signal.aborted || generation !== refreshGeneration.current || writesAtStart !== localWriteRef.current) {
          return executionConfigRef.current;
        }
        executionConfigRef.current = config;
        setExecutionConfigState(config);
        lastLoadedAt.current = loadedAt;
        return config;
      })
      .finally(() => {
        // Settled means resolved OR rejected: a failed first load still allows picker hydration
        // from defaults. An unmount cancellation must never update the cleaned-up mount.
        if (!controller.signal.aborted) setConfigLoaded(true);
        if (activeRefresh.current === pending) activeRefresh.current = null;
      });
    activeRefresh.current = pending;
    return pending;
  }, [configLoader]);

  const readExecutionConfigForSend = useCallback(async () => {
    // A focus/SSE/Settings refresh may still be in flight when Send is clicked. Await the newest
    // read and use its ref immediately, without relying on React to render the picker first.
    if (!activeRefresh.current && (lastLoadedAt.current === null || io.current.now() - lastLoadedAt.current >= EXECUTION_CONFIG_MAX_AGE_MS)) {
      invalidate({ key: configKey });
      refreshExecutionConfig();
    }
    while (activeRefresh.current) await activeRefresh.current;
    return executionConfigRef.current;
  }, [refreshExecutionConfig, invalidate, configKey]);

  useEffect(() => {
    const controller = new AbortController();
    lifecycleRef.current = controller;
    // Another window/desktop can save execution config while this dock stays mounted. Settings
    // already publishes this namespace on save; focus/visible also catch changes outside the tab.
    const refresh = () => {
      void refreshExecutionConfig().catch((error: unknown) => {
        // The dock is present on every route. Keep defaults/current state on a background failure,
        // but a pre-send refresh rejection is propagated so it cannot silently send a stale pick.
        if (!isAbortError(error)) console.error("[AssistantDock] failed to load execution config", error);
      });
    };
    const revalidate = () => { invalidate({ key: configKey }); refresh(); };
    const onVisible = () => { if (document.visibilityState === "visible") revalidate(); };
    refresh();
    window.addEventListener("focus", revalidate);
    document.addEventListener("visibilitychange", onVisible);
    const unsubscribe = subscribeToSettingsRefresh((scope) => {
      if (!scope || scope.includes(EXECUTION_NAMESPACE)) {
        revalidate();
      }
    });
    return () => {
      controller.abort();
      window.removeEventListener("focus", revalidate);
      document.removeEventListener("visibilitychange", onVisible);
      unsubscribe();
      activeRefresh.current = null;
    };
  }, [refreshExecutionConfig, invalidate, configKey]);

  /**
   * Whether a BYOK credential is stored server-side for this admin — see {@link UseExecutionConfig.hasStoredAdminKey}'s
   * own doc for why `apiModeAvailable` cannot be answered from `executionConfig.byok.apiKey` alone
   * any more. Read-only and independent of the ledger load above: a failed GET here leaves this
   * `null`/`false` (picker reads as "not configured"), which is the same fail-soft posture the
   * ledger load's own `.catch` takes — never blocks the dock, only degrades one affordance.
   *
   * Re-reads on {@link subscribeToSettingsRefresh}, not just on mount. This dock mounts once at the
   * app shell and never remounts for the session (`AssistantDock.tsx`'s own header comment), so
   * without this a key saved, rotated, or cleared from a settings screen's OWN
   * `useAdminExecutionCredential` (a different, independently-mounted copy of the same server row —
   * see that hook's "Cross-mount staleness" doc) would leave this picker showing "not configured" (or
   * a stale "configured") for the rest of the session, not just briefly.
   */
  const [hasStoredAdminKey, setHasStoredAdminKey] = useState<boolean | null>(null);
  useEffect(() => {
    const controller = new AbortController();
    // Same restart-survival and cancellation handling as the ledger load above; `hasStoredAdminKey`
    // stays `null` (unknown) while retrying rather than claiming "not configured".
    const refresh = () => {
      void retryWhileUnreachable({ load: () => credentialLoader.load(), signal: controller.signal })
        .then((view) => {
          if (!controller.signal.aborted) setHasStoredAdminKey(view.isSet);
        })
        .catch((error: unknown) => {
          if (isAbortError(error)) return;
          console.error("[AssistantDock] failed to load stored BYOK credential state", error);
          if (!controller.signal.aborted) setHasStoredAdminKey(false);
        });
    };
    refresh();
    const unsubscribe = subscribeToSettingsRefresh((scope) => {
      if (scope && !scope.includes(EXECUTION_NAMESPACE)) return;
      invalidate({ key: credentialKey });
      refresh();
    });
    return () => {
      controller.abort();
      unsubscribe();
    };
  }, [credentialLoader, invalidate, credentialKey]);

  /**
   * Persists a mode switch made from THIS dock's own picker back through the same
   * `saveExecutionConfig` chokepoint the Execution-mode settings tab uses (ADR-028's single write
   * chokepoint), so the two surfaces can never disagree about which mode is active.
   *
   * `publishSettingsRefresh([EXECUTION_NAMESPACE])` on save success — same cross-mount staleness
   * fix `handleByokModelChange` below already applies to a model pick, now applied here too so an
   * already-open settings tab (or another `AssistantDock` mount) re-reads instead of sitting on the
   * mode the operator just changed away from.
   */
  const handleExecutionModeChange = useCallback((mode: "local" | "api") => {
    const nextMode: ExecutionConfig["mode"] = mode === "api" ? "byok" : "local-cli";
    const write = applyExecutionConfigChange(setExecutionConfig, (previous) =>
      previous.mode === nextMode ? previous : { ...previous, mode: nextMode });
    if (write) persistWrite(write, "[AssistantDock] failed to save execution mode");
    // `setExecutionConfig` added: it's a `useCallback([], ...)`-wrapped setter (itself stable for
    // the component's lifetime, see its own declaration above), so listing it is a no-op that only
    // satisfies the linter — Part 2 triage fix, not a suppression.
  }, [setExecutionConfig, persistWrite]);

  return {
    executionConfig,
    executionConfigRef,
    setExecutionConfig,
    handleExecutionModeChange,
    hasStoredAdminKey,
    configLoaded,
    readExecutionConfigForSend,
  };
}

export interface UseByokRuntime {
  byokRuntime: {
    providerLabel?: string;
    iconId?: string;
    model: string;
    models: readonly { id: string; label: string }[];
  };
  handleByokModelChange: (model: string) => void;
}

/**
 * Owns the BYOK model-discovery state and the composer's write-back for a model chosen there. Split
 * out of `AssistantDock` so the discovery-failure path (models stay empty rather than throwing into
 * the composer) is directly assertable via `renderHook`.
 *
 * @param input.executionConfig - The live execution config; only `executionConfig.byok` and
 *   `executionConfig.mode` are read.
 * @param input.setExecutionConfig - The setter {@link useExecutionConfig} returns, so a model
 *   picked here writes back through the same state.
 * @param options.createPort - Model-discovery IO factory; defaults to the existing execution adapter.
 * @param options.persistWrite - Write seam for component tests; defaults to the shared dock writer.
 * @returns `byokRuntime` (provider identity, model, and discovered options for the picker) and
 *   `handleByokModelChange`.
 * @example
 * const { byokRuntime, handleByokModelChange } = useByokRuntime({ executionConfig, setExecutionConfig });
 */
export function useByokRuntime(
  {
    executionConfig,
    setExecutionConfig,
  }: {
    executionConfig: ExecutionConfig;
    setExecutionConfig: React.Dispatch<React.SetStateAction<ExecutionConfig>>;
  },
  { createPort = createExecutionPort, persistWrite = persistExecutionConfigWrite }: {
    createPort?: typeof createExecutionPort;
    persistWrite?: typeof persistExecutionConfigWrite;
  } = {},
): UseByokRuntime {
  /**
   * Models the saved BYOK credential can actually run — the same list `features/ai-assistant/AiAssistant.tsx`'s
   * and `features/settings/SettingsUi.tsx`'s Model fields show, discovered through the same
   * `createExecutionPort().listModels` call.
   *
   * Discovered here rather than passed down because the dock outlives any settings screen: a
   * picker whose options only existed while the settings tab was open would be empty in the case
   * that matters. Empty on failure, which downgrades the picker's model row to read-only text
   * rather than offering an empty dropdown.
   *
   * SAFE with respect to the keystroke-leak finding
   * (`ADS-memory/reports/findings/2026-08-04-byok-discovery-keystroke-key-leak.md`): the endpoint
   * here comes from SAVED config, which an operator committed with an explicit Save, never from a
   * field being typed into. There is no partial-hostname state for this effect to walk.
   */
  const executionPort = useRef(createPort());
  const [byokModels, setByokModels] = useState<readonly { id: string; label: string }[]>([]);
  const { apiKey: byokApiKey, baseUrl: byokBaseUrl, protocol: byokProtocol } = executionConfig.byok;

  // Keyed on the credential and endpoint only — editing `model` must not re-ask the provider
  // which models exist, and would loop against the write-back below if it did.
  // biome-ignore lint/correctness/useExhaustiveDependencies: keyed on credential/endpoint only; listing `model` would loop against the write-back below.
  useEffect(() => {
    if (executionConfig.mode !== "byok" || !byokApiKey.trim()) {
      setByokModels([]);
      return undefined;
    }
    let cancelled = false;
    executionPort.current
      .listModels?.(executionConfig.byok)
      .then((models) => {
        if (!cancelled) setByokModels(models.map((id) => ({ id, label: id })));
      })
      // Silent: a failed discovery must not put an error in a chat composer. The visible
      // consequence is only that the model row stays a plain value instead of a picker.
      .catch(() => {
        if (!cancelled) setByokModels([]);
      });
    return () => {
      cancelled = true;
    };
  }, [executionConfig.mode, byokApiKey, byokBaseUrl, byokProtocol]);

  /**
   * The provider identity, model, and option list the runtime picker shows while BYOK is active.
   *
   * `resolveSelectedPreset` rather than a protocol-to-name map: the same protocol backs several
   * presets (OpenRouter and Ollama are both `openai`-protocol gateways), so keying off `protocol`
   * alone would label a gateway with the wrong vendor's name. A hand-typed custom endpoint matches
   * no preset and correctly yields no label and no icon, which the picker renders as a generic mode
   * name and glyph rather than inventing a vendor.
   */
  const byokRuntime = useMemo(
    () => {
      const preset = resolveSelectedPreset(DEFAULT_PROVIDER_PRESETS, executionConfig.byok);
      const iconId = preset ? BYOK_PRESET_ICON_IDS[preset.id] : undefined;
      return {
        ...(preset ? { providerLabel: preset.title } : {}),
        ...(iconId ? { iconId } : {}),
        model: executionConfig.byok.model,
        models: byokModels,
      };
    },
    [executionConfig.byok, byokModels],
  );

  /**
   * Write-back for a model chosen in the composer's picker — the "stay in sync" half.
   *
   * Goes through `saveExecutionConfig`, the same ADR-028 chokepoint the settings screens and
   * {@link useExecutionConfig}'s `handleExecutionModeChange` use, so the composer and both settings
   * surfaces are three views of one stored value rather than three copies of it. `publishSettingsRefresh`
   * then tells an already-open settings tab to re-read, which is what stops it from sitting on the
   * model the operator just changed. Namespace-scoped so unrelated slices do not refetch.
   */
  const handleByokModelChange = useCallback(
    (model: string) => {
      const write = applyExecutionConfigChange(setExecutionConfig, (previous) =>
        previous.byok.model === model ? previous : { ...previous, byok: { ...previous.byok, model } });
      if (write) persistWrite(write, "[AssistantDock] failed to save BYOK model");
    },
    [setExecutionConfig, persistWrite],
  );

  return { byokRuntime, handleByokModelChange };
}

/**
 * Brand mark for a BYOK provider, keyed by `ProviderPreset.id`, resolved against the artwork this
 * host actually ships in `src/public/agent-icons/`.
 *
 * Maps to CLI-agent icon ids because that is the asset set `AgentIcon` reads and the marks are the
 * vendors' own — `gemini.svg` is Google's logo whether a Gemini CLI or a Gemini API key is what
 * runs. A preset absent from this table (Azure OpenAI, OpenRouter, Ollama — no artwork on disk)
 * deliberately yields nothing, and the picker shows a generic API glyph. That is honest; pointing
 * `AgentIcon` at an id with no file would render a broken image or an unrelated initial-letter
 * badge, and inventing a nearby vendor's logo would be worse than showing none.
 *
 * Lives here, next to `useByokRuntime` (its only consumer), rather than in `AssistantDock.tsx`
 * where it previously sat — that component file no longer touches provider-icon resolution at all
 * once this hook owns it.
 */
const BYOK_PRESET_ICON_IDS: Readonly<Record<string, string>> = {
  anthropic: "claude",
  openai: "codex",
  "google-gemini": "gemini",
};

export interface UseLocalCliSelection {
  /** The Local CLI picker's current agent+model choice — fully controlled, fed straight into
   *  `<ChatPane selection={...}>` (see {@link AssistantDock}'s JSX). */
  localCliSelection: ChatPaneAgentSelection;
  handleLocalCliSelectionChange: (selection: ChatPaneAgentSelection) => void;
  /** Saved selection at dispatch time, preserving a pending/failed local pick. */
  readLocalCliSelectionForSend?: (config: ExecutionConfig) => ChatPaneAgentSelection;
}

/**
 * Owns the Local CLI picker's agent, model and reasoning as a fully controlled `ChatPane` selection,
 * persisted through the same ADR-028 `saveExecutionConfig` chokepoint `useByokRuntime`'s
 * `handleByokModelChange` already uses — so a pick here survives a reload the same way BYOK's
 * model and the mode switch already do (`executionConfig.localCli.agentId`/`.modelByAgentId`/
 * `.reasoningByAgentId`,
 * `execution-settings.ts`'s `loadExecutionConfig`/`selectedLocalCliModel` — real, persisted state
 * that nothing read the run-start path from until this hook existed, 2026-08-05).
 *
 * Split out of `AssistantDock` for the same reason `useByokRuntime` is: the synchronization and
 * write-back paths are directly assertable via `renderHook`, without mounting a full dock or a
 * real `ChatPane`.
 *
 * `ChatPane` accepts `selection`/`onSelectionChange` as a genuinely controlled pair (confirmed in
 * `@jini-ai/chat`'s `useChatPane.hooks.ts`: `requestedSelection = options.selection ?? internalSelection`,
 * and its `setSelection`/`AgentRuntimePicker`-driven change handler always calls
 * `options.onSelectionChange` even when controlled) — chosen over the dock's previously-hardcoded
 * `initialSelection` prop because that prop is read exactly once, inside `useChatPane`'s own
 * `useState` initializer, at `ChatPane`'s first mount. The ledger load is an async GET
 * (`loadExecutionConfig`'s `api.getSettingsEffective` call) that resolves AFTER that first
 * render — a value hydrated from it into `initialSelection` would arrive too late to ever take
 * effect without a synthetic remount. A fully controlled `selection` has no such one-shot window:
 * it is read on every render, so the transition from the hardcoded default to the hydrated value
 * flows straight through like any other prop update.
 *
 * @param input.executionConfig - The live execution config; only `.localCli` is read.
 * @param input.setExecutionConfig - The setter {@link useExecutionConfig} returns, so a pick made
 *   here writes back through the same state (and the same `localWriteRef` race guard)
 *   `useByokRuntime` already shares it with.
 * @param input.configLoaded - {@link UseExecutionConfig.configLoaded} — gates initial hydration
 *   until the first ledger GET settles. Later reads synchronize unless a local save is pending.
 * @returns `localCliSelection` (the controlled value) and `handleLocalCliSelectionChange`
 *   (`ChatPane`'s `onSelectionChange`).
 * @example
 * const { localCliSelection, handleLocalCliSelectionChange } =
 *   useLocalCliSelection({ executionConfig, setExecutionConfig, configLoaded });
 */
export function useLocalCliSelection(
  { executionConfig, setExecutionConfig, configLoaded }: {
    executionConfig: ExecutionConfig;
    setExecutionConfig: React.Dispatch<React.SetStateAction<ExecutionConfig>>;
    configLoaded: boolean;
  },
  { persistWrite = persistExecutionConfigWrite }: { persistWrite?: typeof persistExecutionConfigWrite } = {},
): UseLocalCliSelection {
  /**
   * Same hardcoded starting point the dock always used (`{ agentId: "claude" }`) before this hook
   * existed — now just the value shown for the brief window before the ledger's GET settles, or
   * permanently for an operator who has never picked anything.
   */
  const [localCliSelection, setLocalCliSelection] = useState<ChatPaneAgentSelection>({ agentId: "claude" });
  /** Read-fresh mirror of `localCliSelection` for {@link isSelectionNormalizationEcho} in the
   *  change handler below, which must compare against the value `ChatPane` was actually given. */
  const localCliSelectionRef = useRef(localCliSelection);
  localCliSelectionRef.current = localCliSelection;

  /**
   * `touchedRef` stops a ledger GET from silently overwriting a selection the operator already
   * picked with their own hand: the load and a fast pick have no ordering guarantee. Previously
   * `hydratedRef` also blocked every later ledger read. Refreshes must now synchronize saved picks,
   * so only a pending/failed local save stays protected; a successful save unlocks external sync.
   * `pickGeneration` ensures an older save's completion cannot unlock a newer, unsaved pick.
   */
  const touchedRef = useRef(false);
  const pickGeneration = useRef(0);
  const syncedSelection = useRef<string | null>(null);
  const normalizationRef = useRef<{ key: string | null; selection: ChatPaneAgentSelection } | null>(null);
  const persistRef = useRef(persistWrite);
  persistRef.current = persistWrite;

  const readLocalCliSelectionForSend = useCallback((config: ExecutionConfig) => {
    if (touchedRef.current) return localCliSelectionRef.current;
    const saved = localCliSelectionFromConfig({ config });
    // Keep ChatPane's default-model normalization when the saved axes haven't changed. It is
    // display/runtime state, not a ledger edit (see isSelectionNormalizationEcho below).
    const normalized = normalizationRef.current;
    return normalized && JSON.stringify(saved) === normalized.key ? normalized.selection : saved;
  }, []);

  useEffect(() => {
    if (!configLoaded || touchedRef.current) return;
    const selection = readLocalCliSelectionForSend(executionConfig);
    syncedSelection.current = JSON.stringify(localCliSelectionFromConfig({ config: executionConfig }));
    localCliSelectionRef.current = selection;
    setLocalCliSelection(selection);
  }, [configLoaded, executionConfig.localCli, readLocalCliSelectionForSend]);

  /**
   * `ChatPane`'s `onSelectionChange` — fires for an operator pick AND for `ChatPane`'s own
   * normalization of the value passed in (see {@link isSelectionNormalizationEcho}; only the pick is
   * saved). Updates the controlled value immediately, so the picker
   * reflects the pick without waiting on a round trip, and persists through the same ADR-028
   * chokepoint `handleByokModelChange` uses, so a Local CLI pick and a BYOK model pick can never
   * disagree about which write path is authoritative.
   * See {@link withLocalCliSelection} for the exact config change.
   */
  const handleLocalCliSelectionChange = useCallback((selection: ChatPaneAgentSelection) => {
    // `ChatPane` echoing its own default-model fill-in on mount: show it, but it is not a pick —
    // saving it re-wrote the ledger on every page load, and marking `touchedRef` blocked hydration.
    if (isSelectionNormalizationEcho({ current: localCliSelectionRef.current, incoming: selection, agents: readAgentsSnapshot() })) {
      normalizationRef.current = { key: syncedSelection.current, selection };
      localCliSelectionRef.current = selection;
      setLocalCliSelection(selection);
      return;
    }
    normalizationRef.current = null;
    touchedRef.current = true;
    pickGeneration.current += 1;
    const generation = pickGeneration.current;
    localCliSelectionRef.current = selection;
    setLocalCliSelection(selection);
    const write = applyExecutionConfigChange(setExecutionConfig, (previous) => withLocalCliSelection({ previous, selection }));
    if (write) {
      void persistRef.current(write, "[AssistantDock] failed to save Local CLI selection").then((saved) => {
        if (saved && generation === pickGeneration.current) touchedRef.current = false;
      });
    }
  }, [setExecutionConfig]);

  return { localCliSelection, handleLocalCliSelectionChange, readLocalCliSelectionForSend };
}

export interface UseComposerCapabilities {
  /** The composer's discovery catalog — see {@link useComposerCapabilities}'s own doc for what
   *  feeds it and why it starts empty. */
  composerCapabilities: ComposerCapabilityProjection;
}

/**
 * Projects the composer's discovery catalog (debate 2, "Composer slash commands") from the bundled,
 * compile-time source and installed skills, refreshed on open, changes, focus and visibility,
 * plus a conditional check every 60 seconds while the dock is open and the document visible. Split out of
 * `AssistantDock` (2026-08-14 DI migration pass) for the same reason the three hooks above it were:
 * per `INFO.md`'s Components rule 3, any hook doing DOM/IO work gets an injectable seam on
 * `AssistantDockProps`, defaulted to this real implementation — see `AssistantDock.tsx` for the
 * wiring.
 *
 * The raw tool catalog is deliberately NOT in the source list: the menu's job is to let a user point
 * the assistant at a Skill or Agent Plugin whose instructions it should follow, not to hand it a raw
 * tool name (the assistant already picks its own tools once it understands the goal). The ~25 live
 * tool rows that source contributed were also structurally inert — every capability it produces
 * carried no `resolve`, so selecting one did nothing. The unused source and its dedicated tests
 * were removed after confirming that no production code imports them.
 *
 * Starts empty while asynchronous sources load; stale responses are discarded. Installed-source
 * failures leave bundled commands available. The raw tool catalog is intentionally excluded.
 *
 * @returns `composerCapabilities` — the resolved projection, or the empty one before it settles.
 * @complexity O(n) time/space per refresh for n capabilities; at most one pending ordinary check.
 * @example
 * const { composerCapabilities } = useComposerCapabilities();
 */
export function useComposerCapabilities(_input: Record<string, never> = {}, _options = {}): UseComposerCapabilities {
  const { queryScope, checking } = useAdminBootScope();
  const [catalog, setCatalog] = useState(() => ({ scope: queryScope, projection: emptyComposerCapabilityProjection() }));

  useEffect(() => {
    if (checking) return undefined;
    // One source per authenticated boot scope and document (same-origin site/API, fixed workspace).
    // No module singleton can retain another user's installed capabilities.
    const installed = createInstalledSkillsComposerCapabilitySource();
    let cancelled = false;
    let generation = 0;
    let shown = "";
    let stopPolling = () => {};
    /** Reproject only current work; an unchanged catalog retains its React state identity. */
    const reload = (_required = {}, { force = false } = {}) => {
      generation += 1;
      const current = generation;
      return projectComposerCapabilities([createBundledComposerCapabilitySource(), { id: installed.id, list: () => installed.reload({}, { force }) }])
      .then((projection) => {
        // An unchanged catalog keeps its state, so refreshes do not re-render the dock. JSON drops
        // `resolve`; every source's binding is derived from the serialized fields (item id).
        const next = JSON.stringify([...projection.byItemId.values()]);
        if (cancelled || current !== generation || next === shown) return;
        shown = next;
        setCatalog({ scope: queryScope, projection });
      })
      .catch((error: unknown) => {
        console.error("[AssistantDock] composer capability projection failed", error);
      });
    };
    void reload();
    const refreshVisible = () => {
      if (document.visibilityState !== "hidden") void reload();
    };
    // Polling belongs to the dock's visible lifetime, including an unfocused visible window.
    const syncPolling = (_required = {}, _options = {}) => {
      stopPolling();
      if (getAssistantDockOpen() && document.visibilityState !== "hidden") {
        stopPolling = startVisibleInterval(() => { void reload(); }, 60_000);
      }
    };
    const visibilityChanged = () => { syncPolling(); refreshVisible(); };
    const skillsChanged = () => { void reload({}, { force: true }); };
    const stopDockSubscription = subscribeToAssistantDock(() => {
      syncPolling();
      if (getAssistantDockOpen()) refreshVisible();
    });
    syncPolling();
    window.addEventListener(SKILLS_CHANGED_EVENT, skillsChanged);
    window.addEventListener("focus", refreshVisible);
    document.addEventListener("visibilitychange", visibilityChanged);
    return () => {
      cancelled = true;
      stopPolling();
      stopDockSubscription();
      window.removeEventListener(SKILLS_CHANGED_EVENT, skillsChanged);
      window.removeEventListener("focus", refreshVisible);
      document.removeEventListener("visibilitychange", visibilityChanged);
    };
  }, [queryScope, checking]);

  return { composerCapabilities: catalog.scope === queryScope && !checking ? catalog.projection : emptyComposerCapabilityProjection() };
}

/**
 * Builds the `I18nAdapter` `AssistantDock.tsx` passes to `<JiniChatProvider i18n={...}>` — a thin
 * memoized wrapper around `createChatI18nAdapter` (`assistant-dock-i18n.ts`), which does the actual
 * dictionary lookup and is already independently tested there. Extracted (2026-08-18) purely to get
 * the `useMemo` call itself out of the component body — no I/O, no seam: `locale` is the only input
 * and `createChatI18nAdapter` is a pure function of it.
 *
 * @param locale - `useWiredAdminLocale()`'s current value.
 * @returns The memoized adapter, stable for as long as `locale` does not change.
 * @example
 * const chatI18n = useChatI18n(locale);
 */
export interface UseSelectedAgentPlugins {
  /** Every currently-pinned Agent Plugin ref, in pin order — see {@link addPluginRef}. */
  readonly selectedPluginRefIds: readonly string[];
  /**
   * Pins one plugin ref as a removable chip. Deduplicated by id: pinning an already-pinned ref is
   * a no-op (selecting the same composer row twice must not produce two chips), matching the
   * de-dup posture `composer.attachments` gets for free from `@jini-ai/chat`'s own upload batching.
   */
  readonly addPluginRef: (pluginRefId: string) => void;
  /** Unpins one plugin ref — the chip's own remove-button handler. Removing an id that is not
   *  currently pinned is also a no-op. */
  readonly removePluginRef: (pluginRefId: string) => void;
}

/**
 * Owns which Agent Plugins the operator has pinned onto the composer as removable chips
 * (`composer-capabilities.ts`'s `pluginRefId` field, resolved into this state by
 * `resolveComposerDiscoveryOutcome`'s `addPluginRef` dep). Host-owned state, not part of
 * `@jini-ai/chat`'s own `useComposer()` attachment tray: a pinned plugin ref is a Tovu concept the
 * package does not know about, the same "package owns mechanism, host owns taxonomy" boundary
 * `composer-capabilities.ts`'s module doc states for `kind`.
 *
 * Deliberately NOT cleared on send, unlike `composer.attachments` (which `useChatPane`'s own
 * `composer.reset()` clears every turn): a pinned plugin stays in front of the agent for every
 * later turn in the same conversation until the operator removes its chip. There is no send-time
 * hook this dock can observe to clear it automatically either — `ChatPane`'s `runContext` prop is
 * called and its result captured BEFORE `composer.reset()` runs (`useChatPane.hooks.ts`'s
 * `sendPrompt`), and `onDiscoverySelect` only fires on a discovery selection, never on send — so
 * "clear after the turn that used it" was never a reachable design without a new seam Jini does
 * not expose today. Sticky-until-removed is the simplest behavior consistent with what IS
 * reachable, and matches a plain reading of "pin a plugin, use it for a while, then remove it."
 *
 * @returns `selectedPluginRefIds` (for rendering the chip tray and feeding `useRunContext`) plus
 *   `addPluginRef`/`removePluginRef` (the chip tray's add/remove handlers).
 * @example
 * const { selectedPluginRefIds, addPluginRef, removePluginRef } = useSelectedAgentPlugins();
 */
export function useSelectedAgentPlugins(): UseSelectedAgentPlugins {
  const [selectedPluginRefIds, setSelectedPluginRefIds] = useState<readonly string[]>([]);

  const addPluginRef = useCallback((pluginRefId: string) => {
    setSelectedPluginRefIds((previous) =>
      previous.includes(pluginRefId) ? previous : [...previous, pluginRefId],
    );
  }, []);

  const removePluginRef = useCallback((pluginRefId: string) => {
    setSelectedPluginRefIds((previous) => previous.filter((id) => id !== pluginRefId));
  }, []);

  return { selectedPluginRefIds, addPluginRef, removePluginRef };
}

export function useChatI18n(locale: string): I18nAdapter {
  return useMemo(() => createChatI18nAdapter(locale), [locale]);
}

/**
 * The composer's pinned-Agent-Plugin chips — `selectedPluginRefIds` (see
 * {@link useSelectedAgentPlugins}) projected through `composerCapabilities.byPluginRefId` into the
 * `{ pluginRefId, label }` pairs `SelectedAgentPluginTray` renders.
 *
 * Chip labels come from the projection itself, not a second hardcoded copy — the same row a pinned
 * ref came FROM is the one place its display label is authored
 * (`composer-capabilities.ts`'s bundled catalog). Falls back to the bare id only if the projection
 * has not resolved yet or no longer carries a matching capability (e.g. a stale chip from a catalog
 * that changed shape underneath it) — better than dropping the chip and silently losing track of a
 * ref that will still be sent.
 *
 * @complexity Time/space: O(selectedPluginRefIds.length) per recompute — one `Map.get` per pinned id.
 */
export function useSelectedPluginChips(
  selectedPluginRefIds: readonly string[],
  composerCapabilities: ComposerCapabilityProjection,
): readonly SelectedAgentPluginChip[] {
  return useMemo(
    () =>
      selectedPluginRefIds.map((pluginRefId) => ({
        pluginRefId,
        label: composerCapabilities.byPluginRefId.get(pluginRefId)?.item.label ?? pluginRefId,
      })),
    [selectedPluginRefIds, composerCapabilities],
  );
}

/**
 * Builds the `ChatTransport` `AssistantDock.tsx` passes to both `<JiniChatProvider>` and
 * `<ChatPane>` directly. Injectable per `INFO.md`'s Components rule 3 (real I/O: every `startRun`
 * this transport drives is a network call) — defaulted to the real hook on `AssistantDockProps`.
 *
 * The transport holds no per-render state; rebuilding it each render would drop in-flight runs —
 * that is why this stays a `useMemo` with an empty-shaped dependency list (`executionConfigRef` is
 * a ref object, stable for the component's lifetime, so including it does not defeat the memo).
 * `getExecutionConfig` reads `executionConfigRef.current` fresh on every call instead of closing
 * over `executionConfig` by value, so a mode change mid-session takes effect on the NEXT message
 * without forcing a new transport instance.
 *
 * @param input.executionConfigRef - {@link UseExecutionConfig.executionConfigRef} — read fresh
 *   inside `getExecutionConfig`, never captured by value.
 * @param input.ensureConversationId - `useChatsSeam`'s `ensureConversationId`. Stable for the
 *   component's lifetime (a `useCallback` over two other stable callbacks — see its own declaration
 *   in `use-assistant-chats.hooks.ts`), so listing it in the dependency array below does not defeat
 *   the memo any more than `executionConfigRef` does. Optional so a test that injects a `useChats`
 *   stub predating it still builds a working transport — one without first-turn session capture,
 *   which is exactly the pre-fix behavior and never a crash.
 * @returns The memoized transport instance.
 * @param input.onDaemonStartingChange - Reports a send's activation still pending after 500 ms;
 *   clears on activation settlement or Stop, independently of page attachment and run acceptance.
 * @example
 * const transport = useAssistantTransport({ executionConfigRef, ensureConversationId: chats.ensureConversationId });
 */
export function useAssistantTransport(
  input: {
    agentBridge?: FrontendSessionBridge | null;
    executionConfigRef: React.MutableRefObject<ExecutionConfig>;
    readExecutionConfigForSend?: () => Promise<ExecutionConfig>;
    readLocalCliSelectionForSend?: (config: ExecutionConfig) => ChatPaneAgentSelection;
    ensureConversationId?: () => Promise<string | null>;
    persistUserTurn?: (conversationId: string, message: ChatMessage) => Promise<void>;
    onDaemonStartingChange?: (starting: boolean) => void;
  },
  { createTransport = createTovuAssistantTransport, prepareBinding = prepareAssistantPageBinding }: { createTransport?: typeof createTovuAssistantTransport; prepareBinding?: typeof prepareAssistantPageBinding } = {},
): ReturnType<typeof createTovuAssistantTransport> {
  const { executionConfigRef, ensureConversationId, persistUserTurn } = input;
  const io = useRef({ input, createTransport, prepareBinding });
  io.current = { input, createTransport, prepareBinding };
  return useMemo<ReturnType<typeof createTovuAssistantTransport>>(() => {
    const transport = io.current.createTransport({
      getExecutionConfig: () => executionConfigRef.current,
      // Turn 1's run has no conversation id of its own to send — the pane adopts one lazily, from
      // a message delta that does not exist yet when `runContext` is frozen. See
      // `CreateTovuAssistantTransportOptions.ensureConversationId` for the full mechanism and the
      // amnesia it caused.
      ...(ensureConversationId ? { ensureConversationId } : {}),
      // Defect 2 (2026-09-11): awaited by `startRun` before `POST /api/runs`, so a run can never
      // be dispatched for a message that exists nowhere durable. Same optional-spread shape as
      // `ensureConversationId` above and for the same reason — a test that injects a `useChats`
      // stub predating it still builds a working transport, just without the pre-dispatch write.
      ...(persistUserTurn ? { persistUserTurn } : {}),
      // ADR-059's AG-UI canary — off by default, flipped per-tab via `localStorage` (see
      // `isAgUiTransportEnabled`'s own doc). Read fresh per `startRun` call, same as
      // `getExecutionConfig` above.
      getAgUiEnabled: isAgUiTransportEnabled,
      // Which Local CLI agentIds carry their own multi-turn memory — see this file's own
      // `getResumeCapableAgentIds` doc, and `assistant-transport.ts`'s
      // `CreateTovuAssistantTransportOptions.getResumeCapableAgentIds` for the full contract.
      // `useRuntimeAccess`'s `listAgents`/`rescanAgents` keep the set it reads current.
      getResumeCapableAgentIds,
    });
    return {
      ...transport,
      async startRun(runInput, handlers) {
        const fresh = io.current.input;
        // ChatPane freezes agent/context before startRun. Re-read the saved Local CLI selection
        // here so a just-finished refresh is used even before React renders the updated picker.
        // The deployed-site UI gate may still be discovering a local host. Await its effective
        // read in either mode so the pending BYOK projection cannot misroute a local first send.
        if (fresh.readExecutionConfigForSend) {
          const config = await fresh.readExecutionConfigForSend();
          if (config.mode === "local-cli") {
            runInput = withLatestLocalCliSelection({ runInput, config }, { readSelection: fresh.readLocalCliSelectionForSend });
          }
        }
        // The pane froze context while the cold bridge was parked. Read its token after attach.
        if (fresh.executionConfigRef.current.mode === "local-cli") {
          const signals = [runInput.cancelSignal, runInput.signal].filter((signal): signal is AbortSignal => Boolean(signal));
          const signal = AbortSignal.any(signals);
          await pageBindToken({ bridge: fresh.agentBridge, signal }, {
            prepareBinding: io.current.prepareBinding,
            onDaemonStartingChange: (starting) => io.current.input.onDaemonStartingChange?.(starting),
          });
          signal.throwIfAborted();
          if (fresh.agentBridge) {
            const token = fresh.agentBridge.bindToken();
            if (!token) throw new Error("the assistant page is not attached");
            runInput = { ...runInput, context: { ...runInput.context, frontendBindToken: token } };
          }
        }
        return transport.startRun(runInput, handlers);
      },
    };
  }, [executionConfigRef, ensureConversationId, persistUserTurn]);
}

/** Pre-warms the per-site agent daemon while the dock is open in Local CLI mode (ADR-070 #7).
 * API · BYOK runs in the API process, so it never wakes the daemon; neither does the default mode
 * before the saved one has loaded. Return a failed wake for the dock's visible status; first send retries it.
 * @complexity O(1), one activation per open/config/bridge change; no polling. */
export function useLocalCliDaemonPrewarm(
  { mode, configLoaded, agentBridge }: { mode: ExecutionConfig["mode"]; configLoaded: boolean; agentBridge?: FrontendSessionBridge | null },
  { activate = activateAssistantDaemon }: { activate?: typeof activateAssistantDaemon } = {},
): string | null {
  const dockOpen = useSyncExternalStore(subscribeToAssistantDock, getAssistantDockOpen);
  const [error, setError] = useState<string | null>(null);
  const wake = useRef(activate);
  wake.current = activate;
  useEffect(() => {
    if (!dockOpen || !configLoaded || mode !== "local-cli") return;
    const controller = new AbortController();
    setError(null);
    void prepareAssistantPageBinding({ bridge: agentBridge, signal: controller.signal }, { activate: wake.current }).catch((failure: unknown) => {
      if (controller.signal.aborted) return;
      setError(failure instanceof Error ? failure.message : "The assistant could not attach to this page. Retry your message; if it keeps failing, restart the site.");
    });
    return () => controller.abort();
  }, [dockOpen, configLoaded, mode, agentBridge]);
  return dockOpen && mode === 'local-cli' ? error : null;
}

/** A required page binding must succeed before dispatch; failures and Stop reject the send.
 * Surfaces without page control retain run acceptance's existing cold-start path if wake fails.
 * Startup feedback covers only activation, never the subsequent page-attachment wait.
 * @returns The prepared token; the caller must re-read it at dispatch after this async boundary.
 * @complexity O(1), one timer and one abort listener, both released when the wait ends.
 */
async function pageBindToken(
  { bridge, signal }: { bridge?: FrontendSessionBridge | null; signal?: AbortSignal },
  { prepareBinding, onDaemonStartingChange }: {
    prepareBinding: typeof prepareAssistantPageBinding;
    onDaemonStartingChange: (starting: boolean) => void;
  },
): Promise<string | undefined> {
  signal?.throwIfAborted();
  let activationPending = true;
  const timer = setTimeout(() => onDaemonStartingChange(true), 500);
  // Stop and activation settlement may both arrive; a late completion must not clear a new send.
  const finishActivation = () => {
    if (!activationPending) return;
    activationPending = false;
    clearTimeout(timer);
    onDaemonStartingChange(false);
  };
  signal?.addEventListener("abort", finishActivation, { once: true });
  try {
    const token = await prepareBinding({ bridge, signal }, { onActivationSettled: finishActivation });
    signal?.throwIfAborted();
    return token;
  }
  catch (error) {
    if (signal?.aborted) throw signal.reason;
    if (!bridge) return undefined;
    throw error;
  }
  finally {
    finishActivation();
    signal?.removeEventListener("abort", finishActivation);
  }
}

/** Keep the saved CLI selection authoritative at dispatch, before adding the live page binding. */
function withLatestLocalCliSelection(
  { runInput, config }: { runInput: StartRunInput; config: ExecutionConfig },
  { readSelection }: { readSelection?: (config: ExecutionConfig) => ChatPaneAgentSelection } = {},
): StartRunInput {
  const selection = readSelection?.(config) ?? localCliSelectionFromConfig({ config });
  const { model: _oldModel, reasoning: _oldReasoning, ...context } = runInput.context ?? {};
  // A pending picker save stays authoritative even if a refresh still sees the old
  // ledger effort. Missing effort retains the existing fallback for legacy callers.
  const reasoning = selection.reasoning ?? selectedLocalCliReasoning({
    ...config, localCli: { ...config.localCli, agentId: selection.agentId },
  });
  return {
    ...runInput,
    agentId: selection.agentId,
    context: { ...context, ...(selection.model ? { model: selection.model } : {}), ...(reasoning ? { reasoning } : {}) },
  };
}

/**
 * Builds the `uploadAttachments` callback `AssistantDock.tsx` passes to `<ChatPane>`. Injectable
 * per `INFO.md`'s Components rule 3 (real I/O: every upload is a `fetch` to the daemon's own
 * `/api/attachments` route) — defaulted to the real hook on `AssistantDockProps`.
 *
 * `''` baseUrl: `createDaemonAttachmentUploader` builds `${baseUrl}/api/attachments`, so an empty
 * string resolves to the same bare `/api/attachments` relative path `AGENTS_URL`/the rescan route
 * below already use — same-origin, proxied by `src/server/modules/assistant.ts` to the agent
 * daemon, matching every other request this dock makes. Memoized for the same reason the transport
 * is: it owns internal per-uploader batch-quota state (`create-daemon-attachment-uploader.ts`'s
 * `batchUsage` map), so rebuilding it on every render would silently reset a turn's running quota
 * mid-upload.
 *
 * @returns The memoized uploader instance.
 * @example
 * const uploadAttachments = useAttachmentUploader();
 */
/**
 * Mirrors the website daemon's own per-file/per-turn caps so a rejection surfaces here, before any
 * bytes are sent, rather than only after the daemon's own enforcement rejects them. `apps/admin` is
 * a separate browser bundle from `apps/website` (no shared import today — see `tsconfig.json`'s
 * `@tovu/*` aliases for the narrow, dependency-free exceptions that DO cross that boundary), so
 * these are duplicated literals, not an import, matching this codebase's existing convention for a
 * client-side check that mirrors a server-side one it cannot reach (see `rules.ts`'s
 * `MEDIA_HTML_ATTRIBUTE_ALLOWED_NAMES` doc for the same "keep identical, by hand" pattern).
 *
 * Owner-directed (2026-09-21): must stay equal to `apps/website/src/features/media/upload-limits.ts`'s
 * `TOVU_MAX_UPLOAD_BYTES` (50 MiB) and `agent-daemon-server.ts`'s `ATTACHMENT_MAX_BATCH_BYTES`
 * (100 MiB, `TOVU_MAX_UPLOAD_BYTES * 2`) — update both together if either changes.
 */
const CHAT_ATTACHMENT_MAX_BYTES = 50 * 1024 * 1024;
const CHAT_ATTACHMENT_MAX_BATCH_BYTES = CHAT_ATTACHMENT_MAX_BYTES * 2;

export function useAttachmentUploader(): ReturnType<typeof createDaemonAttachmentUploader> {
  return useMemo(
    () =>
      createDaemonAttachmentUploader({ baseUrl: "", fetch }, {
        maxAttachmentBytes: CHAT_ATTACHMENT_MAX_BYTES,
        maxBatchBytes: CHAT_ATTACHMENT_MAX_BATCH_BYTES,
      }),
    [],
  );
}

/**
 * Routes skill packages to the install proposal; ordinary files retain their uploader result.
 * @returns A stable callback, refreshed when either injected dependency changes.
 * @complexity O(files) selection time and O(1) routing space; upload costs belong to the adapters.
 */
export function useSkillAwareAttachmentUploader(
  { uploadAttachments, proposeFiles }: {
    uploadAttachments: ReturnType<typeof createDaemonAttachmentUploader>;
    proposeFiles: (files: readonly File[]) => Promise<void>;
  },
  _optional: Record<string, never> = {},
): ReturnType<typeof createDaemonAttachmentUploader> {
  return useCallback(async (files, options) => {
    const { skills, attachments } = await partitionChatPackages({ files });
    if (skills.length > 0) await proposeFiles(skills);
    if (attachments.length === 0) return [];
    // The composer owns the message batch and cancellation lifetime. Dropping these options
    // makes separate attach actions create different batches, which the daemon cannot claim.
    return options === undefined ? uploadAttachments(attachments) : uploadAttachments(attachments, options);
  }, [uploadAttachments, proposeFiles]);
}

/**
 * Allows skill selection until the selected local runtime explicitly reports no tools.
 * @returns Whether the current runtime can receive skill guidance.
 * @complexity O(agents) time, O(1) space.
 */
export function resolveSkillsAvailable(
  { executionMode, selectedAgentId, agents }: {
    executionMode: ExecutionConfig["mode"];
    selectedAgentId: string;
    agents: readonly Pick<ChatPaneAgent, "id" | "supportsTools">[] | undefined;
  },
): boolean {
  return executionMode === "byok" || agents?.find(agent => agent.id === selectedAgentId)?.supportsTools !== false;
}

/**
 * Builds the `validateAttachments` callback `AssistantDock.tsx` passes to `<ChatPane>` — the host
 * half of restoring a persisted composer draft's ATTACHMENTS. Injectable per `INFO.md`'s Components
 * rule 3 for the same reason {@link useAttachmentUploader} above is: every probe is a real `fetch`
 * to `/api/attachments/:ref`, which a fake bypasses entirely.
 *
 * Without this prop `@jini-ai/chat` restores such a draft's TEXT only: it persists the attachment
 * references, but hands back none that no host has vouched for, because the staged bytes sit under
 * the daemon's one-hour `retentionMs` and a chip for a pruned file looks intact and dies at send.
 * See `lib/chat-attachment-liveness.ts` for the full rule and why a HEAD answers it.
 *
 * Memoized for the same reason the uploader is: `ChatPane` reads this on a draft restore at mount,
 * and a new identity each render would make that a moving dependency.
 *
 * @returns The memoized validator instance.
 * @example
 * const validateAttachments = useAttachmentValidator();
 */
export function useAttachmentValidator(): ReturnType<typeof createChatAttachmentValidator> {
  return useMemo(() => createChatAttachmentValidator(), []);
}

/**
 * Mirrors `lib/api.ts`'s `DEFAULT_REQUEST_TIMEOUT_MS` (60s). `listAgents`/`rescanAgents`/
 * `daemonOnline` below bypass that shared `request()` seam entirely — `/api/agents` is not under
 * `request()`'s `/api/admin/v1` base path — so without their own bound they can hang forever under
 * the same per-origin connection-pool exhaustion `api.ts`'s own `REQUEST_TIMEOUT_CODE` doc
 * describes (every open admin tab keeps one `EventSource` connection open forever; see
 * `lib/settings-events.ts`).
 */
const AGENTS_URL = "/api/agents";
const AGENTS_FETCH_TIMEOUT_MS = 60_000;

/**
 * `ChatPaneAgent` plus the one extra, Tovu-only field `GET /api/agents` actually serializes for
 * each entry — `apps/website/src/assistant/agents.ts`'s `AssistantAgentSummary.carriesOwnMemory`.
 * `@jini-ai/chat`'s own `ChatPaneAgent` type never declares it (it's a Tovu transport decision, not
 * a `@jini-ai/chat` concern), so this widened alias exists purely so this file can read it off the
 * same response `fetchAgents`/`rescanAgents` already fetch, without a second request.
 */
type AgentWithMemoryFlag = ChatPaneAgent & { carriesOwnMemory?: boolean };

/**
 * The pure half of {@link fetchAgents}/`useRuntimeAccess`'s `rescanAgents`: which agentIds are
 * resume-capable, from an already-fetched `/api/agents` payload. Split out so it's directly
 * testable against a plain fixture — no `fetch` mock, no module-state reset, required.
 */
export function extractResumeCapableAgentIds(agents: readonly AgentWithMemoryFlag[]): ReadonlySet<string> {
  return new Set(agents.filter((agent) => agent.carriesOwnMemory === true).map((agent) => agent.id));
}

/**
 * The last resume-capable agentId set observed from `/api/agents` — module-scoped, same "outlive
 * the component, read fresh per call" shape the provider cache above uses. This is the
 * live binding `useAssistantTransport`'s `getResumeCapableAgentIds` option reads through
 * {@link getResumeCapableAgentIds} below.
 *
 * Starts empty: before the first `/api/agents` response resolves, every agentId fails open to the
 * full-transcript path — see `assistant-transport.ts`'s `CreateTovuAssistantTransportOptions
 * .getResumeCapableAgentIds` doc for why "not yet known" must mean "send everything," not "send
 * only the latest message."
 */
let resumeCapableAgentIds: ReadonlySet<string> = new Set();

/** Test seam — same purpose as `execution-settings.ts`'s `resetLocalAgentDetectionCache`: this
 *  module's state persists across cases in a file, so a suite asserting on it needs to start cold. */
export function resetResumeCapableAgentIds(): void {
  resumeCapableAgentIds = new Set();
}

/**
 * {@link useAssistantTransport}'s `getResumeCapableAgentIds` — a stable top-level reference (same
 * "never captured by value" shape `isAgUiTransportEnabled` already has for `getAgUiEnabled`) so the
 * memoized transport always reads the CURRENT set, not whatever was live when it was built.
 *
 * Exported for the same reason {@link extractResumeCapableAgentIds} is: a test asserting that
 * `listAgents`/`rescanAgents` actually populated the module state needs a way to read it back.
 */
export function getResumeCapableAgentIds(): ReadonlySet<string> {
  return resumeCapableAgentIds;
}

/** Records one fresh inventory everywhere that reads it: the resume-capable set the transport
 *  consults, and the localStorage placeholder for the next cold load. Called on what the cache
 *  settles on, not inside {@link fetchAgents}: a GET that was in flight across a rescan answers
 *  with the older list, which must not overwrite what the rescan recorded. */
function recordAgents<T extends readonly AgentWithMemoryFlag[]>(agents: T): T {
  resumeCapableAgentIds = extractResumeCapableAgentIds(agents);
  writeAgentsSnapshot(agents);
  return agents;
}

/**
 * Reads one `/api/agents` (or rescan) response as an inventory, or throws when it is not one.
 *
 * Throws, never resolves `[]`, for both a non-2xx status and an empty list: `ChatPane` reads a
 * RESOLVED list as a finished detection and shows "No usable CLI is selected" when nothing in it is
 * usable, while a REJECTION tells it there is no answer yet, so it shows "Connecting to the
 * assistant…" and retries. The empty case matters because the server lists every CLI it knows
 * (`apps/website/src/assistant/agents.ts`, available or not), so `[]` only ever comes from a daemon
 * that is mid-restart — resolving it once cached it (`staleTime: Infinity`) until a hard reload.
 * Throwing also keeps it out of the query cache and the localStorage snapshot.
 */
async function readAgentsResponse(
  { inventory: { agents }, label }: { inventory: { agents?: AgentWithMemoryFlag[] }; label: string },
  _options: Record<string, never> = {},
): Promise<AgentWithMemoryFlag[]> {
  if (!Array.isArray(agents) || agents.length === 0) throw new Error(`${label} answered with no agents`);
  return agents;
}

async function fetchAgents(): Promise<ChatPaneAgent[]> {
  const inventory = await authenticatedAdminRequest<{ agents?: AgentWithMemoryFlag[] }>({ path: "", method: "GET" }, {
    basePath: "/api/agents",
    requireJson: true,
    signal: AbortSignal.timeout(AGENTS_FETCH_TIMEOUT_MS),
    errorFactory: ({ error }) => new ApiError(`GET ${AGENTS_URL} answered ${error.status}`, error.status, error.code, error.body),
  });
  return readAgentsResponse({ inventory, label: `GET ${AGENTS_URL}` });
}

/** The client-side cache key for `/api/agents`, scoped to the current admin boot below. */
const AGENTS_QUERY_KEY = ["assistant", "agents"] as const;

// Match @jini-ai/agent-runtime/src/model-discovery.ts:8; its export requires Node APIs.
const AGENTS_STALE_TIME_MS = 15 * 60_000;
const AGENTS_RETRY_TIME_MS = 30_000;
const AGENTS_PENDING_DELAYS_MS = [1_000, 2_000, 4_000] as const;

/** The agents `CachedLoader` plus the accepted snapshot's refresh deadline. */
export type AgentsLoader = CachedLoader<ChatPaneAgent[]> & { refreshAt(): number | undefined };

// Keys are snapshots owned by the boot-scoped query cache, so deadlines cannot leak across boots.
const agentsDeadlines = new WeakMap<ChatPaneAgent[], { expiresAt: number; pendingStep: number }>();

/** Records the server catalog's lifetime, capped at the browser's 15-minute maximum.
 * Pending snapshots advance through a short backoff before the normal failure cooldown.
 * Completed snapshots retaining an expired catalog use the 30-second retry cooldown. */
function rememberAgentsDeadline(
  { agents, pendingStep = 0 }: { agents: ChatPaneAgent[]; pendingStep?: number },
  _options: Record<string, never> = {},
): void {
  const now = Date.now();
  const pending = agents.some(agent => agent.discoveryPending);
  const lifetime = pending ? (AGENTS_PENDING_DELAYS_MS[pendingStep] ?? AGENTS_RETRY_TIME_MS) : AGENTS_STALE_TIME_MS;
  const expiresAt = pending ? now + lifetime : agents.reduce((deadline, agent) => {
    if (!agent.modelCatalog || agent.discoveryPending) return deadline;
    const catalogExpiry = Date.parse(agent.modelCatalog.expiresAt);
    const failureDeadline = agent.modelCatalog.freshness === "fresh" ? deadline : now + AGENTS_RETRY_TIME_MS;
    const catalogDeadline = catalogExpiry <= now ? now + AGENTS_RETRY_TIME_MS : catalogExpiry;
    return Math.min(deadline, failureDeadline, Number.isFinite(catalogDeadline) ? catalogDeadline : failureDeadline);
  }, now + lifetime);
  agentsDeadlines.set(agents, { expiresAt, pendingStep: pending ? pendingStep + 1 : 0 });
}

/** Writes a fresh inventory into the cache and everything that reads it. */
export function replaceAgents(loader: CachedLoader<ChatPaneAgent[]>, agents: ChatPaneAgent[]): ChatPaneAgent[] {
  recordAgents(agents);
  loader.replace({ value: agents });
  rememberAgentsDeadline({ agents: loader.peek() ?? agents });
  return agents;
}

/** A rescan: the POST's answer replaces the cached list; when the POST gives no usable answer, a
 *  cache-bypassing GET does instead. When both fail it rejects without touching the cache, so a
 *  failed rescan never overwrites a good inventory (`ChatPane` keeps showing the last good list). */
async function rescanAgentsInto(loader: CachedLoader<ChatPaneAgent[]>): Promise<ChatPaneAgent[]> {
  const inventory = await authenticatedAdminRequest<{ agents?: AgentWithMemoryFlag[] }>({ path: "/rescan", method: "POST" }, {
    basePath: "/api/agents",
    requireJson: true,
    signal: AbortSignal.timeout(AGENTS_FETCH_TIMEOUT_MS),
    errorFactory: ({ error }) => new ApiError(`POST ${AGENTS_URL}/rescan answered ${error.status}`, error.status, error.code, error.body),
  }).catch((error: unknown) => {
    // Fall back on an unusable response; a failed/canceled fetch still rejects as before.
    if ((error instanceof ApiError && error.status > 0) || error instanceof SyntaxError) return null;
    throw error;
  });
  const rescanned = inventory === null ? null : await readAgentsResponse({ inventory, label: `POST ${AGENTS_URL}/rescan` }).catch(() => null);
  return replaceAgents(loader, rescanned ?? (await fetchAgents()));
}

/** Shares GET ownership through Jini's boot-scoped cache; accepted snapshot deadlines govern reads.
 * Structural sharing can publish a different array from the transport result. Overlapping readers
 * and late pre-Rescan GETs must not extend a newer snapshot's deadline. Exposes that same deadline
 * so pane retries can wait out a pending cooldown instead of spending their budget on cached reads. */
function useAgentsLoader(): AgentsLoader {
  const { queryScope } = useAdminBootScope();
  const key = useMemo(() => [...AGENTS_QUERY_KEY, queryScope], [queryScope]);
  const loader = useCachedLoader({ key, fetch: fetchAgents }, { staleTime: AGENTS_STALE_TIME_MS });
  return useMemo(() => createAgentsLoader(loader), [loader]);
}

/** {@link useAgentsLoader}'s deadline rules over any `CachedLoader` — the hook passes the provider's,
 *  a test a plain object. `CachedLoader.peek` may answer `undefined` (its contract promises nothing
 *  more), so each read of the accepted snapshot falls back to the array this call itself holds. */
export function createAgentsLoader(loader: CachedLoader<ChatPaneAgent[]>): AgentsLoader {
  return {
    peek: loader.peek,
    replace: loader.replace,
    refreshAt: () => {
      const cached = loader.peek();
      return cached && agentsDeadlines.get(cached)?.expiresAt;
    },
    load: () => {
      const cached = loader.peek();
      const previous = cached && agentsDeadlines.get(cached);
      if (cached && previous && Date.now() < previous.expiresAt) return Promise.resolve(cached);
      // Bypass freshness only for a due read; retain idle data and join requests without invalidation.
      return loader.load(undefined, { staleTime: 0 }).then(agents => {
        const accepted = loader.peek() ?? agents;
        if (!agentsDeadlines.has(accepted) || agentsDeadlines.get(accepted) === previous) {
          rememberAgentsDeadline({ agents: accepted, pendingStep: previous?.pendingStep ?? 0 });
        }
        return accepted;
      }, error => {
        if (cached && agentsDeadlines.get(cached) === previous) {
          agentsDeadlines.set(cached, { expiresAt: Date.now() + AGENTS_RETRY_TIME_MS, pendingStep: previous?.pendingStep ?? 0 });
        }
        throw error;
      });
    },
  };
}

/**
 * In-flight `daemonOnline()` reads share each runtime-access instance's pending probe so its
 * overlapping callers reuse one transport instead of each starting their own fetch. Health checks
 * bypass the provider's connectivity gate: the browser's internet flag says nothing about the local daemon.
 *
 * `@jini-ai/chat/react`'s `useChatPaneRuntimeInventory` polls `daemonOnline` on a bare
 * `window.setInterval` every 5s while the tab is visible (0.3.11+ pauses it while hidden), and its
 * own de-dup (`useLatestOperation`) only ignores a STALE RESULT — it never
 * aborts the underlying fetch. Under connection-pool exhaustion, a `fetch` that queues forever
 * previously meant a brand new permanently-stuck request was added on every single tick, an
 * unbounded leak for as long as the tab stayed open (see
 * `ADS-memory/reports/2026-08-17-vite-proxy-pool-saturation-investigation.md`). Reusing one
 * in-flight promise caps that cost at one connection per runtime-access instance, the same fixed
 * cost the settings-events SSE already holds, instead of growing without bound.
 */
async function readDaemonOnline(): Promise<boolean> {
  const response = await fetch(AGENTS_URL, {
    credentials: "same-origin",
    signal: AbortSignal.timeout(AGENTS_FETCH_TIMEOUT_MS),
  });
  return response.ok;
}

/**
 * Builds the `runtimeAccess` object `AssistantDock.tsx` passes to `<ChatPane>` — the Local CLI
 * picker's agent list, rescan, and daemon-online poll. Injectable per `INFO.md`'s Components rule 3
 * (real I/O: all three members are `fetch`-backed) — defaulted to the real hook on
 * `AssistantDockProps`.
 *
 * `listAgents` reads through the shared query cache ({@link useAgentsLoader}), so a remounted pane,
 * a conversation switch, or a second screen gets completed inventory without another request.
 * Due reads join one GET for this boot. Pending snapshots use bounded backoff in Jini;
 * `getAgentsRefreshAt` aligns those retries with the shared cache, including across pane remounts.
 * completed catalogs honor server expiry, with a 15-minute maximum and 30-second failure cooldown.
 * A non-2xx or empty answer REJECTS and is never cached (see {@link readAgentsResponse}): `ChatPane` then
 * shows "Connecting to the assistant…" and retries until the daemon answers.
 *
 * `rescanAgents` writes its answer into that cache. It falls back to a plain re-fetch of the same
 * `/api/agents` GET whenever the rescan POST itself gives no usable answer; when that fails too it
 * rejects, and `ChatPane` keeps whatever agents are currently known instead of going blank.
 *
 * @returns The memoized inventory, refresh-deadline, rescan and health access `ChatPane` reads.
 * @example
 * const runtimeAccess = useRuntimeAccess();
 */
export function useRuntimeAccess(): ChatPaneRuntimeAccess {
  const loader = useAgentsLoader();
  const pendingHealth = useRef<Promise<boolean> | null>(null);
  const daemonOnline = useCallback(() => {
    if (pendingHealth.current) return pendingHealth.current;
    const pending = readDaemonOnline().finally(() => { pendingHealth.current = null; });
    pendingHealth.current = pending;
    return pending;
  }, []);
  return useMemo(
    () => ({
      listAgents: () => loader.load().then(recordAgents),
      getAgentsRefreshAt: loader.refreshAt,
      rescanAgents: () => rescanAgentsInto(loader),
      // A health probe must reach loopback even when the browser reports no internet connection.
      daemonOnline,
    }),
    [loader, daemonOnline],
  );
}

/**
 * The inventory `ChatPane` shows before its own `listAgents` call resolves (its `agents` prop, read
 * once per pane mount): the cached live list when this tab already has one, otherwise the last list
 * this browser saw (`lib/assistant-agents-snapshot.ts`), otherwise nothing — the pre-existing
 * "Loading available CLIs" state. Re-read every render so a pane re-keyed by a conversation switch
 * seeds from the live list rather than the snapshot the dock mounted with.
 *
 * @returns The placeholder list, or `undefined` when there is none.
 * @example
 * const agentsPlaceholder = useAgentsPlaceholder();
 */
export function useAgentsPlaceholder(): readonly ChatPaneAgent[] | undefined {
  const loader = useAgentsLoader();
  const [snapshot] = useState(readAgentsSnapshot);
  return loader.peek() ?? snapshot;
}

/**
 * Builds the composer's native working-directory access — see
 * `@/lib/browser-working-directory-access`'s module doc for the File System Access API details
 * and its known folder-NAME-not-path limitation. Injectable per `INFO.md`'s Components rule 3
 * (this is a browser API, `window.showDirectoryPicker`) — defaulted to the real hook on
 * `AssistantDockProps`.
 *
 * Memoized for the same reason `useAttachmentUploader` above is: the returned object's identity
 * feeds `ChatPane`'s own `workingDirectoryAccess`-changed effect
 * (`useChatPaneWorkingDirectory.hooks.ts`), so a new object on every render would re-run that
 * effect's directory validation on every render too.
 *
 * @returns The memoized access object, or `undefined` on a browser with no native picker (Safari,
 * Firefox) — `ChatPane` falls back to its own text-input popover when this is `undefined`.
 * @example
 * const workingDirectoryAccess = useWorkingDirectoryAccess();
 */
export function useWorkingDirectoryAccess(): ChatPaneWorkingDirectoryAccess | undefined {
  return useMemo(() => createBrowserWorkingDirectoryAccess(), []);
}

// `resolveComposerDiscoveryOutcome` and its deps live in `./resolve-composer-discovery-outcome.ts`;
// re-exported here so `AssistantDock.tsx`'s re-export (and every existing import) keeps working.
export { resolveComposerDiscoveryOutcome, type ResolveComposerDiscoveryOutcomeDeps };

/**
 * Wraps {@link resolveComposerDiscoveryOutcome} as the `onDiscoverySelect` callback
 * `AssistantDock.tsx` passes to `<ChatPane composerSlots={...}>`. Pure derivation/wiring, not I/O
 * of its own — `navigate` is a synchronous client-side route change (already a plain import, not a
 * seam anywhere else in this file), and `callAllowlistedTool` is supplied by the caller (the same
 * `mcpUiToolCaller` singleton registered for MCP-UI surfaces), so this hook has nothing of its own
 * to inject; no `INFO.md` rule-3 seam.
 *
 * @param input.composerCapabilities - {@link UseComposerCapabilities.composerCapabilities} — the
 *   live discovery-catalog projection.
 * @param input.callAllowlistedTool - {@link ResolveComposerDiscoveryOutcomeDeps.callAllowlistedTool}.
 * @param input.addPluginRef - {@link ResolveComposerDiscoveryOutcomeDeps.addPluginRef}.
 * @returns The memoized `onDiscoverySelect` callback.
 * @example
 * const handleComposerDiscoverySelect = useComposerDiscoverySelect({
 *   composerCapabilities,
 *   callAllowlistedTool: mcpUiToolCaller,
 *   addPluginRef,
 * });
 */
export function useComposerDiscoverySelect(
  { composerCapabilities, callAllowlistedTool, addPluginRef, skillsAvailable, addSkill, readDraft }: {
    composerCapabilities: ComposerCapabilityProjection;
    callAllowlistedTool: ResolveComposerDiscoveryOutcomeDeps["callAllowlistedTool"];
    addPluginRef?: ResolveComposerDiscoveryOutcomeDeps["addPluginRef"];
    skillsAvailable?: boolean;
    addSkill?: ResolveComposerDiscoveryOutcomeDeps["addSkill"];
    readDraft?: ResolveComposerDiscoveryOutcomeDeps["readDraft"];
  },
): (selection: ComposerDiscoverySelection) => Promise<ComposerDiscoveryOutcome | void> {
  return useCallback(
    (selection: ComposerDiscoverySelection) =>
      resolveComposerDiscoveryOutcome(selection, {
        capabilities: composerCapabilities,
        navigate,
        callAllowlistedTool,
        addPluginRef,
        skillsAvailable,
        addSkill,
        readDraft,
      }),
    [composerCapabilities, callAllowlistedTool, addPluginRef, skillsAvailable, addSkill, readDraft],
  );
}

/**
 * Whether a completed run's messages-change delta should trigger the refresh announcements, and
 * what the next `settledRunMessageId` marker should be. Pulled out of `handleMessagesChange` so the
 * "fire once per finished run, not once per streaming delta" dedup logic is directly assertable
 * without a live `ChatPane`.
 *
 * Deliberately triggered by RUN COMPLETION rather than by inspecting the transcript for a settings
 * or content tool call. Matching tool names here would put a list of them in the admin shell, where
 * it would fall out of date the first time the catalog grows — and the whole cost of being wrong is
 * a few sub-millisecond SQLite reads per run. Ignorance is cheaper than coupling.
 *
 * @param input.messages - The full transcript as of this `onMessagesChange` event.
 * @param input.settledRunMessageId - The last message id already published for, or `null`.
 * @returns `publish` (whether to announce now) and `nextSettledRunMessageId`
 *   (what the caller's ref should hold next; a live retry clears its earlier completion mark).
 * @example
 * const { publish, nextSettledRunMessageId } = shouldPublishOnMessagesChange({
 *   messages,
 *   settledRunMessageId: settledRunMessageId.current,
 * });
 */
export function shouldPublishOnMessagesChange(
  { messages, settledRunMessageId }: { messages: ChatMessage[]; settledRunMessageId: string | null },
): { publish: boolean; nextSettledRunMessageId: string | null } {
  const last = messages[messages.length - 1];
  if (!last || last.role !== "assistant") {
    return { publish: false, nextSettledRunMessageId: settledRunMessageId };
  }
  if (!isTerminalRunStatus({ status: last.runStatus })) {
    // Retry reuses a saved assistant message's id; its next real completion must still publish.
    return { publish: false, nextSettledRunMessageId: settledRunMessageId === last.id ? null : settledRunMessageId };
  }
  if (settledRunMessageId === last.id) {
    return { publish: false, nextSettledRunMessageId: settledRunMessageId };
  }
  return { publish: true, nextSettledRunMessageId: last.id };
}

/** How far through a run's tool calls the content-refresh publisher has already announced. */
export interface ToolProgressMark {
  readonly messageId: string;
  readonly toolResultCount: number;
}

/**
 * Whether a newly-returned tool call should announce a content refresh right now, and what the
 * next {@link ToolProgressMark} the caller's ref should hold is.
 *
 * Exists because {@link shouldPublishOnMessagesChange} only fires at run completion: a run that
 * writes content and then, in the same turn, navigates to inspect the write is shown a screen that
 * fetched before the write, since nothing had been published yet. Counting `tool_result` events
 * (rather than matching a tool name) keeps the "ignorance is cheaper than coupling" property this
 * file's own doc argues for — see {@link shouldPublishOnMessagesChange}'s doc comment. The count is
 * monotonic within one RUN, but not within one message id: a retry reuses the failed message's id
 * with `events` reset, so the mark is superseded by a lower count as well as by a different id.
 *
 * @param input.messages - The full transcript as of this `onMessagesChange` event.
 * @param input.publishedToolProgress - The mark already published for, or `null`.
 * @returns `publish` (whether to announce now) and `nextPublishedToolProgress` (what the caller's
 *   ref should hold next — unchanged when `publish` is `false`).
 */
export function shouldPublishContentOnToolProgress(
  { messages, publishedToolProgress }: {
    messages: ChatMessage[];
    publishedToolProgress: ToolProgressMark | null;
  },
): { publish: boolean; nextPublishedToolProgress: ToolProgressMark | null } {
  const last = messages[messages.length - 1];
  if (!last || last.role !== "assistant") {
    return { publish: false, nextPublishedToolProgress: publishedToolProgress };
  }
  const toolResultCount = (last.events ?? []).filter((event) => event.kind === "tool_result").length;
  // A count BELOW the mark under the same id is a NEW run, not a delta already announced: retrying
  // a failed run rebuilds that assistant message in place — same `id`, `events` reset to `[]` — so
  // the retry's counts restart at 1 while the mark still holds the failed run's higher count.
  // Keyed on the id alone, every retried tool call up to that count reads as "already announced",
  // and `shouldPublishOnMessagesChange` cannot cover for it because its own `settledRunMessageId`
  // already holds the same id. Within one run `events` only ever grows, so a decrease is unambiguous.
  const mark = publishedToolProgress?.messageId === last.id ? publishedToolProgress : null;
  const alreadyPublished = mark && mark.toolResultCount <= toolResultCount ? mark.toolResultCount : 0;
  if (toolResultCount <= alreadyPublished) {
    return { publish: false, nextPublishedToolProgress: publishedToolProgress };
  }
  return { publish: true, nextPublishedToolProgress: { messageId: last.id, toolResultCount } };
}

/**
 * Builds the `onMessagesChange` callback `AssistantDock.tsx` passes to `<ChatPane>`. Pure
 * state/wiring, not I/O of its own — `chats.onMessagesChange` and `publishSettingsRefresh` are
 * already-wired dependencies (the former injected via `useChats`, the latter the same bus singleton
 * {@link useExecutionConfig} already calls directly), so this hook has nothing of its own to inject;
 * no `INFO.md` rule-3 seam.
 *
 * Owns `settledRunMessageId` internally (a `useRef`, not exposed) — last assistant message id seen
 * in a terminal state, so a run's completion fires the settings refresh below exactly once.
 * `onMessagesChange` runs on every delta of a streaming reply, and the terminal message keeps
 * arriving in later calls after it settles. A restored pane seeds these markers from its saved
 * history: hydration is not a new run completion or a newly returned tool call.
 *
 * A finished run may have written a setting — `settings_set_ui_preference` is agent-callable — so
 * the mounted settings tabs re-read. Without this the write lands in `content.db` and the open tab
 * keeps rendering the value it fetched at mount, which reads as the tool having silently done
 * nothing.
 *
 * The identical thing was true of CONTENT until 2026-08-26, just with no bus to say it on:
 * `taxonomy_create_taxonomy` is agent-callable too, and the Categories & Tags screen sitting beside
 * this dock kept listing what it fetched at mount until the operator hit Ctrl-R. So this publisher
 * now announces on `lib/content-refresh-bus` as well. It is one trigger with two announcements, not
 * a second trigger — the dedup below still fires it exactly once per finished run, and neither bus
 * carries a payload, so widening what is announced cannot widen what any subscriber can read.
 *
 * Deliberately triggered by RUN COMPLETION rather than by inspecting the transcript for a settings
 * or taxonomy tool call — see {@link shouldPublishOnMessagesChange}'s own doc for why. `undefined`
 * scope (rather than a namespace or resource list) for the same reason: this publisher does not know
 * what changed, and saying so is more honest than guessing.
 *
 * @param input.chats - The persistence callback and optional pane/history metadata, which seeds
 *   the existing publication markers on restoration.
 * @returns The memoized `onMessagesChange` callback.
 * @example
 * const handleMessagesChange = useMessagesChangeHandler({ chats });
 */
export function useMessagesChangeHandler(
  { chats }: { chats: Pick<UseAssistantChats, "onMessagesChange"> & Partial<Pick<UseAssistantChats, "paneKey" | "initialMessages">> },
): (messages: ChatMessage[]) => void {
  const settledRunMessageId = useRef<string | null>(null);
  const publishedToolProgress = useRef<ToolProgressMark | null>(null);
  const history = useRef<Partial<Pick<UseAssistantChats, "paneKey" | "initialMessages">>>({});

  return useCallback(
    (messages: ChatMessage[]) => {
      if (history.current.paneKey !== chats.paneKey || history.current.initialMessages !== chats.initialMessages) {
        history.current = { paneKey: chats.paneKey, initialMessages: chats.initialMessages };
        const initialMessages = chats.initialMessages ?? [];
        settledRunMessageId.current = shouldPublishOnMessagesChange({ messages: initialMessages, settledRunMessageId: null }).nextSettledRunMessageId;
        publishedToolProgress.current = shouldPublishContentOnToolProgress({ messages: initialMessages, publishedToolProgress: null }).nextPublishedToolProgress;
      }
      window.__tovuAssistantMessages = messages;
      // Persistence is selective, not per-delta — see `lib/assistant-chats.ts`'s
      // `persistableMessages` for why a streaming reply is written once rather than per token.
      chats.onMessagesChange(messages);

      const { publish, nextSettledRunMessageId } = shouldPublishOnMessagesChange({
        messages,
        settledRunMessageId: settledRunMessageId.current,
      });
      settledRunMessageId.current = nextSettledRunMessageId;

      const toolProgress = shouldPublishContentOnToolProgress({
        messages,
        publishedToolProgress: publishedToolProgress.current,
      });
      publishedToolProgress.current = toolProgress.nextPublishedToolProgress;

      // Settings stay on run completion: `settings_set_ui_preference` writes are rare, and the
      // settings tabs hold editable form state a mid-run reload would be more likely to disturb
      // than to help.
      if (publish) publishSettingsRefresh();
      // One publish per delta at most, so a terminal delta that also carries a new tool result
      // does not announce twice.
      if (publish || toolProgress.publish) publishContentRefresh();
    },
    [chats],
  );
}

/** `value === undefined ? {} : { [key]: value }` as a named helper — same complexity-budget
 *  rationale as `use-external-mcp.hooks.ts`'s `includeIfDefined`: moves this branch out of
 *  {@link resolveRunContext}'s own scope without changing what it sends on the wire. */
function includeIfDefined<K extends string, V>(key: K, value: V | undefined): { [P in K]?: V } {
  return (value === undefined ? {} : { [key]: value }) as { [P in K]?: V };
}

/** `typeof value === "string" && value.length > 0 ? { [key]: value } : {}` as a named helper —
 *  same rationale as {@link includeIfDefined}: each of {@link resolveRunContext}'s "send only when
 *  a real value is present" string fields was its own two-branch (`&&` + ternary) contributor to
 *  that function's own complexity. Same value, same "absent means default" behavior.
 *
 *  `null` is accepted alongside `undefined` and treated identically — `conversationId` is
 *  `chats.activeId`, which is `null` (not `undefined`) between chats. The `typeof` guard already
 *  excluded it; only the parameter type had not said so. */
function includeIfNonEmptyString<K extends string>(key: K, value: string | null | undefined): { [P in K]?: string } {
  return (typeof value === "string" && value.length > 0 ? { [key]: value } : {}) as { [P in K]?: string };
}

/** Same rationale as {@link includeIfNonEmptyString}, for `pluginRefIds` — a non-empty readonly
 *  array rather than a non-empty string. */
function includeIfNonEmptyArray<K extends string, V>(key: K, value: readonly V[] | undefined): { [P in K]?: readonly V[] } {
  return (value && value.length > 0 ? { [key]: value } : {}) as { [P in K]?: readonly V[] };
}

/**
 * Builds the per-call run context the daemon reads `frontendBindToken`/`model` out of
 * (`assistant-transport.ts`'s `contextRef` wiring). Omits each key entirely when absent, rather
 * than sending it as `undefined` or an empty string, matching the daemon's own "absent means
 * default" contract for both fields.
 *
 * `model` is forwarded opaque and unfiltered — including the `'default'` sentinel
 * (`DEFAULT_MODEL_OPTION.id`, `@jini-ai/agent-runtime`) that `ChatPane`'s own selection resolution
 * falls back to when nothing else is picked. Every agent def's `buildArgs` (and
 * `resolveModelForAgent`) already treats `'default'`/absent identically as "omit `--model`, defer
 * to the CLI's own config" — that is the one place this decision is made; duplicating the check
 * here would only be a second copy of it to keep in sync.
 *
 * @param input.bindToken - The current tab's page-control bind token, or `undefined` if unbound.
 * @param input.model - The Local CLI picker's live model selection, or `undefined` before a
 *   selection has resolved (e.g. no agents detected yet).
 * @param input.pluginRefIds - {@link UseSelectedAgentPlugins.selectedPluginRefIds} — the
 *   composer's currently-pinned Agent Plugin chips.
 * @param input.conversationId - `chats.activeId` (`useChatsSeam`) — the same id already passed to
 *   `<ChatPane conversationId={...}>` for message persistence. Lets `agent-daemon-server.ts`'s
 *   `onStarted` key its per-conversation agent-CLI session lookup (`agent-session-resume.ts`,
 *   `RunEndPayload.sessionRef`'s round trip) — see that file's own doc. `undefined` before any
 *   conversation is active (e.g. `chats.activeId` is `null` right after "New chat").
 * @returns The context object to merge into a run's `contextRef`.
 * @example
 * const context = resolveRunContext({ bindToken: agentBridge?.bindToken(), model: selection.model, pluginRefIds, conversationId });
 */
export function resolveRunContext(
  { bindToken, model, reasoning, pluginRefIds, selectedSkills, conversationId, pageContext }: {
    bindToken: string | undefined;
    model?: string;
    reasoning?: string;
    pluginRefIds?: readonly string[];
    selectedSkills?: readonly SelectedComposerSkill[];
    conversationId?: string | null;
    /** `readAgentScreenContext()` at send time — the screen "this page" refers to. */
    pageContext?: AgentScreenContext;
  },
): {
  frontendBindToken?: string;
  model?: string;
  reasoning?: string;
  pluginRefIds?: readonly string[];
    selectedSkills?: readonly SelectedComposerSkill[];
  conversationId?: string;
  pageContext?: AgentScreenContext;
} {
  return {
    ...includeIfDefined("frontendBindToken", bindToken),
    ...includeIfNonEmptyString("model", model),
    // The Execution tab's persisted "Reasoning effort" pick, carried on exactly the same terms as
    // `model` — including the empty-string omission, since `""` is the ledger's own "no explicit
    // effort" and sending it would mean the same thing as sending nothing while looking like a
    // real selection on the wire.
    ...includeIfNonEmptyString("reasoning", reasoning),
    // Omitted entirely when empty, same "absent means none" convention as the two fields above —
    // a run with no pinned plugin carries no key for it, matching `attachmentIds`'s own posture in
    // `assistant-transport.ts`'s `buildLocalCliContextRef`.
    ...includeIfNonEmptyArray("pluginRefIds", pluginRefIds),
    ...includeIfNonEmptyArray("selectedSkills", selectedSkills),
    ...includeIfNonEmptyString("conversationId", conversationId),
    ...includeIfDefined("pageContext", pageContext),
  };
}

/**
 * Builds the MCP-UI sandbox proxy's iframe URL as a same-document `data:` URL, in place of a route
 * served from this admin app's own origin (`GET /mcp-ui/sandbox-proxy.html`, `apps/website`'s
 * `mcp-ui-sandbox-proxy-route.ts`). `@mcp-ui/client`'s `AppFrame` hardcodes `sandbox="allow-scripts
 * allow-same-origin allow-forms"` on the iframe it creates — not configurable away by this app or by
 * `@jini-ai/ui` — so a same-origin route means any third-party MCP server's HTML, once
 * `document.write`-n into that iframe by the proxy script, gets this admin origin's cookies, storage,
 * and same-origin fetches. A `data:` URL's origin is opaque under the URL Standard's own origin
 * algorithm regardless of `allow-same-origin` (verified live against a real Chromium build,
 * 2026-09-03 — see `@jini-ai/ui`'s `sandbox-proxy.ts` module doc), so switching to one closes that gap
 * without needing a second host, DNS entry, or CORS change: `buildSandboxProxyDataUrl` bakes this
 * admin app's own origin into the served script as a literal (never read back from the iframe's own
 * URL), so the ready/resource-ready handshake still only accepts messages from this window's real
 * parent.
 *
 * The old same-origin route stays mounted server-side (harmless, and it may still have other
 * consumers), but this admin dock no longer points an iframe at it.
 *
 * @param hostOrigin - This admin app's own real origin — `globalThis.location.origin`, always, never
 *   a value parsed back out of this document's own URL.
 */
export function buildAssistantMcpUiSandboxProxyUrl(hostOrigin: string): URL {
  return new URL(buildSandboxProxyDataUrl(hostOrigin));
}

/**
 * `useMcpUiHost`'s `onOpenLink` implementation for this admin dock (S-G1b, memory
 * `links_open_new_tab` — generic, not Supabase-specific: any bundled or third-party plugin's
 * rendered MCP-UI card gets the same "links open in a new tab" behavior). `McpUiHostOptions`'s own
 * doc is explicit that omitting this option makes the Host refuse every `ui/open-link` request, so
 * before this existed a link inside a rendered card did nothing at all — not a broken link, an
 * inert one.
 *
 * `https:` only, on purpose: a View is untrusted content (a third-party MCP server's own HTML,
 * `@mcp-ui/client`'s whole reason for existing), and `window.open` will happily hand a
 * `javascript:` URL a same-tab execution context, or hand a `file:`/`data:` URL more than a chat
 * card should ever be able to reach. Rejecting everything except `https:` is a strict allowlist,
 * not a denylist of the schemes seen so far. A URL that fails to parse at all (`new URL` throwing)
 * is treated the same as a wrong scheme — refused, not surfaced as an error to the View.
 *
 * One exception, a root-relative path (`/admin/…`, never protocol-relative `//host`): owner
 * 2026-10-08, every chat link opens a new tab, in-app links included. A View's `<a href>` reaches
 * here unresolved — Jini's sandbox proxy forwards link clicks as `ui/open-link`, and its opaque
 * `data:` document has no base to resolve a path against — so the path is resolved against this
 * admin's own origin, the only page it can mean. That opens this app itself, whatever its scheme.
 *
 * `noopener,noreferrer` on the `window.open` call itself closes `window.opener` back-reference
 * access (the tab-nabbing vector `rel="noopener"` exists for on a plain `<a>`) and withholds the
 * `Referer` header, matching how this app already opens every other off-site link — see memory
 * `links_open_new_tab`.
 *
 * @param url - The View's requested target, exactly as `useMcpUiHost` receives it from the
 *   `ui/open-link` request — not yet validated.
 * @complexity O(1) — one `URL` parse, at most one `window.open` call.
 */
export function openMcpUiLink(url: string): void {
  if (/^\/(?!\/)/.test(url)) {
    window.open(new URL(url, window.location.origin).href, "_blank", "noopener,noreferrer");
    return;
  }
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error("Could not open the link.");
  }
  if (parsed.protocol !== "https:") throw new Error("Could not open the link.");
  window.open(url, "_blank", "noopener,noreferrer");
}

/**
 * Builds the `runContext` callback `AssistantDock.tsx` passes to `<ChatPane>` — a thin memoized
 * wrapper around {@link resolveRunContext}. Pure derivation, not I/O of its own (`agentBridge` is
 * caller-owned, `model` is a plain string); no `INFO.md` rule-3 seam.
 *
 * A function, and the token read *inside* it via `agentBridge?.bindToken()`, because `EventSource`
 * reconnects on its own — a daemon restart, a sleeping laptop, an ordinary blip — and every reattach
 * mints a new session and a new token. Capturing the value once would keep sending a dead one, and
 * the only symptom would be the agent being told "no frontend is bound to this run" on every page
 * call, long after the reconnect that caused it.
 *
 * Depends on `agentBridge` identity rather than reading a ref: the bridge object is stable for the
 * tab's lifetime, so this rebuilds only when page control genuinely appears or goes away. Also
 * depends on `model` (not the whole `localCliSelection` object, which would rebuild on every
 * keystroke-equivalent picker interaction that leaves the model alone) so a run started right after
 * a model pick carries it — {@link useLocalCliSelection} owns the picker's live value, and this is
 * the one place that value needs to leave React state.
 *
 * @param input.agentBridge - This tab's page-control connection, or `null`/`undefined` if unbound.
 * @param input.model - {@link UseLocalCliSelection.localCliSelection}`.model`, the live picker
 *   value.
 * @param input.reasoning - The selected agent's persisted reasoning effort
 *   (`selectedLocalCliReasoning`, `lib/execution-settings.ts`). Read from the ledger rather than
 *   from a dock-local picker because the Execution tab owns that control; same "rebuild when it
 *   changes" posture as `model`, so flipping the effort takes effect on the NEXT message.
 * @param input.pluginRefIds - {@link UseSelectedAgentPlugins.selectedPluginRefIds}, read fresh on
 *   every rebuild — same "never captured, always the live value" posture as `model`, so pinning or
 *   removing a chip mid-session takes effect on the NEXT message without forcing a new callback
 *   identity mid-render.
 * @param input.conversationId - {@link resolveRunContext}'s own `conversationId` doc — forwarded
 *   straight through, same "rebuild when it changes" posture as `model`/`pluginRefIds`.
 * @param input.readScreenContext - Reads the admin screen the operator is on; called inside the
 *   callback, like `bindToken()`, because navigation does not rebuild this callback. Defaults to
 *   `lib/agent-screen-context.ts`'s real store; a test passes its own.
 * @returns The memoized `runContext` callback.
 * @example
 * const runContext = useRunContext({ agentBridge, model: localCliSelection.model, pluginRefIds: selectedPluginRefIds, conversationId: chats.activeId });
 */
export function useRunContext(
  { agentBridge, model, reasoning, pluginRefIds, selectedSkills, conversationId, readScreenContext = readAgentScreenContext }: {
    agentBridge: FrontendSessionBridge | null | undefined;
    model?: string;
    reasoning?: string;
    pluginRefIds?: readonly string[];
    selectedSkills?: readonly SelectedComposerSkill[];
    conversationId?: string | null;
    readScreenContext?: () => AgentScreenContext | undefined;
  },
): () => {
  frontendTabId: string;
  frontendBindToken?: string;
  model?: string;
  reasoning?: string;
  pluginRefIds?: readonly string[];
    selectedSkills?: readonly SelectedComposerSkill[];
  conversationId?: string;
  pageContext?: AgentScreenContext;
} {
  return useMemo(
    () => () =>
      ({ ...resolveRunContext({
        bindToken: agentBridge?.bindToken(),
        model,
        reasoning,
        pluginRefIds,
        selectedSkills,
        conversationId,
        pageContext: readScreenContext(),
      }), frontendTabId: adminFrontendTabId }),
    [agentBridge, model, reasoning, pluginRefIds, selectedSkills, conversationId, readScreenContext],
  );
}

/**
 * @file Seam layer (2026-08-18, added after the inline-hook-extraction pass above, in response to
 * live review of that pass): one `use*Seam` wrapper per `INFO.md` rule-3 injectable prop on
 * `AssistantDockProps`, each fusing "pick the override or default the real hook" and "call it" into
 * a single call `AssistantDock.tsx` makes directly — `const { … } = useExecutionConfigSeam(props.useExecutionConfig)`
 * — rather than the two-step `const useXState = resolveXHook(props.useX); const { … } = useXState();`
 * the component previously did for each of the eight seamed hooks.
 *
 * Moving this here, not just shortening it in place, is the point: `INFO.md`'s own table says
 * `<Name>.tsx` holds "props interface + JSX, and nothing else" and `<Name>.hooks.tsx` holds "the
 * state, effects, refs, and DOM/IO logic, as named `use*` hooks" — the override-or-default decision
 * is part of a seamed hook's own contract, not a rendering concern, so it belongs here. The
 * `resolveXHook` functions this replaces existed as separately-scoped functions (not inline default
 * parameters, `SeeMore`'s `{ useClamp = useSeeMoreClamp }` idiom) specifically to keep ESLint's
 * cyclomatic-complexity rule from counting each seam's default against `AssistantDock`'s OWN
 * function body (see that function's own `@complexity` doc). A `use*Seam` wrapper preserves that
 * property for free: its `??` lives in the wrapper's body, not `AssistantDock`'s, so
 * `AssistantDock`'s measured complexity is unchanged by this pass (still 5 cyclomatic / 2 cognitive
 * — verify with `check-admin-complexity-drift.ts` after any further edit here).
 *
 * `AssistantDockProps` itself, its seam docs, and `resolveAgentBridge` (not hook-shaped — a plain
 * `override ?? null`, never a two-step resolve-then-call) are unaffected and stay in
 * `AssistantDock.tsx`; only the eight hook seams move (later joined by a ninth, folded into
 * `useAssistantDockChrome` — see its own doc below). External behavior is identical: same prop
 * names, same default-to-the-real-hook semantics, same "AssistantDock use*Injection" test coverage
 * (`components/__tests__/AssistantDock.unit.test.tsx`) — this is a pure internal relocation.
 */

export function useChatsSeam(
  override: (() => UseAssistantChats) | undefined,
  { principalId }: { principalId?: string } = {},
): UseAssistantChats {
  // `principalId` reaches only the wired hook: it scopes the remembered last conversation, which an
  // injected test hook has no use for.
  return override ? override() : useWiredAssistantChats({ principalId });
}

export interface AssistantDockChrome {
  /** The resolved locale string — {@link AssistantDockProps.useAdminLocale}'s override, or
   *  `useWiredAdminLocale`'s real fetched value. */
  locale: string;
  /** Translates this component's OWN pane chrome (eyebrow, title fallback, composer placeholder) —
   *  `assistant-dock-i18n.ts`'s own `t`, which falls back to `COMMON_I18N` via
   *  `createDictionaryTranslator` before returning the raw key. Recomputed each render (cheap: one
   *  object lookup), not memoized — matches this closure's pre-extraction behavior exactly. */
  t: (key: string) => string;
  /** The `I18nAdapter` `<JiniChatProvider i18n={...}>` takes — `@jini-ai/chat/react`'s OWN
   *  translation contract, covering the `ConversationList` switcher mounted in `header` below, a
   *  DIFFERENT (larger, package-owned) key set than `t` above. See {@link useChatI18n}. */
  chatI18n: I18nAdapter;
}

/** Delegate title cleanup and automatic-title casing to Jini; saved custom wording is preserved.
 * @complexity O(c + m + p) for conversations, loaded messages and the first prompt's length.
 */
export function resolveAssistantConversationTitle({ chats, fallback }: {
  chats: Pick<UseAssistantChats, 'conversations' | 'activeId' | 'initialMessages'>; fallback: string;
}, _options = {}): string {
  const conversation = chats.conversations.find(item => item.id === chats.activeId);
  if (!conversation) return fallback;
  return conversationTitleForDisplay({
    title: conversation.title, titleSource: conversation.titleSource,
    firstPrompt: chats.initialMessages.find(message => message.role === 'user')?.content,
  }) ?? fallback;
}

/**
 * Ninth seam, added on top of the original eight after live review: `useWiredAdminLocale()` was
 * still being called bare in `AssistantDock.tsx` — the one hook in the component touching real
 * DOM/IO (`port.loadLanguage()`'s fetch, `port.subscribeToSettingsRefresh`) that had NOT been given
 * an `INFO.md` rule-3 seam, unlike every other IO hook here. Consequence: every existing
 * `AssistantDock` test was making an unstubbed real fetch attempt for the locale on every render
 * (silently swallowed by `useAdminLocale`'s own `.catch(() => undefined)`, landing on
 * `DEFAULT_LOCALE`), and no test could drive `locale`/`chatI18n`/`t()` for any OTHER locale without
 * either stubbing `lib/settings-tabs` globally or asserting only ever the English default.
 *
 * Bundles `locale`, `t`, and `chatI18n` into one call — not three separate ones
 * (`useAdminLocaleSeam(...)`, an inline `t` closure, `useChatI18n(locale)`) — because all three
 * exist for exactly one shared purpose (translating this dock's own chrome) and were only ever
 * consumed together at the one call site in `AssistantDock.tsx`. A prior revision of this pass kept
 * them as three separate steps in the component body; that was redundant on inspection — three
 * statements standing in for what is really one derived value. `t` itself was also still inline in
 * the component before this consolidation (a plain closure, not a raw hook call, so it was outside
 * this pass's original "extract every inline hook" mandate on a literal reading — but leaving it
 * splintered from `locale`/`chatI18n`, its only two reasons to exist, made no sense once those two
 * were unified here).
 *
 * `useChatI18n` (above) is still its own export, composed internally rather than inlined — it keeps
 * its own direct, narrower tests (locale in, adapter out, no coupling to how `locale` was obtained),
 * and this hook's own tests can stay focused on the seam and the `t()` dictionary behavior.
 *
 * `useWiredAdminLocale` is not itself newly extracted here — it already existed as a properly split,
 * independently tested `useX(port)`/`useWiredX()` pair (`use-admin-locale.hooks.ts`,
 * `admin-locale-dependencies.hooks.ts`, `admin-locale-port.hooks.ts`, with its own
 * `use-admin-locale.hooks.test.ts`) called bare from ~40 files repo-wide by deliberate, documented
 * choice (`use-admin-locale.hooks.ts`'s own header: "converting every one of those call sites was
 * out of scope for this pass... once every remaining bare call site is converted to
 * `useWiredAdminLocale()`, this default can be dropped"). This seam does not touch that shared hook
 * or its ~39 other bare call sites — it only gives `AssistantDock` specifically the same
 * per-consumer prop override every other IO hook in this file already has, the same way `useChats`
 * (also a shared, externally-defined hook) already gets one without every OTHER `useAssistantChats`
 * call site needing to.
 *
 * @param useAdminLocaleOverride - {@link AssistantDockProps.useAdminLocale}. Defaults to the real
 *   `useWiredAdminLocale`.
 * @returns `{ locale, t, chatI18n }` — see {@link AssistantDockChrome}.
 * @example
 * const { locale, t, chatI18n } = useAssistantDockChrome(useAdminLocale);
 */
export function useAssistantDockChrome(useAdminLocaleOverride: (() => string) | undefined): AssistantDockChrome {
  const locale = (useAdminLocaleOverride ?? useWiredAdminLocale)();
  const t = (key: string): string => translateAssistantDockLabel(locale, key);
  const chatI18n = useChatI18n(locale);
  return { locale, t, chatI18n };
}

export function useExecutionConfigSeam(override: typeof useExecutionConfig | undefined): UseExecutionConfig {
  return (override ?? useExecutionConfig)();
}

export function useByokRuntimeSeam(
  override: typeof useByokRuntime | undefined,
  input: {
    executionConfig: ExecutionConfig;
    setExecutionConfig: React.Dispatch<React.SetStateAction<ExecutionConfig>>;
  },
): UseByokRuntime {
  return (override ?? useByokRuntime)(input);
}

export function useLocalCliSelectionSeam(
  override: typeof useLocalCliSelection | undefined,
  input: {
    executionConfig: ExecutionConfig;
    setExecutionConfig: React.Dispatch<React.SetStateAction<ExecutionConfig>>;
    configLoaded: boolean;
  },
): UseLocalCliSelection {
  return (override ?? useLocalCliSelection)(input);
}

export function useComposerCapabilitiesSeam(
  override: typeof useComposerCapabilities | undefined,
): UseComposerCapabilities {
  return (override ?? useComposerCapabilities)();
}

/** Keeps startup display state in the dock's hooks layer without rebuilding the transport. */
export function useAssistantTransportSeam(
  input: Parameters<typeof useAssistantTransport>[0],
  { useTransport = useAssistantTransport }: { useTransport?: typeof useAssistantTransport } = {},
): { transport: ReturnType<typeof createTovuAssistantTransport>; daemonStarting: boolean } {
  const [daemonStarting, setDaemonStarting] = useState(false);
  const transport = useTransport({ ...input, onDaemonStartingChange: setDaemonStarting });
  return { transport, daemonStarting };
}

export function useAttachmentUploaderSeam(
  override: typeof useAttachmentUploader | undefined,
): ReturnType<typeof createDaemonAttachmentUploader> {
  return (override ?? useAttachmentUploader)();
}

export function useAttachmentValidatorSeam(
  override: typeof useAttachmentValidator | undefined,
): ReturnType<typeof createChatAttachmentValidator> {
  return (override ?? useAttachmentValidator)();
}

export function useRuntimeAccessSeam(override: typeof useRuntimeAccess | undefined): ChatPaneRuntimeAccess {
  return (override ?? useRuntimeAccess)();
}

function useNoAgentsPlaceholder(): undefined {
  return undefined;
}

/** {@link useAgentsPlaceholder} reads the REAL runtime access's cache, so it only applies when that
 *  real access is in use: an injected `useRuntimeAccess` fake has no cache to seed from. */
export function useAgentsPlaceholderSeam(
  runtimeAccessOverride: typeof useRuntimeAccess | undefined,
): readonly ChatPaneAgent[] | undefined {
  return (runtimeAccessOverride ? useNoAgentsPlaceholder : useAgentsPlaceholder)();
}

export function useWorkingDirectoryAccessSeam(
  override: typeof useWorkingDirectoryAccess | undefined,
): ChatPaneWorkingDirectoryAccess | undefined {
  return (override ?? useWorkingDirectoryAccess)();
}

/**
 * Bridges `useFolderDrop`'s imperative `handleDropCapture` out of `AssistantDock` to the wrapping
 * `<aside onDropCapture={...}>` in `App.tsx` (SPEC-053) — `AssistantDock.tsx` itself holds "props
 * interface + JSX, and nothing else" per this file's own header, so the `useEffect` that publishes
 * the handler through a caller-supplied ref lives here, not there. Not a `use*Seam` wrapper like its
 * neighbors above: `useFolderDrop` is this feature's own new hook, not an existing DOM/IO hook this
 * component previously called bare, so there is no "real hook to default to when no override is
 * given" to resolve — `useComposerVoiceInput` (a bare call in `AssistantDock.tsx`, no seam) is the
 * closer precedent, not the eight/nine `use*Seam` hooks.
 *
 * @param input - {@link UseFolderDropInput} — passed straight through to `useFolderDrop`.
 * @param onReady - `AssistantDockProps.onFolderDropCaptureReady`. Invoked once per identity change
 *   of `handleDropCapture` (which itself only changes if `input.composerHandle` or `useFolderDrop`'s
 *   internal callbacks change — effectively once per mount). `undefined` when the caller (e.g. a
 *   test rendering `AssistantDock` directly) does not care to receive it.
 * @returns {@link UseFolderDrop} — `AssistantDock.tsx` renders `notice`/`dismiss`/`retry` from this
 *   directly; `handleDropCapture` is consumed only via `onReady` above, never by `AssistantDock.tsx`
 *   itself (nothing there needs to call it directly).
 * @complexity Time/space: O(1) beyond what `useFolderDrop` itself costs.
 */
export function useFolderDropBridge(
  input: UseFolderDropInput,
  onReady: ((handleDropCapture: (event: DragEvent<HTMLElement>) => void) => void) | undefined,
  proposeSkillFiles?: (files: readonly File[], paths?: readonly string[]) => Promise<void>,
  onSkillDropError?: (message: string) => void,
): UseFolderDrop {
  const folderDrop = useFolderDrop(input);
  const handleDropCapture = useCallback((event: DragEvent<HTMLElement>) => {
    if (proposeSkillFiles && captureSkillDrop({ event, proposeFiles: proposeSkillFiles, fallback: folderDrop.handleDropCapture }, onSkillDropError ? { onError: onSkillDropError } : {})) return;
    folderDrop.handleDropCapture(event);
  }, [proposeSkillFiles, folderDrop.handleDropCapture, onSkillDropError]);
  useEffect(() => { onReady?.(handleDropCapture); }, [onReady, handleDropCapture]);
  return { ...folderDrop, handleDropCapture };
}

import { useRef } from "react";
import { agentHandle, type AgentElementRole } from "@jini-ai/agentic";
import type { AdminWidgetType } from "../../lib/api";
import { useAdminLocale } from "../../hooks/use-admin-locale.hooks";
import { t as sharedComponentsT } from "../shared-components-i18n";
import { MediaPickerDialog } from "../MediaPickerDialog/MediaPickerDialog";
import { WidgetPickerDialog, WidgetSelectionDialog } from "../WidgetPickerDialog/WidgetPickerDialog";
import { useEmbedInsertControl, type EmbedEditor } from "./EmbedInsertControl.hooks";

/**
 * @file `EmbedInsertControl` — quick-and-dirty per the owner's explicit instruction (2026-08-05,
 * "skip formal spec/ADR process, just get it working"): one "Embed" trigger on `PostEditor.tsx`'s
 * `Toolbar`, replacing the previously-separate "Media" and "Insert widget" buttons.
 *
 * Key insight this control is built around: "Form" and "Menu" are not separate embedding
 * mechanisms — they are just the `contact-form` and `menu` widget TYPES
 * (`WidgetConfigFields.tsx`'s `WIDGET_TYPE_OPTIONS`). Before this control, reaching either one
 * meant opening "Insert widget" and then changing a type `<select>` — two clicks buried behind an
 * unrelated label. This control surfaces four top-level choices instead:
 *   - Media   — `MediaPickerDialog` + `editor.commands.insertMediaEmbed` (2026-09-11: switched from
 *               the legacy `image`-only `insertMediaRef` to the generic `media` node — see
 *               `lib/media-embed-extension.tsx`'s own file header for why).
 *   - Form    — shortcut straight to `WidgetPickerDialog` pinned to `widgetType: "contact-form"`.
 *   - Menu    — same shortcut pattern, pinned to `widgetType: "menu"`.
 *   - Widget… — the original full flow (type `<select>` then the same dialog) for the other three
 *               types, via the existing `WidgetAddControl` unchanged — kept because narrowing its
 *               hardcoded `WIDGET_TYPE_OPTIONS` would mean forking it, which is more code and more
 *               risk than just keeping all five types reachable there too.
 *
 * Deliberately composes `MediaPickerDialog`, `WidgetPickerDialog`, `WidgetAddControl`, and the
 * `useWidgetAddControl` hook exactly as exported — none of their internals change. Those are
 * shared with `RegionPlacementList`, `CollectionEntryEditor.tsx`, and `WidgetRegionEditor.tsx` (see
 * `widget-embed-extension.tsx` and `WidgetPickerDialog.tsx`'s own file headers), so their existing
 * exported shape has to stay intact for those other call sites.
 *
 * Desktop 0.1.13: Widget… now opens `WidgetSelectionDialog`, which reuses the
 * same picker forms inline inside one native modal. Type selection leaves the
 * toolbar entirely; the retained inline AddControl still serves region editors.
 *
 * No new design system: plain buttons, matches `PostEditor.tsx`'s `Toolbar` `.tb-btn` idiom.
 *
 * Moved here from `lib/` (was `lib/embed-insert-control.tsx`) per the owner's ruling on that
 * directory split: the file extension isn't the test, addressability is. A TipTap `Node` schema and
 * its node view stay in `lib/` because a node view is React only `ReactNodeViewRenderer` can mount,
 * 1:1 with its schema (see `media-image-extension.tsx`'s header) — this is an ordinary toolbar
 * component any screen can render, ordinary `components/` territory. State — the menu/dialog
 * visibility flags and the two pinned `useWidgetAddControl` instances — now lives in
 * `EmbedInsertControl.hooks.tsx`, split out the same way `ConfirmDialog`/`ConfirmDialog.hooks.tsx`
 * does in `@jini-ai/admin`; the `useEmbed` prop below lets a test render this JSX against a fake
 * without driving the real menu/dialog state machine or the real `useWidgetAddControl` fetches.
 */

export interface EmbedInsertControlProps {
  editor: EmbedEditor | null;
  /** Injectable seam for the menu/dialog visibility state and the two pinned Form/Menu
   *  `useWidgetAddControl` instances. Defaults to the real {@link useEmbedInsertControl}; a test
   *  can pass a fake here to exercise this component's rendering without the real state machine. */
  useEmbed?: typeof useEmbedInsertControl;
  /** This control's own base handle — see this file's "Agent handles" doc for the full scheme.
   *  Omit to leave every element below (including the dialogs this control opens) untagged. */
  agentHandle?: string;
}

/** The inline popover behind the "Embed" trigger: the four-choice menu (Media/Form/Menu/Widget…),
 * or the "Widget…" full flow once picked. Split out of `EmbedInsertControl` because this menu's
 * own two-state switch (`open`, then `widgetMode` once inside it) was one of the two independent
 * "wide branch set" halves of the original function — this half owns menu navigation, the other
 * (`WidgetShortcutPicker` below) owns the Form/Menu shortcut dialogs.
 *
 * `agentHandle` here is `EmbedInsertControl`'s own base, unmodified — the four menu-item actions
 * are literal choices this menu makes (never caller data), so they're appended directly as
 * `<base>-media`/`-form`/`-menu`/`-widget`, and `WidgetAddControl` gets `<base>-widget-control` as
 * ITS OWN base once "Widget…" is picked. */

/** `{...(base ? agentHandle(\`${base}-<suffix>\`, opts) : {})}` as a named helper — same
 *  complexity-budget rationale as `WidgetPickerDialog.tsx`'s identical helper: each of this menu's
 *  four conditional agent-handle spreads was its own nested branch in `EmbedMenu`'s own cognitive
 *  complexity count. `{}` (no markup) when `base` is unset, same as every inline occurrence it
 *  replaces. */
function handleSpread(base: string | undefined, suffix: string, opts: { role: AgentElementRole; label: string }): Record<string, unknown> {
  return base ? agentHandle({ handle: `${base}-${suffix}` }, opts) : {};
}

/** `base ? \`${base}-<suffix>\` : undefined` as a named helper — same rationale as
 *  {@link handleSpread}, for the sub-handle string handed to `WidgetAddControl` as its own base. */
function subHandle(base: string | undefined, suffix: string): string | undefined {
  return base ? `${base}-${suffix}` : undefined;
}

function EmbedMenu(props: {
  open: boolean;
  onPickMedia: () => void;
  onPickForm: () => void;
  onPickMenu: () => void;
  onPickGallery: () => void;
  onEnterWidgetMode: () => void;
  agentHandle?: string;
  t: (key: string) => string;
}) {
  const { open, onPickMedia, onPickForm, onPickMenu, onPickGallery, onEnterWidgetMode, agentHandle: base, t } = props;
  if (!open) return null;

  return (
    <span className="embed-insert-menu" role="menu" aria-label={t("Insert")}>
          <button
            type="button"
            role="menuitem"
            className="tb-btn"
            onClick={onPickMedia}
            {...handleSpread(base, "media", { role: "button", label: "Insert an existing media asset" })}
          >
            {t("Media")}
          </button>
          <button
            type="button"
            role="menuitem"
            className="tb-btn"
            onClick={onPickForm}
            {...handleSpread(base, "form", { role: "button", label: "Insert a contact form" })}
          >
            {t("Form")}
          </button>
          <button
            type="button"
            role="menuitem"
            className="tb-btn"
            onClick={onPickMenu}
            {...handleSpread(base, "menu", { role: "button", label: "Insert a menu" })}
          >
            {t("Menu")}
          </button>
          <button
            type="button"
            role="menuitem"
            className="tb-btn"
            onClick={onPickGallery}
            {...handleSpread(base, "gallery", { role: "button", label: "Insert a gallery" })}
          >
            {t("Gallery")}
          </button>
          <button type="button" role="menuitem" className="tb-btn"
            onClick={onEnterWidgetMode}
            {...handleSpread(base, "widget", { role: "button", label: "Insert any other widget type" })}
          >
            {t("Widget…")}
          </button>
    </span>
  );
}

/** The Form/Menu "shortcut" flow: the pinned-type `WidgetPickerDialog` plus its own error slot.
 * Identical shape for both `formControl` and `menuControl` (each a separate `useWidgetAddControl`
 * instance pinned to a `widgetType`, per `EmbedInsertControl.hooks.tsx`'s own header) — one
 * component used twice, rather than the same four-ternary pair written out inline twice.
 * `agentHandle` here is passed straight through as the opened `WidgetPickerDialog`'s own base. */
function WidgetShortcutPicker(props: {
  pickerType: AdminWidgetType | null;
  error: string | null;
  onUseExisting: (widgetInstanceId: string) => void;
  onCreateNew: (title: string, config: Record<string, unknown>) => void;
  onCancel: () => void;
  agentHandle?: string;
}) {
  const { pickerType, error, onUseExisting, onCreateNew, onCancel, agentHandle: base } = props;
  return (
    <>
      {pickerType ? (
        <WidgetPickerDialog
          widgetType={pickerType}
          onUseExisting={onUseExisting}
          onCreateNew={onCreateNew}
          onCancel={onCancel}
          agentHandle={base}
        />
      ) : null}
      {error ? (
        <span className="save-error" role="alert">
          {error}
        </span>
      ) : null}
    </>
  );
}

/**
 * The toolbar's single "Embed" trigger — opens a small inline menu of four choices (Media, Form,
 * Menu, Widget…) in place of the old separate Media/Insert-widget buttons.
 *
 * ## Agent handles
 *
 * Given `agentHandle="post-embed"` this publishes the trigger button directly under `<base>`
 * (single root action, no suffix — the "action omitted, element IS base" case), then forwards the
 * SAME base down to {@link EmbedMenu} for its four menu-item handles, `<base>-media-dialog` to the
 * media picker, and `<base>-form-dialog`/`<base>-menu-dialog` to the two
 * {@link WidgetShortcutPicker} instances as THEIR dialogs' own base. Omit `agentHandle` and none of
 * this control's own elements, or any dialog it opens, are tagged.
 */
export function EmbedInsertControl({ useEmbed = useEmbedInsertControl, agentHandle: base, ...props }: EmbedInsertControlProps) {
  const triggerRef = useRef<HTMLButtonElement>(null);
  const locale = useAdminLocale();
  const t = (key: string) => sharedComponentsT({ locale: locale, key: key });
  const { open, setOpen, widgetMode, setWidgetMode, mediaPicking, setMediaPicking, formControl, menuControl, galleryControl, insertWidget } =
    useEmbed(props.editor);

  if (!props.editor) return null;
  const editor = props.editor;

  return (
    <span className="embed-insert-control">
      <button
        ref={triggerRef}
        type="button"
        className="tb-btn"
        title={t("Insert media, a form, a menu, or a widget")}
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => {
          setOpen((o) => !o);
          setWidgetMode(false);
        }}
        {...(base ? agentHandle({ handle: base }, { role: "button", label: "Insert media, a form, a menu, or a widget" }) : {})}
      >
        {t("Embed")}
      </button>
      <EmbedMenu
        open={open}
        onPickMedia={() => {
          setMediaPicking(true);
          setOpen(false);
        }}
        onPickForm={() => {
          formControl.setPickerType("contact-form");
          setOpen(false);
        }}
        onPickMenu={() => {
          menuControl.setPickerType("menu");
          setOpen(false);
        }}
        onPickGallery={() => { galleryControl.setPickerType("gallery"); setOpen(false); }}
        onEnterWidgetMode={() => {
          // The menu item unmounts on open; give the native dialog a persistent
          // opener to restore instead of capturing the removed item's body fallback.
          triggerRef.current?.focus();
          setWidgetMode(true);
          setOpen(false);
        }}
        agentHandle={base}
        t={t}
      />

      {widgetMode ? (
        <WidgetSelectionDialog
          onResolved={(widgetInstanceId) => { insertWidget(widgetInstanceId); setWidgetMode(false); }}
          onCancel={() => setWidgetMode(false)}
          agentHandle={subHandle(base, "widget-control")}
        />
      ) : null}

      {mediaPicking ? (
        <MediaPickerDialog
          onSelect={(item) => {
            // 2026-09-11: inserts the generic `media` node (`insertMediaEmbed`), not the legacy
            // `image`-only ref (`insertMediaRef`) — see `lib/media-embed-extension.tsx`'s own file
            // header. A picked video asset now actually plays once saved.
            editor.commands.insertMediaEmbed({ assetId: item.id, transformName: "public", alt: item.alt || item.title });
            setMediaPicking(false);
          }}
          onCancel={() => setMediaPicking(false)}
          agentHandle={base ? `${base}-media-dialog` : undefined}
        />
      ) : null}

      <WidgetShortcutPicker
        pickerType={formControl.pickerType}
        error={formControl.error}
        onUseExisting={formControl.handleUseExisting}
        onCreateNew={formControl.handleCreateNew}
        onCancel={() => formControl.setPickerType(null)}
        agentHandle={base ? `${base}-form-dialog` : undefined}
      />
      <WidgetShortcutPicker pickerType={galleryControl.pickerType} error={galleryControl.error} onUseExisting={galleryControl.handleUseExisting} onCreateNew={galleryControl.handleCreateNew} onCancel={() => galleryControl.setPickerType(null)} agentHandle={subHandle(base, "gallery-dialog")} />
      <WidgetShortcutPicker
        pickerType={menuControl.pickerType}
        error={menuControl.error}
        onUseExisting={menuControl.handleUseExisting}
        onCreateNew={menuControl.handleCreateNew}
        onCancel={() => menuControl.setPickerType(null)}
        agentHandle={base ? `${base}-menu-dialog` : undefined}
      />
    </span>
  );
}

import { Dialog } from "@jini-ai/ui-kit/react";
import "../../styles/native-domain-dialogs.css";
import { agentHandle, type AgentElementRole } from "@jini-ai/agentic";
import type { AdminWidget, AdminWidgetType } from "../../lib/api";
import { interpolate } from "@jini-ai/ui/panel-kit";
import { widgetTypeLabel } from "@jini-ai/admin/widgets";
import { t as translateWidgets } from "../../features/widgets/widgets-i18n";
import { WidgetConfigFields, WIDGET_TYPE_OPTIONS } from "../WidgetConfigFields/WidgetConfigFields";
import { Select, type SelectOption } from "../Select/Select";
import { useWidgetAddControl, useWiredWidgetAddControl, useWiredWidgetPickerDialog } from "./WidgetPickerDialog.hooks";

/**
 * @file `WidgetPickerDialog` (`ui.spec.md` §2/§3.9/§4.8) — REQ-33's explicit reuse-vs-duplicate
 * modal. Two call sites: `RegionPlacementList.onAddWidgetRequest` and `WidgetEmbedNode`'s toolbar
 * insertion trigger (`widget-embed-extension.tsx`) — no third call site is authorized by the spec.
 *
 * Reuses Jini's native dialog owner, like `Collections.tsx`; no second focus trap, global
 * Escape listener or backdrop lifecycle is needed.
 *
 * `ui.spec.md` §5's rendering rule (followed literally per its own §8 disclosure against ADR-047
 * Amendment 5's "default to reuse" prose): when `existingInstances.length > 0`, BOTH "use existing"
 * and "create new" render as explicit, equally-weighted options with no pre-selected default —
 * implemented here as two always-visible sections, not tabs defaulting to one or the other.
 *
 * Split into this file (props + JSX for both `WidgetPickerDialog` and `WidgetAddControl`) and
 * `WidgetPickerDialog.hooks.tsx` (their state, effects, and the `useExistingInstances` fetch both
 * lean on), per the `@jini-ai/admin` `<Name>.tsx`/`<Name>.hooks.tsx` extraction pattern
 * (`ConfirmDialog.tsx`/`ConfirmDialog.hooks.tsx` in that package). Both components below carry the
 * same kind of injectable seam `ConfirmDialog`'s `useDialog` prop is (`useDialog` here, and
 * `useAddControl` on `WidgetAddControl`) — each does real IO (`useExistingInstances`'s fetch,
 * `useWidgetAddControl`'s `api.createWidget`) or DOM work (the deferred autofocus
 * effect), so a test can swap either for a fake without touching the network.
 *
 * ## Agent handles
 *
 * Given `agentHandle="place-widget"` this publishes:
 *
 * | element | handle | role |
 * |---|---|---|
 * | the "use existing" select (when shown) | `place-widget-existing-select` | via `Select`'s own scheme |
 * | the "Use this widget" submit | `place-widget-existing-submit` | `button` |
 * | the new-title field | `place-widget-new-title` | `field` |
 * | the config sub-form | `place-widget-new-config` | via `WidgetConfigFields`'s own scheme |
 * | the "Create and place" submit | `place-widget-new-submit` | `button` |
 * | the Cancel button | `place-widget-cancel` | `button` |
 *
 * Omit `agentHandle` and host controls receive no handles; shared Select and dialog controls
 * retain their own automatic handles.
 */

/** `{...(base ? agentHandle(\`${base}-<suffix>\`, opts) : {})}` as a named helper — same
 *  complexity-budget rationale as `Select.tsx`'s `resolveSelectTriggerHandleProps`: this dialog
 *  spreads a conditional agent-handle six times, and each was its own branch in
 *  `WidgetPickerDialog`'s own cyclomatic count. `{}` (no markup) when `base` is unset, same as
 *  every inline occurrence it replaces. */
function handleSpread(base: string | undefined, suffix: string, opts: { role: AgentElementRole; label: string }): Record<string, unknown> {
  return base ? agentHandle({ handle: `${base}-${suffix}` }, opts) : {};
}

/** `base ? \`${base}-<suffix>\` : undefined` as a named helper — the sub-handle string handed to a
 *  composed component (`Select`/`WidgetConfigFields`) rather than spread as `data-agent-*`
 *  attributes directly. Same rationale as {@link handleSpread}. */
function subHandle(base: string | undefined, suffix: string): string | undefined {
  return base ? `${base}-${suffix}` : undefined;
}

/** The existing-instance `Select`'s options as a named helper — the map's shape conversion, out
 *  of `WidgetPickerDialog`'s own scope: one `SelectOption` per loaded instance. It used to take
 *  `instances ?? []`; its only caller renders after `hasExisting`, so it now takes the loaded list. */
function toExistingOptions(instances: readonly AdminWidget[]): SelectOption[] {
  return instances.map((instance) => ({ value: instance.id, label: instance.title }));
}

export interface WidgetPickerDialogProps {
  widgetType: AdminWidgetType;
  onUseExisting: (widgetInstanceId: string) => void;
  onCreateNew: (title: string, config: Record<string, unknown>) => void;
  onCancel: () => void;
  /** Injectable seam for the dialog's fetch/form/Escape-listener/autofocus state. Defaults to the
   *  real {@link useWiredWidgetPickerDialog}; a test can pass a fake here to exercise this
   *  component's rendering without the real `listWidgets` fetch or `document`-level Escape
   *  listener. */
  useDialog?: typeof useWiredWidgetPickerDialog;
  /** This dialog's own base handle — see this file's "Agent handles" doc for the full scheme. Omit
   *  to leave it untagged. */
  agentHandle?: string;
  /** Embed the same forms in a parent native dialog, without a nested modal lifecycle. */
  presentation?: "dialog" | "inline";
}

export function WidgetPickerDialog({ useDialog = useWiredWidgetPickerDialog, agentHandle: base, ...props }: WidgetPickerDialogProps) {
  const {
    instances,
    loadError,
    selectedExistingId,
    setSelectedExistingId,
    newTitle,
    setNewTitle,
    newConfig,
    setNewConfig,
    error,
    existingSelectId,
    newTitleInputId,
    newTitleInputRef,
    typeLabel,
    hasExisting,
    submitUseExisting,
    submitCreateNew,
    t,
  } = useDialog(props);
  // Native modality keeps Tab inside; Jini also restores the opener when this dialog unmounts.

  const content = (
    <>
        <div className="widget-picker-body">
          {loadError ? <div className="notice error">{loadError}</div> : null}
          {error ? (
            <span className="save-error" role="alert">
              {error}
            </span>
          ) : null}

          {hasExisting ? (
            <form onSubmit={submitUseExisting} className="widget-picker-section">
              <h3>{t("Use existing")}</h3>
              <div className="field">
                <label className="field-label" htmlFor={existingSelectId}>
                  {interpolate({ template: t("Existing {typeLabel} widgets"), vars: { typeLabel } })}
                </label>
                <Select
                  id={existingSelectId}
                  value={selectedExistingId}
                  onChange={setSelectedExistingId}
                  // `hasExisting` is `(instances?.length ?? 0) > 0` (the hook), so this section only
                  // renders once `instances` is a loaded, non-empty list; the old `?? []` here could not fire.
                  options={toExistingOptions(instances!)}
                  placeholder={t("Choose a widget…")}
                  agentHandle={subHandle(base, "existing-select")}
                  t={t}
                />
              </div>
              <button type="submit" {...handleSpread(base, "existing-submit", { role: "button", label: "Use this widget" })}>
                {t("Use this widget")}
              </button>
            </form>
          ) : null}

          <form onSubmit={submitCreateNew} className="widget-picker-section">
            <h3>{t("Create new")}</h3>
            <div className="field">
              <label className="field-label" htmlFor={newTitleInputId}>
                {t("Title")}
              </label>
              <input
                id={newTitleInputId}
                ref={newTitleInputRef}
                value={newTitle}
                onChange={(e) => setNewTitle(e.target.value)}
                {...handleSpread(base, "new-title", { role: "field", label: "The new widget's title" })}
              />
            </div>
            <WidgetConfigFields
              widgetType={props.widgetType}
              config={newConfig}
              onChange={setNewConfig}
              agentHandle={subHandle(base, "new-config")}
              t={t}
            />
            <button type="submit" {...handleSpread(base, "new-submit", { role: "button", label: "Create and place this widget" })}>
              {t("Create and place")}
            </button>
          </form>
        </div>

        <div className="widget-picker-footer">
          <span className="editor-actions">
            <button
              type="button"
              className="btn-secondary"
              data-jini-autofocus=""
              onClick={props.onCancel}
              {...handleSpread(base, "cancel", { role: "button", label: "Close without placing a widget" })}
            >
              {t("Cancel")}
            </button>
          </span>
        </div>
    </>
  );
  if (props.presentation === "inline") return content;
  return (
    <Dialog open title={interpolate({ template: t("Place a {typeLabel} widget"), vars: { typeLabel } })}
      onClose={() => props.onCancel()} className="settings-dialog jini-domain-dialog widget-picker-dialog">
      {content}
    </Dialog>
  );
}

/**
 * The shared "choose a type, then open `WidgetPickerDialog`" two-step trigger (`ui.spec.md` §4.7's
 * `RegionPlacementList.onAddWidgetRequest` and §4.9's `WidgetEmbedNode.onInsertRequest` both name
 * this exact flow). One small control, reused by `WidgetRegionEditor.tsx`'s "+ Add widget" and the
 * TipTap toolbar's "Insert widget" button — avoids two independent implementations of the same
 * type-choice step.
 *
 * ## Agent handles
 *
 * Given `agentHandle="add-widget"` this publishes `<base>-type` (the type `Select`, via its own
 * scheme) and `<base>-open` (the trigger button); the nested `WidgetPickerDialog`, once opened,
 * gets `<base>-picker` as ITS OWN base — see that component's "Agent handles" doc for what that
 * expands to. Without `agentHandle`, only shared controls retain their automatic handles.
 */
export interface WidgetAddControlProps {
  triggerLabel: string;
  onResolved: (widgetInstanceId: string) => void | Promise<void>;
  /** Injectable seam for the two-step type-choice/create-or-reuse state. Defaults to the real
   *  {@link useWiredWidgetAddControl}; a test can pass a fake here to exercise this component's
   *  rendering without the real `api.createWidget` call. */
  useAddControl?: typeof useWiredWidgetAddControl;
  /** This control's own base handle — see this file's "Agent handles" doc above. Omit to leave it
   *  (and the dialog it opens) untagged. */
  agentHandle?: string;
  /** Open directly at this type when the control is mounted inside a picker dialog. */
  initialWidgetType?: AdminWidgetType;
}

/** The retained host catalog owns type labels for both inline controls and the native picker. */
function widgetTypeOptions({ locale }: { locale: string }, _optional: Record<string, never> = {}): SelectOption[] {
  return WIDGET_TYPE_OPTIONS.map((o) => ({ value: o.value, label: widgetTypeLabel({ widgetType: o.value, types: WIDGET_TYPE_OPTIONS }, { t: key => translateWidgets({ locale, key }) }) }));
}

export function WidgetAddControl({ useAddControl = useWiredWidgetAddControl, agentHandle: base, ...props }: WidgetAddControlProps) {
  const { pickerType, setPickerType, selectedType, setSelectedType, error, handleCreateNew, handleUseExisting, t, locale } =
    useAddControl(props);
  // `WIDGET_TYPE_OPTIONS`'s own labels are the English source strings; translate them through the
  // same `widgetTypeLabel` lookup `WidgetPickerDialog.hooks.tsx`'s `typeLabel` uses, so this type
  // picker and the dialog it opens agree on one widget type's display name per locale.
  const typeOptions = widgetTypeOptions({ locale });

  return (
    <span className="widget-add-control">
      <Select
        value={selectedType}
        onChange={(v) => setSelectedType(v as AdminWidgetType)}
        options={typeOptions}
        aria-label={t("Widget type")}
        agentHandle={base ? `${base}-type` : undefined}
        t={t}
      />
      <button
        type="button"
        onClick={() => setPickerType(selectedType)}
        {...(base ? agentHandle({ handle: `${base}-open` }, { role: "button", label: props.triggerLabel }) : {})}
      >
        {props.triggerLabel}
      </button>
      {error ? (
        <span className="save-error" role="alert">
          {error}
        </span>
      ) : null}
      {pickerType ? (
        <WidgetPickerDialog
          widgetType={pickerType}
          onUseExisting={handleUseExisting}
          onCreateNew={handleCreateNew}
          onCancel={() => setPickerType(null)}
          agentHandle={base ? `${base}-picker` : undefined}
        />
      ) : null}
    </span>
  );
}

export { useWidgetAddControl };

/** Full widget flow for Embed: one native dialog owns dismissal and focus, while
 * type changes remount only the forms so drafts and late fetches cannot cross types.
 * A settled create also refreshes the forms, exposing its new widget under Use existing
 * if placement fails, as the add-control owner's recovery message promises.
 * Creation and placement still go through the existing add-control owner. */
export function WidgetSelectionDialog({ useAddControl = useWiredWidgetAddControl, agentHandle: base, onCancel, ...props }: {
  onResolved: WidgetAddControlProps["onResolved"];
  onCancel: () => void;
  agentHandle?: string;
  useAddControl?: typeof useWiredWidgetAddControl;
  useDialog?: typeof useWiredWidgetPickerDialog;
}, _optional: Record<string, never> = {}) {
  const vm = useAddControl({ triggerLabel: "Insert widget", onResolved: props.onResolved, initialWidgetType: "text" });
  return (
    <Dialog open title={vm.t("Insert widget")} onClose={() => onCancel()}
      className="settings-dialog jini-domain-dialog widget-picker-dialog">
      <Select value={vm.selectedType}
        onChange={(value) => { vm.setSelectedType(value as AdminWidgetType); vm.setPickerType(value as AdminWidgetType); }}
        options={widgetTypeOptions({ locale: vm.locale })} aria-label={vm.t("Widget type")}
        agentHandle={subHandle(base, "type")} t={vm.t} />
      {vm.error ? <span className="save-error" role="alert">{vm.error}</span> : null}
      <WidgetPickerDialog key={`${vm.selectedType}:${vm.pickerType === null ? "settled" : "draft"}`}
        widgetType={vm.selectedType} presentation="inline"
        onUseExisting={vm.handleUseExisting} onCreateNew={vm.handleCreateNew} onCancel={onCancel}
        useDialog={props.useDialog}
        agentHandle={subHandle(base, "picker")} />
    </Dialog>
  );
}

import { useEffect, useState } from "react";

// The shared DEFAULT translator (`lib/api.ts`), not `../rules`'s screen-level override — that
// override's `FORBIDDEN` copy names "the AI assistant's settings" specifically, which would be a
// wrong claim here: this hook's `system.write` denial is about restarting the daemon process, not
// about a settings write. `rules.ts`'s own doc invites exactly this per-screen judgment call.
import { describeApiError } from "@/lib/api";
import { defaultAssistantDaemonRestartPort } from "./assistant-daemon-restart-dependencies.hooks";
import type { AssistantDaemonRestartPort } from "./assistant-daemon-restart-port.hooks";

/**
 * @file State for `AssistantDaemonRestart` — the "Admin AI Assistant" tab's manual recovery
 * control for the Local CLI daemon process (`AiAssistant.tsx`'s `AdminExecutionMode` sibling).
 *
 * Two independent pieces of state, matching the port's two operations: `restart` (the mutation)
 * and `status` (the read). `checkStatus()` runs once on mount, undelayed — so an operator who opens
 * this tab sees the current state without having to press anything first — and again after every
 * `restart()` settles, regardless of whether the restart was accepted or refused, because "is a
 * failure currently latched" is useful information either way. It is deliberately a single read,
 * not a poll loop: `restart()` returns as soon as a restart is INITIATED, never once the daemon is
 * healthy (there is no such signal anywhere in `daemon-supervisor.ts` — see that module's own
 * header), so a fixed number of automatic re-checks would only manufacture a false sense of
 * "waited long enough". `checkStatus` stays exposed on the controller so the operator can press
 * "Check status" again themselves, as many times as they want.
 *
 * The POST-RESTART re-check specifically waits `postRestartCheckDelayMs` first (source-control-ui
 * finding, 2026-08-17, live-verified): a freshly spawned process cannot plausibly be listening
 * within milliseconds of `restart()` resolving, so firing that one read immediately would almost
 * certainly just re-report the OLD state — directly under a line telling the operator to "check the
 * status below". This is still a single read, not a wait-until-ready loop: the delay changes WHEN
 * the one read happens, it does not retry toward a target state, so it does not compromise the "no
 * health signal exists, so we never claim one" principle above. The mount-time check and manual
 * `checkStatus()` presses are never delayed — only this one automatic follow-up is.
 */

export interface AssistantDaemonRestartDependencies {
  port: AssistantDaemonRestartPort;
  /** See this file's own header for why only the post-restart re-check is delayed. Defaults to `0`
   *  here (fast, deterministic tests) — `useWiredAssistantDaemonRestart` supplies the real-world
   *  value below. */
  postRestartCheckDelayMs?: number;
}

/** How long the real (wired) hook waits before its post-restart status re-check. Not a "the daemon
 *  is definitely up by now" claim — just long enough that an immediate re-check reporting the OLD
 *  state stops being the COMMON case. A few seconds is well within a Local CLI daemon's normal
 *  `tsx`-compile-and-listen boot time in dev; production's compiled boot is faster still. */
const REAL_POST_RESTART_CHECK_DELAY_MS = 2500;

export interface AssistantDaemonRestartController {
  restarting: boolean;
  /** The server's own answer to the last restart attempt — `null` before the first press. */
  restartResult: { ok: boolean; reason?: string } | null;
  /** Set only when `restart()` itself failed unexpectedly (network, 403, 500) — never for an
   *  ordinary `{ok: false, reason}` refusal, which lands in `restartResult` instead. */
  restartError: string | null;
  checkingStatus: boolean;
  /** `null` until the first status check settles; `true`/`false` thereafter. Never claims more
   *  than `/readyz` itself does — `false` means "no failure is currently latched", not "healthy". */
  knownFailed: boolean | null;
  statusError: string | null;
  restart(): Promise<void>;
  checkStatus(): Promise<void>;
}

export function useAssistantDaemonRestart({
  port,
  postRestartCheckDelayMs = 0,
}: AssistantDaemonRestartDependencies): AssistantDaemonRestartController {
  const [restarting, setRestarting] = useState(false);
  const [restartResult, setRestartResult] = useState<{ ok: boolean; reason?: string } | null>(null);
  const [restartError, setRestartError] = useState<string | null>(null);
  const [checkingStatus, setCheckingStatus] = useState(false);
  const [knownFailed, setKnownFailed] = useState<boolean | null>(null);
  const [statusError, setStatusError] = useState<string | null>(null);

  async function checkStatus() {
    setCheckingStatus(true);
    setStatusError(null);
    try {
      const readyz = await port.getReadyz();
      setKnownFailed(readyz.assistantDaemonKnownFailed === true);
    } catch (e) {
      setStatusError(describeApiError(e, "failed to check the assistant daemon's status"));
    } finally {
      setCheckingStatus(false);
    }
  }

  useEffect(() => {
    void checkStatus();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function restart() {
    setRestarting(true);
    setRestartError(null);
    try {
      const result = await port.restart();
      setRestartResult(result);
    } catch (e) {
      setRestartError(describeApiError(e, "failed to restart the assistant"));
    } finally {
      setRestarting(false);
    }
    // Outside the try/finally above: a failed status re-check must never overwrite
    // `restartResult`/`restartError`, which already answered the question this press was actually
    // about, and `restarting` must already read `false` for the whole delay — this follow-up read
    // is not part of "a restart is in flight" from the button's point of view.
    if (postRestartCheckDelayMs > 0) {
      await new Promise((resolve) => setTimeout(resolve, postRestartCheckDelayMs));
    }
    void checkStatus();
  }

  return { restarting, restartResult, restartError, checkingStatus, knownFailed, statusError, restart, checkStatus };
}

/**
 * Binds the real assistant-daemon restart client — see `assistant-daemon-restart-dependencies
 * .hooks.ts`. The zero-argument-dependencies half of the `useX(dependencies)` / `useWiredX()` pair,
 * so `AiAssistant.tsx` composes this and a test composes {@link useAssistantDaemonRestart} with
 * `createFakeAssistantDaemonRestartPort`.
 */
export function useWiredAssistantDaemonRestart(): AssistantDaemonRestartController {
  return useAssistantDaemonRestart({
    port: defaultAssistantDaemonRestartPort,
    postRestartCheckDelayMs: REAL_POST_RESTART_CHECK_DELAY_MS,
  });
}

import { PasskeySignIn } from '@jini-ai/user-management/react';
import { ownerPasskeySignInPort } from '../../lib/owner-passkey-api';
import { api } from '../../lib/api';
import { OwnerRecoverySignIn } from "./OwnerRecoverySignIn";
import { ErrorNotice } from "@jini-ai/ui/panel-kit";
import type { AdminUser } from "../../lib/api";
import { SecretInput } from "@/components/SecretInput/SecretInput";
import { useWiredAdminLocale } from "../../hooks/use-admin-locale.hooks";
import { t as translateAuth } from "./auth-i18n";
import { useWiredLogin } from "./hooks/use-login.hooks";

/**
 * @file The Login screen — markup only.
 *
 * State and the submit handler live in `hooks/use-login.hooks.ts`. Nothing here computes a value
 * (no derivations, no branchy formatting), so this feature has no `rules.ts`.
 */
export interface LoginProps {
  onLogin: (user: AdminUser) => void;
  /**
   * Dependency injection seam for tests — the same convention `Posts.tsx`'s `usePostsHook` and
   * `@jini-ai/ui`'s `useCustomSelect` use. Defaulted to the real hook, so production callers pass
   * nothing and behave exactly as before.
   */
  useLoginHook?: typeof useWiredLogin;
}

export function Login({ onLogin, useLoginHook = useWiredLogin }: LoginProps) {
  const { username, setUsername, password, setPassword, error, failure, busy, submit, mfa } = useLoginHook({ onLogin });
  const locale = useWiredAdminLocale();
  const t = (key: string): string => translateAuth({ locale: locale, key: key });

  return (
    <div className="login-screen">
      <form className="login-card" onSubmit={submit}>
        <h1>Tovu</h1>
        <p>{t("Sign in to your workspace")}</p>
        {mfa ? <label>
          {t("Authenticator code")}
          <input autoComplete="one-time-code" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} data-agent-private="" value={mfa.code} onChange={event => mfa.setCode(event.target.value)} autoFocus />
        </label> : <>
        <label>
          {t("Username")}
          <input autoComplete="username" value={username} onChange={(e) => setUsername(e.target.value)} autoFocus />
        </label>
        {/* Not wrapped in its <label> like Username: the eye toggle's name would join the input's. */}
        <div className="login-field">
          <label htmlFor="login-password">{t("Password")}</label>
          <SecretInput label={t("Password")} locale={locale} id="login-password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} />
        </div>
        </>}
        {failure ? <ErrorNotice failure={failure} t={t} className="login-error" /> : error ? <div className="login-error">{error}</div> : null}
        <button disabled={busy}>{busy ? t("Signing in…") : mfa ? t("Verify code") : t("Sign in")}</button>
        {mfa ? <button type="button" disabled={busy} onClick={mfa.cancel}>{t("Cancel")}</button> : null}
      </form>
      {mfa ? <PasskeySignIn port={ownerPasskeySignInPort} pendingToken={mfa.pendingToken} translate={t}
        onComplete={async () => { const result = await api.me(); onLogin(result.user); }} /> : null}
      <OwnerRecoverySignIn t={t} />
    </div>
  );
}

import { ErrorNotice, type Translate } from '@jini-ai/ui/panel-kit';
import type { UserFacingError } from '@jini-ai/core';
import { useState, type FormEvent } from 'react';
import { AGENT_PRIVATE_ATTRIBUTE } from '@jini-ai/agentic';
import { SecretInput } from '@/components/SecretInput/SecretInput';
import { ownerRecoveryPort, ownerRecoveryFailure, type OwnerRecoveryPort } from '../../lib/owner-recovery-api';

const identityTranslate: Translate = text => text;

/** Sign-in adapter for a lost owner password; code scope is selected only by the server.
 * @complexity O(1), one request on explicit submit (64-character code and bounded password), no polling.
 */
export function OwnerRecoverySignIn({ recover = ownerRecoveryPort.recover, t = identityTranslate }: { recover?: OwnerRecoveryPort['recover']; t?: Translate }) {
  const [code, setCode] = useState(''), [password, setPassword] = useState(''), [confirmation, setConfirmation] = useState('');
  const [failure, setFailure] = useState<UserFacingError | null>(null);
  const [busy, setBusy] = useState(false), [message, setMessage] = useState('');
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (password !== confirmation) { setMessage(t('The passwords do not match. Enter the same password in both fields. Details: owner-recovery-confirmation')); return; }
    setBusy(true); setMessage(''); setFailure(null);
    try {
      await recover({ code: code.trim(), password });
      setMessage(t('Owner password reset. Sign in with your new password. Authenticators, passkeys, sessions and recovery codes were invalidated.'));
    } catch (error) { setFailure(ownerRecoveryFailure({ error, message: 'The owner account could not be recovered.', action: 'Follow the server explanation. Ask the host operator for help if recovery is unavailable.', step: 'owner-recovery-redeem', t, secrets: [code.trim(), password] })); }
    finally { setCode(''); setPassword(''); setConfirmation(''); setBusy(false); }
  }
  return <details className="login-card"><summary>{t('Lost your owner password?')}</summary>
    <p>{t('Use a saved recovery code to reset your password and remove authenticators and passkeys. Without a code, ask the host operator to recover this site.')}</p>
    <form onSubmit={submit}>
      <label htmlFor="owner-recovery-code">{t('Recovery code')}</label>
      <SecretInput id="owner-recovery-code" label={t('Recovery code')} autoComplete="new-password" maxLength={64} value={code} onChange={event => setCode(event.target.value)} {...{ [AGENT_PRIVATE_ATTRIBUTE]: '' }} />
      <label htmlFor="owner-recovery-password">{t('New password')}</label>
      <SecretInput id="owner-recovery-password" label={t('New password')} autoComplete="new-password" maxLength={512} value={password} onChange={event => setPassword(event.target.value)} {...{ [AGENT_PRIVATE_ATTRIBUTE]: '' }} />
      <label htmlFor="owner-recovery-confirm">{t('Confirm new password')}</label>
      <SecretInput id="owner-recovery-confirm" label={t('Confirm new password')} autoComplete="new-password" maxLength={512} value={confirmation} onChange={event => setConfirmation(event.target.value)} {...{ [AGENT_PRIVATE_ATTRIBUTE]: '' }} />
      <button disabled={busy || !code || !password}>{t('Recover owner account')}</button>
    </form>
    {failure ? <ErrorNotice failure={failure} t={t} /> : null}
    {message ? <p className="notice" role="status">{message}</p> : null}
  </details>;
}

import { EditorContent, type Editor } from "@tiptap/react";
import { agentHandle } from "@jini-ai/agentic";
import { type ContentTypeFieldDef } from "../../lib/api";
import { buildAgentListHandles } from "@jini-ai/agentic";
import { WidgetEmbedInsertControl } from "../../lib/widget-embed-extension";
import { useWiredCollectionEntryEditor } from "./hooks/use-collection-entry-editor.hooks";
import { ServerLabel } from "@/components/status-labels";
import { TermPicker } from "../taxonomy/TermPicker";
import { useJsonFieldControl } from "./hooks/use-json-field-control.hooks";

/**
 * @file Collections' entry editor (design-spec.md §1.5/§1.6) — the
 * `/admin/collections/{typeKey}/{entryId|new}` route. Markup only: every piece of state and every
 * API call lives in `hooks/use-collection-entry-editor.hooks.ts` — see its header for why. The
 * Categories & Tags box is the shared `features/taxonomy/TermPicker.tsx`.
 *
 * Disclosed deviation from design-spec.md §1.5's "do not build a second TipTap wiring from
 * scratch — extract/reuse [PostEditor.tsx's]" direction: this dispatch's own scope discipline
 * lists `apps/admin/src/{App.tsx,nav.ts,lib/api.ts}` and new files under `sections/` as the touch
 * boundary — `PostEditor.tsx` is not in it, so extracting a shared component (which would require
 * editing `PostEditor.tsx` to consume it) was out of scope. This file duplicates a trimmed
 * subset of `PostEditor.tsx`'s TipTap wiring instead (StarterKit only — no image extension, no
 * drag-and-drop image handling, no formatting toolbar beyond what `StarterKit`'s own keyboard
 * shortcuts already provide) rather than a full second copy of the richer editor. A future pass
 * extracting both into a shared `components/RichTextEditor.tsx` is a reasonable follow-up, not
 * done here to respect the declared scope boundary.
 */

const EXT_SITE_PATH = ["ext", "site"] as const;

/** Reads `fieldsJson.ext.site.{name}` defensively — the JSON shape is server-validated, not
 * client-typed, so this never assumes a key is present. */
function readExtSiteField(fieldsJson: unknown, name: string): unknown {
  if (typeof fieldsJson !== "object" || fieldsJson === null) return undefined;
  const ext = (fieldsJson as Record<string, unknown>)[EXT_SITE_PATH[0]];
  if (typeof ext !== "object" || ext === null) return undefined;
  const site = (ext as Record<string, unknown>)[EXT_SITE_PATH[1]];
  if (typeof site !== "object" || site === null) return undefined;
  return (site as Record<string, unknown>)[name];
}

/** A `DynamicField` control's own props, once the field/value/onChange triple has been narrowed
 * down to the one input it renders.
 *
 * `agentHandleProps` is the same optional-pass-through shape this workstream's shared components
 * use: `DynamicField` computes the one handle each field gets (see `EntryFieldsSection`'s own
 * comment) and hands it down as ready-to-spread attribute props, so every one of the five controls
 * below stays a one-line function while still publishing its own handle on the actual `<input>` —
 * not a wrapper `<div>` around it, which `page.fill`/`page.select_option` cannot resolve into a
 * fillable control. */
interface FieldControlProps {
  inputId: string;
  value: unknown;
  onChange: (value: unknown) => void;
  agentHandleProps: ReturnType<typeof agentHandle>;
  /** This field's own schema name — only `JsonFieldControl` (M2) uses it, to key its parse-validity
   *  report; every other control ignores it. */
  fieldName: string;
  /** M2: forwarded straight through to `JsonFieldControl` — see that control's own comment. */
  setFieldValidity: (fieldName: string, valid: boolean) => void;
}

function TextFieldControl({ inputId, value, onChange, agentHandleProps }: FieldControlProps) {
  return (
    <input
      id={inputId}
      value={typeof value === "string" ? value : ""}
      onChange={(e) => onChange(e.target.value)}
      {...agentHandleProps}
    />
  );
}

function IntegerFieldControl({ inputId, value, onChange, agentHandleProps }: FieldControlProps) {
  return (
    <input
      id={inputId}
      type="number"
      step="1"
      value={typeof value === "number" ? value : ""}
      onChange={(e) => onChange(e.target.value === "" ? undefined : Number(e.target.value))}
      {...agentHandleProps}
    />
  );
}

function RealFieldControl({ inputId, value, onChange, agentHandleProps }: FieldControlProps) {
  return (
    <input
      id={inputId}
      type="number"
      value={typeof value === "number" ? value : ""}
      onChange={(e) => onChange(e.target.value === "" ? undefined : Number(e.target.value))}
      {...agentHandleProps}
    />
  );
}

function BooleanFieldControl({ inputId, value, onChange, agentHandleProps }: FieldControlProps) {
  return (
    <input
      id={inputId}
      type="checkbox"
      checked={value === true}
      onChange={(e) => onChange(e.target.checked)}
      {...agentHandleProps}
    />
  );
}

function DatetimeFieldControl({ inputId, value, onChange, agentHandleProps }: FieldControlProps) {
  return (
    <input
      id={inputId}
      type="datetime-local"
      value={typeof value === "string" ? value : ""}
      onChange={(e) => onChange(e.target.value)}
      {...agentHandleProps}
    />
  );
}

/** `json`-kind field control: a raw-JSON textarea backed by `useJsonFieldControl` (state/parsing
 * lives there, not here — see that hook's own header). `aria-invalid` flags an unparseable buffer
 * without inventing new copy for it; the last value that DID parse is what stays in `extFields`
 * and what a save sends, regardless of how the buffer currently looks. */
function JsonFieldControl({ inputId, value, onChange, agentHandleProps, fieldName, setFieldValidity }: FieldControlProps) {
  const { text, parseError, handleTextChange } = useJsonFieldControl({ value, onChange, fieldName, setFieldValidity });
  return (
    <textarea
      id={inputId}
      value={text}
      aria-invalid={parseError}
      onChange={(e) => handleTextChange(e.target.value)}
      {...agentHandleProps}
    />
  );
}

/** One control per `ContentTypeFieldDef.kind` (design-spec.md §1.5). A `Record` keyed by the
 * closed `kind` union rather than a switch/ternary chain — same exhaustiveness guarantee (add a
 * kind to the union and `tsc` rejects this object until a control is added for it), but as a flat
 * lookup instead of nested conditionals.
 *
 * `relation` deliberately reuses `TextFieldControl` rather than a same-shaped duplicate: it stores
 * a foreign entity id and shares `text`'s storage class server-side (`@jini-ai/cms`'s
 * `content-types/types.ts`), so a plain text input is a correct control for it, not a fallback. */
const FIELD_CONTROLS: Record<ContentTypeFieldDef["kind"], (props: FieldControlProps) => React.JSX.Element> = {
  text: TextFieldControl,
  integer: IntegerFieldControl,
  real: RealFieldControl,
  boolean: BooleanFieldControl,
  datetime: DatetimeFieldControl,
  relation: TextFieldControl,
  json: JsonFieldControl,
};

function DynamicField(props: {
  field: ContentTypeFieldDef;
  value: unknown;
  onChange: (value: unknown) => void;
  /** This field's own distinct handle base — see `EntryFieldsSection`'s own comment for why it's
   *  computed once, up there (via `buildAgentListHandles`), rather than per-field here. */
  agentBase: string;
  /** M2: forwarded to `Control` as `setFieldValidity` — only `JsonFieldControl` uses it. */
  setFieldValidity: (fieldName: string, valid: boolean) => void;
}) {
  const { field, value, onChange, agentBase, setFieldValidity } = props;
  const inputId = `entry-field-${field.name}`;
  const Control = FIELD_CONTROLS[field.kind];

  return (
    <div className="collections-dynamic-field">
      <label htmlFor={inputId}>
        {field.name}
        {field.required ? " *" : ""}
      </label>
      <Control
        inputId={inputId}
        value={value}
        onChange={onChange}
        agentHandleProps={agentHandle({ handle: agentBase }, {
          role: field.kind === "boolean" ? "checkbox" : "field",
          label: `This content type's "${field.name}" field${field.required ? " (required)" : ""}`,
        })}
        fieldName={field.name}
        setFieldValidity={setFieldValidity}
      />
    </div>
  );
}

/** The page-header action cluster: back link, save/error status, and the status-dependent
 * Publish/Unpublish/Save button set. Split out of `CollectionEntryEditor` because this cluster
 * alone carried most of that function's branching — the entry's lifecycle status governs which
 * buttons and status pill are showing at once. */
/** Publish/Unpublish/Save — split out of `EntryPageActions` because the status-dependent branch
 * pairs (which lifecycle button shows, which class the Save button gets) alone pushed that
 * function's branch count over the ceiling; this trio is one coherent unit of "buttons driven by
 * publish state" on its own. */
function EntryLifecycleButtons(props: {
  entry: { status: string } | null | undefined;
  saving: boolean;
  /** True while save OR a lifecycle toggle is in flight (H2) — disables all three buttons, since
   *  Publish now runs a save leg before its lifecycle leg and either one being in flight must
   *  block a second click. `saving` alone stays the Save button's own LABEL source (unchanged). */
  busy: boolean;
  onToggleLifecycle: (op: "publish" | "unpublish") => void;
  onSave: () => void;
  t: (key: string) => string;
}) {
  const { entry, saving, busy, onToggleLifecycle, onSave, t } = props;
  const isPublished = entry?.status === "published";

  return (
    <>
      {entry && !isPublished ? (
        <button
          type="button"
          onClick={() => onToggleLifecycle("publish")}
          disabled={busy}
          {...agentHandle({ handle: "entry-publish" }, {
            role: "button",
            label: "Publish this entry immediately, saving its current title, fields and body",
          })}
        >
          {t("Publish")}
        </button>
      ) : null}
      {/* Reversible-but-access-affecting (drops the entry off the site; still editable here,
          still re-publishable) — `.btn-warning`, matching `Posts.tsx`/`Pages.tsx` RowMenu's
          own Disable, not `.btn-danger`, which stays reserved for the genuinely destructive
          trash action. */}
      {entry && isPublished ? (
        <button
          type="button"
          className="btn-warning"
          onClick={() => onToggleLifecycle("unpublish")}
          disabled={busy}
          {...agentHandle({ handle: "entry-unpublish" }, {
            role: "button",
            label: "Unpublish this entry — removes it from the live site without deleting it",
          })}
        >
          {t("Unpublish")}
        </button>
      ) : null}
      {/* Secondary while Publish is also showing (draft entries) so the two don't compete for
          primary weight — mirrors `PostEditor.tsx`'s identical Save/Publish pairing exactly.
          Once published, Publish is gone and Save is this screen's one remaining primary
          action, so it goes back to bare/primary. */}
      <button
        type="button"
        className={entry && !isPublished ? "btn-secondary" : undefined}
        onClick={onSave}
        disabled={busy}
        {...agentHandle({ handle: "entry-save" }, { role: "button", label: "Save this entry's title, slug, fields and body" })}
      >
        {saving ? t("Saving…") : t("Save")}
      </button>
    </>
  );
}

function EntryPageActions(props: {
  contentTypeKey: string;
  contentTypeLabel: string;
  entry: { status: string } | null | undefined;
  message: string | null;
  error: string | null;
  saving: boolean;
  busy: boolean;
  onToggleLifecycle: (op: "publish" | "unpublish") => void;
  onSave: () => void;
  t: (key: string) => string;
}) {
  const { contentTypeKey, contentTypeLabel, entry, message, error, saving, busy, onToggleLifecycle, onSave, t } = props;

  return (
    <div className="page-actions">
      {/* Plain `<a className="btn-secondary">`, not a `<button>` nested inside an `<a>` (invalid
          HTML, undefined activation behaviour) — same `a.btn-*` mechanism `Dashboard.tsx`'s
          "View site ↗" already uses. */}
      <a
        className="btn-secondary"
        href={`/admin/collections/${contentTypeKey}`}
        {...agentHandle({ handle: "entry-back" }, { role: "link", label: "Back to this content type's list of entries" })}
      >
        ← {contentTypeLabel}
      </a>
      {message ? <span className="save-ok">{message}</span> : null}
      {error ? <span className="save-error">{error}</span> : null}
      {entry ? <span className={`status status-${entry.status}`}><ServerLabel value={entry.status} /></span> : null}
      <EntryLifecycleButtons
        entry={entry}
        saving={saving}
        busy={busy}
        onToggleLifecycle={onToggleLifecycle}
        onSave={onSave}
        t={t}
      />
    </div>
  );
}

/** The `/{slug}` row under the title: an existing entry's slug is immutable (plain text), a new
 * entry's slug is an editable field. Split out of `CollectionEntryEditor` alongside the fields
 * section below — both are self-contained "does this thing exist yet" branches that don't need
 * anything else in the parent's scope. */
function EntrySlugField(props: {
  entry: { slug: string } | null | undefined;
  slug: string;
  onSlugChange: (value: string) => void;
  t: (key: string) => string;
}) {
  const { entry, slug, onSlugChange, t } = props;
  return (
    <div className="editor-slug">
      /{" "}
      {entry ? (
        <span>{entry.slug}</span>
      ) : (
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Entry slug")}</span>
          <input
            value={slug}
            onChange={(e) => onSlugChange(e.target.value)}
            placeholder="entry-slug"
            {...agentHandle({ handle: "entry-slug" }, {
              role: "field",
              label: "This entry's URL slug — only editable while creating a new entry",
            })}
          />
        </label>
      )}
    </div>
  );
}

/** The dynamic-fields section (design-spec.md §1.5) — hidden entirely when the content type
 * defines no custom fields. */
function EntryFieldsSection(props: {
  fields: ContentTypeFieldDef[];
  entry: { fieldsJson?: unknown } | null | undefined;
  extFields: Record<string, unknown>;
  onFieldChange: (name: string, value: unknown) => void;
  /** M2: forwarded to each `DynamicField`. */
  setFieldValidity: (fieldName: string, valid: boolean) => void;
  t: (key: string) => string;
}) {
  const { fields, entry, extFields, onFieldChange, setFieldValidity, t } = props;
  if (fields.length === 0) return null;

  // Field names are this content type's own schema keys, unique by construction (Collections.tsx's
  // `EditFieldsDialog` is where they're defined) — `buildAgentListHandles` still slugifies+dedupes
  // rather than assuming that, the same defensive stance every other list handle in this workstream
  // takes (a schema author is still free to pick a name that isn't already handle-shaped).
  const fieldHandles = buildAgentListHandles({ prefix: "entry-field", ids: fields.map((field) => field.name) }
  );

  return (
    <div className="collections-dynamic-fields">
      <h3>{t("Fields")}</h3>
      {fields.map((field, index) => (
        <DynamicField
          key={field.name}
          field={field}
          value={extFields[field.name] ?? readExtSiteField(entry?.fieldsJson, field.name)}
          onChange={(value) => onFieldChange(field.name, value)}
          agentBase={fieldHandles[index]}
          setFieldValidity={setFieldValidity}
        />
      ))}
    </div>
  );
}

export interface CollectionEntryEditorProps {
  contentTypeKey: string;
  entryId: string | null;
  /** Dependency injection seam for tests — the same convention `@jini-ai/ui`'s `CustomSelect` uses
   *  for `useCustomSelect`. Defaulted to the real hook, so production callers (`panels.tsx`) pass
   *  only `contentTypeKey`/`entryId` and behave exactly as before. */
  useCollectionEntryEditorHook?: typeof useWiredCollectionEntryEditor;
}

/**
 * Resolves the injected hook prop to the real wired hook when a caller passes none. Pulled into its
 * own function, the same `??`-avoidance idiom `MenuEditor.tsx`'s `orEmpty` uses (see that function's
 * own doc): `CollectionEntryEditor` was already sitting at the 9/9 complexity ceiling, and ESLint's
 * cyclomatic-complexity rule counts a default value or `??` inside a function's OWN body as one of
 * that function's own branches — a call out to a separately-scoped resolver does not.
 */
function resolveCollectionEntryEditorHook(
  override: typeof useWiredCollectionEntryEditor | undefined
): typeof useWiredCollectionEntryEditor {
  return override ?? useWiredCollectionEntryEditor;
}

export function CollectionEntryEditor(props: CollectionEntryEditorProps) {
  const useCollectionEntryEditorHook = resolveCollectionEntryEditorHook(props.useCollectionEntryEditorHook);
  const {
    contentType,
    entry,
    title,
    setTitle,
    slug,
    setSlug,
    extFields,
    setExtFields,
    message,
    error,
    loadError,
    loaded,
    saving,
    busy,
    editor,
    save,
    toggleLifecycle,
    setFieldValidity,
    t,
  } = useCollectionEntryEditorHook({ contentTypeKey: props.contentTypeKey, entryId: props.entryId });

  if (loadError) return <div className="notice error">{loadError}</div>;
  if (!loaded || contentType === undefined) return <div className="notice">{t("Loading entry…")}</div>;
  if (!contentType) return <div className="notice error">{t('Unknown content type "{contentTypeKey}".').replace("{contentTypeKey}", props.contentTypeKey)}</div>;
  if (props.entryId && !entry) return <div className="notice error">{t("Entry not found.")}</div>;

  return (
    <div className="page">
      <div
        className="page-header"
        {...agentHandle({ handle: "entry-header" }, {
          role: "region",
          label: "Entry editor header — back link, save status, publish state and the Save button",
        })}
      >
        <div className="page-header-text">
          <p className="page-kicker">{t("Content")}</p>
          <h1 className="page-title">
            {t(entry ? "Edit {label} entry" : "New {label} entry").replace("{label}", contentType.label)}
          </h1>
          <p className="page-description">{t("Update this entry's title, fields, and body.")}</p>
        </div>
        <EntryPageActions
          contentTypeKey={props.contentTypeKey}
          contentTypeLabel={contentType.label}
          entry={entry}
          message={message}
          error={error}
          saving={saving}
          busy={busy}
          onToggleLifecycle={toggleLifecycle}
          onSave={save}
          t={t}
        />
      </div>

      {/* Audit finding: placeholder-only, no `<label>` — same fix as `PostEditor.tsx`'s title/slug
          (see `styles/editor.css`'s `.a11y-label-wrap` comment). The slug field's label is only
          rendered in the `!entry` (create) branch, matching that branch's own `<input>`. */}
      <label className="a11y-label-wrap">
        <span className="visually-hidden">{t("Entry title")}</span>
        <input
          className="editor-title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder={t("Entry title")}
          {...agentHandle({ handle: "entry-title" }, { role: "field", label: "This entry's title" })}
        />
      </label>
      <EntrySlugField entry={entry} slug={slug} onSlugChange={setSlug} t={t} />

      <div
        className="editor-shell"
        {...agentHandle({ handle: "entry-editor-shell" }, { role: "region", label: "Formatting toolbar and the entry body editor" })}
      >
        <div className="editor-toolbar" role="toolbar" aria-label={t("Formatting")}>
          <div className="grp">
            <WidgetEmbedInsertControl editor={editor} agentHandle="entry-insert-widget" />
          </div>
        </div>
        {/* `role: "field"`, not `region`: this is a TipTap `contenteditable`, which the page driver
            treats as a fillable rich-text surface (see its `isEditableRegion`) — same convention
            `PostEditor.tsx`'s own `post-body` handle documents. */}
        <div
          className="editor-body"
          {...agentHandle({ handle: "entry-body" }, { role: "field", label: "This entry's rich-text body content" })}
        >
          <EditorContent editor={editor as Editor} />
        </div>
      </div>

      <EntryFieldsSection
        fields={contentType.fields}
        entry={entry}
        extFields={extFields}
        onFieldChange={(name, value) => setExtFields((current) => ({ ...current, [name]: value }))}
        setFieldValidity={setFieldValidity}
        t={t}
      />

      {entry ? (
        <TermPicker contentType={props.contentTypeKey} contentId={entry.id} />
      ) : null}
    </div>
  );
}

import { useRef, useState } from "react";

import { type AdminContentType } from "@/lib/api";
import { useFetchMutation } from "@jini-ai/ui/fetch-query";
import {
  addDraftField,
  describeEditFieldsError,
  draftFieldsFromContentType,
  KEYS,
  removeDraftField,
  stripDraftFieldRowIds,
  updateDraftField,
  validateEditFieldsDraft,
  type DraftField,
} from "../rules";
import { useAdminLocale } from "@/hooks/use-admin-locale.hooks";
import { t as translate } from "../collections-i18n";
import { defaultEditFieldsDialogPort } from "./edit-fields-dialog-dependencies.hooks";
import type { EditFieldsDialogPort } from "./edit-fields-dialog-port.hooks";
import type { Translate } from "@jini-ai/ui/panel-kit";

/**
 * @file `EditFieldsDialog`'s own state and submit action (SPEC-037 REQ-05 — post-creation
 * field-schema editing), so the dialog in `Collections.tsx` is only markup.
 *
 * Extracted verbatim — same state, same validation, same `409`-vs-generic error split (now
 * `describeEditFieldsError` in `rules.ts`). Draft-field list editing shares `rules.ts` helpers
 * with `use-new-content-type-dialog.hooks.ts`, including the row-id counter — see that module's
 * header for why it has to stay one shared instance.
 *
 * Naming follows `hooks/use-settings-slice.hooks.ts`: `use-<thing>.hooks.ts`. Feature-local because
 * nothing outside `features/collections` needs it.
 *
 * `port` is injected — see `edit-fields-dialog-port.hooks.ts` — rather than importing `lib/api`
 * directly, so a test can describe the submit outcome against `createFakeEditFieldsDialogPort`
 * instead of stubbing global `fetch`. `useWiredEditFieldsDialog` below is the pair `Collections.tsx`
 * actually mounts. No `locale`/`useAdminLocale` here — `describeEditFieldsError` never resolves a
 * translated string (unlike `use-new-content-type-dialog.hooks.ts`'s `t(locale, ...)` fallback).
 *
 * `@jini-ai/ui/fetch-query` migration (2026-08-12): `updateContentTypeFields` is a `useFetchMutation` that
 * `invalidates: [KEYS.list]` — a field-schema change affects the content-type list AND every entries
 * list/entry editor nested under it (`rules.ts`'s `KEYS` doc), matching what `props.onSaved`'s caller
 * (`Collections.tsx`, via `load`) used to refresh by hand.
 */

export interface EditFieldsDialogController {
  fields: DraftField[];
  updateField: (rowId: number, patch: Partial<DraftField>) => void;
  removeField: (rowId: number) => void;
  addField: () => void;
  error: string | null;
  saving: boolean;
  submit: (e: React.FormEvent) => void;
  /** Backdrop/Cancel/Escape all route here instead of `props.onCancel` directly — a no-op while
   * `updateContentTypeFields` is in flight, so those dismiss paths can't unmount the dialog out
   * from under its own pending write (H4). */
  cancel: () => void;
}

export function useEditFieldsDialog(
  props: {
    contentType: AdminContentType;
    onSaved: () => void;
    onCancel: () => void;
  },
  port: EditFieldsDialogPort,
  options: { t?: Translate } = {},
): EditFieldsDialogController {
  const t = options.t ?? ((key: string) => key);
  const [fields, setFields] = useState<DraftField[]>(() => draftFieldsFromContentType(props.contentType.fields));
  const [validationError, setValidationError] = useState<string | null>(null);
  const inFlightRef = useRef(false);

  function cancel() {
    if (inFlightRef.current) return;
    props.onCancel();
  }

  const updateFieldsMutation = useFetchMutation({
    run: ({ input }: { input: { key: string; fields: ReturnType<typeof stripDraftFieldRowIds>; expectedVersion: number } }) =>
      port.updateContentTypeFields(input),
  }, {
    invalidates: [KEYS.list],
  });

  function updateField(rowId: number, patch: Partial<DraftField>) {
    setFields((current) => updateDraftField(current, rowId, patch));
  }

  function removeField(rowId: number) {
    setFields((current) => removeDraftField(current, rowId));
  }

  function addField() {
    setFields((current) => addDraftField(current));
  }

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setValidationError(null);

    const draftError = validateEditFieldsDraft(fields, t);
    if (draftError) {
      setValidationError(draftError);
      return;
    }

    inFlightRef.current = true;
    try {
      await updateFieldsMutation.mutate({ input: {
        key: props.contentType.key,
        fields: stripDraftFieldRowIds(fields),
        expectedVersion: props.contentType.version,
      } });
      props.onSaved();
    } catch {
      // already surfaced through updateFieldsMutation.error -> error below
    } finally {
      inFlightRef.current = false;
    }
  }

  const saving = updateFieldsMutation.status === "pending";
  const error = validationError ?? (updateFieldsMutation.error ? describeEditFieldsError(updateFieldsMutation.error, t) : null);

  return { fields, updateField, removeField, addField, error, saving, submit, cancel };
}

/**
 * Binds the real `/api/.../content-types/{key}/fields` client — see
 * `edit-fields-dialog-dependencies.hooks.ts`.
 *
 * The zero-argument-port half of the `useX(dependencies)` / `useWiredX()` pair, so `Collections.tsx`
 * composes this and a test composes {@link useEditFieldsDialog} with
 * `createFakeEditFieldsDialogPort`.
 */
export function useWiredEditFieldsDialog(props: {
  contentType: AdminContentType;
  onSaved: () => void;
  onCancel: () => void;
}): EditFieldsDialogController {
  const locale = useAdminLocale();
  const t = (key: string): string => translate({ locale: locale, key: key });
  return useEditFieldsDialog(props, defaultEditFieldsDialogPort, { t });
}

import { useRef, useState } from "react";

import { describeApiError } from "@/lib/api";
import { useFetchMutation } from "@jini-ai/ui/fetch-query";
import {
  addDraftField,
  emptyField,
  KEYS,
  removeDraftField,
  stripDraftFieldRowIds,
  updateDraftField,
  validateNewContentTypeDraft,
  type DraftField,
} from "../rules";
import { useAdminLocale } from "@/hooks/use-admin-locale.hooks";
import { t } from "../collections-i18n";
import { defaultNewContentTypeDialogPort } from "./new-content-type-dialog-dependencies.hooks";
import type { NewContentTypeDialogPort } from "./new-content-type-dialog-port.hooks";

/**
 * @file `NewContentTypeDialog`'s own state and submit action (design-spec.md §1.3), so the dialog
 * in `Collections.tsx` is only markup.
 *
 * Extracted verbatim — same state, same validation order, same error strings. Draft-field list
 * editing (`updateField`/`removeField`/`addField`) and the row-id counter it depends on now live in
 * `rules.ts`, shared with `use-edit-fields-dialog.hooks.ts` — see that file's header for why the
 * counter has to stay a single shared instance rather than one per hook.
 *
 * Naming follows `hooks/use-settings-slice.hooks.ts`: `use-<thing>.hooks.ts`. Feature-local because
 * nothing outside `features/collections` needs it.
 *
 * `port`/`locale` are injected — see `new-content-type-dialog-port.hooks.ts` — rather than reaching
 * `lib/api`/`useAdminLocale()` directly, so a test can describe the submit outcome against
 * `createFakeNewContentTypeDialogPort` instead of stubbing global `fetch`.
 * `useWiredNewContentTypeDialog` below is the pair `Collections.tsx` actually mounts.
 *
 * `@jini-ai/ui/fetch-query` migration (2026-08-12): `createContentType` is a `useFetchMutation` that
 * `invalidates: [KEYS.list]` instead of `props.onCreated`'s caller (`Collections.tsx`) reloading by
 * hand.
 */

export interface NewContentTypeDialogController {
  label: string;
  setLabel: (value: string) => void;
  key: string;
  setKey: (value: string) => void;
  fields: DraftField[];
  updateField: (rowId: number, patch: Partial<DraftField>) => void;
  removeField: (rowId: number) => void;
  addField: () => void;
  error: string | null;
  saving: boolean;
  submit: (e: React.FormEvent) => void;
  /** Backdrop/Cancel/Escape all route here instead of `props.onCancel` directly — a no-op while
   * `createContentType` is in flight, so those dismiss paths can't unmount the dialog out from
   * under its own pending write (H4). */
  cancel: () => void;
}

export interface NewContentTypeDialogDependencies {
  port: NewContentTypeDialogPort;
  locale: string;
}

export function useNewContentTypeDialog(
  props: {
    onCreated: () => void;
    onCancel: () => void;
  },
  deps: NewContentTypeDialogDependencies
): NewContentTypeDialogController {
  const { port, locale } = deps;
  const [label, setLabel] = useState("");
  const [key, setKey] = useState("");
  const [fields, setFields] = useState<DraftField[]>([emptyField()]);
  const [validationError, setValidationError] = useState<string | null>(null);
  const inFlightRef = useRef(false);

  function cancel() {
    if (inFlightRef.current) return;
    props.onCancel();
  }

  const createMutation = useFetchMutation({
    run: ({ input }: { input: { key: string; label: string; fields: ReturnType<typeof stripDraftFieldRowIds> } }) =>
      port.createContentType(input),
  }, {
    invalidates: [KEYS.list],
  });

  function updateField(rowId: number, patch: Partial<DraftField>) {
    setFields((current) => updateDraftField(current, rowId, patch));
  }

  function removeField(rowId: number) {
    setFields((current) => removeDraftField(current, rowId));
  }

  function addField() {
    setFields((current) => addDraftField(current));
  }

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setValidationError(null);

    const draftError = validateNewContentTypeDraft({ key, label, fields }, locale);
    if (draftError) {
      setValidationError(draftError);
      return;
    }

    inFlightRef.current = true;
    try {
      await createMutation.mutate({ input: {
        key: key.trim(),
        label: label.trim(),
        fields: stripDraftFieldRowIds(fields),
      } });
      props.onCreated();
    } catch {
      // already surfaced through createMutation.error -> error below
    } finally {
      inFlightRef.current = false;
    }
  }

  const saving = createMutation.status === "pending";
  const error = validationError ?? (createMutation.error ? describeApiError(createMutation.error, t({ locale: locale, key: "Failed to create content type" })) : null);

  return { label, setLabel, key, setKey, fields, updateField, removeField, addField, error, saving, submit, cancel };
}

/**
 * Binds the real `/api/.../content-types` client and the resolved `useAdminLocale()` value — see
 * `new-content-type-dialog-dependencies.hooks.ts`. The zero-argument-deps half of the
 * `useX(dependencies)` / `useWiredX()` pair, so `Collections.tsx` composes this and a test composes
 * {@link useNewContentTypeDialog} with `createFakeNewContentTypeDialogPort`.
 */
export function useWiredNewContentTypeDialog(props: {
  onCreated: () => void;
  onCancel: () => void;
}): NewContentTypeDialogController {
  const locale = useAdminLocale();
  return useNewContentTypeDialog(props, { port: defaultNewContentTypeDialogPort, locale });
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { ConsentFieldProblem, ConsentSettingsView } from '@jini-ai/admin/consent/react';
import type { Translate } from '@jini-ai/ui/panel-kit';
import { describeApiError } from '@/lib/api';
import { createConsentAutosave, type ConsentAutosave, type ConsentTimers } from './consent-autosave';
import { canPublishConsent, consentPreviewScale, isConsentConflict, type ConsentSaveState } from './rules';
import type { ConsentEditorLimits, ConsentReadiness, ConsentRevisionsPort, ConsentSettingsSnapshot } from './settings.hooks';

/**
 * @file State for the Cookie Consent page. The page edits one draft revision (autosaved, see
 * `consent-autosave.ts`) and publishes it explicitly; the live site changes only on Publish. All
 * I/O goes through {@link ConsentRevisionsPort}; the page and its tabs are markup only.
 */

export interface ConsentPageController {
  loadError: string | null;
  editor: ConsentEditorLimits | null;
  /** `null` until the first load. Draft first, else the live (published or legacy) settings. */
  value: ConsentSettingsView | null;
  onChange(required: { patch: Partial<ConsentSettingsView> }, optional?: Record<string, never>): void;
  /** The saved draft's blocking problems; Publish stays off while there are any. */
  problems: ConsentFieldProblem[];
  saveState: ConsentSaveState;
  saveError: string | null;
  /** The newest saved draft revision, or null before the first save. */
  draftId: string | null;
  hasUnpublished: boolean;
  everPublished: boolean;
  /** Whether the banner is on for visitors right now. */
  liveEnabled: boolean;
  canPublish: boolean;
  publishing: boolean;
  publishError: string | null;
  /** Bumps after each publication so readiness can refresh. */
  publishedCount: number;
  publish(): Promise<void>;
  reload(): void;
}

interface Heads { draftId: string | null; publishedId: string | null }

function withDraftId(draftId: string): (current: Heads) => Heads {
  return (current) => ({ ...current, draftId });
}

function withPreviewError(error: string): (current: ConsentPreviewState) => ConsentPreviewState {
  return (current) => ({ ...current, error });
}

/** Loads the revisions, autosaves edits as a draft and publishes it on request.
 * @complexity O(1) per edit; one request in flight at a time. */
export function useConsentPage({ port, t }: { port: ConsentRevisionsPort; t: Translate }, { delayMs, timers }: { delayMs?: number; timers?: ConsentTimers } = {}): ConsentPageController {
  const [loadNonce, setLoadNonce] = useState(0);
  const [snapshot, setSnapshot] = useState<ConsentSettingsSnapshot | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [value, setValue] = useState<ConsentSettingsView | null>(null);
  const [heads, setHeads] = useState<Heads>({ draftId: null, publishedId: null });
  const [problems, setProblems] = useState<ConsentFieldProblem[]>([]);
  const [saveState, setSaveState] = useState<ConsentSaveState>('idle');
  const [settled, setSettled] = useState(true);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [publishing, setPublishing] = useState(false);
  const [publishError, setPublishError] = useState<string | null>(null);
  const [liveEnabled, setLiveEnabled] = useState(false);
  const [publishedCount, setPublishedCount] = useState(0);
  const valueRef = useRef<ConsentSettingsView | null>(null);
  const autosave = useRef<ConsentAutosave | null>(null);

  useEffect(() => {
    let alive = true;
    setLoadError(null);
    port.get().then(loaded => {
      if (!alive) return;
      const draftId = loaded.draft?.id ?? null;
      valueRef.current = loaded.draft?.config ?? loaded.effective;
      setSnapshot(loaded);
      setValue(valueRef.current);
      setHeads({ draftId, publishedId: loaded.published?.id ?? null });
      setLiveEnabled(loaded.effective.enabled);
      setProblems([]); setSaveState('idle'); setSettled(true); setSaveError(null); setPublishError(null);
      autosave.current = createConsentAutosave({ port, draftId, events: {
        onSaving: () => setSaveState('saving'),
        onSaved: ({ result, settled: done }) => {
          setHeads(withDraftId(result.revision.id));
          setProblems(result.blockingProblems);
          if (done) { setSaveState('saved'); setSettled(true); }
        },
        onConflict: () => setSaveState('conflict'),
        onError: ({ error }) => { setSaveState('error'); setSaveError(describeApiError(error, t("Couldn't save."))); },
      } }, consentAutosaveOptions({ delayMs, timers }));
    }, error => { if (alive) setLoadError(describeApiError(error, t("Couldn't load cookie consent."))); });
    return () => { alive = false; autosave.current?.stop(); };
  }, [port, loadNonce]); // eslint-disable-line react-hooks/exhaustive-deps -- t/delay/timers are fixed per mount

  const hasUnpublished = heads.draftId !== null && heads.draftId !== heads.publishedId;

  function onChange({ patch }: { patch: Partial<ConsentSettingsView> }) {
    if (!valueRef.current || saveState === 'conflict') return;
    valueRef.current = { ...valueRef.current, ...patch };
    setValue(valueRef.current);
    setSettled(false);
    setPublishError(null);
    autosave.current!.change({ config: valueRef.current });
  }

  const canPublish = canPublishConsent({ saveState, settled, hasUnpublished, problems, publishing });

  async function publish() {
    if (!canPublish) return;
    // canPublish implies a saved, loaded draft: draftId, the value and autosave all exist.
    const draftId = heads.draftId!;
    setPublishing(true);
    setPublishError(null);
    try {
      await port.publish({ draftId, expectedPublishedId: heads.publishedId });
      setHeads({ draftId, publishedId: draftId });
      setLiveEnabled(valueRef.current!.enabled);
      setPublishedCount(count => count + 1);
    } catch (error) {
      if (isConsentConflict({ error })) { autosave.current!.stop(); setSaveState('conflict'); }
      else setPublishError(describeApiError(error, t("Couldn't publish.")));
    } finally {
      setPublishing(false);
    }
  }

  return {
    loadError, editor: snapshot?.editor ?? null, value, onChange, problems, saveState, saveError,
    draftId: heads.draftId, hasUnpublished, everPublished: heads.publishedId !== null, liveEnabled, canPublish, publishing, publishError, publishedCount,
    publish, reload: () => setLoadNonce(nonce => nonce + 1),
  };
}

export interface ConsentPreviewState {
  html: string | null;
  problems: ConsentFieldProblem[];
  warnings: ConsentFieldProblem[];
  error: string | null;
}

/** The real renderer's gated page for the current (unsaved) settings, debounced; a response that
 * arrives after a newer request was sent is dropped. CSS warnings travel with the preview, never
 * into the saved draft's publish blockers. @complexity O(1) requests per settle. */
export function useConsentPreview({ port, config, t }: { port: ConsentRevisionsPort; config: ConsentSettingsView | null; t: Translate }, { delayMs = 500 }: { delayMs?: number } = {}): ConsentPreviewState {
  const [state, setState] = useState<ConsentPreviewState>({ html: null, problems: [], warnings: [], error: null });
  const sequence = useRef(0);
  useEffect(() => {
    if (!config) return undefined;
    sequence.current += 1;
    const ticket = sequence.current;
    const timer = setTimeout(() => {
      port.preview({ config }).then(
        result => { if (ticket === sequence.current) setState({ html: result.html, problems: result.blockingProblems, warnings: result.warnings ?? [], error: null }); },
        error => { if (ticket === sequence.current) setState(withPreviewError(describeApiError(error, t("Couldn't render the preview.")))); },
      );
    }, delayMs);
    return () => clearTimeout(timer);
  }, [port, config, delayMs]); // eslint-disable-line react-hooks/exhaustive-deps -- t is fixed per mount
  return state;
}

/** Tracks the preview pane's width as the scale that fits a desktop-width page into it, so the
 * Desktop preview shows the banner's desktop layout. Without ResizeObserver (tests) it stays 1.
 * @complexity O(1) per resize. */
export function useConsentPreviewScale(_required: Record<string, never> = {}, _optional = {}): { ref: (node: HTMLElement | null) => void; scale: number } {
  const [scale, setScale] = useState(1);
  const observer = useRef<ResizeObserver | null>(null);
  const ref = useCallback((node: HTMLElement | null) => {
    observer.current?.disconnect();
    observer.current = null;
    if (!node || typeof ResizeObserver === 'undefined') return;
    observer.current = new ResizeObserver(entries => setScale(consentPreviewScale({ paneWidth: entries[0]?.contentRect.width ?? 0 })));
    observer.current.observe(node);
  }, []);
  return { ref, scale };
}

/** Readiness for Overview: the server checks the draft (else the live settings) as if it were on.
 * Reloads whenever `refresh` changes. */
export function useConsentReadiness({ port, refresh, t }: { port: ConsentRevisionsPort; refresh: string; t: Translate }, _optional = {}): { readiness: ConsentReadiness | null; error: string | null } {
  const [state, setState] = useState<{ readiness: ConsentReadiness | null; error: string | null }>({ readiness: null, error: null });
  useEffect(() => {
    let alive = true;
    port.readiness({}).then(
      readiness => { if (alive) setState({ readiness, error: null }); },
      error => { if (alive) setState({ readiness: null, error: describeApiError(error, t("Couldn't check readiness.")) }); },
    );
    return () => { alive = false; };
  }, [port, refresh]); // eslint-disable-line react-hooks/exhaustive-deps -- t is fixed per mount
  return state;
}

/** Preserve omitted autosave options so the autosave owner supplies its browser defaults. */
function consentAutosaveOptions({ delayMs, timers }: { delayMs: number | undefined; timers: ConsentTimers | undefined }) {
  return { ...(delayMs === undefined ? {} : { delayMs }), ...(timers ? { timers } : {}) };
}

