}

import { useCallback, useEffect, useRef, useState } from "react";

import { describeApiError, type AdminExportRunSnapshot } from "@/lib/api";
import { useFetchQuery } from "@jini-ai/ui/fetch-query";
import { useAdminLocale } from "@/hooks/use-admin-locale.hooks";
import { useContentRefreshSubscription } from "@/hooks/use-content-refresh-subscription.hooks";
import { t as defaultT, exportLoadErrorMessage, exportPollErrorMessage, exportTriggerErrorMessage } from "../deployment-i18n";
import { DEPLOYMENT_EXPORT_RESOURCE } from "../rules";
import type { Translate } from "@jini-ai/ui/panel-kit";
import { defaultStaticExportPort } from "./static-export-dependencies.hooks";
import type { StaticExportPort } from "./static-export-port.hooks";

/**
 * @file Everything the Static Site tab's "Build static export" action does, so `StaticSiteTab.tsx`
 * is only markup. Wired 2026-08-15 against `POST`/`GET .../system/export`
 * (`src/server/routes/admin/system/export-site.ts`) — see that route's header for the trigger+poll
 * shape this hook mirrors: a real export is seconds to minutes, so a click starts the run and this
 * hook polls the status route until it settles, rather than holding one request open.
 *
 * `run` is seeded from a `getSiteExportStatus()` read on mount (via `useFetchQuery`, once — see
 * `seededRef` below) so a reload mid-export, or a second browser tab, still shows the real state
 * instead of a blank "not started". After that first paint, `run` is owned entirely by
 * {@link trigger} and the poll loop, never by a background refetch of the query — same "no
 * `invalidates`, set state from the write's own response" reasoning `use-dockerfile-source.hooks.ts`'s
 * header documents, extended here to the poll (which is this hook's OWN repeated read, not the
 * query's).
 *
 * `clean` defaults to `false` and is never silently flipped by this hook — `exportSite` itself
 * refuses to overwrite a non-empty output directory, and surfacing that refusal honestly (rather
 * than working around it here) is the point: see `StaticSiteTab.tsx`'s own reason text for the
 * checkbox.
 *
 * ## `useContentRefreshSubscription` — a bespoke reload, not the usual one-liner
 *
 * Staleness-bug generalization pass (see that hook's own header): an assistant run that called
 * `deployment_trigger_export` (`apps/website/src/features/deployments/agent-tools.ts`) from a
 * DIFFERENT tab/session should not leave this tab showing "Not started" indefinitely. This can't be
 * the usual `useInvalidate()` one-liner (`use-media.hooks.ts`'s shape) because `run` is not read
 * from `query.data` after the FIRST load — `seededRef` above deliberately blocks a later background
 * refetch of the SAME `useFetchQuery` from re-seeding it, so invalidating that query would silently
 * do nothing. Instead, {@link refreshRun} calls `port.getSiteExportStatus()` directly and sets
 * `run` from the response, bypassing the query entirely — the same "reach past the query, call the
 * port directly" shape `use-access-tokens.hooks.ts`'s own `reloadAllStores` uses for the identical
 * reason. This is safe unconditionally, unlike a re-seed of `use-dockerfile-source.hooks.ts`'s
 * `draft`: `run` is a pure status snapshot the operator only ever VIEWS, never types into, so there
 * is no in-progress edit a background refresh could clobber. If the fresh status comes back
 * `"running"`, the poll effect below picks it up on its own next render (it re-arms whenever
 * `isRunning` flips true) — this function does not need to start polling itself.
 */
export interface StaticExportController {
  /** The current/most recent run this hook knows about — `undefined` until the first status read
   *  resolves (mirrors `DeploymentOverviewController.snapshot`'s own "undefined = still loading"
   *  convention). */
  run: AdminExportRunSnapshot | undefined;
  /** True whenever `run.status === "running"` AND polling can still reach the status endpoint —
   *  drives the poll loop and the button's disabled state (never trigger a second export while one
   *  is in flight; the server would 409 anyway, but disabling here avoids a round trip that can only
   *  fail). Also requires {@link pollError} to be `null`: once bounded polling has given up, this
   *  flips false so the button re-enables even though the server-side run may still be in progress —
   *  see {@link pollError}'s own doc. */
  isRunning: boolean;
  /** Already-formatted, translated error from the INITIAL status read — `null` while loading or
   *  once loaded successfully. Distinct from {@link triggerError}: a failed initial read and a
   *  failed trigger are different failures (same split `use-dockerfile-source.hooks.ts`'s
   *  `error`/`saveError` draws). */
  loadError: string | null;
  /** Already-formatted, translated error from the poll loop giving up after
   *  {@link StaticExportController.isRunning}'s own consecutive-failure bound — `null` while polling
   *  is healthy (or hasn't started) and reset to `null` at the start of every new {@link trigger}.
   *  Distinct from both {@link loadError} (the one-shot initial read) and {@link triggerError} (the
   *  POST that starts a run): this is the REPEATED read that keeps a `"running"` run's status
   *  current. Without a bound, an unreachable status endpoint (routine in local dev — `tsx watch`
   *  restarts kill the in-flight poll on every file save) retried forever behind a stuck spinner with
   *  the action disabled and no way out. */
  pollError: string | null;
  /** Already-formatted, translated error from the most recent {@link trigger} call — `null` until a
   *  trigger fails, reset to `null` at the start of every new attempt. Covers both a genuine
   *  rejection (malformed request) and the expected `409` from clicking while a run is already in
   *  flight. */
  triggerError: string | null;
  /** True while the trigger POST is in flight — briefer than {@link isRunning}, which stays true for
   *  the whole export, not just the initial request. */
  triggering: boolean;
  /** Whether the next {@link trigger} should ask the server to remove the output directory's
   *  existing contents first. See this file's header for why this is never set anywhere but by the
   *  operator's own gesture. */
  clean: boolean;
  setClean: (value: boolean) => void;
  /** Starts a new export run with the current {@link clean} value. Resolves either way (a failure is
   *  surfaced through {@link triggerError}, not a thrown rejection) — callers don't need a try/catch
   *  of their own. */
  trigger: () => Promise<void>;
  /** Bound translator — see `use-deployment-overview.hooks.ts`'s header for this app's standing i18n
   *  rule. */
  t: Translate;
}

/** How often the poll loop re-checks the run's status while it is `"running"`. Short enough that a
 *  ~1s local export (the fastest one this feature has been observed to take) still shows more than
 *  one "Exporting…" frame, long enough not to flood the server for a run documented as "seconds to
 *  minutes". */
const EXPORT_POLL_INTERVAL_MS = 1500;

/** How many CONSECUTIVE poll failures the loop below tolerates before giving up and surfacing
 *  {@link StaticExportController.pollError} instead of retrying forever. At `EXPORT_POLL_INTERVAL_MS`
 *  (1.5s) this is ~4.5s of tolerance — enough to ride out a `tsx watch` restart (the routine local-dev
 *  cause the audit finding this closes calls out, C2) without stranding a genuinely permanent failure
 *  (server crash, revoked auth) on a dead spinner indefinitely. */
const POLL_FAILURE_LIMIT = 3;

export function useStaticExport(port: StaticExportPort, t: Translate, locale: string): StaticExportController {
  const query = useFetchQuery({ key: ["deployment", "export"], fetch: () => port.getSiteExportStatus() });
  const [run, setRun] = useState<AdminExportRunSnapshot | undefined>(undefined);
  const [clean, setClean] = useState(false);
  const [triggering, setTriggering] = useState(false);
  const [triggerError, setTriggerError] = useState<string | null>(null);
  const [pollError, setPollError] = useState<string | null>(null);

  // Seeds `run` from the query's first successful load, exactly once — see this file's header.
  const seededRef = useRef(false);
  useEffect(() => {
    if (seededRef.current || query.status === "loading" || !query.data) return;
    seededRef.current = true;
    setRun(query.data);
  }, [query.status, query.data]);

  const loadError = query.error ? exportLoadErrorMessage(locale, describeApiError(query.error, "unknown error")) : null;

  // See this file's header for why this bypasses the query/`seededRef` entirely rather than being
  // the usual `useInvalidate()` one-liner. A failed background refresh is swallowed rather than
  // surfaced through `loadError`/`triggerError` — this is a best-effort catch-up read, not a load or
  // trigger the operator directly asked for, and the visible `run` simply stays what it was.
  const refreshRun = useCallback(async () => {
    try {
      const status = await port.getSiteExportStatus();
      setRun(status);
    } catch {
      // best-effort; see comment above
    }
  }, [port]);
  // `useContentRefreshSubscription`'s `onRefresh` is a synchronous `() => void` — wrapping rather
  // than passing `refreshRun` directly, mirroring `use-access-tokens.hooks.ts`'s identical
  // `reloadAllStores`/`triggerReload` split, so the subscription never hands the bus a dangling
  // Promise.
  const triggerRefresh = useCallback(() => {
    void refreshRun();
  }, [refreshRun]);
  useContentRefreshSubscription(DEPLOYMENT_EXPORT_RESOURCE, triggerRefresh);

  // Counts CONSECUTIVE poll failures for the `POLL_FAILURE_LIMIT` bound below — a ref, not state,
  // because it is read and written only from inside the poll loop's own effect and must never itself
  // trigger a render (only the `pollError` it may eventually set does that).
  const pollFailuresRef = useRef(0);

  const isRunning = run?.status === "running" && pollError === null;

  // Poll loop: re-armed only when `isRunning` FLIPS to true (mount-while-running counts), not on
  // every `run` update the loop itself produces — a dependency on `run` here would re-schedule (or,
  // worse, fail to reschedule after a transient fetch error that never touched `run`) on every tick
  // instead of running as one self-scheduling loop. Each iteration decides whether to continue from
  // the STATUS IT JUST FETCHED, not from the outer `isRunning` closure, which is correctly stale
  // inside a single effect run. A fetch failure retries on the same schedule rather than silently
  // giving up — a transient network hiccup must not strand the UI on "Exporting…" forever.
  // biome-ignore lint/correctness/useExhaustiveDependencies: re-armed only when `isRunning` flips true; `run`/`port` deliberately excluded — see comment above.
  useEffect(() => {
    if (!isRunning) return undefined;
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout>;

    function scheduleNext() {
      timer = setTimeout(poll, EXPORT_POLL_INTERVAL_MS);
    }
    async function poll() {
      try {
        const status = await port.getSiteExportStatus();
        if (cancelled) return;
        pollFailuresRef.current = 0;
        setRun(status);
        if (status.status === "running") scheduleNext();
      } catch (err) {
        if (cancelled) return;
        pollFailuresRef.current += 1;
        if (pollFailuresRef.current >= POLL_FAILURE_LIMIT) {
          // Bounded (C2): give up rather than retry forever. Setting `pollError` also flips
          // `isRunning` false on the next render, which re-arms this very effect's cleanup and
          // re-enables the Build button — but `return` here (no `scheduleNext()`) is what actually
          // stops the loop; it must not depend on that later render having happened yet.
          setPollError(exportPollErrorMessage(locale, describeApiError(err, "unknown error")));
          return;
        }
        scheduleNext();
      }
    }
    scheduleNext();

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [isRunning]);

  // Synchronous duplicate-submit guard — same reasoning as `use-static-publish.hooks.ts`'s
  // `publishingRef` (C4): two calls in one tick both read this render's `triggering: false`
  // (terra review 2026-09-20, finding 5).
  const triggeringRef = useRef(false);

  async function trigger() {
    if (triggeringRef.current) return;
    triggeringRef.current = true;
    // Local action supersedes any still-pending bootstrap read: mark it consumed BEFORE the request
    // even starts, so a bootstrap GET that resolves late — after this trigger's own response already
    // set `run` — cannot land on top of it and silently kill polling for a run the server is still
    // actually running (C1). Ordering is what makes this safe: this write is synchronous and
    // happens-before the `await` below, so it wins the race regardless of how late the bootstrap
    // read resolves.
    seededRef.current = true;
    // A fresh trigger also clears any earlier poll-failure standoff (C2) — the operator retrying via
    // this same button is exactly the recovery path a stalled `pollError` is meant to unblock.
    pollFailuresRef.current = 0;
    setPollError(null);
    setTriggerError(null);
    setTriggering(true);
    try {
      const started = await port.triggerSiteExport({ clean });
      setRun(started);
    } catch (err) {
      setTriggerError(exportTriggerErrorMessage(locale, describeApiError(err, "unknown error")));
    } finally {
      triggeringRef.current = false;
      setTriggering(false);
    }
  }

  return { run, isRunning, loadError, pollError, triggerError, triggering, clean, setClean, trigger, t };
}

/**
 * Binds the real `/api/.../system/export` client, and a `t` bound to the real resolved locale — the
 * zero-argument half of the `useX(dependencies)` / `useWiredX()` pair, same shape
 * `use-deployment-overview.hooks.ts`'s `useWiredDeploymentOverview` documents.
 */
export function useWiredStaticExport(): StaticExportController {
  const locale = useAdminLocale();
  const t = (key: string): string => defaultT({ locale: locale, key: key });
  return useStaticExport(defaultStaticExportPort, t, locale);
}

import { TOVU_ERROR_REDACTION_OPTIONS } from "@tovu/contracts/secret-redaction";
import { useEffect, useMemo, useRef, useState } from "react";
import { formatUserFacingError, type UserFacingError } from "@jini-ai/core";

import {
  describeApiError,
  type AdminPublishRunSnapshot,
  type AdminPublishTargetDescriptor,
  type AdminStaticPublishConfig,
  type AdminStaticPublishPreview,
  type AdminStaticPublishTargetId,
} from "@/lib/api";
import { localizePublishTargets } from "@/lib/descriptor-i18n";
import { useFetchQuery } from "@jini-ai/ui/fetch-query";
import { useAdminLocale } from "@/hooks/use-admin-locale.hooks";
import {
  t as defaultT,
  publishLoadErrorMessage,
  publishPollErrorMessage,
  publishPreviewErrorMessage,
  publishTriggerErrorMessage,
} from "../deployment-i18n";
import type { Translate } from "@jini-ai/ui/panel-kit";
import {
  buildStaticPublishConfig,
  publishTargetById,
  staticPublishFormReadyForPreview,
  staticPublishFormReadyToPublish,
  staticPublishProjectNameCopy,
  staticPublishProjectNameToSend,
  type StaticPublishProjectNameCopy,
} from "../rules";
import { defaultStaticPublishPort } from "./static-publish-dependencies.hooks";
import type { StaticPublishPort } from "./static-publish-port.hooks";

const UNKNOWN_ERROR = "The publish service returned no explanation. Check publish status before trying again, and report this message if the problem continues.";

/**
 * @file Everything the Static Site tab's "Getting it online" provider form does — target selection,
 * the host's config fields and projectName, the preview action, and the publish
 * trigger+poll — so `StaticSiteTab.tsx` is only markup. Wired 2026-08-15 against
 * `src/server/routes/admin/system/publish-site.ts`'s three routes (preview, trigger, status).
 *
 * ## One form, fields from the host's descriptor
 *
 * The hosts, and each host's config fields, come from `GET .../system/publish-targets` (the deploy
 * plugin's descriptors) — this hook names no host. Config values are kept per target id, so
 * switching hosts never discards another host's half-filled fields, and `buildStaticPublishConfig`
 * (`rules.ts`) sends only the fields the selected host declares.
 *
 * ## `basePath` is never a field here
 *
 * There is no `setBasePath` anywhere in this file, on purpose — `AdminStaticPublishConfig` (the
 * wire type) has no such field either. The base path is always what `preview.basePath`/
 * `run.result.basePath` REPORT the server already computed, never something this form could send
 * back. See `static-publish/adapter.ts`'s `computeBasePath` for why that is structural, not a
 * missing feature.
 *
 * ## `preview` is invalidated by every field edit
 *
 * A stale preview computed against a DIFFERENT owner/repo would show the wrong base path next to a
 * form the operator has since changed — worse than showing nothing, since it looks current. Every
 * setter below clears `preview`/`previewError` as a side effect, so the "Preview" affordance always
 * either reflects the fields currently on screen or is honestly empty.
 */
export interface StaticPublishController {
  /** The deploy registry's targets, in its order — `undefined` until the first load resolves. */
  targets: readonly AdminPublishTargetDescriptor[] | undefined;
  /** Translated error from loading {@link targets}, `null` otherwise. */
  targetsError: string | null;
  /** The selected target's id — the operator's pick, else the first listed target; `""` while the
   *  list loads. */
  target: AdminStaticPublishTargetId;
  /** {@link target}'s descriptor, `undefined` while the list loads. */
  selectedTarget: AdminPublishTargetDescriptor | undefined;
  setTarget: (target: AdminStaticPublishTargetId) => void;
  /** The selected target's config values, keyed by descriptor field name. */
  configValues: Readonly<Record<string, string>>;
  setConfigField: (name: string, value: string) => void;
  /** Whether Preview / Publish may be asked for with the current values (`rules.ts`). */
  canPreview: boolean;
  canPublish: boolean;
  /** The selected host's label and help for {@link projectName}; `null` when the host takes no
   *  project name, so the tab shows no such field. */
  projectNameCopy: StaticPublishProjectNameCopy | null;
  projectName: string;
  setProjectName: (value: string) => void;

  /** The most recent preview result — `undefined` until {@link checkPreview} has resolved at least
   *  once since the fields were last edited (see this file's header). */
  preview: AdminStaticPublishPreview | undefined;
  previewLoading: boolean;
  previewError: string | null;
  /** Runs a preview against the CURRENT field values for the CURRENT target. Resolves either way — a
   *  failure is surfaced through {@link previewError}. */
  checkPreview: () => Promise<void>;

  /** The current/most recent publish run — `undefined` until the first status read resolves. */
  run: AdminPublishRunSnapshot | undefined;
  /** True whenever `run.status === "running"` AND polling can still reach the status endpoint — see
   *  {@link pollError}'s own doc for why the second half matters (same shape
   *  `StaticExportController.isRunning` documents). */
  isPublishing: boolean;
  /** Already-formatted, translated error from the INITIAL status read — `null` while loading or once
   *  loaded successfully. Distinct from {@link publishError}: same split
   *  `StaticExportController.loadError`/`triggerError` draws. */
  loadError: string | null;
  /** Already-formatted, translated error from the poll loop giving up after a bounded number of
   *  consecutive failures — `null` while healthy, reset at the start of every new {@link publish}.
   *  Same shape and same reason `StaticExportController.pollError` exists: an unbounded retry here
   *  would strand the operator on a stuck "Publishing…" spinner with the button disabled forever. */
  pollError: string | null;
  publishError: string | null;
  publishFailure?: UserFacingError | null;
  /** True while a {@link publish} POST is in flight — briefer than {@link isPublishing}, which stays
   *  true for the whole publish, not just the initial request. Exposed (unlike an internal-only flag)
   *  so the caller can disable the Publish button on this alone, before any run comes back — without
   *  it, a double-click could send two POSTs before the first one's response ever arrives. */
  publishing: boolean;
  /** Starts a real publish with the current field values. Resolves either way — a failure is
   *  surfaced through {@link publishError}, never a thrown rejection. A call while {@link publishing}
   *  is already true is a duplicate submit and is ignored outright, not just discouraged by the
   *  disabled button — see this function's own implementation note.
   *
   *  `options.credentialId` names the saved connection the publish must use (terra review
   *  2026-09-20, finding 1). This hook never picks one itself: it has no credentials controller, and
   *  the caller (`StaticSiteTab`) is the one screen that knows which connection the operator is
   *  actually looking at. Omitted when this provider has no saved connection.
   *
   *  `options.destination` replays a saved destination (the Sites Export tab's Publish list) instead
   *  of this form's fields: the server already validated that target, project and config once. */
  publish: (options?: StaticPublishOptions) => Promise<void>;

  t: Translate;
}

/** What one {@link StaticPublishController.publish} call may name. */
export interface StaticPublishOptions {
  credentialId?: string;
  destination?: { config: AdminStaticPublishConfig; projectName: string };
}

/** Same interval `use-static-export.hooks.ts` polls its own run at — see that constant's doc for
 *  why this width. Publishing additionally blocks on an external provider's own build (up to
 *  roughly a minute per `publish-site.ts`'s header), so this loop simply runs for longer, not
 *  faster or slower. */
const PUBLISH_POLL_INTERVAL_MS = 1500;

/** Same bound and same rationale as `use-static-export.hooks.ts`'s own `POLL_FAILURE_LIMIT` — how
 *  many CONSECUTIVE poll failures the loop below tolerates before giving up and surfacing
 *  {@link StaticPublishController.pollError} instead of retrying forever. */
const PUBLISH_POLL_FAILURE_LIMIT = 3;

export function useStaticPublish(port: StaticPublishPort, t: Translate, locale: string): StaticPublishController {
  const targetsQuery = useFetchQuery({ key: ["deployment", "publish-targets"], fetch: () => port.listPublishTargets() });
  // The host's own text in the viewer's locale, once, so every consumer (this form, the credential
  // rows built from these targets) renders it translated.
  const targets = useMemo(() => localizePublishTargets(targetsQuery.data, locale), [targetsQuery.data, locale]);
  const targetsError = targetsQuery.error ? publishLoadErrorMessage(locale, describeApiError(targetsQuery.error, UNKNOWN_ERROR)) : null;
  const [chosenTarget, setChosenTarget] = useState<AdminStaticPublishTargetId | null>(null);
  const target = selectedPublishTargetId({ chosenTarget, targets });
  const selectedTarget = publishTargetById(targets, target);
  const [valuesByTarget, setValuesByTarget] = useState<Record<AdminStaticPublishTargetId, Record<string, string>>>({});
  const configValues = valuesByTarget[target] ?? {};
  const [projectName, setProjectName] = useState("");

  const [preview, setPreview] = useState<AdminStaticPublishPreview | undefined>(undefined);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [previewError, setPreviewError] = useState<string | null>(null);

  // Bumped by every field edit (via `invalidatePreview` below) so `checkPreview` can tell whether
  // the fields it was called against are still the CURRENT fields once its request resolves — see
  // that function's own note (C3 fix).
  const previewGenerationRef = useRef(0);

  // Synchronous duplicate-submit guard for `checkPreview()` (2026-09-05 stale-settlement sweep, C5
  // fix) — same reasoning `publishingRef` documents for `publish()` below, PLUS a second failure mode
  // specific to `checkPreview`: with no guard, two overlapping calls share the one `previewLoading`
  // flag, so whichever call's own `finally` fires FIRST clears it while the OTHER is still in flight —
  // the Preview button (and any caller depending on `previewLoading`) would read "not loading" with a
  // request still outstanding. A ref, not `previewLoading` (state) itself: a same-tick double call
  // (or any caller reaching `checkPreview()` directly, not just through the disabled button) must see
  // the other call's claim synchronously, before either has re-rendered.
  const previewCallRef = useRef(false);

  // Every setter below clears the (now stale) preview as a side effect — see this file's header.
  function invalidatePreview() {
    previewGenerationRef.current += 1;
    setPreview(undefined);
    setPreviewError(null);
  }
  function setTarget(value: AdminStaticPublishTargetId) {
    if (publishTargetById(targets, value) === undefined) return;
    setChosenTarget(value);
    invalidatePreview();
  }
  function setConfigField(name: string, value: string) {
    setValuesByTarget((prev) => ({ ...prev, [target]: { ...prev[target], [name]: value } }));
    invalidatePreview();
  }

  async function checkPreview() {
    // A second call while the first is still in flight is a duplicate submit — ignore it here too,
    // not just via the UI's `previewLoading`-gated disabled state, so the race can't still send two
    // requests or tear down `previewLoading` out from under the call that's still running (C5 fix,
    // same "ignored outright" idiom `publish()`'s `publishingRef` uses below). Safe against a
    // same-tick double call specifically because it is synchronous: nothing yields between the read
    // and the write, so a second synchronous call always observes this call's claim.
    if (previewCallRef.current || selectedTarget === undefined) return;
    previewCallRef.current = true;
    // Captured BEFORE the request starts — if a field edit bumps `previewGenerationRef` while this
    // request is in flight, the comparison below after `await` tells us this result is now stale
    // (C3 fix: without it, a slow preview response for `acme/old` could resolve AFTER the operator
    // had already changed the field to `acme/new` and repopulate the form with the wrong target).
    const requestGeneration = previewGenerationRef.current;
    setPreviewError(null);
    setPreviewLoading(true);
    try {
      const result = await port.getPublishPreview(buildStaticPublishConfig(selectedTarget, configValues));
      // A field edited after this request started already invalidated the preview and moved the
      // generation forward — applying this now-stale result would repopulate the OLD fields over a
      // form the operator has since changed. Discard it silently; the edit's own `invalidatePreview()`
      // already left `preview`/`previewError` in the right (empty) state.
      if (previewGenerationRef.current !== requestGeneration) return;
      setPreview(result);
    } catch (err) {
      if (previewGenerationRef.current !== requestGeneration) return;
      setPreviewError(publishPreviewErrorMessage(locale, describeApiError(err, UNKNOWN_ERROR)));
    } finally {
      // Unconditional, unlike the two branches above: this request's own spinner must stop once ITS
      // OWN network call settles regardless of generation, or a discarded stale response would leave
      // `previewLoading` stuck true forever with nothing left in flight to ever clear it. Safe to
      // always release `previewCallRef` here too now that duplicates are refused at entry, above —
      // there is never a second, still-running call left whose own flag this could clobber.
      previewCallRef.current = false;
      setPreviewLoading(false);
    }
  }

  const query = useFetchQuery({ key: ["deployment", "publish"], fetch: () => port.getPublishStatus() });
  const [run, setRun] = useState<AdminPublishRunSnapshot | undefined>(undefined);
  const [publishing, setPublishing] = useState(false);
  const [publishError, setPublishError] = useState<string | null>(null);
  const [publishFailure, setPublishFailure] = useState<UserFacingError | null>(null);
  const [pollError, setPollError] = useState<string | null>(null);

  // Seeds `run` from the query's first successful load, exactly once — same shape
  // `use-static-export.hooks.ts`'s own `seededRef` uses, and for the same reason (a reload mid-
  // publish, or a second tab, should show the real state rather than a blank "not started").
  const seededRef = useRef(false);
  useEffect(() => {
    if (seededRef.current || query.status === "loading" || !query.data) return;
    seededRef.current = true;
    setRun(query.data);
  }, [query.status, query.data]);

  const loadError = query.error ? publishLoadErrorMessage(locale, describeApiError(query.error, UNKNOWN_ERROR)) : null;

  // Counts CONSECUTIVE poll failures for the `PUBLISH_POLL_FAILURE_LIMIT` bound below — same ref-not-
  // state reasoning `use-static-export.hooks.ts`'s own `pollFailuresRef` documents.
  const pollFailuresRef = useRef(0);
  // Synchronous duplicate-submit guard for `publish()` — a ref, not the `publishing` state, because a
  // true double-click can fire two calls in the same synchronous tick, before React has re-rendered
  // with `publishing: true`; `publishing` (state) still exists to let the UI disable the button, but
  // the guard that actually stops a second POST from ever being sent has to be synchronous (C4 fix).
  const publishingRef = useRef(false);

  const isPublishing = run?.status === "running" && pollError === null;

  // Self-scheduling poll loop, re-armed only when `isPublishing` flips true — identical shape and
  // identical reasoning to `use-static-export.hooks.ts`'s own poll effect; see that file's comment
  // for why `run`/`port` are deliberately excluded from the dependency list.
  // biome-ignore lint/correctness/useExhaustiveDependencies: re-armed only when `isPublishing` flips true; `run`/`port` deliberately excluded — see comment above.
  useEffect(() => {
    if (!isPublishing) return undefined;
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout>;

    function scheduleNext() {
      timer = setTimeout(poll, PUBLISH_POLL_INTERVAL_MS);
    }
    async function poll() {
      try {
        const status = await port.getPublishStatus();
        if (cancelled) return;
        pollFailuresRef.current = 0;
        setRun(status);
        if (status.status === "running") scheduleNext();
      } catch (err) {
        if (cancelled) return;
        pollFailuresRef.current += 1;
        if (pollFailuresRef.current >= PUBLISH_POLL_FAILURE_LIMIT) {
          // Bounded (C2, same shape as use-static-export.hooks.ts's own fix): give up rather than
          // retry forever. Setting `pollError` also flips `isPublishing` false on the next render,
          // which re-arms this effect's own cleanup — but `return` here (no `scheduleNext()`) is
          // what actually stops the loop; it must not depend on that later render having happened.
          setPollError(publishPollErrorMessage(locale, describeApiError(err, UNKNOWN_ERROR)));
          return;
        }
        scheduleNext();
      }
    }
    scheduleNext();

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [isPublishing]);

  async function publish(options: StaticPublishOptions = {}) {
    // A second call while the first is still in flight is a duplicate submit (e.g. a double-click
    // landing before React re-renders with the button disabled) — ignore it here too, not just via
    // the UI's `publishing`-gated disabled state, so the race can't still send two POSTs (C4 fix).
    // This check-then-set is safe against a same-tick double call specifically BECAUSE it is
    // synchronous: nothing yields between the read and the write below, so a second synchronous call
    // always observes this call's write.
    const request = publishRequestFor({ options, selectedTarget, configValues, projectName });
    if (publishingRef.current || request === undefined) return;
    publishingRef.current = true;
    // Local action supersedes any still-pending bootstrap read — same C1 fix and same reasoning
    // `use-static-export.hooks.ts`'s own `trigger()` documents: this write is synchronous and
    // happens-before the `await` below, so it wins the race regardless of how late the bootstrap
    // read resolves.
    seededRef.current = true;
    // A fresh publish also clears any earlier poll-failure standoff (C2) — the operator retrying via
    // this same button is exactly the recovery path a stalled `pollError` is meant to unblock.
    pollFailuresRef.current = 0;
    setPollError(null);
    setPublishError(null);
    setPublishFailure(null);
    setPublishing(true);
    try {
      const started = await port.triggerPublish({
        ...request,
        // Conditional spread, never `credentialId: options.credentialId` — an absent choice must not
        // reach the wire as an explicit `undefined` key.
        ...(options.credentialId !== undefined ? { credentialId: options.credentialId } : {}),
      });
      setRun(started);
    } catch (err) {
      const failure = formatUserFacingError({ message: publishTriggerErrorMessage(locale, describeApiError(err, UNKNOWN_ERROR)),
        action: t("Check publish status before starting another publish. Copy details and report this problem."), step: "static.publish.start", cause: err }, TOVU_ERROR_REDACTION_OPTIONS);
      setPublishError(failure.message);
      setPublishFailure(failure);
    } finally {
      publishingRef.current = false;
      setPublishing(false);
    }
  }

  return {
    targets,
    targetsError,
    target,
    selectedTarget,
    setTarget,
    configValues,
    setConfigField,
    canPreview: staticPublishFormReadyForPreview(selectedTarget, configValues),
    canPublish: staticPublishFormReadyToPublish(selectedTarget, configValues, projectName),
    projectNameCopy: staticPublishProjectNameCopy(selectedTarget),
    projectName,
    setProjectName,
    preview,
    previewLoading,
    previewError,
    checkPreview,
    run,
    isPublishing,
    loadError,
    pollError,
    publishError,
    publishFailure,
    publishing,
    publish,
    t,
  };
}

/** The target config and project name a publish sends: a replayed destination as saved, else the
 *  form's current fields. `undefined` while the form has no target loaded yet. @complexity O(f). */
function publishRequestFor(input: {
  options: StaticPublishOptions;
  selectedTarget: AdminPublishTargetDescriptor | undefined;
  configValues: Readonly<Record<string, string>>;
  projectName: string;
}): { config: AdminStaticPublishConfig; projectName: string } | undefined {
  if (input.options.destination) return input.options.destination;
  if (input.selectedTarget === undefined) return undefined;
  return {
    config: buildStaticPublishConfig(input.selectedTarget, input.configValues),
    projectName: staticPublishProjectNameToSend(input.selectedTarget, input.projectName),
  };
}

/**
 * Binds the real `/api/.../system/publish*` client, and a `t` bound to the real resolved locale —
 * the zero-argument half of the `useX(dependencies)` / `useWiredX()` pair, same shape
 * `use-static-export.hooks.ts`'s `useWiredStaticExport` documents.
 */
export function useWiredStaticPublish(): StaticPublishController {
  const locale = useAdminLocale();
  const t = (key: string): string => defaultT({ locale: locale, key: key });
  return useStaticPublish(defaultStaticPublishPort, t, locale);
}

/** A chosen target wins; the initial target follows the provider's published ordering. */
function selectedPublishTargetId({ chosenTarget, targets }: {
  chosenTarget: AdminStaticPublishTargetId | null;
  targets: Parameters<typeof publishTargetById>[0];
}): AdminStaticPublishTargetId {
  return chosenTarget ?? targets?.[0]?.id ?? "";
}

import { useCallback, useEffect, useMemo, useState } from "react";

import { ApiError } from "@/lib/api";
import { emailApi, type EmailApi, type EmailTemplateDetail, type EmailTemplatePreview } from "../email-api";
import { errorMessage, useLoad, type LoadView } from "./email-load.hooks";

/**
 * @file One email template's editor page state: the raw HTML working copy, `{{field}}` fill-in
 * values (seeded from the template's declared samples), a debounced live preview of the UNSAVED
 * HTML (`POST …/email-templates/preview`), Save (`PUT …/:id/html`, conditioned on the version that
 * was loaded) and Rename (`PATCH …/:id`).
 *
 * Preview modes: `admin` keeps scripts (shown only inside the sandboxed preview iframe, the Pages
 * preview's sandbox); `sent` is exactly what a mail client gets — static HTML, scripts stripped.
 */

export type PreviewMode = "admin" | "sent";

export interface EmailTemplateEditorController {
  view: LoadView<EmailTemplateDetail>;
  html: string;
  setHtml: (html: string) => void;
  dirty: boolean;
  values: Record<string, string>;
  setValue: (field: string, value: string) => void;
  /** Field names to show: declared ones first, then any the HTML uses without declaring. */
  fieldNames: string[];
  mode: PreviewMode;
  setMode: (mode: PreviewMode) => void;
  preview: { data: EmailTemplatePreview | null; error: string | null; pending: boolean };
  saving: boolean;
  saveError: string | null;
  savedAt: string | null;
  save: () => Promise<void>;
  name: string;
  setName: (name: string) => void;
  commitName: () => Promise<void>;
  renameError: string | null;
}

/** Declared fields, then undeclared ones the HTML uses, without repeats. Pure. */
export function templateFieldNames(required: { declared: readonly { name: string }[]; undeclared: readonly string[] }): string[] {
  return [...new Set([...required.declared.map((field) => field.name), ...required.undeclared])];
}

/** The friendly line for a save failure; a 409 means someone else saved first. Pure. */
export function saveFailureText(error: unknown): string {
  if (error instanceof ApiError && error.status === 409) return "Someone else changed this template. Reload to get their version; copy your edits first.";
  return errorMessage(error);
}

/** Keeps the last good preview on screen beside the failure. */
function previewFailed(error: string): (current: EmailTemplateEditorController["preview"]) => EmailTemplateEditorController["preview"] {
  return (current) => ({ data: current.data, error, pending: false });
}

/**
 * @param required.api - the Email API port; a fake in tests.
 * @param required.id - the template id from the route.
 * @param optional.debounceMs - preview settle time; 0 in tests.
 */
export function useEmailTemplateEditor(
  required: { api: Pick<EmailApi, "getTemplate" | "saveTemplateHtml" | "renameTemplate" | "previewTemplate">; id: string },
  optional: { debounceMs?: number } = {},
): EmailTemplateEditorController {
  const { api, id } = required;
  const debounceMs = optional.debounceMs ?? 400;
  const { view, setData } = useLoad({ load: useCallback(() => api.getTemplate({ id }), [api, id]) });
  const detail = view.kind === "loaded" ? view.data : null;
  const [html, setHtml] = useState("");
  const [values, setValues] = useState<Record<string, string>>({});
  const [mode, setMode] = useState<PreviewMode>("admin");
  const [preview, setPreview] = useState<EmailTemplateEditorController["preview"]>({ data: null, error: null, pending: true });
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [savedAt, setSavedAt] = useState<string | null>(null);
  const [name, setName] = useState("");
  const [renameError, setRenameError] = useState<string | null>(null);

  // Seed the working copy once per loaded template (not on every save's fresh detail).
  const loadedId = detail?.id ?? null;
  useEffect(() => {
    if (!detail) return;
    setHtml(detail.html);
    setName(detail.name);
    setValues(Object.fromEntries(detail.fields.map((field) => [field.name, field.sample ?? ""])));
    // eslint-disable-next-line react-hooks/exhaustive-deps -- keyed on the id on purpose (see above).
  }, [loadedId]);

  useEffect(() => {
    if (!loadedId) return undefined;
    if (!html.trim()) {
      setPreview({ data: null, error: null, pending: false });
      return undefined;
    }
    let live = true;
    setPreview((current) => ({ ...current, pending: true }));
    const timer = setTimeout(() => {
      api.previewTemplate({ html, values, mode }).then(
        (data) => { if (live) setPreview({ data, error: null, pending: false }); },
        (error: unknown) => { if (live) setPreview(previewFailed(errorMessage(error))); },
      );
    }, debounceMs);
    return () => { live = false; clearTimeout(timer); };
  }, [api, loadedId, html, values, mode, debounceMs]);

  const dirty = detail !== null && html !== detail.html;
  const setValue = useCallback((field: string, value: string) => setValues((all) => ({ ...all, [field]: value })), []);
  const fieldNames = useMemo(() => templateFieldNames({
    declared: detail?.fields ?? [],
    undeclared: preview.data?.undeclaredFields ?? detail?.undeclaredFields ?? [],
  }), [detail, preview.data]);

  const save = useCallback(async () => {
    if (!detail || saving || !dirty) return;
    setSaving(true);
    setSaveError(null);
    try {
      const saved = await api.saveTemplateHtml({ id: detail.id, html, expectedVersion: detail.version });
      setData(saved);
      // The server stores its normalized copy (it trims the trailing newline), so adopt it unless the
      // owner typed more while saving; otherwise `dirty` stayed true after every save.
      setHtml((current) => (current === html ? saved.html : current));
      setSavedAt(saved.updatedAt);
    } catch (error) {
      setSaveError(saveFailureText(error));
    } finally {
      setSaving(false);
    }
  }, [api, detail, saving, dirty, html, setData]);

  const commitName = useCallback(async () => {
    if (!detail) return;
    const next = name.trim();
    if (!next || next === detail.name) {
      setName(detail.name);
      return;
    }
    setRenameError(null);
    try {
      const renamed = await api.renameTemplate({ id: detail.id, name: next, expectedVersion: detail.version });
      // Keep the working copy: a rename only changes the title and the version the next save states.
      setData({ ...detail, name: renamed.name, version: renamed.version, updatedAt: renamed.updatedAt });
    } catch (error) {
      setRenameError(saveFailureText(error));
      setName(detail.name);
    }
  }, [api, detail, name, setData]);

  return {
    view, html, setHtml, dirty, values, setValue, fieldNames, mode, setMode, preview, saving, saveError, savedAt, save, name, setName, commitName, renameError,
  };
}

/** The real API port. */
export function useWiredEmailTemplateEditor(required: { id: string }): EmailTemplateEditorController {
  return useEmailTemplateEditor({ api: emailApi, id: required.id });
}

