/**
 * @file The colocated `PublishContentDialog` behaviour — Escape-to-cancel, plus plan -> confirm ->
 * execute ceremony (`ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §4
 * task 11). The component renders what this returns and decides nothing itself, per the standing
 * rule that component logic belongs in a hook.
 *
 * ## What is NOT here
 *
 * The ceremony's *rules* — which rows a run writes, what each outcome is called, and when a plan may
 * be confirmed or executed — live in `@tovu/publish-content-ui` (`apps/website/src/features/
 * publish-content/ui/`), next to the planner whose behaviour they restate. This file is the React
 * shell around them: state, effects, and the three port calls. A rule that could drift from
 * `planner.ts` does not belong in this package.
 *
 * ## Why execute is fired from an effect rather than inline after confirm
 *
 * Plan §4 task 11's acceptance criterion is that the dialog *cannot* fire execute without a
 * confirmed plan. Executing inline at the end of `confirmAndPublish` would make that a property of
 * one function's control flow — true today, and one early-return away from not being true. Instead
 * the token only exists inside a `confirmed` phase, {@link confirmationTokenFor} is the only reader,
 * and the execute effect keys off that reader's result. There is no code path in this file that can
 * call `port.executePublish` with anything else.
 *
 * The server enforces the same property independently — `gateway.execute()` re-runs `computePlan()`
 * and hash-compares it against the confirmed token before any write (`features/publish-content/
 * gated-hooks.ts`). This half exists so the operator never sees a button that would 409.
 */

/** The empty state's offer to connect — what replaces the old "configure a peer in Settings" dead
 *  end (`destination.ts`'s header: the connect action lives here, behind Publish, rather than on a
 *  settings screen the owner has to already know to visit). `message` is the server's own sentence
 *  (`AdminPublishDestinationView.message`) verbatim, never rewritten here. */
export interface PublishContentConnectOffer {
  readonly message: string;
  /** `null` on a fresh install with nothing deployed yet — the primary button stays disabled until
   *  there is a candidate to connect to. */
  readonly candidateUrl: string | null;
}

/** Everything `PublishContentDialog.tsx` renders. Nothing here is a raw port or a setter — the
 *  component gets finished strings and booleans, not state to interpret. */
export interface PublishContentConfirmView {
  readonly phase: PublishContentPhase;
  readonly peers: readonly PublishContentPeerSummary[];
  readonly selectedPeerId: string | null;
  /** Choosing a different site discards any plan on screen — a plan belongs to the site that made
   *  it — and is ignored while {@link peerSelectionEnabled} is `false`. */
  readonly onSelectPeer: (peerId: string) => void;
  /** `false` while a plan is being worked out and from the moment the operator commits: there the
   *  site is part of what is already in flight, and changing it could only misdescribe it. */
  readonly peerSelectionEnabled: boolean;
  /** `false` from confirm until the publish has an outcome on screen. The run cannot be aborted
   *  once confirm is sent, so closing then would cancel nothing and only hide whether it worked. */
  readonly dismissible: boolean;
  /** Closes the dialog — the one handler behind Cancel and the backdrop. A no-op while
   *  {@link dismissible} is `false`; Escape follows the same rule. */
  readonly onDismiss: () => void;
  readonly rows: readonly PublishReportRow[];
  /** {@link rows} minus the up-to-date ones, in the same order — what the table always lists. */
  readonly listedRows: readonly PublishReportRow[];
  /** The up-to-date rows, A–Z (owner 2026-09-26): folded behind one {@link upToDateLabel} row and
   *  listed after it only while {@link upToDateExpanded}. */
  readonly upToDateRows: readonly PublishReportRow[];
  /** "N already up to date", or `null` when no row is — then there is no fold row at all. */
  readonly upToDateLabel: string | null;
  readonly upToDateExpanded: boolean;
  readonly onToggleUpToDate: () => void;
  /** How many columns the table has, for a row that spans all of them. */
  readonly columnCount: number;
  readonly summary: PublishReportSummary | null;
  /** The keys of the rows this run would publish — every {@link PublishReportRow.selectable} row the
   *  operator has not unchecked. Rows that are not selectable are never in here. */
  readonly selectedKeys: ReadonlySet<string>;
  /** Owner decision 2026-09-25 — the carried-along media rows ({@link PublishReportRow.includedFor})
   *  that currently publish, because a page/post that uses them is still ticked. Their checkbox is
   *  shown ticked (and never clickable) exactly when the row is in here. */
  readonly carriedAlongKeys: ReadonlySet<string>;
  readonly onToggleRow: (key: string) => void;
  /** Checks every selectable row, or unchecks every one of them when any is currently checked. */
  readonly onToggleAll: () => void;
  /** `false` once the operator has committed (confirming/executing/done) — the report stays on
   *  screen through those phases, but its checkboxes stop being an offer at that point. */
  readonly selectionEnabled: boolean;
  /** Header-checkbox state. `someSelected` is the indeterminate case and is never true at the same
   *  time as `allSelected`. */
  readonly allSelected: boolean;
  readonly someSelected: boolean;
  /**
   * publish-overwrite-live-plan §4/S9. Whether the plan on screen came from a peer that can honour a
   * forced overwrite at all (`plan.liveCanOverwrite`). `true` while there is no plan on screen —
   * harmless, since {@link PublishReportRow.overwritable} rows don't exist yet either.
   */
  readonly liveCanOverwrite: boolean;
  /** The keys currently ticked "Overwrite on live" — a strict subset of every row's own key, never
   *  read for anything but rendering `checked`. */
  readonly overwriteKeys: ReadonlySet<string>;
  /** The rows that carry an "Overwrite on live" box: every {@link PublishReportRow.overwritable} row,
   *  plus every ticked one — a tick turns its row `forced`, and the box must stay to be unticked. */
  readonly overwriteOfferKeys: ReadonlySet<string>;
  /** Whether the overwrite column renders at all: the peer can honour it and some row offers a box. */
  readonly showOverwriteColumn: boolean;
  /** Ticks or unticks one row's "Overwrite on live" box, then immediately re-plans against it (see
   *  this file's `applyOverwriteKeys`) — the report on screen updates to show the tick actually
   *  taking effect (the row turns `forced`) rather than promising something a later Confirm might
   *  refuse. */
  readonly onToggleOverwrite: (key: string) => void;
  /** Ticks every {@link overwriteOfferKeys} row at once, or clears them all when every one already
   *  is — the overwrite column's own header control, independent of {@link onToggleAll}. */
  readonly onToggleAllOverwrite: () => void;
  readonly allOverwriteTicked: boolean;
  readonly someOverwriteTicked: boolean;
  /** Set while at least one box is ticked — the aggregate "this will replace things on the live site"
   *  notice, shown independent of {@link errorMessage}. `null` otherwise. */
  readonly overwriteWarning: string | null;
  /** Set when a ticking re-plan disagrees with what the operator already reviewed (see
   *  `overwriteReplanIsConsistent`) — the live site moved between the first plan and this tick. The
   *  report on screen already shows the new truth; this is the sentence explaining why it changed.
   *  Cleared the moment the ticked set changes again. */
  readonly overwriteMismatch: string | null;
  /** Set when at least one row could be overwritten in principle (`row.overwritable` on an
   *  untouched, unticked report) but the peer this plan targets cannot honour it
   *  (`!liveCanOverwrite`) — the dialog shows this sentence instead of any checkbox. */
  readonly overwriteUnavailable: string | null;
  /** `plan-publish-sections-2026-09-25.md` §2 S2 — the dialog's own `<h2>`, an English copy key the
   *  screen's `t()` resolves the same way it resolves every other string here. Always
   *  `publishScopeTitleKey(props.scope)`; unlike `primaryLabel`, it never changes once a plan lands. */
  readonly title: string;
  /** Owner decision 2026-09-25 — the description line under the title, an English copy key naming
   *  what this dialog sends: `publishScopeDescriptionKey(props.scope)`. */
  readonly description: string;
  /** Which control the forward button is: `start` connects or plans, `confirm` publishes. They
   *  render as two different buttons, never one relabelled in place — see {@link CONFIRM_ARM_DELAY_MS}. */
  readonly primaryKind: PublishPrimaryKind;
  readonly primaryLabel: string;
  readonly primaryDisabled: boolean;
  /** Ignored for {@link CONFIRM_ARM_DELAY_MS} after the confirm control becomes clickable. */
  readonly onPrimary: () => void;
  /** A failed plan/confirm/execute, or a failed peer read. `null` when nothing has gone wrong. */
  readonly errorMessage: string | null;
  /** Set when the whole run refused (a content-hash version mismatch) — a different thing from an
   *  error, and it gets its own sentence rather than being flattened into one. */
  readonly refusalReason: string | null;
  readonly doneMessage: string | null;
  /** The server's own lines for each live menu the run could not repoint (plan §2.7) — reported,
   *  never silent. Empty outside the `done` phase and for a live built before the repoint pass. */
  readonly doneNotices: readonly string[];
  /** The live site's post-publish safety check: one line per published item that landed but won't
   *  show correctly there (e.g. a video whose type is unknown, a missing poster). Empty outside the
   *  `done` phase and for a live built before the check. */
  readonly doneProblems: readonly string[];
  /** One line per type the live site can't take yet (`plan.notSupportedByLive`) — those rows never
   *  reach the report, so this is the only place they show. Empty when the live took everything. */
  readonly liveGapNotices: readonly string[];
  /** Set once peers have loaded empty and the destination check has resolved. `null` while peers
   *  exist, are still loading, or the destination check hasn't resolved yet — see this file's
   *  connect-offer effect. */
  readonly connectOffer: PublishContentConnectOffer | null;
}

const EMPTY_ROWS: readonly PublishReportRow[] = [];

export type PublishPrimaryKind = "start" | "confirm";

/**
 * How long the confirm control ignores activation after it becomes clickable (owner report
 * 2026-09-26). The button used to turn from a disabled "Planning…" into "Publish N items" in place,
 * so a click aimed at "Planning…" that waited for the button to enable — an automated click does
 * exactly that — published to live. Confirm is now its own control, and a click this soon after it
 * appears can't have been aimed at it. It stays enabled meanwhile: a disabled window would only make
 * a waiting click wait for it.
 */
export const CONFIRM_ARM_DELAY_MS = 400;

/** `start` until a plan is on screen (or the run is done), `confirm` from then on. @complexity O(1). */
function primaryKindFor(
  phase: PublishContentPhase,
  connectOffer: PublishContentConnectOffer | null
): PublishPrimaryKind {
  if (connectOffer || canRequestPlan(phase) || phase.kind === "planning") return "start";
  return "confirm";
}

/**
 * Builds the primary button's label. Counted copy is assembled from `t()`-resolved fragments rather
 * than one interpolated key, because this app's translator is a key lookup with no interpolation
 * (`lib/dictionary-translator.ts`) — the alternative is a key per possible count.
 *
 * The connect offer takes priority over every phase check below it: while it is present, the same
 * button IS the connect action (see this file's header note on why one control is reused rather
 * than adding a second button next to a disabled "Publish").
 *
 * @complexity O(1).
 */
function primaryLabelFor(
  phase: PublishContentPhase,
  selectedPublishing: number,
  connectOffer: PublishContentConnectOffer | null,
  connecting: boolean,
  t: Translate,
  scope: PublishScope | undefined,
  onlyLiveGaps: boolean
): string {
  if (connectOffer) return connecting ? t("Connecting…") : t("Connect");
  if (phase.kind === "planning") return t("Planning…");
  if (phase.kind === "confirming" || phase.kind === "executing") return t("Publishing…");
  if (phase.kind === "done") return t("Published");
  // plan-publish-sections-2026-09-25.md §2 S2 — before a plan lands, the idle button promises what
  // this dialog is scoped to, same label as its own title (`publishScopeTitleKey`).
  if (phase.kind !== "planned") return t(publishScopeTitleKey(scope));
  return plannedPrimaryLabel({ selectedPublishing, onlyLiveGaps, t });
}

function plannedPrimaryLabel(
  { selectedPublishing, onlyLiveGaps, t }: { selectedPublishing: number; onlyLiveGaps: boolean; t: Translate },
  _options: Record<string, never> = {}
): string {
  // The SELECTED count, not the plan's own: the button must promise what this click will actually
  // do. A plan of 59 writable rows with 56 unchecked says "Publish 3 items".
  // An empty report whose types the live site simply can't take yet is not "nothing to publish" —
  // the content is there, the live is behind (see `liveGapLinesFor`).
  if (selectedPublishing === 0) return onlyLiveGaps ? t("Update the live site first") : t("Nothing to publish");
  return `${t("Publish")} ${selectedPublishing} ${selectedPublishing === 1 ? t("item") : t("items")}`;
}

/**
 * One line per type the live site can't take yet, e.g. "Forms (7) can't publish yet: the live site
 * needs an update first." The plural type name comes from `PUBLISH_SECTIONS` (`ui/sections.ts`);
 * the count sits in brackets so the sentence reads the same for 1 and for 7 in every locale (this
 * app's translator has no plurals or interpolation — see `primaryLabelFor`).
 *
 * Lines are A–Z by the translated type name — the shared publish-list order (`publish-order.ts`).
 *
 * @complexity O(n log n) in `entries.length`.
 */
export function liveGapLinesFor(
  entries: readonly PublishContentNotSupportedByLive[] | undefined,
  t: Translate,
  locale?: string
): readonly string[] {
  return (entries ?? [])
    .filter((entry) => entry.count > 0)
    .map((entry) => ({ label: t(publishEntityTypePluralLabel(entry.entityType)), count: entry.count }))
    .sort(publishOrderComparator(locale, (line) => ({ group: "blocked", label: line.label })))
    .map((line) => `${line.label} (${line.count}) ${t("can't publish yet: the live site needs an update first.")}`);
}

/**
 * Whether the operator may change which site this dialog publishes to. Only where no request is in
 * flight and nothing is committed: `idle`, a `planned` report still being reviewed, or `failed`.
 * `done` is closed for the same reason `canRequestPlan` excludes it — close and reopen to go again.
 *
 * @complexity O(1).
 */
function peerSelectionOpen(phase: PublishContentPhase): boolean {
  return phase.kind === "idle" || phase.kind === "planned" || phase.kind === "failed";
}

/**
 * The confirmation banner shown once a publish executes: how many entities changed, plus how many
 * live menu links were repointed to follow them (`plan-publish-repoint-menus-2026-09-24.md` §2.7/R6).
 * `doneMessage` is `null` outside the `done` phase, same as the field this replaces.
 *
 * Counted copy is assembled from `t()`-resolved fragments for the same reason `primaryLabelFor` above
 * is: this app's translator has no interpolation. The menu-links clause is appended only when
 * `menuLinksUpdated` is greater than 0 — a run that repointed nothing says nothing about menus at
 * all, rather than a confusing "Menu links updated: 0." `?? 0` covers a peer built before R5, whose
 * `PublishContentExecuteResult` carries no `menuLinksUpdated` at all.
 *
 * @complexity O(n) in actual report rows, with no additional requests.
 */
function completionMessagesFor(
  { phase, t }: { phase: PublishContentPhase; t: Translate },
  _options: Record<string, never> = {}
): Pick<PublishContentConfirmView, "doneMessage" | "doneNotices" | "doneProblems"> {
  if (phase.kind !== "done") return { doneMessage: null, doneNotices: [], doneProblems: [] };
  const base = completionOutcomeMessage({ result: phase.result, t });
  const menuLinksUpdated = phase.result.menuLinksUpdated ?? 0;
  return {
    doneMessage: menuLinksUpdated <= 0 ? base : `${base} ${t("Menu links updated:")} ${menuLinksUpdated}.`,
    // De-duplicated: a grant that doesn't cover menus refuses every menu with the same line.
    doneNotices: [...new Set(phase.result.menuLinksNotUpdated ?? [])],
    doneProblems: [...new Set(phase.result.verificationProblems ?? [])],
  };
}

/** Count actual row outcomes, retaining the count-only reply from older peers.
 * @complexity O(n) actual report rows; no I/O. */
function completionOutcomeMessage({ result, t }: { result: PublishContentExecuteResult; t: Translate }, _options = {}): string {
  const actual = result.report ? summarizePublishReport(toPublishReportRows(result.report)) : null;
  const changeCount = actual?.publishing ?? result.changeSetIds.length;
  const published = publishedCountMessage({ count: changeCount, t });
  const skipped = actual?.skipped ?? 0;
  if (skipped === 0) return published;
  return `${published} ${skipped} ${skipped === 1 ? t("item skipped.") : t("items skipped.")}`;
}

/** Word a completed count, including a run in which every proposed write was refused.
 * @complexity O(1), pure translation. */
function publishedCountMessage({ count, t }: { count: number; t: Translate }, _options = {}): string {
  if (count === 0) return t("Nothing published.");
  return `${t("Published")} ${count} ${count === 1 ? t("change") : t("changes")}.`;
}

/**
 * The overwrite checkbox's `title` — `plan-publish-repoint-menus-2026-09-24.md` §2.7/R6: when the
 * retired holder still feeds a live menu, the tooltip names it too, so an operator ticking
 * "overwrite" can see what else moves with it. `undefined` for a row with no `retires` target at all
 * (`PublishContentDialog.tsx` only renders this control for an offered row in the first place, but
 * the function stays defensive rather than assuming that holds).
 *
 * @complexity O(n) in `referencedByLabels.length` for the join; O(1) otherwise.
 */
export function overwriteTooltipFor(
  row: Pick<PublishReportRow, "retiresLabel" | "referencedByLabels">,
  t: Translate
): string | undefined {
  if (!row.retiresLabel) return undefined;
  const base = `${row.retiresLabel} ${t("moves to")} ${t("Trash")}`;
  if (row.referencedByLabels.length === 0) return base;
  return `${base}. ${t("Menu links follow:")} ${row.referencedByLabels.join(", ")}`;
}

/**
 * The line a row shows under its status (owner 2026-09-26: no mostly-empty "Why" column) — a
 * carried-along row's "Used by …" note, else the row's reason. `null` adds nothing under the pill.
 *
 * @complexity O(1).
 */
export function reportRowNote(row: Pick<PublishReportRow, "usedByNote" | "reason">, t: Translate): string | null {
  if (row.usedByNote) return t(row.usedByNote);
  return row.reason ? row.reason : null;
}

/** Maps a row's disposition to the `.status-*` pill `styles.css` already defines, so the table
 *  reads the same as every other status column in the app in both themes. */
const DISPOSITION_PILL_CLASS = {
  publish: "status status-active",
  unchanged: "status status-draft",
  skipped: "status status-warning",
} as const;

/**
 * The status pill's class: the disposition's, except an update that trashes the item on live
 * (2026-09-26), which takes the app's own Trash styling so it never reads as an ordinary publish.
 *
 * @complexity O(1).
 */
export function reportRowPillClass(row: Pick<PublishReportRow, "disposition" | "trashes">): string {
  return row.trashes ? "status status-trashed" : DISPOSITION_PILL_CLASS[row.disposition];
}

/**
 * Whether a publish has been committed and has no outcome yet: confirm is on its way or answered,
 * or execute is running. From here the live site finishes the run whatever this dialog does (terra
 * review 2026-09-20, finding 3), so the dialog stays open until it can say how that went.
 *
 * @complexity O(1).
 */
function publishInFlight(phase: PublishContentPhase): boolean {
  return phase.kind === "confirming" || phase.kind === "confirmed" || phase.kind === "executing";
}

/**
 * Whether `peerId` is an actually-chosen site, as opposed to the picker's blank placeholder
 * (`PublishContentDialog.tsx`'s `<option value="">`, which fires `onSelectPeer("")`) or nothing
 * chosen at all. Every guard downstream of a peer id — the start gate, the confirm gate, and the
 * execute effect's gate — reads this rather than a bare `!== null`, so an empty string can never slip
 * through one of them into a `planPublish`/`confirmPublish`/`executePublish` call with an empty
 * `:peerId` segment (a confusing 404, since Express can't route an empty path segment, instead of the
 * button simply staying disabled — plan-server.md's BLOCKED-CLAIMED finding, 2026-09-20).
 * `onSelectPeer` below also normalizes `""` to `null` in {@link selectedPeerId} itself, so this
 * belongs to defense in depth for anything that reads {@link planPeerRef} after an `await`, not the
 * only thing standing between the picker and the network.
 * @complexity O(1).
 */
function isChosenPeerId(peerId: string | null): peerId is string {
  return peerId !== null && peerId !== "";
}

/**
 * S2 — what `props.onPlanned` is called with: the SAME `rows`/`selection` the dialog itself renders
 * from, so a chat/WebMCP caller's report can never disagree with what the operator sees on screen.
 *
 * `willOverwrite` is a subset of `willPublish`, not a separate list: a `forced` row is also a row
 * that will be published (plan §2's own `PublishRequestResult` doc says as much — "what would be
 * published or overwritten"), it just publishes BY overwriting. `leftAlone` only ever names a
 * `skipped` row — an `unchanged` row isn't "left alone" by the criteria, it was already a no-op
 * before any criteria existed.
 *
 * @complexity O(rows).
 */
function buildCriteriaPublishResult(
  rows: readonly PublishReportRow[],
  selection: CriteriaSelection,
  siteLabel: string | null
): PublishRequestResult {
  const willPublish: string[] = [];
  const willOverwrite: string[] = [];
  const leftAlone: { label: string; reason: string }[] = [];
  const selected = new Set(selectableRowKeys(rows).filter((key) => !selection.deselectedKeys.has(key)));
  for (const row of rows) {
    // A carried-along media row publishes with the pages/posts that use it (`rowPublishesWithSelection`).
    if (rowPublishesWithSelection(row, selected)) {
      willPublish.push(row.entityLabel);
      if (row.outcome === "forced") willOverwrite.push(row.entityLabel);
      continue;
    }
    // `toPublishReportRows` gives every skipped row a reason (its own MISSING_REASON fallback when the
    // peer sent none), so a skipped row's `reason` is never null here.
    if (row.disposition === "skipped") leftAlone.push({ label: row.entityLabel, reason: row.reason! });
  }
  return {
    opened: true,
    planned: true,
    site: siteLabel,
    willPublish,
    willOverwrite,
    leftAlone,
    unmatchedItems: selection.unmatchedItems,
    unknownTypes: selection.unknownTypes,
    nextStep: "Check the list in the Publish dialog, then click Publish.",
  };
}

/**
 * @param props.onCancel Called when the dialog should close (Escape, Cancel, the backdrop) — never
 *   while a committed publish has no outcome yet; see `publishInFlight`.
 * @param props.t The screen's own bound translator, threaded down rather than resolved again here.
 * @param props.port Dependency injection seam for tests — see `publish-content-port.hooks.ts`.
 * @param props.criteria `publish-criteria-tool-webmcp-plan-2026-09-24.md` §4 S2 — a caller with no
 *   button of its own (chat, WebMCP, or the admin's own `?publish=` deep link) names what it asked
 *   for here. Applied exactly once, against the first plan that lands: it becomes the dialog's
 *   STARTING `deselectedKeys`/overwrite ticks, never a second selection mechanism of its own — see
 *   this file's "S2 — applying criteria" block below, and plan §2's own header for why this can never
 *   itself write anything (planning is read-only; only a person's own click reaches confirm/execute).
 * @param props.scope `plan-publish-sections-2026-09-25.md` §2 S2 — what this dialog is about (a
 *   section button's "Publish pages", say), sent unchanged on every `port.planPublish` call via this
 *   hook's own `planInScope` helper. `undefined` for the Dashboard's own "Publish all content" and
 *   for every criteria-only (chat/WebMCP) open — see `ui/contract.ts`'s `PublishScope` header for why
 *   this is kept separate from `props.criteria`.
 * @param props.onPlanned Fires once, with what the (possibly criteria-narrowed) plan actually shows —
 *   after any overwrite re-plan the criteria triggered has settled, never before. `undefined` for the
 *   Dashboard's own ordinary open (plan §0's caller 1), which has no one waiting on an answer.
 * @param props.confirmArmDelayMs Defaults to {@link CONFIRM_ARM_DELAY_MS}; tests pass 0.
 * @complexity Time: O(n) per re-render in the plan's row count (row shaping + the summary counts);
 * space: O(n) for the shaped rows. Native dialog dismissal is owned by Jini.
 */
/** A replan's scope: just the peer, plus the ticked overwrite keys when there are any. */
function planScope(peerId: string, overwriteKeys: ReadonlySet<string>): { peerId: string; overwriteEntityKeys?: string[] } {
  return overwriteKeys.size === 0 ? { peerId } : { peerId, overwriteEntityKeys: Array.from(overwriteKeys) };
}

/** A confirmable plan with at least one row publishing and no overwrite replan still in flight. */
function canConfirmSelection(
  { phase, selectedPublishing, overwriteReplanPending }: { phase: PublishContentPhase; selectedPublishing: number; overwriteReplanPending: boolean },
): boolean {
  return canConfirmPlan(phase) && selectedPublishing > 0 && !overwriteReplanPending;
}

/** A sole target is unambiguous; multiple targets still require the operator's selection. */
function singlePublishPeerId(peers: readonly PublishContentPeerSummary[]): string | null {
  return peers.length === 1 ? peers[0].id : null;
}

export function usePublishContentConfirm(props: {
  onCancel: () => void;
  t: Translate;
  port?: PublishContentPort;
  criteria?: PublishCriteria;
  scope?: PublishScope;
  onPlanned?: (result: PublishRequestResult) => void;
  confirmArmDelayMs?: number;
}): PublishContentConfirmView {
  const { onCancel, t } = props;
  const port = props.port ?? defaultPublishContentPort;
  const locale = useWiredAdminLocale();

  // plan-publish-sections-2026-09-25.md §2 S2 — the ONE place `scope` reaches `port.planPublish`
  // from, so no bare `port.planPublish` call under this hook can forget it. `props.scope` is fixed
  // for the dialog's whole lifetime (it is not operator-changeable state), so this needs no memo
  // beyond `useCallback`'s own identity stability.
  const planInScope = useCallback(
    (input: { peerId: string; selectedEntityKeys?: readonly string[]; overwriteEntityKeys?: readonly string[] }) =>
      port.planPublish(props.scope === undefined ? input : { ...input, scope: props.scope }),
    [port, props.scope]
  );

  // `live` guards every `setState` that follows an `await`: the dialog is unmounted by its own
  // Cancel button and by Escape, either of which can land while a plan or a publish is in flight.
  const live = useRef(true);
  useEffect(() => {
    live.current = true;
    return () => {
      live.current = false;
    };
  }, []);

  const [phase, setPhase] = useState<PublishContentPhase>({ kind: "idle" });
  // Load the target list before offering destination discovery for an empty install.
  const [peers, setPeers] = useState<readonly PublishContentPeerSummary[]>([]);
  const [peersLoaded, setPeersLoaded] = useState(false);
  const [selectedPeerId, setSelectedPeerId] = useState<string | null>(null);
  const [peersError, setPeersError] = useState<string | null>(null);

  // The empty state's connect offer — only ever populated when the peer list comes back empty (see
  // the effect below). `destination` and `destinationError` are mutually exclusive with each other,
  // same convention as `peers`/`peersError`.
  const [destination, setDestination] = useState<AdminPublishDestinationView | null>(null);
  const [destinationLoaded, setDestinationLoaded] = useState(false);
  const [destinationError, setDestinationError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    const readDestination = async (_required: Record<string, never>, _options: Record<string, never> = {}) => {
      try {
        const view = await port.getDestination();
        if (cancelled || !live.current) return;
        setDestination(view);
      } catch (destinationErr) {
        if (cancelled || !live.current) return;
        setDestinationError(
          describeApiError(destinationErr, t("Could not check whether this install can publish yet."))
        );
      } finally {
        if (!cancelled && live.current) setDestinationLoaded(true);
      }
    };
    void (async () => {
      try {
        const { peers: loaded } = await port.listPeers();
        if (cancelled || !live.current) return;
        setPeers(loaded);
        // Auto-select when there is exactly one target: the overwhelmingly common case is a single
        // production peer, and making the operator pick it from a list of one is friction with no
        // decision behind it. With two or more, the dialog asks.
        setSelectedPeerId(singlePublishPeerId(loaded));
        // Nothing to publish to yet — check whether this install can offer a one-click connect
        // instead of failing shut. Sequenced after `listPeers` rather than fired in parallel: the
        // common case (already connected) never needs this second call at all.
        if (loaded.length === 0) {
          await readDestination({});
        }
      } catch (error) {
        if (cancelled || !live.current) return;
        setPeersError(describeApiError(error, t("Could not load publish targets.")));
      } finally {
        if (!cancelled && live.current) setPeersLoaded(true);
      }
    })();
    return () => {
      cancelled = true;
    };
    // `t` is read only for a fallback string and is deliberately NOT a dependency: a caller whose
    // translator is a fresh closure each render would otherwise refetch the peer list on every
    // render. The worst case is a fallback sentence in a stale locale.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [port]);

  const connectOffer = publishConnectOffer({
    peersLoaded,
    peers,
    peersError,
    destinationLoaded,
    destination,
  });

  const [connecting, setConnecting] = useState(false);

  // Stored as what the operator UNCHECKED, not as what is checked. "All checked by default" is then
  // the empty set rather than a value that has to be seeded from the plan the moment it arrives —
  // there is no effect to forget, no window where the rows render before the seeding lands, and a
  // re-plan's new rows arrive checked without anything having to re-seed them.
  const [deselectedKeys, setDeselectedKeys] = useState<ReadonlySet<string>>(() => new Set());

  // publish-overwrite-live-plan §4/S9 — the "Overwrite on live" ticks. Kept as its own state, never
  // folded into `deselectedKeys`: unchecking a row means "don't publish this", ticking here means
  // "resolve this skip by overwriting live", and the two are independent (a ticked row is also, once
  // it turns `forced`, a selectable row that can itself still be deselected).
  const [overwriteKeys, setOverwriteKeys] = useState<ReadonlySet<string>>(() => new Set());
  // Set only when a ticking re-plan finds the live site moved since the plan the operator is looking
  // at — cleared the instant the ticked set changes again, since a fresh re-plan speaks for itself.
  const [overwriteMismatch, setOverwriteMismatch] = useState<string | null>(null);
  // The plan `requestPlan` most recently landed for the CURRENT peer, before any overwrite tick —
  // what unticking the last box goes back to without a network call. Reset alongside
  // `overwriteKeys` on every fresh plan, and marked stale (`basePlanStaleRef`) the moment a ticking
  // re-plan shows live moved since: from then on it no longer describes live, so unticking the last
  // box asks live again instead of putting an out-of-date list back on screen.
  const basePlanRef = useRef<PublishContentPlanResult | null>(null);
  const basePlanStaleRef = useRef(false);
  // The ticked set as of the MOST RECENT `applyOverwriteKeys` call, read synchronously inside that
  // call's own async continuation so a superseded tick's response never overwrites a newer one's —
  // the same shape as `planPeerRef`'s "answering for a peer we've left" guard, one level down.
  const overwriteKeysRef = useRef<ReadonlySet<string>>(new Set());
  // Whether a ticking re-plan is still out. While it is, the plan on screen is not the one the ticks
  // describe, so confirming it would publish WITHOUT the overwrite just asked for — and the late
  // re-plan would then be dropped as answering a phase that has moved on. The ref is the synchronous
  // guard `confirmPlan` reads; the state is what disables the button.
  const overwriteReplanPendingRef = useRef(false);
  const [overwriteReplanPending, setOverwriteReplanPending] = useState(false);
  const setReplanPending = useCallback((pending: boolean): void => {
    overwriteReplanPendingRef.current = pending;
    setOverwriteReplanPending(pending);
  }, []);

  const dismissible = !publishInFlight(phase);
  const onDismiss = (): void => {
    if (dismissible) onCancel();
  };

  // The site the current phase's plan was requested from — what confirm and execute address, never
  // the picker's value at click time (terra review 2026-09-20, finding 2). `PublishContentPlanResult`
  // carries no peer id of its own, so the binding is kept here: set when a plan is requested, cleared
  // when the operator picks another site. A ref because `requestPlan` compares against it after an
  // `await`, where a state read would be the stale closure value.
  const planPeerRef = useRef<string | null>(null);

  // Takes `peerId` explicitly rather than reading `selectedPeerId` off closure: `onConnect` below
  // calls this in the same tick it learns the newly-connected peer's id, before that `setState` has
  // committed, so a closure read here would still see `null`.
  //
  // Guards with `isChosenPeerId` itself rather than trusting every caller to check first (a3-review-4
  // handoff, 2026-09-21): `onConnect` calls this with whatever `site.id` `connectDestination` answers,
  // with no check of its own — a contract violation there would otherwise reach
  // `port.planPublish({ peerId: "" })` unguarded. This is the one function every network call in this
  // hook goes through, so the guard belongs here, not repeated (and possibly forgotten) at each caller.
  const requestPlan = useCallback(
    async (peerId: string) => {
      if (!isChosenPeerId(peerId)) return;
      planPeerRef.current = peerId;
      setPhase({ kind: "planning" });
      try {
        const plan = await planInScope({ peerId });
        // A plan answering for a site the dialog is no longer pointed at is dropped, not shown.
        if (!live.current || planPeerRef.current !== peerId) return;
        // A fresh top-level plan is the new baseline every overwrite tick gets checked against, and
        // starts with nothing ticked — same reasoning as `deselectedKeys` resetting on a re-plan.
        basePlanRef.current = plan;
        basePlanStaleRef.current = false;
        overwriteKeysRef.current = new Set();
        setOverwriteKeys(new Set());
        setOverwriteMismatch(null);
        setReplanPending(false);
        setPhase({ kind: "planned", plan });
      } catch (error) {
        if (!live.current || planPeerRef.current !== peerId) return;
        setPhase({
          kind: "failed",
          message: describeApiError(error, t("Could not work out what would be published.")),
          code: null,
        });
      }
    },
    [planInScope, setReplanPending, t]
  );

  /**
   * The core of S9's "ticking re-plans" flow. Re-plans with `nextOverwriteKeys` and puts the result
   * on screen; when it disagrees with the report the operator was looking at
   * (`overwriteReplanIsConsistent`), it adds the mismatch sentence too. A `planned` phase is the only
   * one this ever fires from — ticking is offered only while a report is up for review.
   *
   * `nextOverwriteKeys.size === 0` (the operator unticked the last box) goes straight back to
   * `basePlanRef.current` with no network call — unless a mismatch has shown that plan no longer
   * describes live, in which case live is asked again (with no keys).
   */
  const applyOverwriteKeys = useCallback(
    (nextOverwriteKeys: ReadonlySet<string>) => {
      const peerId = planPeerRef.current;
      const base = basePlanRef.current;
      if (!isChosenPeerId(peerId) || base === null || phase.kind !== "planned") return;
      const shown = phase.plan;
      // Keys ticked or unticked by this click, plus any still in flight from an earlier one: the
      // consistency check compares everything ELSE between the screen and the answer.
      const changing = new Set([...overwriteKeysRef.current, ...nextOverwriteKeys]);
      overwriteKeysRef.current = nextOverwriteKeys;
      setOverwriteKeys(nextOverwriteKeys);
      setOverwriteMismatch(null);
      const useBase = nextOverwriteKeys.size === 0 && !basePlanStaleRef.current;
      setReplanPending(!useBase);
      // Superseded by a newer tick, a peer switch, or an unmount while this was in flight.
      const isCurrentReplan = (_required: Record<string, never>, _options: Record<string, never> = {}): boolean =>
        live.current && planPeerRef.current === peerId && overwriteKeysRef.current === nextOverwriteKeys;
      void (async () => {
        try {
          const replanned = useBase
            ? base
            : await planInScope(planScope(peerId, nextOverwriteKeys));
          if (!isCurrentReplan({})) return;
          setReplanPending(false);
          if (
            !useBase &&
            !overwriteReplanIsConsistent({
              shown: shown.details,
              next: replanned.details,
              tickedKeys: nextOverwriteKeys,
              changing,
            })
          ) {
            basePlanStaleRef.current = true;
            setOverwriteMismatch(publishMismatchMessage({ peers, peerId, t }));
          }
          setPhase((current) => (current.kind === "planned" ? { kind: "planned", plan: replanned } : current));
        } catch (error) {
          if (!isCurrentReplan({})) return;
          setReplanPending(false);
          setPhase({
            kind: "failed",
            message: describeApiError(error, t("Could not work out what would be published.")),
            code: null,
          });
        }
      })();
    },
    [peers, phase, planInScope, setReplanPending, t]
  );

  const onToggleOverwrite = useCallback(
    (key: string): void => {
      const next = new Set(overwriteKeysRef.current);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      applyOverwriteKeys(next);
    },
    [applyOverwriteKeys]
  );

  // The connect action behind the empty state — `destination.ts`'s header explains why it lives
  // here rather than on a settings screen. Success folds the newly connected site straight into
  // `peers`/`selectedPeerId` and moves on to planning immediately: the operator asked to publish,
  // not to "connect", so the one extra click stays inside the same flow rather than landing back on
  // a now-idle dialog they'd have to press Publish on again.
  // Re-entry is already blocked one level up: `onConnect` is only reached through `onPrimary`, whose
  // `primaryInFlightRef` holds until this promise settles (and `connecting` is reset before it does),
  // so a second press can never land while a connect runs.
  const onConnect = useCallback(async () => {
    setConnecting(true);
    setDestinationError(null);
    try {
      const view = await port.connectDestination();
      if (!live.current) return;
      if (view.site === null) {
        // Contract violation, not a user-facing failure mode: `destination.ts`'s `/connect` always
        // returns a site on success. Guarded rather than assumed so a server regression here shows
        // up as a sentence instead of a crash.
        setDestinationError(t("Could not connect."));
        setConnecting(false);
        return;
      }
      const { site } = view;
      setPeers([site]);
      setSelectedPeerId(site.id);
      setConnecting(false);
      void requestPlan(site.id);
    } catch (error) {
      if (!live.current) return;
      setDestinationError(describeApiError(error, t("Could not connect.")));
      setConnecting(false);
    }
  }, [port, requestPlan, t]);

  const reportConfirmFailure = useCallback(
    ({ error, peerId }: { error: unknown; peerId: string }, _options: Record<string, never> = {}): void => {
      // The narrowed re-plan writes a different set than the one reviewed: put that plan on screen
      // with the same sentence a drifting overwrite tick gets, rather than confirming unseen rows.
      if (error instanceof PublishPlanDriftError) {
        basePlanStaleRef.current = true;
        setOverwriteMismatch(publishMismatchMessage({ peers, peerId, t }));
        setPhase({ kind: "planned", plan: error.plan });
        return;
      }
      setPhase({ kind: "failed", message: describeApiError(error, t("Could not publish.")), code: null });
    },
    [peers, t]
  );

  const confirmPreparedPlan = useCallback(
    async (
      { peerId, confirmed }: { peerId: string; confirmed: PublishContentPlanResult },
      _options: Record<string, never> = {}
    ): Promise<void> => {
      if (!live.current) return;
      if (!canConfirmPlan({ kind: "planned", plan: confirmed })) {
        setPhase({ kind: "planned", plan: confirmed });
        return;
      }
      const { confirmationToken } = await port.confirmPublish({
        peerId,
        planId: confirmed.planId,
        planHash: confirmed.planHash,
      });
      if (!live.current) return;
      setPhase({ kind: "confirmed", plan: confirmed, confirmationToken });
    },
    [port]
  );

  /**
   * Confirms the plan on screen — and, when the operator unchecked rows, RE-PLANS first against a
   * bundle narrowed to what is still checked, then confirms THAT plan.
   *
   * The re-plan is what makes a deselection real. A confirmation token is bound to one plan hash, and
   * the destination applies the bundle it planned — so the only way to publish a subset is to give
   * the destination that subset to plan in the first place (`export-bundle.ts`'s
   * `selectBundleEntities`, via `push/plan`'s `selectedEntityKeys`). The alternative, carrying a
   * selection into execute for the apply loop to honour, would put the operator's exclusion behind a
   * flag a destination running an older build would silently ignore and publish everything anyway.
   *
   * A narrowed re-plan that turns out to write nothing lands back on `planned` with the narrowed
   * rows showing rather than confirming a run that would burn a restore point to do nothing.
   */
  const confirmPlan = useCallback(async () => {
    const peerId = planPeerRef.current;
    if (!isChosenPeerId(peerId) || phase.kind !== "planned") return;
    if (!canConfirmPlan(phase)) return;
    // The plan on screen is not yet the one the operator's latest tick describes.
    if (overwriteReplanPendingRef.current) return;
    const { plan } = phase;
    const planRows = toPublishReportRows(plan.details);
    const selectable = selectableRowKeys(planRows);
    const keep = selectable.filter((key) => !deselectedKeys.has(key));
    if (keep.length === 0) return;
    // A carried-along media row is never selectable, so it is never in `keep` — but it still publishes
    // while a page/post using it is kept, and the narrowed re-plan carries it again. Its "Overwrite on
    // live" tick must survive with it, or that page publishes against the old live image.
    setPhase({ kind: "confirming", plan });
    try {
      // Carries `plan.overwriteEntityKeys` (already echoed onto `plan` by any ticking re-plan)
      // into this narrowing re-plan too — deselecting an unrelated row must never silently
      // drop an "Overwrite on live" tick. A ticked row the operator ALSO unchecked is not in
      // `keep`, so its key is dropped here: an overwrite of something not being published
      // would only ask live to force a row the bundle doesn't carry.
      const confirmed = await preparePublishConfirmation({
        plan,
        deselectedKeys,
        planPublish: (input) => planInScope({ peerId, ...input }),
      });
      await confirmPreparedPlan({ peerId, confirmed });
    } catch (error) {
      if (!live.current) return;
      reportConfirmFailure({ error, peerId });
    }
  }, [confirmPreparedPlan, deselectedKeys, phase, planInScope, reportConfirmFailure]);

  // The ONLY call site of `port.executePublish` in this package. Its input is whatever
  // `confirmationTokenFor` returns, which is `null` for every phase but `confirmed`/`executing` —
  // see this file's header for why the guard is shaped this way rather than as an inline check.
  const executionToken = confirmationTokenFor(phase);
  useEffect(() => {
    const peerId = planPeerRef.current;
    if (executionToken === null || phase.kind !== "confirmed" || !isChosenPeerId(peerId)) return;
    const { plan } = phase;
    setPhase({ kind: "executing", plan, confirmationToken: executionToken });
    void (async () => {
      try {
        // `plan.bundleId` travels from the plan response into the execute call — the peer refuses a
        // token presented against any bundle but the one it planned. `plan.overwriteEntityKeys` is
        // the CONFIRMED plan's own echoed value (S9) — never re-read from operator state here, so
        // execute can only ever force the exact set the confirmation token was issued for.
        const result = await port.executePublish({
          peerId,
          bundleId: plan.bundleId,
          confirmationToken: executionToken,
          ...(plan.overwriteEntityKeys && plan.overwriteEntityKeys.length > 0
            ? { overwriteEntityKeys: plan.overwriteEntityKeys }
            : {}),
        });
        if (!live.current) return;
        setPhase({ kind: "done", result });
      } catch (error) {
        if (!live.current) return;
        setPhase({ kind: "failed", message: describeApiError(error, t("Could not publish.")), code: null });
      }
    })();
  }, [executionToken, phase, port, t]);

  const {
    visiblePlan,
    rows,
    summary,
    listedRows,
    upToDateRows,
    liveGapNotices,
    selectableKeys,
    selectedKeys,
    selectedPublishing,
    carriedAlongKeys,
    allSelected,
    someSelected,
  } = publishReportSelection({ phase, locale, t, deselectedKeys });
  const [upToDateExpanded, setUpToDateExpanded] = useState(false);
  const onToggleUpToDate = useCallback(() => setUpToDateExpanded((open) => !open), []);

  const {
    liveCanOverwrite,
    overwritableRows,
    overwriteOfferKeys,
    showOverwriteColumn,
    allOverwriteTicked,
    someOverwriteTicked,
  } = publishOverwriteSelection({ visiblePlan, rows, overwriteKeys });
  // Ticks every offered row — earlier ticks included — or clears them all when every one already is.
  const onToggleAllOverwrite = (): void => {
    applyOverwriteKeys(allOverwriteTicked ? new Set() : new Set(overwriteOfferKeys));
  };
  const currentPeerLabel = peers.find((peer) => peer.id === selectedPeerId)?.label ?? t("the live site");

  // --- S2 (publish-criteria-tool-webmcp-plan-2026-09-24.md §4) — applying `props.criteria` as the
  // dialog's STARTING selection, for a caller with no button of its own to click. Three refs, because
  // this happens at most once per mount and each step waits on the one before it settling:
  //   1. `criteriaAutoPlanRef` — plans automatically once a site is resolved, standing in for the
  //      click a person would otherwise make first (planning writes nothing, so this is safe to do
  //      unprompted — the gate in plan §3 is about confirm/execute, never about a read-only plan).
  //   2. `criteriaAppliedRef` — applies the criteria's selection/overwrite ticks against that FIRST
  //      plan and only that one; a later re-plan (a peer switch, a hand tick) is left alone.
  //   3. `criteriaAwaitingReplanRef` — set only when the criteria ticked something, so `onPlanned`
  //      waits for that re-plan's real `forced` rows instead of reporting the pre-overwrite skips.
  const criteriaAutoPlanRef = useRef(false);
  const criteriaAppliedRef = useRef(false);
  const criteriaSelectionRef = useRef<CriteriaSelection | null>(null);
  const criteriaAwaitingReplanRef = useRef(false);

  useEffect(() => {
    if (props.criteria === undefined || criteriaAutoPlanRef.current) return;
    if (phase.kind !== "idle" || !isChosenPeerId(selectedPeerId)) return;
    criteriaAutoPlanRef.current = true;
    void requestPlan(selectedPeerId);
  }, [props.criteria, selectedPeerId, phase, requestPlan]);

  useEffect(() => {
    if (props.criteria === undefined || criteriaAppliedRef.current || phase.kind !== "planned") return;
    criteriaAppliedRef.current = true;
    const sel = applyPublishCriteria(toPublishReportRows(phase.plan.details), props.criteria);
    criteriaSelectionRef.current = sel;
    setDeselectedKeys(sel.deselectedKeys);
    if (sel.overwriteKeys.size > 0) {
      criteriaAwaitingReplanRef.current = true;
      applyOverwriteKeys(sel.overwriteKeys);
    }
    // `applyOverwriteKeys`/`props.criteria` deliberately excluded: this must run against the render
    // where `phase` FIRST becomes "planned" (so `applyOverwriteKeys`'s own `phase.kind==="planned"`
    // guard is current, not stale — see this block's own header), and it self-guards with the ref
    // against ever running a second time regardless of what else changes identity around it.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase]);

  useEffect(() => {
    const sel = criteriaSelectionRef.current;
    if (sel === null || phase.kind !== "planned" || props.onPlanned === undefined) return;
    if (criteriaAwaitingReplanRef.current) {
      // The real (not stale-closure) current value — see this file's header on why `requestPlan`
      // can't read `phase` this way but a ref always can.
      if (overwriteReplanPendingRef.current) return;
      criteriaAwaitingReplanRef.current = false;
    }
    criteriaSelectionRef.current = null;
    const siteLabel = peers.find((peer) => peer.id === selectedPeerId)?.label ?? null;
    props.onPlanned(buildCriteriaPublishResult(rows, sel, siteLabel));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase, rows]);

  const { overwriteWarning, overwriteUnavailable } = publishOverwriteNotices({
    liveCanOverwrite,
    overwriteKeys,
    overwritableRows,
    currentPeerLabel,
    t,
  });

  // Checkboxes are an offer, and the offer closes the moment the operator commits: `planned` is the
  // only phase where changing the selection could still change what gets published.
  const selectionEnabled = phase.kind === "planned";

  const onToggleRow = (key: string): void => {
    setDeselectedKeys((current) => {
      const next = new Set(current);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  // "Any checked -> uncheck everything", so the header is an escape hatch from a big plan rather
  // than a toggle whose meaning flips at an invisible halfway point.
  const onToggleAll = (): void => {
    setDeselectedKeys(selectedKeys.size > 0 ? new Set(selectableKeys) : new Set());
  };

  const peerSelectionEnabled = peerSelectionOpen(phase);
  const onSelectPeer = (peerId: string): void => {
    // The picker's blank "Choose a site…" option fires this with `""` (its `value`) — normalized to
    // `null` here so `selectedPeerId` can never hold it, the same "nothing chosen" state a fresh
    // dialog starts in. This is the fix, not just a defense: every downstream guard reads
    // `selectedPeerId`/`planPeerRef` off THIS state, so keeping it out from the start is what makes
    // `isChosenPeerId`'s other call sites redundant-but-safe rather than load-bearing on their own.
    const normalized = peerId === "" ? null : peerId;
    if (!peerSelectionEnabled || normalized === selectedPeerId) return;
    setSelectedPeerId(normalized);
    // The report on screen, and the rows unchecked in it, describe the site being left.
    planPeerRef.current = null;
    setPhase({ kind: "idle" });
    setDeselectedKeys(new Set());
    basePlanRef.current = null;
    basePlanStaleRef.current = false;
    setReplanPending(false);
    overwriteKeysRef.current = new Set();
    setOverwriteKeys(new Set());
    setOverwriteMismatch(null);
  };

  const runPrimary = useCallback((): Promise<void> => {
    if (connectOffer) return onConnect();
    if (!canRequestPlan(phase)) return confirmPlan();
    return isChosenPeerId(selectedPeerId) ? requestPlan(selectedPeerId) : Promise.resolve();
  }, [confirmPlan, connectOffer, onConnect, phase, requestPlan, selectedPeerId]);

  const primaryKind = primaryKindFor(phase, connectOffer);
  const primaryDisabled = publishPrimaryDisabled({
    phase,
    selectedPeerId,
    connectOffer,
    connecting,
    selectedPublishing,
    overwriteReplanPending,
  });

  // When the confirm control last became clickable (appeared, or re-enabled after a tick's re-plan).
  // A layout effect, so the stamp lands before the browser can deliver a click to the new control.
  const confirmArmDelayMs = props.confirmArmDelayMs ?? CONFIRM_ARM_DELAY_MS;
  const confirmClickable = primaryKind === "confirm" && !primaryDisabled;
  const confirmClickableSinceRef = useRef(0);
  useLayoutEffect(() => {
    if (confirmClickable) confirmClickableSinceRef.current = performance.now();
  }, [confirmClickable]);

  // Synchronous duplicate-submit guard (terra review 2026-09-20, finding 5's sibling). The button's
  // `disabled` is render-time phase; two calls in one tick both see `planned`, and each confirmed
  // phase would fire its own execute at the live site. Held until the step's own request settles.
  const primaryInFlightRef = useRef(false);
  const onPrimary = useCallback(() => {
    if (primaryKind === "confirm" && performance.now() - confirmClickableSinceRef.current < confirmArmDelayMs) return;
    if (primaryInFlightRef.current) return;
    primaryInFlightRef.current = true;
    void runPrimary().finally(() => {
      primaryInFlightRef.current = false;
    });
  }, [confirmArmDelayMs, primaryKind, runPrimary]);

  return {
    phase,
    peers,
    selectedPeerId,
    onSelectPeer,
    peerSelectionEnabled,
    dismissible,
    onDismiss,
    rows,
    listedRows,
    upToDateRows,
    upToDateLabel: upToDateRows.length > 0 ? `${upToDateRows.length} ${t("already up to date")}` : null,
    upToDateExpanded,
    onToggleUpToDate,
    // Select, Type, Item, What happens — plus Overwrite on live while it shows.
    columnCount: showOverwriteColumn ? 5 : 4,
    summary,
    selectedKeys,
    carriedAlongKeys,
    onToggleRow,
    onToggleAll,
    selectionEnabled,
    allSelected,
    someSelected,
    liveCanOverwrite,
    overwriteKeys,
    overwriteOfferKeys,
    showOverwriteColumn,
    onToggleOverwrite,
    onToggleAllOverwrite,
    allOverwriteTicked,
    someOverwriteTicked,
    overwriteWarning,
    overwriteMismatch,
    overwriteUnavailable,
    title: publishScopeTitleKey(props.scope),
    description: publishScopeDescriptionKey(props.scope),
    primaryLabel: primaryLabelFor(
      phase,
      selectedPublishing,
      connectOffer,
      connecting,
      t,
      props.scope,
      rows.length === 0 && liveGapNotices.length > 0
    ),
    primaryKind,
    primaryDisabled,
    onPrimary,
    ...publishPhaseMessages({ phase, peersError, destinationError, t }),
    liveGapNotices,
    connectOffer,
  };
}

/** Derive the report and checked selection from the existing publish UI rules. */
function publishReportSelection(
  {
    phase,
    locale,
    t,
    deselectedKeys,
  }: { phase: PublishContentPhase; locale: string; t: Translate; deselectedKeys: ReadonlySet<string> },
  _options: Record<string, never> = {}
) {
  // The report stays on screen through confirm and execute — `planOnScreen` owns which phases have
  // one, so this file never has to re-enumerate them (and cannot get `planning`, which has no plan
  // yet, wrong).
  const visiblePlan = planOnScreen(phase);
  const report = reportOnScreen({ phase });
  // Display order only (owner rule 2026-09-26, `publish-order.ts`): to publish, then skipped, then up
  // to date, A–Z in each. Selection and re-plans go by row key, so the order never reaches the plan.
  const rows =
    report === null ? EMPTY_ROWS : sortPublishReportRows(toPublishReportRows(report, { completed: phase.kind === "done" }), locale);
  const summary = report === null || phase.kind === "done" ? null : summarizePublishReport(rows);
  // Owner 2026-09-26 — up-to-date rows fold into one row. They already sort last (`publish-order.ts`),
  // so splitting them off keeps both halves in the shared order.
  const listedRows = rows.filter((row) => row.disposition !== "unchanged");
  const upToDateRows = rows.filter((row) => row.disposition === "unchanged");
  const liveGapNotices = liveGapLinesFor(visiblePlan?.notSupportedByLive, t, locale);

  // Derived every render rather than stored: `deselectedKeys` is the only state, so these can never
  // disagree with it or with the rows currently on screen.
  const selectableKeys = selectableRowKeys(rows);
  const selectedKeys: ReadonlySet<string> = new Set(selectableKeys.filter((key) => !deselectedKeys.has(key)));
  const selectedPublishing = countSelectedPublishing(rows, selectedKeys);
  const carriedAlongKeys: ReadonlySet<string> = new Set(
    rows
      .filter((row) => row.includedFor.length > 0 && rowPublishesWithSelection(row, selectedKeys))
      .map((row) => row.key)
  );
  const allSelected = selectableKeys.length > 0 && selectedKeys.size === selectableKeys.length;
  const someSelected = selectedKeys.size > 0 && !allSelected;

  return {
    visiblePlan,
    rows,
    summary,
    listedRows,
    upToDateRows,
    liveGapNotices,
    selectableKeys,
    selectedKeys,
    selectedPublishing,
    carriedAlongKeys,
    allSelected,
    someSelected,
  };
}

/** Keep overwrite affordances visible after their rows become forced. */
function publishOverwriteSelection(
  {
    visiblePlan,
    rows,
    overwriteKeys,
  }: {
    visiblePlan: PublishContentPlanResult | null;
    rows: readonly PublishReportRow[];
    overwriteKeys: ReadonlySet<string>;
  },
  _options: Record<string, never> = {}
) {
  // publish-overwrite-live-plan §4/S9. `true` with no plan on screen is harmless: `overwritableRows`
  // is empty then too, so nothing reads this as "go ahead and offer a box".
  const liveCanOverwrite = visiblePlan?.liveCanOverwrite ?? true;
  const overwritableRows = rows.filter((row) => row.overwritable);
  // A ticked row keeps its box: once its re-plan lands it is `forced`, no longer `overwritable`, and
  // dropping the box then would leave a tick the operator can neither see nor undo — and, for the
  // only such row, take the whole column (and its header box) with it.
  const overwriteOfferKeys: ReadonlySet<string> = new Set(
    rows.filter((row) => row.overwritable || overwriteKeys.has(row.key)).map((row) => row.key)
  );
  const showOverwriteColumn = visiblePlan !== null && liveCanOverwrite && overwriteOfferKeys.size > 0;
  const allOverwriteTicked =
    overwriteOfferKeys.size > 0 && [...overwriteOfferKeys].every((key) => overwriteKeys.has(key));
  const someOverwriteTicked = overwriteKeys.size > 0 && !allOverwriteTicked;

  return {
    liveCanOverwrite,
    overwritableRows,
    overwriteOfferKeys,
    showOverwriteColumn,
    allOverwriteTicked,
    someOverwriteTicked,
  };
}

function publishOverwriteNotices(
  {
    liveCanOverwrite,
    overwriteKeys,
    overwritableRows,
    currentPeerLabel,
    t,
  }: {
    liveCanOverwrite: boolean;
    overwriteKeys: ReadonlySet<string>;
    overwritableRows: readonly PublishReportRow[];
    currentPeerLabel: string;
    t: Translate;
  },
  _options: Record<string, never> = {}
) {
  const overwriteWarning =
    liveCanOverwrite && overwriteKeys.size > 0
      ? t("Ticked items will replace what's on the live site, and stay recoverable in its Trash or history.")
      : null;

  // Shown only when the peer itself can't honour the overwrite AND there is something it would
  // otherwise have offered — an older live with a plain unchanged/created/applied report says nothing
  // extra here.
  const overwriteUnavailable =
    !liveCanOverwrite && overwritableRows.length > 0
      ? `${currentPeerLabel} ${t("is on an older Tovu and can't overwrite these yet. Update it, then publish again.")}`
      : null;

  return { overwriteWarning, overwriteUnavailable };
}

function publishPhaseMessages(
  {
    phase,
    peersError,
    destinationError,
    t,
  }: { phase: PublishContentPhase; peersError: string | null; destinationError: string | null; t: Translate },
  _options: Record<string, never> = {}
) {
  return {
    errorMessage: peersError ?? destinationError ?? (phase.kind === "failed" ? phase.message : null),
    refusalReason: phase.kind === "planned" && phase.plan.details.refused ? phase.plan.details.refusalReason : null,
    ...completionMessagesFor({ phase, t }),
  };
}

function publishPrimaryDisabled(
  {
    phase,
    selectedPeerId,
    connectOffer,
    connecting,
    selectedPublishing,
    overwriteReplanPending,
  }: {
    phase: PublishContentPhase;
    selectedPeerId: string | null;
    connectOffer: PublishContentConnectOffer | null;
    connecting: boolean;
    selectedPublishing: number;
    overwriteReplanPending: boolean;
  },
  _options: Record<string, never> = {}
): boolean {
  const canStart = canRequestPlan(phase) && isChosenPeerId(selectedPeerId);
  return connectOffer
    ? connecting || connectOffer.candidateUrl === null
    : // `selectedPublishing` is ANDed with the plan-level rule, never a replacement for it: a plan
      // that may not be confirmed at all stays disabled whatever is checked, and a confirmable
      // plan with everything unchecked is disabled too — the button never promises a run that
      // would write nothing.
      !(canStart || canConfirmSelection({ phase, selectedPublishing, overwriteReplanPending }));
}

/** The sentence shown when live answered differently from the report on screen. Names the site
 *  from the loaded list, or a generic "the live site" when that list does not name `peerId`
 *  (`onSelectPeer` accepts any id). @complexity O(peers). */
export function publishMismatchMessage(
  { peers, peerId, t }: { peers: readonly PublishContentPeerSummary[]; peerId: string; t: Translate },
  _options: Record<string, never> = {}
): string {
  const peerLabel = peers.find((peer) => peer.id === peerId)?.label ?? t("the live site");
  return `${peerLabel} ${t("changed while you were deciding. Check the list again.")}`;
}

/** The empty-install connection offer, once both discovery reads have settled successfully. */
function publishConnectOffer(
  { peersLoaded, peers, peersError, destinationLoaded, destination }: {
    peersLoaded: boolean;
    peers: readonly PublishContentPeerSummary[];
    peersError: string | null;
    destinationLoaded: boolean;
    destination: AdminPublishDestinationView | null;
  },
  _options: Record<string, never> = {}
): PublishContentConnectOffer | null {
  // `null` until BOTH the peer list came back empty and the destination check that follows it has
  // resolved — so the dialog never flashes a stale "add one in Settings" sentence, and never shows
  // the connect offer a beat before it has anything real to say.
  const noPeers = peersLoaded && peers.length === 0 && peersError === null;
  if (!noPeers || !destinationLoaded || destination === null) return null;
  return { message: destination.message, candidateUrl: destination.candidateUrl };
}

import { publishSectionById, type PublishSectionId } from "@tovu/publish-content-ui";

import { useWiredAdminLocale } from "../../../hooks/use-admin-locale.hooks";
import { t as translateDashboard } from "../../dashboard/dashboard-i18n";
import { usePublishToLiveAvailable } from "./publish-availability.store";
import { requestPublish } from "./publish-request.store";

/**
 * @file `plan-publish-sections-2026-09-25.md` §2 S3 / plan G1 — the hook behind each list page's own
 * "Publish <section>" button. Kept out of `PublishSectionButton.tsx` per the house rule that component
 * logic belongs in a hook, not the `.tsx` — the component only reads `{ label, onClick }` back.
 *
 * Label and scope both come from the one section table (`@tovu/publish-content-ui`'s
 * `PUBLISH_SECTIONS`), and a click opens the SAME dialog the Dashboard wired (`requestPublish`) — a
 * section button never plans or publishes anything itself, it only narrows what the dialog opens
 * scoped to.
 */

export type { PublishSectionId };

export interface PublishSectionButtonController {
  /** `false` on the live site, where there is nowhere to publish to — see
   *  `publish-availability.store.ts`. The button renders nothing then. */
  readonly visible: boolean;
  /** The section's own label, e.g. "Publish pages" — resolved against the caller's locale through
   *  the same `dashboard-i18n` dictionary the dialog's title reads from. */
  readonly label: string;
  /** Opens the Publish dialog scoped to this section's WHOLE `entityTypes` (e.g. collections sends
   *  `["content-type", "collection-entry"]`). `{}` criteria means "start with nothing ticked and let
   *  the dialog's own auto-plan populate it" — the Dashboard's unscoped button's starting shape. */
  readonly onClick: () => void;
}

/**
 * @param section Which publishable section this button opens the dialog scoped to.
 * @complexity O(sections).
 */
export function usePublishSectionButton(section: PublishSectionId): PublishSectionButtonController {
  const locale = useWiredAdminLocale();
  // `PublishSectionId` is derived from the table itself, so the lookup cannot miss.
  const entry = publishSectionById(section)!;
  const visible = usePublishToLiveAvailable();
  return {
    visible,
    label: translateDashboard({ locale: locale, key: entry.labelKey }),
    onClick: () => {
      requestPublish({}, { entityTypes: [...entry.entityTypes] });
    },
  };
}

import { DataTable } from "@jini-ai/admin/react";
import { agentHandle } from "@jini-ai/agentic";
import { I18nProvider, SETTINGS_DIALOG_DICTIONARIES, SettingsDialogShell, type SettingsDialogTab } from "@jini-ai/ui";
import "@jini-ai/ui/settings-dialog.css";

import { buildAgentListHandles } from "@jini-ai/agentic";
import { formatTimestamp } from "@jini-ai/ui/panel-kit";
import type { AdminDisclosureResult, AdminRecoveryStatus, AdminRestorePoint } from "../../lib/api";
import {
  categoryLabel,
  costClassLabel,
  isAssertiveRecoveryBanner,
  recoveryBannerTone,
  restoreButtonAccessibleName,
} from "./rules";
import { useWiredRecovery } from "./hooks/use-recovery.hooks";
import { useRecoveryNavigation } from "./hooks/use-recovery-navigation.hooks";
import { ServerLabel } from "@/components/status-labels";
import { useWiredRestoreFlow, type CeremonyStep } from "./hooks/use-restore-flow.hooks";
import {
  t,
  sinceDiscardMessage,
  discardCountLine,
  baselineUnavailableMessage,
  restorePlanReadyMessage,
  restoreDoneMessage,
} from "./recovery-i18n";

/**
 * @file Recovery screen (design-spec.md §4, ADR-045) — the `/admin/recovery` route.
 *
 * Per design-spec.md §0.1: one screen, holding every restore-point capability — never a separate
 * "Backups" route (ADR-045 explicitly rejects that shape). `development/todos.md`'s "Recovery vs
 * Database's Restore Points tab" entry (owner, 2026-09-10, superseded same morning) is the reason
 * this now has two tabs rather than Database's old three: Database's `RestorePointsSection`
 * (list + create, no restore action) moved here in full, and Database's own `restore-points` tab
 * was removed — restore points were never a "database" concern per the owner's own call. This
 * still applies §6's own recommendation (a full swap, not a modal-over-list) — the swap is now
 * between the two tabs below instead of an untabbed inline ternary.
 *
 * ## Tabs (2026-09-10)
 *
 * The initial implementation chose `TabBar` because this is a list-plus-ceremony operational
 * surface, the same shape as Database, rather than a settings form. The owner's explicit
 * `SettingsDialogShell` requirement takes precedence (2026-10-04 cleanup): the inline shell now
 * matches Agent Plugins, while retaining `?tab=` deep-linking and replace-history navigation.
 * Two tabs: **Restore points** (`RestorePointsPanel` — the list, the create action, and
 * the entry point into a restore) and **Restore** (`RestoreTabPanel` — `RestoreFlow` for whichever
 * point is selected, or a prompt back to the list when nothing is selected yet). Selecting a row
 * and confirming/cancelling the ceremony both navigate between the two tabs explicitly (see
 * `use-recovery-navigation.hooks.ts`) rather than deriving the active tab from `selected` — both
 * sections stay independently reachable either way, same as Database's URL-owned tabs.
 *
 * The restore ceremony (`plan`/`confirm`/`execute`, SPEC-019 C-301/C-302/C-303) is wired to the
 * real `core/gated-mutations`-backed routes (Session 5-6 backend gap closure). `executeRestore`
 * now physically swaps `content.db` (2026-07-16, `DbOpsPort.restoreFromArtifact` — an atomic
 * same-filesystem rename, closing the previously-disclosed "ledger-only" gap). Restart-based, by
 * design, not a live hot-swap: the already-running process keeps its own open file handle to the
 * pre-restore data until an operator restarts it — `restartRequired: true` on the response is
 * that signal, surfaced below rather than silently implied.
 *
 * ## Markup only
 *
 * `Recovery`'s own list/status/create state lives in `hooks/use-recovery.hooks.ts`; `RestoreFlow`'s
 * ceremony state lives in `hooks/use-restore-flow.hooks.ts` — independent state with its own
 * lifecycle, keyed to whichever restore point is selected. `DegradedBannerView`,
 * `RestorePointsList`, `RestorePointsPanel`, and `DisclosurePanel` hold no state of their own and
 * stay as plain, props-driven presentation with no hook. Pure logic (category labels, cost-class
 * badge text/tone, the banner urgency check and severity, the deep-link envelope parse) lives in
 * `rules.ts`.
 *
 * `src/__tests__/unit/admin-nav-recovery-acs.unit.test.ts` reads this file's source directly
 * (`readFileSync`) to assert AC-32 against the `page-description` copy below — keep that
 * `className="page-description">...</p>` line intact if editing the header copy.
 *
 * `locale`/`t`: `Recovery` and `RestoreFlow` each have their own hook (`useRecovery`,
 * `useRestoreFlow`), and each hook already independently calls `useAdminLocale()` for its own
 * error-string translations — so each component now gets `t`/`locale` from its OWN hook rather than
 * `Recovery` threading a single resolved `locale` down as a prop, per the standing i18n rule. This
 * adds no new fetch (see each hook's own file header). `DegradedBannerView`/`RestorePointsList`/
 * `RestorePointsPanel` have no hook of their own, so they keep receiving `locale` as a prop from
 * `Recovery` and import `t` directly — same carve-out `Database.tsx`'s local subcomponents use.
 */

function DegradedBannerView(props: { locale: string; status: AdminRecoveryStatus }) {
  const { locale, status } = props;
  const banner = status.banner;
  if (!banner) return null;

  // AC-27/EC-06/INV-07: `pending-migration`'s action always deep-links to Database's own
  // migration ceremony, never a Recovery restore action — restoring to an older snapshot does not
  // resolve schema drift against the current runtime.
  const assertive = isAssertiveRecoveryBanner(banner);
  // Not every degraded state is equally bad — see `recoveryBannerTone`'s own doc comment.
  const tone = recoveryBannerTone(banner);

  return (
    <div
      className={`notice ${tone} recovery-degraded-banner recovery-plain-notice`}
      role={assertive ? "alert" : undefined}
      aria-live={assertive ? "assertive" : "polite"}
    >
      <span>{banner.accessibleText}</span>
      {banner.actionKind === "deep-link-to-database-migration" ? (
        <a
          className="btn-secondary"
          href="/admin/database"
          {...agentHandle({ handle: "recovery-banner-go-to-database" }, { role: "link", label: "Go to Database to resolve the pending migration" })}
        >
          {t({ locale: locale, key: "Go to Database" })}
        </a>
      ) : null}
      {banner.actionKind === "unblock-interrupted-migration" ? (
        <button
          type="button"
          disabled
          title={t({ locale: locale, key: "No unblock route exists yet — see this screen's file header." })}
          {...agentHandle({ handle: "recovery-banner-unblock" }, { role: "button", label: "Unblock an interrupted migration (not yet available)" })}
        >
          {t({ locale: locale, key: "Unblock (not yet available)" })}
        </button>
      ) : null}
    </div>
  );
}

function RestorePointsList(props: {
  locale: string;
  points: AdminRestorePoint[];
  onSelect: (point: AdminRestorePoint) => void;
}) {
  const { locale } = props;
  // Restore-point ids are stable and unique, same per-row-handle derivation every other list on
  // this workstream uses (`buildAgentListHandles`) — needed because `DataTable`'s `cell` callback
  // only receives the row, not its index.
  const rowHandles = buildAgentListHandles({ prefix: "recovery-row", ids: props.points.map((p) => p.id) }
  );
  const rowHandleById = new Map(props.points.map((p, index) => [p.id, rowHandles[index]!]));
  return (
    <DataTable
      rows={props.points}
      rowKey={(p) => p.id}
      empty={
        <div className="card">
          <div className="empty-state">
            <p>{t({ locale: locale, key: "No restore points yet." })}</p>
          </div>
        </div>
      }
      columns={[
        { key: "timestamp", header: t({ locale: locale, key: "Timestamp" }), cell: (p) => formatTimestamp({ iso: p.createdAt }, { timeZone: "local" }) },
        { key: "trigger", header: t({ locale: locale, key: "Trigger" }), cell: (p) => p.trigger },
        {
          key: "cost-class",
          header: t({ locale: locale, key: "Cost class" }),
          cell: (p) => <span className={`status status-${p.costClass}`}>{costClassLabel(p.costClass, locale)}</span>,
        },
        {
          key: "restore",
          cell: (p) =>
            p.costClass === "unavailable" ? (
              <span className="muted-cell">{t({ locale: locale, key: "No restore-point mechanism available — see the runbook." })}</span>
            ) : (
              <button
                type="button"
                onClick={() => props.onSelect(p)}
                // Every row's visible text is the identical "Restore…" — see
                // `rules.ts`'s `restoreButtonAccessibleName` doc comment for why that is ambiguous
                // to anything resolving elements by accessible name rather than table position, and
                // why this is the one screen where that ambiguity matters most.
                aria-label={restoreButtonAccessibleName(locale, p)}
                {...agentHandle({ handle: `${rowHandleById.get(p.id)}-restore` }, { role: "button", label: "Begin the restore ceremony for this restore point" })}
              >
                {t({ locale: locale, key: "Restore…" })}
              </button>
            ),
        },
      ]}
    />
  );
}

/** The "Restore points" tab's full panel — `RestorePointsList` (unchanged from before the tabs
 *  pass) plus the create action Database's own `RestorePointsSection` used to own
 *  (`development/todos.md`'s "Recovery vs Database's Restore Points tab" entry, 2026-09-10). Split
 *  out from `RestorePointsList` itself, rather than folding the header/button into it, so the bare
 *  list stays reusable exactly as it already is for anything that only needs the table (there is no
 *  such caller today, but the split cost nothing and matches how `Database.tsx`'s own
 *  `RestorePointsSection` kept its header separate from its `DataTable` call). */
function RestorePointsPanel(props: {
  locale: string;
  points: AdminRestorePoint[];
  creating: boolean;
  onCreate: () => void;
  onSelect: (point: AdminRestorePoint) => void;
}) {
  const { locale } = props;
  return (
    <div>
      <div className="editor-header">
        <h2>{t({ locale: locale, key: "Restore points" })}</h2>
        <button
          type="button"
          onClick={props.onCreate}
          disabled={props.creating}
          {...agentHandle({ handle: "recovery-create-restore-point" }, { role: "button", label: "Create a new restore point now" })}
        >
          {props.creating ? t({ locale: locale, key: "Creating…" }) : t({ locale: locale, key: "Create restore point" })}
        </button>
      </div>
      <RestorePointsList locale={locale} points={props.points} onSelect={props.onSelect} />
    </div>
  );
}

/** Step 2 — the discarded-write-window disclosure (design-spec.md §4.3): the load-bearing,
 * blocking centerpiece of this screen. Renders only categories the server response actually
 * contains (never a placeholder row for an uncovered category), and renders `"unknown"` distinctly
 * from `0` (INV-05 — a `0` implies verified-zero-loss, `"unknown"` means the baseline could not be
 * computed at all; these must never be conflated). */
function DisclosurePanel(props: {
  locale: string;
  point: AdminRestorePoint;
  disclosure: AdminDisclosureResult;
  acknowledged: boolean;
  onAcknowledgeChange: (checked: boolean) => void;
}) {
  const { locale } = props;
  const categories = Object.entries(props.disclosure.counts);

  return (
    <div className="recovery-disclosure-panel">
      <div className="recovery-loss-manifest">
        <p className="recovery-loss-lede">{sinceDiscardMessage(locale, props.point.createdAt)}</p>
        <ul className="recovery-loss-list">
          {categories.map(([category, count]) => (
            <li key={category}>{discardCountLine(locale, count, categoryLabel(category, locale))}</li>
          ))}
        </ul>
        <p className="recovery-loss-caveat">{t({ locale: locale, key: "This covers watermark-stamped write paths only (posts/pages and plugin-table writes today) and is NOT a complete count of everything written since this restore point — change-sets, taxonomy writes, Collections entries, and sessions are not yet counted here." })}</p>
      </div>
      {/* A SIBLING of the manifest, not a child of it (web-design pass #3, 2026-09-10). This is the
          one sentence on the screen that changes what an operator should do — it says every figure
          they just read is unverified — so it is the composition's rank-1 element and gets the
          card's full width, the same full-bleed band treatment every other region here has. Nested
          inside the manifest it rendered as a rounded red box floating inside a tinted box, which
          is the boxes-in-boxes shape pass #2's own header says it set out to remove.

          Order is unchanged and must stay unchanged: its own text reads "every count **above** is
          shown as 'unknown'", so it has to follow the counts. That sentence is translated as one
          static block in all 19 locales (`BASELINE_UNAVAILABLE_TEXT`), so moving it ahead of the
          ledger would need 19 rewrites, not a reflow. */}
      {!props.disclosure.watermarkBaselineAvailable ? (
        <p className="save-error recovery-baseline-alarm" role="alert">
          {baselineUnavailableMessage(locale)}
        </p>
      ) : null}
      <label id="recovery-ack-label" className="recovery-ack-gate">
        <input
          type="checkbox"
          checked={props.acknowledged}
          onChange={(e) => props.onAcknowledgeChange(e.target.checked)}
          {...agentHandle({ handle: "recovery-disclosure-acknowledge" }, {
            role: "field",
            label: "Acknowledge the discarded-write-window disclosure",
          })}
        />
        {t({ locale: locale, key: "I understand this count is partial, not exhaustive, and accept the loss window described above." })}
      </label>
    </div>
  );
}

/** The disclosure section (top of `RestoreFlow`): the discarded-write-window error, its loading
 * placeholder, or the panel itself, in that priority order. Split out because — along with
 * `RestoreCeremonySteps` below — this is one of the two independent "wide branch set" halves of
 * the original `RestoreFlow`: this half decides what to show about data loss, the other half
 * decides what to show about ceremony progress, and neither needs the other's branches in scope. */
function RestoreDisclosureStatus(props: {
  locale: string;
  point: AdminRestorePoint;
  disclosure: AdminDisclosureResult | null;
  error: string | null;
  acknowledged: boolean;
  onAcknowledgeChange: (checked: boolean) => void;
}) {
  const { locale, point, disclosure, error, acknowledged, onAcknowledgeChange } = props;

  if (error) return <div className="notice error">{error}</div>;
  if (!disclosure) return <div className="notice">{t({ locale: locale, key: "Computing the discarded-write-window disclosure…" })}</div>;
  return <DisclosurePanel locale={locale} point={point} disclosure={disclosure} acknowledged={acknowledged} onAcknowledgeChange={onAcknowledgeChange} />;
}

/** Step 3a (design-spec.md §4.3) — acknowledge-gated entry into the ceremony. Its own component
 * (rather than inline in `RestoreCeremonySteps`) because the busy-label ternary and the
 * not-yet-acknowledged `title` ternary would otherwise nest two levels deep inside that
 * function's own `step === "idle"` branch — exactly the nesting SonarJS's cognitive-complexity
 * rule penalises beyond what the cyclomatic count shows. */
function RestoreIdleStep(props: { locale: string; acknowledged: boolean; busy: boolean; onStart: () => void }) {
  const { locale, acknowledged, busy, onStart } = props;
  return (
    <div className="recovery-ceremony-step">
      <button
        type="button"
        className="btn-primary"
        disabled={!acknowledged || busy}
        aria-describedby="recovery-ack-label"
        title={!acknowledged ? t({ locale: locale, key: "Acknowledge the disclosure above to continue." }) : undefined}
        onClick={onStart}
        {...agentHandle({ handle: "recovery-restore-start" }, { role: "button", label: "Continue to confirm the restore" })}
      >
        {busy ? t({ locale: locale, key: "Planning…" }) : t({ locale: locale, key: "Continue to confirm" })}
      </button>
    </div>
  );
}

/** Step 3b (SPEC-019 C-301) — plan issued, not yet confirmed. */
function RestorePlannedStep(props: { locale: string; planId: string; busy: boolean; onConfirm: () => void }) {
  const { locale, planId, busy, onConfirm } = props;
  return (
    <div className="recovery-ceremony-step">
      <p>{restorePlanReadyMessage(locale, planId)}</p>
      <button
        type="button"
        className="btn-secondary"
        onClick={onConfirm}
        disabled={busy}
        {...agentHandle({ handle: "recovery-restore-confirm" }, { role: "button", label: "Confirm the planned restore, issuing a one-time execution token" })}
      >
        {busy ? t({ locale: locale, key: "Confirming…" }) : t({ locale: locale, key: "Confirm restore" })}
      </button>
    </div>
  );
}

/** Step 3c (SPEC-019 C-302) — confirmed, execution token in hand, not yet executed. */
function RestoreConfirmedStep(props: { locale: string; busy: boolean; onExecute: () => void }) {
  const { locale, busy, onExecute } = props;
  return (
    <div className="recovery-ceremony-step">
      <p>{t({ locale: locale, key: "Confirmed. Executing performs the restore — this cannot be undone." })}</p>
      <button
        type="button"
        className="btn-danger"
        onClick={onExecute}
        disabled={busy}
        {...agentHandle({ handle: "recovery-restore-execute" }, { role: "button", label: "Execute the confirmed restore now — cannot be undone" })}
      >
        {busy ? t({ locale: locale, key: "Restoring…" }) : t({ locale: locale, key: "Execute restore" })}
      </button>
    </div>
  );
}

/** Step 3d (SPEC-019 C-303) — the ceremony's terminal state. `restartRequired` (2026-07-16,
 * `DbOpsPort.restoreFromArtifact`) surfaces the "already-running process still holds the
 * pre-restore file handle" caveat described in this file's header, rather than silently implying
 * a live hot-swap happened. */
function RestoreDoneStep(props: { locale: string; restoreRunId: string; state: string; restartRequired?: boolean }) {
  const { locale, restoreRunId, state, restartRequired } = props;
  return (
    <div className="recovery-ceremony-step">
      <p role="status">
        {restoreDoneMessage(locale, restoreRunId, <span className={`status status-${state}`}><ServerLabel value={state} /></span>)}
      </p>
      {restartRequired ? (
        <p className="save-error" role="alert">
          {t({ locale: locale, key: "The database file was replaced — this server process is still serving the pre-restore data from its open connection. Restart the server now to pick up the restored data." })}
        </p>
      ) : null}
    </div>
  );
}

/** The four-stage ceremony switch (idle → planned → confirmed → done) plus its own error slot.
 * Exactly one of the four step components below renders at a time, keyed off `step` — this
 * function owns that selection so `RestoreFlow` itself doesn't have to. */
function RestoreCeremonySteps(props: {
  locale: string;
  ceremonyError: string | null;
  step: CeremonyStep;
  busy: boolean;
  acknowledged: boolean;
  plan: { planId: string } | null;
  confirmationToken: string | null;
  result: { restoreRunId: string; state: string; restartRequired?: boolean } | null;
  onStart: () => void;
  onConfirm: () => void;
  onExecute: () => void;
}) {
  const { locale, ceremonyError, step, busy, acknowledged, plan, confirmationToken, result, onStart, onConfirm, onExecute } = props;

  return (
    <>
      {ceremonyError ? <div className="notice error">{ceremonyError}</div> : null}
      {step === "idle" ? <RestoreIdleStep locale={locale} acknowledged={acknowledged} busy={busy} onStart={onStart} /> : null}
      {step === "planned" && plan ? <RestorePlannedStep locale={locale} planId={plan.planId} busy={busy} onConfirm={onConfirm} /> : null}
      {step === "confirmed" && confirmationToken ? <RestoreConfirmedStep locale={locale} busy={busy} onExecute={onExecute} /> : null}
      {step === "done" && result ? (
        <RestoreDoneStep locale={locale} restoreRunId={result.restoreRunId} state={result.state} restartRequired={result.restartRequired} />
      ) : null}
    </>
  );
}

export interface RestoreFlowProps {
  point: AdminRestorePoint;
  onBack: () => void;
  /** Dependency injection seam for tests — see `PostsProps.usePostsHook` for the convention.
   *  Defaulted to the WIRED hook (2026-08-14, Orc-BASH pass) — see `use-restore-flow.hooks.ts`'s
   *  own `useWiredRestoreFlow`. */
  useRestoreFlowHook?: typeof useWiredRestoreFlow;
}

function RestoreFlow({
  point,
  onBack,
  useRestoreFlowHook = useWiredRestoreFlow
}: RestoreFlowProps) {
  const {
    disclosure,
    error,
    acknowledged,
    setAcknowledged,
    step,
    busy,
    ceremonyError,
    plan,
    confirmationToken,
    result,
    startPlan,
    doConfirm,
    doExecute,
    t,
    locale,
  } = useRestoreFlowHook({ point });

  return (
    <div className="recovery-restore-docket">
      <button
        type="button"
        className="btn-ghost recovery-back-link"
        onClick={onBack}
        {...agentHandle({ handle: "recovery-back-to-list" }, { role: "button", label: "Back to the restore points list" })}
      >
        {t("← Restore points")}
      </button>
      <div className="card recovery-restore-card">
        <div className="recovery-ceremony-summary">
          <div className="recovery-restore-title-row">
            <h2 className="recovery-restore-title">
              {t("Restore to")} {formatTimestamp({ iso: point.createdAt }, { timeZone: "local" })}
            </h2>
            <span className="visually-hidden">{t("Cost class")}</span>
            <span className={`status status-${point.costClass}`}>{costClassLabel(point.costClass, locale)}</span>
          </div>
          <p className="recovery-restore-meta">
            <span>
              <span className="recovery-meta-key">{t("Trigger")}</span>
              <span className="recovery-meta-value">{point.trigger}</span>
            </span>
            <span>
              <span className="recovery-meta-key">{t("Kind")}</span>
              <span className="recovery-meta-value">{point.kind}</span>
            </span>
          </p>
        </div>

        <RestoreDisclosureStatus locale={locale} point={point} disclosure={disclosure} error={error} acknowledged={acknowledged} onAcknowledgeChange={setAcknowledged} />

        <RestoreCeremonySteps
          locale={locale}
          ceremonyError={ceremonyError}
          step={step}
          busy={busy}
          acknowledged={acknowledged}
          plan={plan}
          confirmationToken={confirmationToken}
          result={result}
          onStart={startPlan}
          onConfirm={doConfirm}
          onExecute={doExecute}
        />
      </div>
    </div>
  );
}

/** The "Restore" tab's own panel — `RestoreFlow` for whichever point is selected, or a prompt back
 *  to the "Restore points" tab when nothing is selected yet (a direct `?tab=restore` visit, or the
 *  ceremony was already backed out of via `onBack`). Originally split out so `recoveryTabPanel`
 *  stayed a flat dispatch (Database's same complexity-gate reason). The shared shell now owns
 *  that dispatch; this component keeps the selected-point guard out of the page's markup. */
function RestoreTabPanel(props: { locale: string; selected: AdminRestorePoint | null; onBack: () => void }) {
  if (!props.selected) {
    return (
      <div className="notice">
        <p>{t({ locale: props.locale, key: "Select a restore point from the Restore points tab to begin." })}</p>
      </div>
    );
  }
  return <RestoreFlow point={props.selected} onBack={props.onBack} />;
}

export interface RecoveryProps {
  /**
   * Dependency injection seam for tests — the same convention `@jini-ai/ui`'s `CustomSelect` uses
   * for `useCustomSelect`. Defaulted to the real hook, so production callers (`panels.tsx`) pass
   * nothing and behave exactly as before. See `PostsProps.usePostsHook` for the full rationale.
   * Defaulted to the WIRED hook (2026-08-14, Orc-BASH pass) — see `use-recovery.hooks.ts`'s own
   * `useWiredRecovery`.
   */
  useRecoveryHook?: typeof useWiredRecovery;
  /** The `?tab=` query value from `panels.tsx`'s `recovery` route (`URLSearchParams.get` returns
   *  `null` when the param is absent). Validated by `useRecoveryNavigation`. */
  tabId?: string | null;
}

export function Recovery({ useRecoveryHook = useWiredRecovery, tabId }: RecoveryProps = {}) {
  const { status, points, error, creating, createRestorePoint, selected, setSelected, t, locale } = useRecoveryHook();
  const { activeTabId, onTabChange, onSelectPoint, onBackFromFlow } = useRecoveryNavigation({ tabId, setSelected });

  if (error && !points) return <div className="notice error">{error}</div>;
  if (!points || !status) return <div className="notice">{t("Loading restore points…")}</div>;

  // The former recoveryTabPanel used a flat dispatch to avoid nested JSX branch complexity.
  // The shell now owns that dispatch: each tab supplies one presentation-only panel.
  const tabs: SettingsDialogTab[] = [
    {
      id: "restore-points", label: t("Restore points"), title: t("Recovery"),
      panel: <RestorePointsPanel locale={locale} points={points} creating={creating} onCreate={createRestorePoint} onSelect={onSelectPoint} />,
    },
    {
      id: "restore", label: t("Restore"), title: t("Recovery"),
      panel: <RestoreTabPanel locale={locale} selected={selected} onBack={onBackFromFlow} />,
    },
  ];

  return (
    <div className="page">
      <div className="page-header">
        <div className="page-header-text">
          <p className="page-kicker">{t("Operations")}</p>
          <h1 className="page-title">{t("Recovery")}</h1>
          <p className="page-description">{t("Restore this site to a previous point in time using a captured restore point.")}</p>
        </div>
      </div>
      {error ? <div className="notice error">{error}</div> : null}
      <DegradedBannerView locale={locale} status={status} />

      <I18nProvider initialLocale={locale} dictionaries={SETTINGS_DIALOG_DICTIONARIES} fallbackLocale="en" syncDocumentAttributes={false}>
        <div
          className="settings-ui-section settings-ui-section--page-flow recovery-section"
          {...agentHandle({ handle: "recovery-tab-bar" }, { role: "region", label: t("Recovery") })}
        >
          <SettingsDialogShell
            tabs={tabs}
            activeTabId={activeTabId}
            onActiveTabIdChange={onTabChange}
            presentation="inline"
            className="jini-tabbed-dialog--inline"
            fullscreenEnabled={false}
            dialogAriaLabelledBy="recovery-shell-title"
            labels={{ kicker: "", sidebarAriaLabel: t("Recovery") }}
          />
        </div>
      </I18nProvider>
    </div>
  );
}

import { Fragment, type FormEvent } from "react";
import { DataTable, RowMenu, ConfirmDialog } from "@jini-ai/admin/react";
import { agentHandle } from "@jini-ai/agentic";
import type { AdminPolicy, AdminPolicyPermission, AdminRole } from "../../lib/api";
import { buildAgentListHandles } from "@jini-ai/agentic";

import { TabBar } from "@jini-ai/ui/tab-strip";
import { roleMenuItems, policyMenuItems } from "./rules";
import { useWiredRoles, type PendingPermissionRemove } from "./hooks/use-roles.hooks";
import { goToRolesTab, resolveRolesTabId, resolveRolesTabs, type RolesTabId } from "./Roles.hooks";
import { rolesDescriptionParts, roleDeleteBodyParts, policyDeleteBodyParts, permissionRemoveBodyParts } from "./roles-i18n";

/**
 * @file "Roles & Permissions" screen (SPEC-006 + 0.6.0 CRUD-completion amendment) — the
 * `/admin/roles` route. Markup only.
 *
 * State and API calls live in `hooks/use-roles.hooks.ts`; the row-menu logic and the
 * `RESOURCE_CONFLICT`-etc. error copy live in `rules.ts`.
 *
 * Lists roles and policies, creates new ones (`CREATE_ROLE`/`CREATE_POLICY`), and (0.6.0) renames
 * (`UPDATE_ROLE`/`UPDATE_POLICY`), deletes (`DELETE_ROLE`/`DELETE_POLICY`), and — for policies —
 * writes a permission onto a custom policy (`WRITE_POLICY_PERMISSION`, closing the gap this
 * screen's own prior header comment flagged: "granting individual permission strings to a custom
 * policy has no admin route yet"). Every mutating action here is a plain button/inline form, no
 * dedicated edit mode — matches this screen's existing utilitarian style. Role/policy -> user grant
 * assignment stays on `Users.tsx`'s "Manage" row, not duplicated here. Built-in rows never show
 * rename/delete controls (the backend refuses them anyway, INV-06 — hiding the control avoids a
 * guaranteed-failing click).
 *
 * Scope note (RESOLVED 2026-08-24, was OQ-10): removing a single permission from a policy used to
 * have no transition, so the only way to shrink a policy's permission set was delete (only when
 * unused) + recreate — a dead end for a referenced policy, which INV-09 refuses to delete.
 * `REMOVE_POLICY_PERMISSION` closes that. The same inline panel that adds a permission now also
 * lists the policy's current ones and offers each a Remove; listing them at all is new too, since
 * `AdminPolicy` carries no permissions field and nothing previously exposed a row id. (2026-09-20,
 * C1): each Remove now asks first, via a shell `ConfirmDialog`, before the write goes through.
 *
 * Complexity-ceiling pass (2026-08-06): `Roles` and its policy-row map closure both scored over
 * the ceiling (18/10 and 13/13 — one over-sized "Policies" table section reported as two separate
 * numbers, per the brief for this pass). Split into `RolesSection`, `PoliciesSection`/`PolicyRow`,
 * and the two delete dialogs, same top-level-function convention `Users.tsx`/`Taxonomy.tsx` use —
 * a nested closure would not have moved any branching out of `Roles`' own scope, only a sibling
 * function does.
 *
 * ## Tabs (2026-09-06)
 *
 * The two sections are now two `?tab=` tabs on the shared `@jini-ai/ui/tab-strip`, the same primitive
 * `Deployment.tsx`, `Sites.tsx`, `Themes.tsx`, `Security.tsx`, `SourceControl.tsx` and
 * `Database.tsx` already use — the tab shell was ALREADY extracted, so this screen reuses it
 * rather than becoming another implementation. Why two tabs, and the case AGAINST them that was
 * checked first, are in `Roles.hooks.tsx`'s header. Both labels reuse the existing section
 * headings' i18n keys, so the conversion adds no new copy strings.
 *
 * `RolesSection` and `PoliciesSection` are untouched; `RolesTab`/`PoliciesTab` below are thin
 * wrappers holding the prop assembly that used to sit inline in `Roles`'s JSX. Three things stay
 * on the SHELL rather than moving into a panel, each for a stated reason: the page header, the
 * `rowError` banner (set by both sections — `useWiredRoles` keeps one `rowSavingId`/`rowError`
 * pair for roles and policies alike), and both delete dialogs (a confirm dialog is an overlay over
 * the whole page, and its pending state is shell state).
 */
export interface RolesProps {
  /** The `?tab=` query value from `panels.tsx`'s `roles` route (`URLSearchParams.get` returns
   *  `null` when the param is absent). Guarded by `resolveRolesTabId`, so a stale link or a typo
   *  opens the Roles list rather than a blank panel. */
  tabId?: string | null;
  /** Dependency injection seam for tests — the same convention `@jini-ai/ui`'s `CustomSelect` uses
   *  for `useCustomSelect`. Defaulted to the wired hook, so production callers (`panels.tsx`) pass
   *  nothing and behave exactly as before. */
  useRolesHook?: typeof useWiredRoles;
}

/** Everything the two tab panels read, which is simply what `useWiredRoles()` returns — the same
 *  `ReturnType<typeof ...>` shape `Sites.tsx`'s own `sitesTabPanel` takes, rather than a
 *  hand-maintained mirror of a thirty-field controller that would drift the first time the hook
 *  grows a field. */
type RolesController = ReturnType<typeof useWiredRoles>;

/**
 * The create-a-role form, as one thing the section can be handed.
 *
 * Replaces the five loose `roleName`/`setRoleName`/`roleSaving`/`roleError`/`onCreateRole` props the
 * section used to take. They were never independent — every one of them is meaningless without the
 * other four — so naming the group is what lets a caller (or a test) supply a form rather than
 * assemble one out of parts.
 */
export interface RoleCreateFormController {
  name: string;
  setName: (name: string) => void;
  saving: boolean;
  error: string | null;
  submit: (e: FormEvent) => Promise<void>;
}

/** A role row's own affordances: rename in place, or ask for deletion. Grouped for the same reason
 *  as {@link RoleCreateFormController} — `editingId` and `draftName` describe one interaction. */
export interface RoleRowController {
  /** Which role is mid-rename, or `null`. */
  editingId: string | null;
  setEditingId: (roleId: string | null) => void;
  draftName: string;
  setDraftName: (name: string) => void;
  startRename: (role: AdminRole) => void;
  saveRename: (roleId: string) => Promise<void>;
  /** Which row has a write in flight — drives the per-row Saving… label, not a page-wide spinner. */
  savingId: string | null;
  requestDelete: (role: AdminRole | null) => void;
}

export interface RolesSectionProps {
  roles: AdminRole[];
  create: RoleCreateFormController;
  row: RoleRowController;
  t: (key: string) => string;
  locale: string;
}

/** "Roles" heading, create-role form, and the roles `DataTable`.
 *  `DataTable`'s own `cell` callbacks are already separately-scoped closures under ESLint (each
 *  gets its own report), so this split is about the create-form's own branches, not the table.
 *
 *  Exported so a test can render it against hand-built controllers — the seam only counts as one if
 *  something other than `Roles` can drive it. */
export function RolesSection({ roles, create, row, t, locale }: RolesSectionProps) {
  // Role ids are stable and unique, so they disambiguate one row's menu from another's — same
  // reasoning as every other list on this workstream. Built-in rows render no `RowMenu` at all (see
  // the "actions" cell's own guard below), but a handle is still computed for every role so index
  // alignment with `roles` never drifts.
  const roleMenuHandles = buildAgentListHandles({ prefix: "roles-row", ids: roles.map((role) => role.id) }
  );
  return (
    <>
      {/* Kept in the DOM, hidden from view. Once this section sits behind a tab whose label is
          already the word "Roles", a visible `<h2>Roles</h2>` directly beneath it is pure visual
          repetition — but simply deleting it is not the fix, because `role="tab"` buttons do not
          appear in a screen reader's heading list, so the panel would be left with `H1` and nothing
          else (the regression `deployment/HistoryTab.tsx`'s own comment records measuring live).
          `.visually-hidden` keeps the structure for assistive tech and drops the duplicate from the
          page — the same utility `TabBar.tsx` itself uses for its dot label. `Seo.tsx`'s
          "Per-entry SEO" heading stays VISIBLE by the same rule: it is not a verbatim repeat of its
          tab ("Pages & posts"), so it still tells a sighted reader something. */}
      <h2 className="visually-hidden">{t("Roles")}</h2>
      <form onSubmit={create.submit} className="notice integrations-form form-measure">
        {create.error ? <span className="save-error">{create.error}</span> : null}
        <label>
          {t("Role name")}
          <input
            value={create.name}
            onChange={(e) => create.setName(e.target.value)}
            required
            {...agentHandle({ handle: "roles-create-name" }, { role: "field", label: "New role's name" })}
          />
        </label>
        <button
          type="submit"
          disabled={create.saving || !create.name}
          {...agentHandle({ handle: "roles-create-submit" }, { role: "button", label: "Create this new role" })}
        >
          {create.saving ? t("Creating…") : t("Create role")}
        </button>
      </form>
      <DataTable
        rows={roles}
        rowKey={(role) => role.id}
        empty={
          <div className="card">
            <div className="empty-state">
              <p>{t("No roles yet.")}</p>
            </div>
          </div>
        }
        columns={[
          {
            key: "name",
            header: t("Name"),
            cell: (role, index) =>
              row.editingId === role.id ? (
                <input
                  value={row.draftName}
                  onChange={(e) => row.setDraftName(e.target.value)}
                  {...agentHandle({ handle: `${roleMenuHandles[index]}-rename-name` }, { role: "field", label: "This role's new name" })}
                />
              ) : (
                role.name
              ),
          },
          { key: "type", header: t("Type"), cell: (role) => (role.isBuiltin ? t("Built-in") : t("Custom")) },
          {
            key: "actions",
            header: t("More"),
            cell: (role, index) => {
              if (role.isBuiltin) return <span className="muted-cell">—</span>;
              if (row.editingId === role.id) return (
                <span className="editor-actions">
                  <button
                    type="button"
                    disabled={row.savingId === role.id}
                    onClick={() => row.saveRename(role.id)}
                    {...agentHandle({ handle: `${roleMenuHandles[index]}-save` }, { role: "button", label: `Save this role's new name` })}
                  >
                    {row.savingId === role.id ? t("Saving…") : t("Save")}
                  </button>
                  <button
                    type="button"
                    onClick={() => row.setEditingId(null)}
                    {...agentHandle({ handle: `${roleMenuHandles[index]}-cancel` }, { role: "button", label: "Cancel renaming this role" })}
                  >
                    {t("Cancel")}
                  </button>
                </span>
              );
              return (
                <RowMenu
                  triggerLabel={`${t("Actions for role")} "${role.name}"`}
                  agentHandle={`${roleMenuHandles[index]}-menu`}
                  items={roleMenuItems(role, { onRename: row.startRename, onDelete: row.requestDelete }, locale)}
                />
              );
            },
          },
        ]}
      />
    </>
  );
}

/** A policy row's own affordances — {@link RoleRowController}'s counterpart, with the extra
 *  description field a policy carries. */
export interface PolicyRowController {
  /** Which policy is mid-rename, or `null`. */
  editingId: string | null;
  setEditingId: (policyId: string | null) => void;
  draftName: string;
  setDraftName: (name: string) => void;
  draftDescription: string;
  setDraftDescription: (description: string) => void;
  startRename: (policy: AdminPolicy) => void;
  saveRename: (policyId: string) => Promise<void>;
  savingId: string | null;
  requestDelete: (policy: AdminPolicy | null) => void;
}

/** The inline "Add permission" editor: which row it is open on, its two fields, and its write.
 *  Separate from {@link PolicyRowController} because it is a different interaction on the same row —
 *  a row can be mid-rename or mid-permission, and neither controller's state means anything to the
 *  other. */
export interface PolicyPermissionController {
  /** The policy whose permission form is open, or `null` when none is. */
  openForPolicyId: string | null;
  permission: string;
  setPermission: (permission: string) => void;
  resourceType: string;
  setResourceType: (resourceType: string) => void;
  toggleForm: (policyId: string) => void;
  write: (policyId: string) => Promise<void>;
  /** The open policy's current permission rows, and the removal of one (OQ-10). Part of THIS
   *  controller rather than {@link PolicyRowController} because the list is only ever shown inside
   *  this same panel — it opens, loads, and closes with the add form. */
  rows: AdminPolicyPermission[];
  loading: boolean;
  removingId: string | null;
  /** Stages a removal for confirmation (C1) rather than removing directly — no UI path can reach
   *  the unconfirmed write once this replaces a direct `remove` callback on the component contract. */
  requestRemove: (target: PendingPermissionRemove) => void;
}

export interface PolicyRowProps {
  policy: AdminPolicy;
  row: PolicyRowController;
  permission: PolicyPermissionController;
  /** This row's own distinct handle base — computed once, across every rendered policy, by
   *  `PoliciesSection` (via `buildAgentListHandles`); see `Users.tsx`'s `UserRowProps.agentBase`
   *  for why a per-instance uniqueness search does not work here. */
  agentBase: string;
  t: (key: string) => string;
  locale: string;
}

interface PolicyRowActionsProps {
  policy: AdminPolicy;
  row: PolicyRowController;
  permission: PolicyPermissionController;
  agentBase: string;
  t: (key: string) => string;
  locale: string;
}

/** The "More" cell's three-way branch (built-in/frozen -> dash, mid-rename -> Save/Cancel,
 *  at-rest -> `RowMenu`) — extracted out of `PolicyRow`, which was still 13/13 after the first
 *  split pass because this cell's own branches (the `||` guard plus its two nested ternaries) were
 *  still counted in `PolicyRow`'s scope. Same "the panel, not the row, was the actual size" lesson
 *  `Users.tsx`'s `UserRow` -> `UserManagePanel` split already applied. */
function PolicyRowActions({ policy, row, permission, agentBase, t, locale }: PolicyRowActionsProps) {
  if (policy.isBuiltin || policy.isFrozen) return <span className="muted-cell">—</span>;
  if (row.editingId === policy.id) {
    return (
      <span className="editor-actions">
        <button
          type="button"
          disabled={row.savingId === policy.id}
          onClick={() => row.saveRename(policy.id)}
          {...agentHandle({ handle: `${agentBase}-save` }, { role: "button", label: "Save this policy's new name and description" })}
        >
          {row.savingId === policy.id ? t("Saving…") : t("Save")}
        </button>
        <button
          type="button"
          onClick={() => row.setEditingId(null)}
          {...agentHandle({ handle: `${agentBase}-cancel` }, { role: "button", label: "Cancel renaming this policy" })}
        >
          {t("Cancel")}
        </button>
      </span>
    );
  }
  return (
    <RowMenu
      triggerLabel={`${t("Actions for policy")} "${policy.name}"`}
      agentHandle={`${agentBase}-menu`}
      items={policyMenuItems(
        policy,
        permission.openForPolicyId,
        {
          onRename: row.startRename,
          onTogglePermissionForm: permission.toggleForm,
          onDelete: row.requestDelete,
        },
        locale,
      )}
    />
  );
}

interface PolicyPermissionFormProps {
  policyId: string;
  savingId: string | null;
  permission: PolicyPermissionController;
  t: (key: string) => string;
}

interface PolicyPermissionListProps {
  policyId: string;
  permission: PolicyPermissionController;
  t: (key: string) => string;
}

/** The open policy's current permissions, each with a Remove (OQ-10). A separate top-level
 *  function rather than a block inside `PolicyPermissionForm` for the same complexity-ceiling
 *  reason `PolicyRowActions` is one: its loading/empty/list three-way branch plus the per-row
 *  disabled ternary would otherwise all count in the form's own scope. */
function PolicyPermissionList({ policyId, permission, t }: PolicyPermissionListProps) {
  if (permission.loading) return <p className="muted-cell">{t("Loading permissions…")}</p>;
  if (permission.rows.length === 0) return <p className="muted-cell">{t("No permissions yet.")}</p>;
  // Only the currently-open policy's own permission list is ever mounted at once, so a handle
  // needs to be unique within THIS list, not across every policy — same reasoning `Roles`' own
  // per-policy `agentBase` already applies one level up.
  const removeHandles = buildAgentListHandles({ prefix: `policy-permission-remove-${policyId}`, ids: permission.rows.map((row) => row.id) }
  );
  return (
    <ul className="permission-list">
      {permission.rows.map((row, index) => (
        <li key={row.id}>
          <code>{row.permission}</code>
          {row.resourceType ? <span className="muted-cell"> ({row.resourceType})</span> : null}
          <button
            type="button"
            disabled={permission.removingId === row.id}
            aria-label={`${t("Remove permission")} ${row.permission}`}
            onClick={() => permission.requestRemove({ policyId, row })}
            {...agentHandle({ handle: removeHandles[index]! }, { role: "button", label: `Remove the "${row.permission}" permission from this policy` })}
          >
            {permission.removingId === row.id ? t("Removing…") : t("Remove")}
          </button>
        </li>
      ))}
    </ul>
  );
}

/** The inline permission panel — the policy's current permissions (each removable) above the
 *  "Add permission" form. Extracted out of `PolicyRow` verbatim, for the same reason as
 *  `PolicyRowActions` above. */
function PolicyPermissionForm({ policyId, savingId, permission, t }: PolicyPermissionFormProps) {
  // Only the currently-open policy's own form is ever mounted at once — same reasoning
  // `PolicyPermissionList`'s own `removeHandles` comment gives, one level up.
  const formHandleBase = buildAgentListHandles({ prefix: "policy-permission-form", ids: [policyId] })[0]!;
  return (
    <tr>
      <td colSpan={4}>
        <div className="notice integrations-form">
          <p>{t("Current permissions")}</p>
          <PolicyPermissionList policyId={policyId} permission={permission} t={t} />
          <label>
            {t("Permission")}
            <span className="editor-actions permission-form-fields">
              <input
                value={permission.permission}
                onChange={(e) => permission.setPermission(e.target.value)}
                placeholder={t("e.g. content.write")}
                {...agentHandle({ handle: `${formHandleBase}-permission` }, { role: "field", label: "Permission string to grant, e.g. content.write" })}
              />
              <input
                value={permission.resourceType}
                onChange={(e) => permission.setResourceType(e.target.value)}
                placeholder={t("resource type (optional)")}
                {...agentHandle({ handle: `${formHandleBase}-resource-type` }, { role: "field", label: "Optional resource type this permission is scoped to" })}
              />
              <button
                type="button"
                disabled={!permission.permission || savingId === policyId}
                onClick={() => permission.write(policyId)}
                {...agentHandle({ handle: `${formHandleBase}-add` }, { role: "button", label: "Add this permission to the policy" })}
              >
                {savingId === policyId ? t("Saving…") : t("Add")}
              </button>
            </span>
          </label>
        </div>
      </td>
    </tr>
  );
}

/** One policy's row plus its optional inline "Add permission" row. `key` lives on the `<PolicyRow>`
 *  element at the call site, same convention `Users.tsx`'s `UserRow` uses.
 *
 *  Exported for the same reason as {@link RolesSection}. */
export function PolicyRow({ policy, row, permission, agentBase, t, locale }: PolicyRowProps) {
  const renaming = row.editingId === policy.id;
  return (
    <>
      <tr>
        <td>
          {renaming ? (
            <input
              value={row.draftName}
              onChange={(e) => row.setDraftName(e.target.value)}
              {...agentHandle({ handle: `${agentBase}-rename-name` }, { role: "field", label: "This policy's new name" })}
            />
          ) : (
            policy.name
          )}
        </td>
        <td>
          {renaming ? (
            <input
              value={row.draftDescription}
              onChange={(e) => row.setDraftDescription(e.target.value)}
              {...agentHandle({ handle: `${agentBase}-rename-description` }, { role: "field", label: "This policy's new description" })}
            />
          ) : (
            policy.description ?? <span className="muted-cell">—</span>
          )}
        </td>
        <td>
          {policy.isBuiltin ? t("Built-in") : t("Custom")}
          {policy.isFrozen ? ` ${t("(frozen)")}` : ""}
        </td>
        <td>
          <PolicyRowActions policy={policy} row={row} permission={permission} agentBase={agentBase} t={t} locale={locale} />
        </td>
      </tr>
      {permission.openForPolicyId === policy.id ? (
        <PolicyPermissionForm policyId={policy.id} savingId={row.savingId} permission={permission} t={t} />
      ) : null}
    </>
  );
}

