import { ErrorNotice, type Translate } from '@jini-ai/ui/panel-kit';
import type { UserFacingError } from '@jini-ai/core';
import { useEffect, useMemo, useState, type FormEvent } from 'react';
import { AGENT_PRIVATE_ATTRIBUTE } from '@jini-ai/agentic';
import { SecretInput } from '@/components/SecretInput/SecretInput';
import { ownerRecoveryPort, ownerRecoveryFailure, type OwnerRecoveryPort, type OwnerRecoveryStatus } from '../../lib/owner-recovery-api';

const identityTranslate: Translate = text => text;

/** Existing Security page adapter. Codes live only in component memory until saved/dismissed.
 * @complexity O(1), one small status read on mount; one ten-code write per explicit rotation.
 */
export function RecoveryCodesCard({ port = ownerRecoveryPort, t = identityTranslate }: { port?: OwnerRecoveryPort; t?: Translate }) {
  const [status, setStatus] = useState<OwnerRecoveryStatus>();
  const [loadError, setLoadError] = useState<{ cause: unknown } | null>(null);
  useEffect(() => {
    let active = true;
    void port.status().then(value => { if (active) setStatus(value); }).catch(error => {
      if (active) setLoadError({ cause: error });
    });
    return () => { active = false; };
  }, [port]);
  const error = useMemo(() => loadError ? ownerRecoveryFailure({ error: loadError.cause,
    message: 'Owner recovery settings could not load.',
    action: 'Reload this page after resolving the server explanation. Ask the host operator to check the identity database if it continues.',
    step: 'owner-recovery-status', t }) : null, [loadError, t]);
  if (error) return <ErrorNotice failure={error} t={t} />;
  if (!status) return <p>{t('Loading owner recovery…')}</p>;
  if (!status.isOwner || !status.available) return null;
  return <section className="card">
    <h3>{t('Recovery codes')}</h3>
    <p>{t('Save ten single-use codes somewhere private. Using one resets your owner password, removes authenticators and passkeys, signs out all sessions and invalidates every code in the set.')}</p>
    <RecoveryKit port={port} t={t} />
    {status.desktopOwnerReset ? <DesktopOwnerReset port={port} t={t} /> : null}
  </section>;
}

/** Issue only after password proof; never persist raw codes or leave the submitted password in state.
 * @complexity O(1), one rotation per submit and at most ten codes in memory.
 */
function RecoveryKit({ port, t }: { port: OwnerRecoveryPort; t: Translate }) {
  const [password, setPassword] = useState(''), [code, setCode] = useState(''), [codes, setCodes] = useState<string[]>([]);
  const [busy, setBusy] = useState(false), [error, setError] = useState<UserFacingError | null>(null);
  async function submit(event: FormEvent) {
    event.preventDefault(); setBusy(true); setError(null); setCodes([]);
    try { setCodes((await port.issue({ password, ...(code ? { code } : {}) })).codes); }
    catch (error) { setError(ownerRecoveryFailure({ error, message: 'Recovery codes could not be generated.', action: 'Follow the server explanation before generating another set. Ask the host operator for help if it continues.', step: 'owner-recovery-issue', t, secrets: [password, code] })); }
    finally { setPassword(''); setCode(''); setBusy(false); }
  }
  return <div>
    <form onSubmit={submit}>
      <label htmlFor="recovery-current-password">{t('Current owner password')}</label>
      <SecretInput id="recovery-current-password" label={t('Current owner password')} autoComplete="current-password" value={password} onChange={event => setPassword(event.target.value)} {...{ [AGENT_PRIVATE_ATTRIBUTE]: '' }} />
      <label>{t('Authenticator code (if enabled)')}<input autoComplete="one-time-code" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} data-agent-private="" value={code} onChange={event => setCode(event.target.value)} /></label>
      <button className="btn-primary" disabled={busy || !password}>{t('Generate recovery codes')}</button>
      <p>{t('Generating a new set invalidates all previous codes. Codes are shown only now.')}</p>
    </form>
    {error ? <ErrorNotice failure={error} t={t} /> : null}
    {codes.length ? <RecoveryKitOutput codes={codes} dismiss={() => setCodes([])} t={t} /> : null}
  </div>;
}

/** Download the currently displayed kit once, then erase it from this view. No server read.
 * @complexity O(1), one local blob of ten codes (~650 bytes), immediately released.
 */
function RecoveryKitOutput({ codes, dismiss, t }: { codes: string[]; dismiss: () => void; t: Translate }) {
  function download() {
    const url = URL.createObjectURL(new Blob([codes.join('\n') + '\n'], { type: 'text/plain' }));
    const link = document.createElement('a'); link.href = url; link.download = 'tovu-owner-recovery-codes.txt'; link.click();
    URL.revokeObjectURL(url); dismiss();
  }
  return <div {...{ [AGENT_PRIVATE_ATTRIBUTE]: '' }}>
    <pre>{codes.join('\n')}</pre>
    <button type="button" className="btn-secondary" onClick={download}>{t('Download codes')}</button>
    <button type="button" className="btn-secondary" onClick={dismiss}>{t('I saved these codes')}</button>
  </div>;
}

/** Desktop proof restores the ordinary owner session before this action is offered by the server.
 * @complexity O(1) UI state, one reset request per explicit submit; no staff promotion.
 */
function DesktopOwnerReset({ port, t }: { port: OwnerRecoveryPort; t: Translate }) {
  const [password, setPassword] = useState(''), [confirmation, setConfirmation] = useState('');
  const [busy, setBusy] = useState(false), [message, setMessage] = useState('');
  const [failure, setFailure] = useState<UserFacingError | null>(null);
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (password !== confirmation) { setMessage(t('The passwords do not match. Enter the same password in both fields. Details: desktop-owner-confirmation')); return; }
    setBusy(true); setMessage(''); setFailure(null);
    try { await port.reset({ password }); setMessage(t('Owner password reset. All sessions and recovery codes were invalidated. Reopen the site or sign in with your new password.')); }
    catch (error) { setFailure(ownerRecoveryFailure({ error, message: 'The owner password could not be reset.', action: 'Follow the server explanation. Reopen this site in the desktop app to renew local proof if it was refused.', step: 'desktop-owner-reset', t, secrets: [password] })); }
    finally { setPassword(''); setConfirmation(''); setBusy(false); }
  }
  return <details><summary>{t('Reset owner password')}</summary>
    <p>{t('Your desktop launch restored your owner session. Choose a new password; this signs out all sessions and invalidates recovery codes.')}</p>
    <form onSubmit={submit}>
      <label htmlFor="desktop-owner-password">{t('New owner password')}</label>
      <SecretInput id="desktop-owner-password" label={t('New owner password')} autoComplete="new-password" value={password} onChange={event => setPassword(event.target.value)} {...{ [AGENT_PRIVATE_ATTRIBUTE]: '' }} />
      <label htmlFor="desktop-owner-confirm">{t('Confirm new owner password')}</label>
      <SecretInput id="desktop-owner-confirm" label={t('Confirm new owner password')} autoComplete="new-password" value={confirmation} onChange={event => setConfirmation(event.target.value)} {...{ [AGENT_PRIVATE_ATTRIBUTE]: '' }} />
      <button className="btn-primary" disabled={busy || !password}>{t('Reset password and sign out sessions')}</button>
    </form>
    {failure ? <ErrorNotice failure={failure} t={t} /> : null}
    {message ? <p className="notice" role="status">{message}</p> : null}
  </details>;
}

import { useEffect, useRef, type RefObject } from "react";

import { useFocusTrap } from "../../hooks/use-focus-trap.hooks";

/**
 * @file `ExternalMcpToolsModal.tsx`'s own derived-value logic, split out per the
 * `<Name>.tsx`/`<Name>.hooks.tsx` pattern (admin TSX-logic-sweep, 2026-09-05) — this repo's rule
 * that a `.tsx` file carries no functions or derived logic of its own. Mirrors
 * `hooks/use-external-mcp-remove-confirm.hooks.ts`'s own Escape-to-cancel effect (same listener,
 * same cleanup). Kept as this modal's OWN copy rather than importing that file's hook: the two
 * dialogs are otherwise unrelated (that one also derives remove-confirmation copy, which this modal
 * has no equivalent of), and that file's own header already gives the reasoning for not sharing an
 * 8-line effect across a second caller — the point to extract a shared one is a THIRD consumer, not
 * two.
 *
 * Now also owns the Tab trap (2026-09-20 focus-trap inventory, plan-components.md Part 3): this
 * modal declares `aria-modal="true"` but nothing kept Tab from walking out onto the page behind it.
 * `dialogRef`/`useFocusTrap` are returned from here rather than created in the `.tsx` body, for the
 * same "ref and its consuming hook stay together" reason `use-external-mcp-remove-confirm.hooks.ts`
 * gives.
 *
 * Also owns the open/close focus transition (2026-09-21), the same regression `4d52c7783` fixed for
 * `MediaEditDialog`: this modal is conditionally mounted by its caller (`ExternalMcpSettingsPanel.tsx`'s
 * `toolsOpen ? <ExternalMcpToolsModal .../> : null`), so mount/unmount IS the open/close transition —
 * same technique `MediaPickerDialog.hooks.tsx`'s `useMediaPickerDialog` uses for its own `cancelRef`.
 * The sibling `ExternalMcpRemoveConfirmDialog` gets this for free via a plain `autoFocus` on its
 * Cancel button, but this modal's own first control (the picker's Refresh/Cancel/Save buttons) is
 * conditional on picker load state — the modal's own Close button is the one control guaranteed
 * present regardless, the same "stable target present regardless of draft state" reasoning
 * `MediaEditDialogController`'s `altRef` doc gives, so it is the focus target here instead.
 */

export interface ExternalMcpToolsModalController {
  /** Attach to the modal's own `aria-modal` root — see this file's header. */
  dialogRef: RefObject<HTMLDivElement | null>;
  /** Attach to the modal's own Close button — see this file's header's focus-transition section. */
  closeRef: RefObject<HTMLButtonElement | null>;
}

/** Calls `onClose` when Escape is pressed anywhere in the document, for as long as the modal stays
 *  mounted, traps Tab inside the returned `dialogRef`, and moves focus onto `closeRef` on mount,
 *  restoring it to whatever had focus beforehand on unmount — see this file's header.
 *
 *  @complexity O(1) per keypress; one listener for the lifetime of the mount. */
export function useExternalMcpToolsModalEscape(onClose: () => void): ExternalMcpToolsModalController {
  const dialogRef = useRef<HTMLDivElement | null>(null);
  const closeRef = useRef<HTMLButtonElement | null>(null);
  useFocusTrap(dialogRef);

  // Captured at mount, before focus moves onto Close below — the element that had focus then is,
  // by construction, whatever opened this modal (the row's "Tools" button). Restored on unmount.
  const triggerRef = useRef<Element | null>(null);

  useEffect(() => {
    triggerRef.current = document.activeElement;
    closeRef.current?.focus();
    return () => {
      if (triggerRef.current instanceof HTMLElement) triggerRef.current.focus();
    };
  }, []);

  useEffect(() => {
    function onKeyDown(e: KeyboardEvent) {
      if (e.key === "Escape") onClose();
    }
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [onClose]);

  return { dialogRef, closeRef };
}

import { useEffect, useRef, type RefObject } from "react";

import { useFocusTrap } from "../../../hooks/use-focus-trap.hooks";
import type { Translate } from "@jini-ai/ui/panel-kit";
import { buildExternalMcpRemoveConfirmCopy, type RemoveConfirmCopy } from "../rules";

/**
 * @file `ExternalMcpRemoveConfirmDialog`'s only two behaviours — Escape-to-cancel and the
 * name/auth-mode-derived copy — so the dialog component itself is only markup. Mirrors
 * `features/collections/hooks/use-lifecycle-confirm-dialog.hooks.ts` (same split, same reason:
 * `copy` is a derived value, not something the component should compute inline).
 *
 * Not sharing `features/collections`' own `useEscapeToCancel` here: that hook is feature-local by
 * design (its own file header says nothing outside `features/collections` needs it), and this is
 * the only consumer in `features/settings` so far — duplicating an 8-line effect is cheaper than a
 * cross-feature import for one caller. If a third feature needs the same listener, that is the
 * point to extract a shared one, not before.
 *
 * Also owns the Tab trap (2026-09-20 focus-trap inventory, plan-components.md Part 3): this dialog
 * declares `aria-modal="true"` but nothing kept Tab from walking out onto the page behind it. The
 * `dialogRef`/`useFocusTrap` pair lives here rather than in the `.tsx` body, so the ref and the
 * hook that consumes it stay together — a rendering-only component file cannot silently drop the
 * `ref={dialogRef}` attribute without also dropping the whole controller wire-up a test exercises.
 */

export interface ExternalMcpRemoveConfirmController {
  copy: RemoveConfirmCopy;
  /** Attach to the dialog's own `aria-modal` root — see this file's header. */
  dialogRef: RefObject<HTMLDivElement | null>;
}

export function useExternalMcpRemoveConfirm(props: {
  name: string;
  isOAuth: boolean;
  onCancel: () => void;
  t?: Translate;
}): ExternalMcpRemoveConfirmController {
  const { onCancel } = props;
  const dialogRef = useRef<HTMLDivElement | null>(null);
  useFocusTrap(dialogRef);

  useEffect(() => {
    function onKeyDown(e: KeyboardEvent) {
      if (e.key === "Escape") onCancel();
    }
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [onCancel]);

  return { copy: buildExternalMcpRemoveConfirmCopy({ name: props.name, isOAuth: props.isOAuth }, props.t), dialogRef };
}

import { useMemo, useRef, useState } from "react";
import {
  type ExecutionConfig,
  type MemoryTopTab,
  type NotificationsPreferences,
  type PrivacyConsentState,
} from "@jini-ai/ui";
import {
  DEFAULT_EXECUTION_CONFIG,
  EXECUTION_NAMESPACE,
  createExecutionPort,
  loadExecutionConfig,
  reconcileExecutionConfigRefresh,
  saveExecutionConfig,
} from "@/lib/execution-settings";
import {
  DEFAULT_INSTRUCTIONS,
  DEFAULT_INTERFACE,
  DEFAULT_LOCALE,
  DEFAULT_NOTIFICATIONS,
  DEFAULT_PRIVACY,
  INSTRUCTIONS_NAMESPACE,
  INTERFACE_NAMESPACE,
  LANGUAGE_NAMESPACE,
  NOTIFICATIONS_NAMESPACE,
  PRIVACY_NAMESPACE,
  loadInstructions,
  loadInterface,
  loadLanguage,
  loadNotifications,
  loadPrivacy,
  saveInstructions,
  saveInterface,
  saveLanguage,
  saveNotifications,
  savePrivacy,
  type InterfaceConfig,
} from "@/lib/settings-tabs";
import { mergeSaveStates, useSettingsSlice, type SaveState, type SettingsSlice } from "@/hooks/use-settings-slice.hooks";
import { areAnySlicesLoading, firstLoadError } from "../rules";

/**
 * @file `SettingsUi`'s port/slice/save-merge bootstrap, so `SettingsUi` in `SettingsUi.tsx` is only
 * markup (the 9-tab `SettingsDialogTab[]` array and the shell mounts).
 *
 * Extracted verbatim — same state, same declaration order, same slice configs. `ADMIN_LOCALES` and
 * `DEFAULT_INSTRUCTIONS` stay imported directly by `SettingsUi.tsx` rather than being threaded
 * through this controller: they are static render-only data (a locale list, a fallback string),
 * not state this hook owns.
 *
 * Six independent `useSettingsSlice` instances are mounted — one per ledger-backed tab (Execution,
 * Instructions, Notifications, Privacy, Language, User Interface) — each with its
 * own load, debounce, save chain, and diff base (see `use-settings-slice.hooks.ts`'s own header for
 * why that independence matters). Appearance moved with its slice to `AdminAppearance` (Admin UI).
 * Memory and About mount no slice. Skills live under Add-Ons.
 * Workspace (folded in 2026-09-10 — see `SettingsUi.tsx`'s own header), mounts no slice either, for
 * a different reason from the other three: it has a REAL Tovu backend, just not this one — its own
 * `useWiredWorkspace()` (`features/workspace/hooks/use-workspace.hooks.ts`) owns its fetch/save/
 * error state independently of `s`, so this controller has nothing to expose for it at all.
 *
 * The External MCP controller (and a since-removed Composio one) this hook used to expose left on
 * 2026-09-10 with their tabs — see `SettingsUi.tsx`'s header. External MCP is composed by
 * `features/providers/hooks/use-providers.hooks.ts` now, which deliberately does NOT reuse this
 * hook: it was never settings-ledger-backed, and mounting its six slices to reach it would have
 * put the Providers page behind five loads it never displays (`language`, feeds the
 * locale `Providers.tsx` already reads itself through `useAdminLocale()`).
 */

export interface SettingsUiController {
  /** Which segment of the inert-wrapped `MemorySettingsPanel` mount is showing. Local view state
   *  only — nothing here persists, matching every other prop that tab's `inert` control feeds. */
  memoryTopTab: MemoryTopTab;
  setMemoryTopTab: (tab: MemoryTopTab) => void;

  port: ReturnType<typeof createExecutionPort>;

  execution: SettingsSlice<ExecutionConfig>;
  instructions: SettingsSlice<string>;
  notifications: SettingsSlice<NotificationsPreferences>;
  privacy: SettingsSlice<PrivacyConsentState>;
  language: SettingsSlice<string>;
  /** Settings → User Interface (`core.interface`, per operator). */
  interface: SettingsSlice<InterfaceConfig>;

  /** `true` until every mounted slice has settled — see `rules.ts`'s `areAnySlicesLoading`. */
  loading: boolean;
  loadError: string | null;
  save: SaveState;
}

/**
 * @complexity Time: O(1) beyond the six constant-shaped slice mounts; `save`'s `useMemo` body is
 * O(n) in slice count (fixed at 6). Space: O(1) — no caller-controlled collections.
 */
export function useSettingsUi(): SettingsUiController {
  // Same option, same reasoning as `features/ai-assistant/hooks/use-admin-execution-mode.hooks.ts`
  // — this is the SECOND mount of `ExecutionTab` over the same `core.execution` ledger and the same
  // stored credential, and the two must not drift in their port options.
  const port = useRef(
    createExecutionPort({
      // Opts model discovery and "Test connection" into the ADMIN'S OWN server-side credential — the
      // key this very screen configures, encrypted and write-only since 2026-08-05. Without it the
      // probes were sent with the empty browser field and the provider (correctly) answered "No API
      // key", so `ByokProviderForm` never reached `modelDiscovery.status === 'ok'` and rendered its
      // free-text Model input instead of the live picker it already contains.
      //
      // NOT `useStoredCredential` — that is the SITE's visitor key, a different row belonging to a
      // different subject, and opting into it here would silently probe the wrong credential. The two
      // flags are separate for exactly this reason; see `lib/execution-settings.ts`'s option docs.
      useAdminStoredCredential: true,
    }),
  );

  // Which segment of the inert-wrapped `MemorySettingsPanel` mount below is
  // showing. Local view state only — nothing here persists, matching every
  // other prop this tab's `inert` control feeds.
  const [memoryTopTab, setMemoryTopTab] = useState<MemoryTopTab>("memories");

  const execution = useSettingsSlice<ExecutionConfig>({
    load: loadExecutionConfig,
    save: saveExecutionConfig,
    defaultValue: DEFAULT_EXECUTION_CONFIG,
    namespaces: [EXECUTION_NAMESPACE],
    // Without this, an external refresh (a same-tab echo of this slice's own write over the
    // settings-changed SSE feed, another tab, another operator) wipes a typed-but-unsaved API key
    // out of the form — see `reconcileExecutionConfigRefresh`'s own doc.
    reconcileRefresh: reconcileExecutionConfigRefresh,
  });
  const instructions = useSettingsSlice<string>({
    load: loadInstructions,
    save: saveInstructions,
    defaultValue: DEFAULT_INSTRUCTIONS,
    namespaces: [INSTRUCTIONS_NAMESPACE],
  });
  const notifications = useSettingsSlice<NotificationsPreferences>({
    load: loadNotifications,
    save: saveNotifications,
    defaultValue: DEFAULT_NOTIFICATIONS,
    namespaces: [NOTIFICATIONS_NAMESPACE],
  });
  const privacy = useSettingsSlice<PrivacyConsentState>({
    load: loadPrivacy,
    save: savePrivacy,
    defaultValue: DEFAULT_PRIVACY,
    namespaces: [PRIVACY_NAMESPACE],
  });
  const language = useSettingsSlice<string>({
    load: loadLanguage,
    save: saveLanguage,
    defaultValue: DEFAULT_LOCALE,
    namespaces: [LANGUAGE_NAMESPACE],
  });
  const interfacePrefs = useSettingsSlice<InterfaceConfig>({
    load: loadInterface,
    save: saveInterface,
    defaultValue: DEFAULT_INTERFACE,
    namespaces: [INTERFACE_NAMESPACE],
  });

  const slices = [execution, instructions, notifications, privacy, language, interfacePrefs];
  const save = useMemo(
    () => mergeSaveStates(slices.map((slice) => slice.saveState)),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    slices.map((slice) => slice.saveState),
  );

  return {
    memoryTopTab,
    setMemoryTopTab,

    port: port.current,

    execution,
    instructions,
    notifications,
    privacy,
    language,
    interface: interfacePrefs,

    loading: areAnySlicesLoading(slices),
    loadError: firstLoadError(slices),
    save,
  };
}

