export function Taxonomy({ useTaxonomyHook = useWiredTaxonomy }: TaxonomyProps = {}) {
  // Place popups outside the row scroller but inside the bridge's page scope.
  // A callback ref supplies the mounted container before any menu can open.
  const [menuPortalContainer, setMenuPortalContainer] = useState<HTMLDivElement | null>(null);
  const {
    copyHtmlEmbed,
    copyFeedback,
    taxonomies,
    error,
    selectedTermId,
    setSelectedTermId,
    selected,
    load,
    formOpen,
    setFormOpen,
    pendingDeleteTerm,
    requestDeleteTerm,
    deleteTermBusy,
    deleteTermBlocked,
    confirmDeleteTerm,
    pendingDeleteTaxonomy,
    requestDeleteTaxonomy,
    deleteTaxonomyBusy,
    deleteTaxonomyBlocked,
    confirmDeleteTaxonomy,
    t,
  } = useTaxonomyHook();
  const deleteState = { copyHtmlEmbed, requestDeleteTerm, deleteTermBlocked, requestDeleteTaxonomy, deleteTaxonomyBlocked };

  if (error && !taxonomies) return <div className="notice error">{error}</div>;
  if (!taxonomies) return <div className="notice">{t("Loading taxonomies…")}</div>;
  const list = namespaceList({ taxonomies, selectedTermId, setSelectedTermId, load, deleteState, menuPortalContainer, t });

  return (
    <div className="page" ref={setMenuPortalContainer}>
      <TaxonomyPageHeader formOpen={formOpen} setFormOpen={setFormOpen} t={t} />
      <TaxonomyNotices copyFeedback={copyFeedback} error={error} empty={taxonomies.length === 0} t={t} />

      {formOpen ? (
        <NewTaxonomyForm
          onCreated={() => {
            load();
            setFormOpen(false);
          }}
          t={t}
        />
      ) : null}

      {/* Web-design pass (2026-08-05): `.settings-body` is the raw ledger's permanent two-column
          grid (`minmax(16rem,1.1fr) minmax(20rem,1.4fr)`) — reserving that second column even with
          no `selected` term left a large dead void on this screen (the concrete defect the owner
          was seeing). Only wrapping in `.settings-body` once a term IS selected means the list
          renders full-width the rest of the time, matching every reference page's full-width
          content instead of a permanently-split master/detail pane. See this file's own header
          comment for the fuller diagnosis. */}
      {selected ? (
        <div className="settings-body">
          {list}
          <TermDetailPanel
            taxonomy={selected.taxonomy}
            term={selected.term}
            onRenamed={load}
            onMerged={() => {
              setSelectedTermId(null);
              load();
            }}
            t={t}
          />
        </div>
      ) : (
        list
      )}

      <TermDeleteDialog
        pendingDeleteTerm={pendingDeleteTerm}
        deleteTermBusy={deleteTermBusy}
        confirmDeleteTerm={confirmDeleteTerm}
        requestDeleteTerm={requestDeleteTerm}
        t={t}
      />
      <TaxonomyDeleteDialog
        pendingDeleteTaxonomy={pendingDeleteTaxonomy}
        deleteTaxonomyBusy={deleteTaxonomyBusy}
        confirmDeleteTaxonomy={confirmDeleteTaxonomy}
        requestDeleteTaxonomy={requestDeleteTaxonomy}
        t={t}
      />
    </div>
  );
}

/** Extracted so both branches above (two-column with a detail panel, or full-width alone) render
 *  the exact same list markup — see the `selected ? … : …` comment for why there are two branches
 *  at all. `taxonomy-namespace-group`/`taxonomy-term-list` are additive classes (see `styles.css`'s
 *  own comment on that block) that converge this list's padding and type on the reference idiom
 *  without touching the shared `.settings-*` base rules, kept as originally defined for the
 *  since-deleted `settings-raw/Settings.tsx`.
 *
 * `deleteState` (web-design pass, 2026-08-05): bundles the five `useTaxonomy` fields this list needs
 * to offer "Delete taxonomy"/"Delete term" and show a blocked-delete reason — passed as one object
 * rather than five more positional params now that this function's signature already has four.
 * (Code-health pass, 2026-10-20: the whole argument list is now that one required object, and
 * `Taxonomy` calls this once and places the same result in whichever branch renders.)
 *
 * The `buildAgentListHandles`/`Map` calls below are not `useMemo`d: this is a plain helper, not a
 * component (it is called conditionally from the `selected ? … : …` branch in `Taxonomy`'s render),
 * so it has no hook access to begin with. Each call is O(n) over one operator's own taxonomies/terms
 * (see `buildAgentListHandles`'s own `@complexity` doc) — cheap enough next to the list render it
 * feeds that hoisting the computation up into `Taxonomy` to memoize it was not judged worth the
 * added indirection. */
function namespaceList({
  taxonomies,
  selectedTermId,
  setSelectedTermId,
  load,
  deleteState,
  menuPortalContainer,
  t,
}: {
  taxonomies: AdminTaxonomyWithTerms[];
  selectedTermId: string | null;
  setSelectedTermId: (id: string) => void;
  load: () => void;
  deleteState: {
    copyHtmlEmbed: (required: { taxonomy: AdminTaxonomy }) => Promise<void>;
    requestDeleteTerm: (term: AdminTerm | null) => void;
    deleteTermBlocked: { termId: string; state: DeleteBlockedState } | null;
    requestDeleteTaxonomy: (taxonomy: AdminTaxonomy | null) => void;
    deleteTaxonomyBlocked: { taxonomyId: string; state: DeleteBlockedState } | null;
  };
  menuPortalContainer: HTMLElement | null;
  t: (key: string) => string;
}) {
  // Computed once, across every group, so two taxonomies whose names slugify identically still get
  // distinct handles — see `NewTermForm`'s own `agentBase` doc for why this cannot be derived
  // independently inside each group's own `NewTermForm` instance.
  const newTermFormBases = buildAgentListHandles({ prefix: "taxonomy-new-term", ids: taxonomies.map((group) => group.taxonomy.id) }
  );
  // Same id list as `newTermFormBases` above, so a taxonomy's "Delete taxonomy" menu handle and its
  // "+ Add term" form handle share the same id-derived slug (e.g. `taxonomy-new-term-tax-a-open` /
  // `taxonomy-menu-tax-a`) — an agent reading `page.find_elements` can tell they belong to the same
  // group without cross-referencing anything else. `RowMenu`'s `agentHandle` prop only reached this
  // package this session; before that, this menu (and the per-term one below) published no handle at
  // all and its trigger/items were invisible to `page.find_elements` regardless of what this file did.
  const taxonomyMenuHandles = buildAgentListHandles({ prefix: "taxonomy-menu", ids: taxonomies.map((group) => group.taxonomy.id) }
  );
  // Term ids are globally unique across every taxonomy, not scoped per group — same reasoning
  // `CollectionEntryEditor.tsx`'s `TermPicker` documents for its own flat `term-picker-term` list.
  const termHandles = buildAgentListHandles({ prefix: "taxonomy-term", ids: taxonomies.flatMap((group) => group.terms.map((term) => term.id)) }
  );
  let termHandleIndex = 0;

  return (
    <div className="settings-namespace-list">
      {taxonomies.map((group, groupIndex) => {
        const byId = new Map(group.terms.map((term) => [term.id, term]));
        return (
          <section key={group.taxonomy.id} className="settings-namespace-group taxonomy-namespace-group">
            <div className="taxonomy-namespace-group-header">
              <h2>{group.taxonomy.name}</h2>
              <div className="page-actions">
              <button type="button" className="btn-secondary" onClick={() => deleteState.copyHtmlEmbed({ taxonomy: group.taxonomy })}>{t("Copy HTML embed")}</button>
              <TaxonomyRowMenu
                portalContainer={menuPortalContainer}
                triggerLabel={t('Actions for taxonomy "{name}"').replace("{name}", group.taxonomy.name)}
                agentHandle={taxonomyMenuHandles[groupIndex]}
                items={[
                  {
                    key: "delete",
                    label: t("Delete taxonomy"),
                    destructive: true,
                    onSelect: () => deleteState.requestDeleteTaxonomy(group.taxonomy),
                  },
                ]}
              />
              </div>
            </div>
            {deleteState.deleteTaxonomyBlocked?.taxonomyId === group.taxonomy.id ? (
              <p className="notice error" role="alert">
                {t("Can't delete")} &quot;{group.taxonomy.name}&quot;: {deleteState.deleteTaxonomyBlocked.state.message}
              </p>
            ) : null}
            {group.terms.length === 0 ? (
              <p className="muted-cell">{t("No terms yet.")}</p>
            ) : (
              /* `<ul>` carries native list semantics on its own — no explicit `role="list"` needed
                 (it was redundant even before the row fix below). Left off entirely now rather than
                 kept: an explicit `list` role formally expects `listitem`-family children, and each
                 row below is now `role="button"` (see that comment), so an explicit `role="list"`
                 here would assert a parent/child relationship that no longer holds. */
              <ul className="settings-row-list taxonomy-term-list">
                {group.terms.map((term) => {
                  const depth = group.taxonomy.hierarchical ? termDepth({ term, byId }) : 0;
                  // Gated on `hierarchical` for the same reason `depth` is: a term's `parentId` can
                  // still be set on a taxonomy that has since been switched to flat (or seeded with
                  // one before hierarchical mode existed), and this row renders with zero
                  // indentation either way. Without this gate the `aria-label` below announced a
                  // "subcategory of" relationship a screen-reader user could not corroborate from
                  // the (unindented) visual layout — an accessibility mismatch between the two
                  // channels describing the same row.
                  const parentName =
                    group.taxonomy.hierarchical && term.parentId ? byId.get(term.parentId)?.name : undefined;
                  // Consumed in rendered (group, then term) order, matching how `termHandles` was
                  // built above via the identical `flatMap` order.
                  const termHandle = termHandles[termHandleIndex];
                  termHandleIndex += 1;
                  return (
                    <li
                      key={term.id}
                      // `role="button"` (audit finding, not "listitem"): this row is independently
                      // focusable (`tabIndex={0}`) and Enter/Space-activatable below — the exact
                      // keyboard contract WAI-ARIA defines for a button, not a passive list member.
                      // `aria-selected` used to sit here too, but `aria-selected` is only defined for
                      // `option`/`row`/`gridcell`/`tab`/`treeitem`-family roles — on `listitem` (and
                      // still on `button`) it is simply dropped by the accessible-name/state
                      // computation, so no screen reader or accessibility-tree consumer ever saw this
                      // row's selected state (verified: `getAllByRole("listitem", { selected: true })`
                      // throws `"aria-selected" is not supported on role "listitem"` — the existing
                      // test only ever asserted the raw attribute string, not the computed state).
                      // `aria-current` is the correct fit instead — a global state, valid on `button`,
                      // meaning "the current item in a set" — and needs no matching `listbox`/`option`
                      // composite-widget conversion, which would additionally imply a roving-tabindex
                      // keyboard model this row does not (and, given every row is independently
                      // tabbable today, should not) implement.
                      role="button"
                      className={`settings-row${selectedTermId === term.id ? " is-selected" : ""}`}
                      style={depth > 0 ? { marginLeft: `${depth * 1.1}rem` } : undefined}
                      // Explicit now in EVERY case, not only the `parentName` branch: making this
                      // row a real `role="button"` (above) means its name-from-content computation
                      // now matters, and it was garbled — concatenating the term-name span and the
                      // adjacent status span with no separator (verified live: "Selected Termactive"
                      // for a term named "Selected Term" with status "active"). An explicit
                      // `aria-label` is the fix either way, so the `parentName` case no longer needs
                      // to be the only one that sets it.
                      aria-label={parentName ? `${term.name}, subcategory of ${parentName}` : term.name}
                      onClick={() => setSelectedTermId(term.id)}
                      onKeyDown={(e) => {
                        if (e.target !== e.currentTarget) return;
                        if (e.key === "Enter" || e.key === " ") {
                          e.preventDefault();
                          setSelectedTermId(term.id);
                        }
                      }}
                      tabIndex={0}
                      aria-current={selectedTermId === term.id ? "true" : undefined}
                    >
                      {/* The handle sits on this `<span>`, not the `<li>` it lives inside: the `<li>`
                          also contains the RowMenu trigger button below as a descendant, and
                          `controlOf`'s wrapper-descent (`element-handles.ts` in `@jini-ai/agentic`)
                          would adopt that unrelated, unpublished button as "the control" for any
                          handle placed on an ancestor that contains it — silently turning
                          `page.click` on this row into "open the row menu" instead of "select this
                          term". A plain `<span>` has no such descendant, so `page.click`'s
                          `.click()` call on it bubbles a real click event up to the `<li>`'s own
                          `onClick`, exactly as a user's click would. */}
                      <span
                        className="settings-row-key"
                        {...agentHandle({ handle: termHandle }, {
                          role: "button",
                          label: "Select this term to view and edit its details",
                        })}
                      >
                        {term.name}
                      </span>
                      <span className={`status status-${term.status}`}><ServerLabel value={term.status} /></span>
                      {/* Stops the click before it reaches the `<li>`'s own `onClick` above — without
                          this, opening the row menu (or picking an item in it) would ALSO select the
                          row and pop the detail panel open behind the menu, since this trigger sits
                          inside a listitem that is itself a click target. No other screen in this app
                          combines a `RowMenu` with a click-to-select row, so there was no existing
                          precedent to follow here. */}
                      <span onClick={(e) => e.stopPropagation()}>
                        <TaxonomyRowMenu
                          portalContainer={menuPortalContainer}
                          triggerLabel={t('Actions for term "{name}"').replace("{name}", term.name)}
                          agentHandle={`${termHandle}-menu`}
                          items={[
                            {
                              key: "delete",
                              label: t("Delete term"),
                              destructive: true,
                              onSelect: () => deleteState.requestDeleteTerm(term),
                            },
                          ]}
                        />
                      </span>
                    </li>
                  );
                })}
              </ul>
            )}
            {deleteState.deleteTermBlocked && byId.has(deleteState.deleteTermBlocked.termId) ? (
              <p className="notice error" role="alert">
                {t("Can't delete")} &quot;{byId.get(deleteState.deleteTermBlocked.termId)?.name}&quot;:{" "}
                {deleteState.deleteTermBlocked.state.message}
              </p>
            ) : null}
            <NewTermForm taxonomy={group} onCreated={load} agentBase={newTermFormBases[groupIndex]!} t={t} />
          </section>
        );
      })}
    </div>
  );
}

import { agentHandle } from "@jini-ai/agentic";
import { buildAgentListHandles } from "@jini-ai/agentic";
import { SuggestInput } from "@jini-ai/ui/admin-widgets";
import { useId } from "react";
import type { AdminTaxonomyWithTerms } from "@/lib/api";
import { useWiredTermPicker, type TermPickerController } from "./hooks/use-term-picker.hooks";
import { useTermListReveal } from "./hooks/use-term-list-reveal.hooks";

/** Keep the add-term guard shared by the row's loading, pending and blank-name states. */
function termCreationDisabled({ loading, picker, id }: { loading: boolean; picker: TermPickerController; id: string }): boolean {
  return loading || picker.creating(id) || !picker.newTermName(id).trim();
}

/**
 * @file The Categories & Tags box the post, page and collection-entry editors mount (design-spec.md
 * §1.6) — markup only. The boxes start ticked for the terms the content holds, and Save makes it hold
 * exactly the ticked ones; state, loads and the save live in `hooks/use-term-picker.hooks.ts`.
 *
 * Each row also takes a typed name — ticks the matching term or creates it — when the admin may
 * create terms (see the hook's header).
 *
 * A long row folds: it shows a few terms (ticked first) with a "See more" that reveals up to 100,
 * plus a search box past 100 — see `TermChecklist` below (owner, 2026-10-22).
 *
 * Mount it only for content that exists (a saved post/page/entry has an id to tag).
 */
export function TermPicker(props: {
  /** `post`, `page`, or a collection's content-type key. */
  contentType: string;
  contentId: string;
  /** Dependency injection seam for tests — the same convention `@jini-ai/ui`'s `CustomSelect` uses
   *  for `useCustomSelect`. Defaulted to the real hook, so production callers pass nothing. */
  useTermPickerHook?: typeof useWiredTermPicker;
}) {
  const useTermPickerHook = props.useTermPickerHook ?? useWiredTermPicker;
  const picker = useTermPickerHook({
    contentType: props.contentType,
    contentId: props.contentId,
  });
  const { taxonomies, hidden, subject, loading, dirty, saving, message, error, save, t } = picker;

  if (hidden) return null;

  // Term ids are database row ids — globally unique across every taxonomy, not just within one —
  // so one flat handle list across all taxonomies is correct.
  // Keyed by id, not render position: a row shows only some of its terms ("See more"), and a
  // term's handle must not change with what else is on screen.
  const termIds = taxonomies.flatMap(({ terms }) => terms.map((term) => term.id));
  const termHandles = buildAgentListHandles({ prefix: "term-picker-term", ids: termIds });
  const termHandleById = new Map(termIds.map((termId, index) => [termId, termHandles[index]!]));
  const taxonomyIds = taxonomies.map(({ taxonomy }) => taxonomy.id);
  const addInputHandles = buildAgentListHandles({ prefix: "term-picker-new-term", ids: taxonomyIds });
  const addTriggerHandles = buildAgentListHandles({ prefix: "term-picker-open-new-term", ids: taxonomyIds });
  const addButtonHandles = buildAgentListHandles({ prefix: "term-picker-add-term", ids: taxonomyIds });
  const moreHandles = buildAgentListHandles({ prefix: "term-picker-more", ids: taxonomyIds });
  const searchHandles = buildAgentListHandles({ prefix: "term-picker-search", ids: taxonomyIds });

  return (
    <section className="card term-picker">
      <h3 className="card-title">{t("Categories & Tags")}</h3>
      <p className="card-lead">
        {loading ? t("Loading categories & tags…") : t("Tick the categories and tags that apply, then save.")}
      </p>
      {/* One row per taxonomy: its name on the left, its terms on the right. The `<fieldset>` is
          kept for the group's accessible name (its `<legend>`); `styles.css`'s `.term-picker-group`
          strips its browser border and floats the legend so it sits in the row like any label. */}
      <div className="term-picker-groups">
        {taxonomies.map(({ taxonomy, terms }, groupIndex) => {
          const id = taxonomy.id;
          const showInput = picker.showAddInput(id);
          const suggestions = picker.suggestions(id);
          const createError = picker.createError(id);
          return (
            <fieldset key={id} className="term-picker-group">
              <legend className="field-label">{taxonomy.name}</legend>
              <div className="term-picker-body">
                {terms.length === 0 && !showInput ? <p className="field-hint">{t("No terms yet.")}</p> : null}
                {terms.length > 0 ? (
                  <TermChecklist
                    taxonomy={taxonomy}
                    terms={terms}
                    picker={picker}
                    handles={{
                      term: (termId) => termHandleById.get(termId)!,
                      more: moreHandles[groupIndex]!,
                      search: searchHandles[groupIndex]!,
                    }}
                  />
                ) : null}
                {picker.showAddTrigger(id) ? (
                  <button
                    type="button"
                    className="btn-ghost term-picker-add-trigger"
                    onClick={() => picker.setAddOpen(id, true)}
                    {...agentHandle({ handle: addTriggerHandles[groupIndex]! }, {
                      role: "button",
                      label: `Open the box for adding a new "${taxonomy.name}" term to this ${subject}`,
                    })}
                  >
                    {t("+ Add term")}
                  </button>
                ) : null}
                {showInput ? (
                  // Not a `<form>`: the box can sit inside an editor's own form; the hook's key
                  // handler stops Enter from submitting it.
                  <span className="term-picker-add">
                    {/* Our own suggestion list, not a native `<datalist>`: Chrome on macOS draws that
                        as a dark bubble and adds a large ▼ to the box, unstyleable (owner,
                        2026-10-10: "why does the dropdown look so funny?"). Picking a suggestion
                        ticks that term right away. */}
                    <SuggestInput
                      aria-label={t("Term name")}
                      placeholder={t("Type a name, then press Enter")}
                      value={picker.newTermName(id)}
                      suggestions={suggestions}
                      onPick={(name) => picker.pickSuggestion(id, name)}
                      disabled={loading}
                      onValueChange={(value) => picker.setNewTermName(id, value)}
                      onKeyDown={(e) => picker.onNewTermKeyDown(id, e)}
                      agentHandle={addInputHandles[groupIndex]!}
                      agentLabel={`A "${taxonomy.name}" term name to tag this ${subject} with — an existing one is ticked, a new one is created then ticked; press Enter`}
                    />
                    <button
                      type="button"
                      className="btn-secondary"
                      onClick={() => void picker.addTerm(id)}
                      disabled={termCreationDisabled({ loading, picker, id })}
                      {...agentHandle({ handle: addButtonHandles[groupIndex]! }, {
                        role: "button",
                        label: `Tick the typed "${taxonomy.name}" term, creating it if it does not exist yet`,
                      })}
                    >
                      {picker.creating(id) ? t("Saving…") : t("Add term")}
                    </button>
                  </span>
                ) : null}
                {createError ? (
                  <span className="save-error" role="alert">
                    {createError}
                  </span>
                ) : null}
              </div>
            </fieldset>
          );
        })}
      </div>
      {/* `term-picker-actions` is a spacing-only hook layered on `.editor-actions`, same pattern
          as `FormEditor.tsx`'s `.form-actions`: `.editor-actions` sets direction/gap/alignment but
          deliberately no outer margin, and this row follows the taxonomy rows with nothing else
          separating them. Scoped here rather than added to `.editor-actions` itself, which is
          shared with screens where a blanket top margin would be wrong. */}
      <span className="editor-actions term-picker-actions">
        <button
          type="button"
          className="btn-primary"
          onClick={save}
          disabled={saving || !dirty}
          {...agentHandle({ handle: "term-picker-save" }, {
            role: "button",
            label: `Save this ${subject}'s categories and tags as checked above`,
          })}
        >
          {saving ? t("Saving…") : t("Save categories & tags")}
        </button>
        {message ? <span className="save-ok">{message}</span> : null}
        {error ? <span className="save-error">{error}</span> : null}
      </span>
    </section>
  );
}

/**
 * One taxonomy row's checkboxes. Shows the first few, with ticked terms first; "See more" reveals
 * up to 100 and "Show less" folds them back; past 100 a search box finds any term (owner,
 * 2026-10-22: "looking at all this up front is a lot"). What shows is `rules.ts`'s `termListView`.
 */
function TermChecklist(props: {
  taxonomy: AdminTaxonomyWithTerms["taxonomy"];
  terms: AdminTaxonomyWithTerms["terms"];
  picker: TermPickerController;
  handles: { term: (termId: string) => string; more: string; search: string };
}) {
  const { taxonomy, terms, picker, handles } = props;
  const { selected, toggle, loading, subject, t } = picker;
  const reveal = useTermListReveal({ terms, selected, loading });
  const listId = useId();
  return (
    <>
      {reveal.searchable ? (
        <input
          type="search"
          className="term-picker-search"
          aria-label={t("Search terms")}
          aria-controls={listId}
          placeholder={t("Search terms")}
          autoComplete="off"
          value={reveal.query}
          onChange={(event) => reveal.setQuery(event.target.value)}
          {...agentHandle({ handle: handles.search }, {
            role: "field",
            label: `Filter the "${taxonomy.name}" terms shown for this ${subject} by name`,
          })}
        />
      ) : null}
      <div id={listId} className="term-picker-terms">
        {reveal.shown.map((term) => (
          <label key={term.id} className="form-checkbox-field">
            <input
              type="checkbox"
              checked={selected.has(term.id)}
              disabled={loading}
              onChange={() => toggle(term.id)}
              {...agentHandle({ handle: handles.term(term.id) }, {
                role: "checkbox",
                label: `Tag this ${subject} with the "${taxonomy.name}" term "${term.name}"`,
              })}
            />
            {term.name}
          </label>
        ))}
      </div>
      {reveal.canToggle ? (
        <button
          type="button"
          className="link-button term-picker-more"
          aria-expanded={reveal.expanded}
          aria-controls={listId}
          onClick={reveal.toggleExpanded}
          {...agentHandle({ handle: handles.more }, {
            role: "button",
            label: `Show more or fewer of the "${taxonomy.name}" terms`,
          })}
        >
          {reveal.expanded ? t("Show less") : t("See more")}
        </button>
      ) : null}
    </>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState, type Dispatch, type SetStateAction } from "react";

import { describeApiError, type AdminTrashItem } from "@/lib/api";
import { useFetchQuery, useInvalidate } from "@jini-ai/ui/fetch-query";
import { useAdminLocale } from "@/hooks/use-admin-locale.hooks";
import { useContentRefreshSubscription } from "@/hooks/use-content-refresh-subscription.hooks";
import { useSettlementGeneration } from "@jini-ai/ui/panel-kit";
import {
  allVisibleSelected,
  describePurgeReport,
  describeRestoreReport,
  describeTrashLoadError,
  KEYS,
  selectionAfterSelectAll,
  toggleSelection,
  TRASH_RESOURCE,
} from "../rules";
import { t } from "../trash-i18n";
import { defaultTrashPort } from "./trash-dependencies.hooks";
import type { TrashPort } from "./trash-port.hooks";

/**
 * @file All of the Trash screen's state. `Trash.tsx` is markup only.
 *
 * Page 1 is one `useFetchQuery` keyed on `KEYS.list()`; "Load more" pages accumulate locally, for
 * the same reason `use-comment-queue.hooks.ts` and `use-form-submissions.hooks.ts` keep theirs
 * local (one hook, one FIXED key — a cursor-appended list is exactly the shape that convention
 * warns against faking).
 *
 * `useContentRefreshSubscription` is not optional here. Four agent tools and four admin delete
 * paths write trash rows, so without it an operator who asks the assistant to delete a post sees
 * this screen keep reporting an empty Trash. There is no draft state to protect — the only local
 * state is a checkbox selection, and the selection is reconciled against the refreshed rows rather
 * than cleared (see `visibleItems`'s effect below), so a background refresh cannot make a
 * "Delete permanently" click act on a row that is no longer on screen.
 *
 * Because a background refresh (not just this screen's own `reloadAfterAction`) can refetch page 1
 * at any time, a `loadMore` still in flight when that happens must not land its page on top of the
 * fresh page 1 — same race `use-comment-queue.hooks.ts` and `use-form-submissions.hooks.ts` guard
 * with `pageSettlement` (`useSettlementGeneration`, same primitive and shape here): `resetMorePages`
 * mints a fresh generation on every reset, superseding any older in-flight page fetch, and a
 * synchronous `loadingMoreRef` lock covers a same-tick double `loadMore` (2026-09-21).
 *
 * `actorUsernames` (2026-09-21) is a second, independent `useFetchQuery` (`port.listUsers()`) that
 * resolves `actorPrincipalId -> username` for `rules.ts`'s `actorLabel`, so a row from an older
 * server (one that predates the `actorUsername` field entirely) can still read a real name instead
 * of "Unknown" — the owner's own desktop-app server was exactly that case. Deliberately NOT wired
 * into `error`/`reloadAfterAction`: a workspace member without `user.manage`/`member.manage` gets a
 * 403 here, and that must degrade the actor column, never surface as a Trash-screen failure or block
 * the row list from loading.
 */

export interface TrashController {
  /** `null` until the first page settles. */
  items: AdminTrashItem[] | null;
  nextCursor: string | null;
  loadingMore: boolean;
  loadMore: () => void;
  error: string | null;
  /** One-line result of the last restore/purge. */
  notice: string | null;
  busy: boolean;

  selected: ReadonlySet<string>;
  toggle: (id: string) => void;
  toggleAll: () => void;
  allSelected: boolean;

  onRestoreSelected: () => Promise<void>;
  /** Open when the confirm modal is asking about the current selection. */
  purgeConfirmOpen: boolean;
  setPurgeConfirmOpen: Dispatch<SetStateAction<boolean>>;
  onPurgeConfirmed: () => Promise<void>;

  /** The Refresh button's gesture — an imperative re-read regardless of freshness. */
  refresh: () => void;
  /** True while a refresh (including the initial load) is in flight — drives "Refreshing…". */
  refreshing: boolean;

  /**
   * `actorPrincipalId -> username`, for `rules.ts`'s `actorLabel` to resolve a row whose
   * `actorUsername` the server omitted entirely (an older server build). Empty when the port carries
   * no `listUsers` method, the call is still in flight, or it failed (2026-09-21) — `actorLabel`
   * already degrades to "Unknown" for an id this map cannot explain, so an empty map here is a safe
   * default, not a special case `Trash.tsx` needs to branch on.
   */
  actorUsernames: ReadonlyMap<string, string>;

  locale: string;
}

export interface TrashDependencies {
  port: TrashPort;
  locale: string;
}

export function useTrash(deps: TrashDependencies): TrashController {
  const { port, locale } = deps;
  const invalidate = useInvalidate();

  // Stable identity so the subscription effect does not resubscribe every render.
  const invalidateList = useCallback(() => invalidate({ key: KEYS.listRoot }), [invalidate]);
  useContentRefreshSubscription(TRASH_RESOURCE, invalidateList);

  // `staleTime: 0` + `refetchOnWindowFocus: true` (2026-09-21, forms plan §C): deletes can
  // originate from ANY admin screen, the assistant, or a second desktop instance, so there is no
  // single write path to invalidate this key from — always revalidating on mount/focus is cheaper
  // than being wrong. First per-query `staleTime` user in this app.
  const firstPage = useFetchQuery({
    key: KEYS.list(),
    fetch: () => port.listTrash({}),
  }, {
    staleTime: 0,
    refetchOnWindowFocus: true,
  });

  // Loaded once per Trash view, entirely independent of `firstPage` — its failure (missing
  // `user.manage`/`member.manage`) must never surface as a Trash-screen error, and its data must
  // never gate the row list. `enabled: false` when the port carries no `listUsers` at all, rather
  // than calling a method that might not exist.
  const usersQuery = useFetchQuery({
    key: KEYS.actorUsernames(),
    fetch: () => port.listUsers!(),
  }, {
    enabled: Boolean(port.listUsers),
  });
  const actorUsernames = useMemo(() => {
    const map = new Map<string, string>();
    for (const user of usersQuery.data?.users ?? []) map.set(user.principalId, user.username);
    return map;
  }, [usersQuery.data]);

  const [morePages, setMorePages] = useState<AdminTrashItem[]>([]);
  const [moreCursor, setMoreCursor] = useState<string | null>(null);
  const [loadingMore, setLoadingMore] = useState(false);
  const [actionError, setActionError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [selected, setSelected] = useState<ReadonlySet<string>>(new Set<string>());
  const [purgeConfirmOpen, setPurgeConfirmOpen] = useState(false);

  // The "latest call wins" guard for accumulated pages — see the file header. `loadingMoreRef` is
  // the synchronous half (blocks a same-tick double `loadMore`); `pageSettlement` is the async half
  // (a superseded fetch's response must not land once a reset has moved on).
  const loadingMoreRef = useRef(false);
  const pageSettlement = useSettlementGeneration();

  // Supersedes any in-flight "Load more" fetch and clears the accumulated pages back to "just the
  // first page" — called wherever the previous code did a bare `setMorePages([])`, so there is one
  // reset path instead of several ad hoc ones. Does not touch `moreCursor` (set by the effect below,
  // right after this runs) or `actionError` (owned by the restore/purge actions, which already clear
  // it themselves before a successful `reloadAfterAction` gets here).
  const resetMorePages = useCallback(() => {
    pageSettlement.next();
    loadingMoreRef.current = false;
    setLoadingMore(false);
    setMorePages([]);
  }, [pageSettlement]);

  // A refetched first page — from this screen's own `reloadAfterAction` OR a background
  // `useContentRefreshSubscription` refresh (an agent tool wrote a trash row) — must drop the
  // "more" pages it used to leave stale — they are always a continuation of the CURRENT first
  // page, not whichever first page was on screen when they were fetched. `resetMorePages()` also
  // supersedes any `loadMore` already in flight when the refetch lands, so its page can't append
  // afterward.
  useEffect(() => {
    resetMorePages();
    setMoreCursor(firstPage.data?.nextCursor ?? null);
  }, [firstPage.data, resetMorePages]);

  const items = firstPage.data ? [...firstPage.data.items, ...morePages] : null;

  // Reconcile the selection against what is actually on screen. A background refresh (an agent
  // restored something, the 60-day sweeper purged something) can remove a row mid-selection, and a
  // selection holding an id nobody can see any more would send it to the purge endpoint anyway.
  const visibleIds = items ? items.map((item) => item.id).join("\u0000") : null;
  useEffect(() => {
    if (visibleIds === null) return;
    const present = new Set(visibleIds.length > 0 ? visibleIds.split("\u0000") : []);
    setSelected((current) => {
      const kept = new Set([...current].filter((id) => present.has(id)));
      return kept.size === current.size ? current : kept;
    });
  }, [visibleIds]);

  async function loadMore() {
    if (!moreCursor) return;
    if (loadingMoreRef.current) return; // a same-tick double click sends only one request
    loadingMoreRef.current = true;
    const generation = pageSettlement.next();
    setLoadingMore(true);
    try {
      const page = await port.listTrash({ cursor: moreCursor });
      if (!pageSettlement.isCurrent({ generation })) return; // superseded by a reload
      setMorePages((prev) => [...prev, ...page.items]);
      setMoreCursor(page.nextCursor);
    } catch (e) {
      if (!pageSettlement.isCurrent({ generation })) return;
      setActionError(describeTrashLoadError({ error: e, locale }));
    } finally {
      // A superseded call's lock was already released by `resetMorePages`; only the still-current
      // call releases it here — otherwise a stale settlement could free the lock a NEWER, still
      // in-flight `loadMore` still owns.
      if (pageSettlement.isCurrent({ generation })) {
        loadingMoreRef.current = false;
        setLoadingMore(false);
      }
    }
  }

  /** Drops the locally accumulated pages and refetches page 1 — the rows just moved. */
  function reloadAfterAction() {
    resetMorePages();
    invalidate({ key: KEYS.listRoot });
  }

  /**
   * The Refresh button: an explicit re-read regardless of freshness. Reuses `resetMorePages` so an
   * in-flight `loadMore` is superseded the same way a reload after restore/purge already supersedes
   * one (same `pageSettlement` generation guard). Does not touch `selected` — the existing
   * reconcile-selection effect (keyed on `items`) already prunes any id that drops off the
   * refreshed rows once they land.
   */
  function refresh() {
    resetMorePages();
    void firstPage.refetch();
  }

  /** The rows the current selection actually names, resolved from what is on screen. */
  function selectedItems(): AdminTrashItem[] {
    return (items ?? []).filter((item) => selected.has(item.id));
  }

  async function onRestoreSelected() {
    const chosen = selectedItems();
    if (chosen.length === 0 || busy) return;
    setBusy(true);
    setActionError(null);
    try {
      const report = await port.restoreTrashItems({
        items: chosen.map((item) => ({ entityType: item.entityType, entityId: item.entityId })),
      });
      setNotice(describeRestoreReport(locale, report));
      setSelected(new Set<string>());
      reloadAfterAction();
    } catch (e) {
      setActionError(describeApiError(e, t({ locale: locale, key: "failed to restore" })));
    } finally {
      setBusy(false);
    }
  }

  async function onPurgeConfirmed() {
    const chosen = selectedItems();
    if (chosen.length === 0 || busy) return;
    setBusy(true);
    setActionError(null);
    try {
      const report = await port.purgeTrashItems({ ids: chosen.map((item) => item.id) });
      setNotice(describePurgeReport(locale, report));
      setSelected(new Set<string>());
      setPurgeConfirmOpen(false);
      reloadAfterAction();
    } catch (e) {
      setActionError(describeApiError(e, t({ locale: locale, key: "failed to delete permanently" })));
    } finally {
      setBusy(false);
    }
  }

  return {
    items,
    nextCursor: moreCursor,
    loadingMore,
    loadMore,
    error: firstPage.error ? describeTrashLoadError({ error: firstPage.error, locale }) : actionError,
    notice,
    busy,
    selected,
    toggle: (id) => setSelected((current) => toggleSelection(current, id)),
    toggleAll: () =>
      setSelected((current) => selectionAfterSelectAll(items ?? [], allVisibleSelected(items ?? [], current))),
    allSelected: allVisibleSelected(items ?? [], selected),
    onRestoreSelected,
    purgeConfirmOpen,
    setPurgeConfirmOpen,
    onPurgeConfirmed,
    refresh,
    refreshing: firstPage.isFetching,
    actorUsernames,
    locale,
  };
}

/**
 * Binds the real client and the resolved locale — the zero-argument half of the
 * `useX(dependencies)` / `useWiredX()` pair, so `Trash.tsx` composes this and a test composes
 * {@link useTrash} with `createFakeTrashPort`.
 */
export function useWiredTrash(): TrashController {
  const locale = useAdminLocale();
  return useTrash({ port: defaultTrashPort, locale });
}

import { formatTimestamp } from "@jini-ai/ui/panel-kit";
import { agentHandle } from "@jini-ai/agentic";
import { isWorkspaceDirty } from "./rules";
import { useWiredWorkspace } from "./hooks/use-workspace.hooks";
import { t } from "./workspace-i18n";

/**
 * @file "Workspace" admin screen (SPEC-044) — the `/admin/workspace` route — markup only.
 *
 * Mirrors `features/roles/Roles.tsx`'s fetch/loading/error/form shape. Shows the current (single, v1)
 * workspace's `name`/`slug`/`createdAt` and an editable rename form (REQ-04). No list/create UI —
 * v1 always has exactly one workspace, addressable only through the caller's own boot-wired
 * `deps.workspaceId` (see feature.spec.md's Architectural Finding section); `api.getWorkspace()`
 * fetches that one record directly rather than listing then picking the first.
 *
 * The "Delete workspace" control is REQ-07's deliberate choice: present, not hidden, but always
 * disabled with an explanatory notice — `DELETE_WORKSPACE` always refuses in v1 (INV-03, a real
 * guard, not a stub), so a live, clickable button here would just be a guaranteed-failing round
 * trip; omitting the control entirely would look like the capability doesn't exist rather than
 * "exists, guarded, not reachable yet."
 *
 * State, the fetch, and save live in `hooks/use-workspace.hooks.ts`; the error-code overrides and
 * the dirty-form derivation live in `rules.ts`.
 *
 * Web-design pass (2026-08-05): the id/createdAt pair below used to render as a full bordered
 * `.list-table` with exactly two rows — sparse next to every real multi-row `.list-table` elsewhere
 * in this app, and reading as "table for table's sake" for a two-field read-only summary. Swapped
 * for `.settings-layer-grid`/`.settings-layer-cell` — the same compact key/value chip idiom
 * `Taxonomy.tsx`'s `TermDetailPanel` already uses for its own small Status/Parent/Version set.
 */
export interface WorkspaceProps {
  /**
   * Dependency injection seam for tests — the same convention `Posts.tsx`'s `usePostsHook` uses.
   * Defaulted to the real hook, so production callers pass nothing and behave exactly as before.
   */
  useWorkspaceHook?: typeof useWiredWorkspace;
  /**
   * Whether to render this screen's own `.page-header` (kicker "Administration", the "Workspace"
   * `<h1>`, and the identity-summary description). Defaults to `true` (this component's original,
   * standalone-route rendering — unchanged for every other caller).
   *
   * `SettingsUi.tsx` passes `false`: mounted as that screen's `"workspace"` tab, `Workspace` sits
   * *under* `SettingsDialogShell`'s own chrome header, which already renders the tab's `title` and
   * `subtitle` (`SettingsUi.tsx`'s tab entry sets both to this same kicker-free "Workspace" title
   * and identity-summary sentence — see that entry's own comment). Rendering this header too used
   * to say "Workspace" and the same description a second time directly underneath the shell's own
   * — the exact `showTitle`-style seam `ExternalMcpSettingsPanel.tsx` already uses for the
   * identical problem on the Providers screen (see that component's own `showTitle` doc), matched
   * here rather than a CSS override: a `display: none` would leave "Workspace" in the DOM and the
   * accessibility tree, so a screen reader would still announce the title twice even though only
   * one copy is visible.
   *
   * Suppresses the WHOLE header block, not just the `<h1>` the way `showTitle` does on
   * `ExternalMcpSettingsPanel` — that panel's own subtitle is unique content with no shell
   * equivalent, so only its title is redundant; here all three pieces (kicker, title, description)
   * restate something the shell's chrome already shows once this is a tab, not a standalone page,
   * so all three go together. No kicker survives on its own either: no other `SettingsUi` tab shows
   * one, since the shell's single "Settings" kicker already plays that role for all ten.
   */
  showPageHeader?: boolean;
}

/** The rename form's own status pair — a save error, or a "Saved." confirmation once the form is
 *  no longer dirty. Split out of `Workspace` as a top-level function per the complexity-ceiling
 *  brief's extraction rule. */
function WorkspaceFormStatus(props: { locale: string; saveError: string | null; saved: boolean; dirty: boolean }) {
  const { locale, saveError, saved, dirty } = props;
  return (
    <>
      {saveError ? <span className="save-error">{saveError}</span> : null}
      {saved && !dirty ? <span className="save-success">{t({ locale: locale, key: "Saved." })}</span> : null}
    </>
  );
}

export function Workspace({ useWorkspaceHook = useWiredWorkspace, showPageHeader = true }: WorkspaceProps = {}) {
  const { workspace, error, name, setName, slug, setSlug, saving, saveError, saved, onSave, t, locale } = useWorkspaceHook();

  if (error) return <div className="notice error">{error}</div>;
  if (!workspace) return <div className="notice">{t("Loading workspace…")}</div>;

  const dirty = isWorkspaceDirty(workspace, name, slug);

  return (
    // `.workspace-page` caps measure (styles.css) — this is a single-column settings screen, not
    // a table/dashboard, and `.page` itself carries no max-width anywhere in the app (would affect
    // all ~39 other screens using it), so the cap lives on a scoped wrapper class instead.
    <div className="page workspace-page">
      {showPageHeader ? (
        <div className="page-header">
          <div className="page-header-text">
            <p className="page-kicker">{t("Administration")}</p>
            <h1 className="page-title">{t("Workspace")}</h1>
            <p className="page-description">{t("This site's identity — its name, URL slug, and creation date.")}</p>
          </div>
        </div>
      ) : null}

      <form onSubmit={onSave} className="notice integrations-form form-measure">
        <WorkspaceFormStatus locale={locale} saveError={saveError} saved={saved} dirty={dirty} />
        <label>
          {t("Name")}
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            {...agentHandle({ handle: "workspace-name" }, { role: "field", label: "This workspace's name" })}
          />
        </label>
        <label>
          {t("Slug")}
          <input
            value={slug}
            onChange={(e) => setSlug(e.target.value)}
            required
            {...agentHandle({ handle: "workspace-slug" }, { role: "field", label: "This workspace's URL slug" })}
          />
        </label>
        <button
          type="submit"
          disabled={saving || !dirty}
          {...agentHandle({ handle: "workspace-save" }, { role: "button", label: "Save the workspace's name and slug" })}
        >
          {saving ? t("Saving…") : t("Save changes")}
        </button>

        {/* `.workspace-identity-grid` (styles.css) groups these with the rename form above them —
            previously a bare `.settings-layer-grid` sitting on the page by itself below the form's
            own card, reading as an unrelated second block rather than "more facts about this same
            workspace." Same divider idiom `.deployment-route-note`/`.settings-scope-editor` already
            use for a sub-section inside one container. */}
        <div className="settings-layer-grid workspace-identity-grid">
          <div className="settings-layer-cell">
            <span className="settings-layer-label">{t("Workspace ID")}</span>
            <span>{workspace.id}</span>
          </div>
          <div className="settings-layer-cell">
            <span className="settings-layer-label">{t("Created")}</span>
            {/* Raw ISO-8601 (`2026-04-06T00:00:00.000Z`) leaked to the screen unformatted — the
                exact class of bug `format-timestamp.ts`'s own file header describes fixing at ~a
                dozen other call sites; this one was missed. Same shared helper, same YYYY-MM-DD
                HH:MM display, no new formatting logic. */}
            <span>{formatTimestamp({ iso: workspace.createdAt }, { timeZone: "local" })}</span>
          </div>
        </div>
      </form>

      {/* `.card`/`.card-title` (styles.css ~L789/811), the same primitive Deployment's Overview tab
          uses for its own sections — not a bare `<h2>`, which renders at the UA-default 24px against
          `.page-title`'s 26.4px (measured live: 91% of it, different font family, a stray 19.92px
          margin) and reads as a second page starting rather than a section of this one. `.card-danger`
          (new, small, generically reusable) adds the same red-left-border signal `.notice.error`/
          `.notice.warning` already use, for a section that is destructive content rather than a
          message. */}
      <div className="card card-danger">
        <h2 className="card-title">{t("Delete workspace")}</h2>
        <p className="card-lead">
          {t("Every Tovu install must always have at least one workspace, so deleting your only workspace is not available. This becomes available once this install supports more than one workspace.")}
        </p>
        {/* `.btn-danger` at rest, not just on some future enabled state — genuinely destructive by
            nature even while `:disabled`; staying `.btn-danger` means this doesn't quietly read as a
            neutral action if it's ever wired live. Its disabled state now has its own rule
            (`.btn-danger:disabled`, styles.css) — verified live via getComputedStyle that without it,
            `button:disabled`'s primary-tinted fill (out-specifying `.btn-danger`'s own background/
            color) painted a peach fill behind a red border and near-white text, reading as broken
            rather than deliberately unavailable. */}
        <button
          type="button"
          className="btn-danger"
          disabled
          title={t("Not available — this install has only one workspace")}
          {...agentHandle({ handle: "workspace-delete" }, { role: "button", label: "Delete workspace (not available — only one workspace exists)" })}
        >
          {t("Delete workspace")}
        </button>
      </div>
    </div>
  );
}

import { useEffect, useState, type ComponentProps } from "react";
import type { NodeViewProps } from "@tiptap/react";

import { api, describeApiError, type AdminWidget } from "./api";
import type { MediaEditDialogValue } from "../components/MediaEditDialog/MediaEditDialog.hooks";
import type { WidgetPickerDialog } from "../components/WidgetPickerDialog/WidgetPickerDialog";
import { initialPlacementDraft, placementContentAttr, supportsPlacementContent, type PlacementContentDraft } from "./widget-embed-placement-content";

/**
 * @file State, the widget fetch and handlers for `WidgetEmbedNodeView` (`widget-embed-extension.tsx`),
 * so the node view itself stays markup only — same split `media-embed-extension.hooks.ts` makes for
 * `MediaEmbedNodeView`.
 *
 * **Stale responses are dropped.** A node's `widgetEntryId` changes in place (Change ->
 * `updateAttributes`), and `api.getWidget` takes no abort signal, so a slow response for the
 * PREVIOUS id can settle after the current one. The fetch effect marks its own run stale in its
 * cleanup and ignores a settle (success or failure) from a stale run; before this, whichever
 * response settled last won, and a node could show — or be marked broken by — a widget it no longer
 * pointed at. The request itself still completes; only its result is discarded.
 */

type WidgetPickerDialogProps = ComponentProps<typeof WidgetPickerDialog>;

/** The Change dialog's props, present only while it is open AND a widget has resolved to scope it
 *  to (the dialog is typed to the current widget's own `widgetType`). */
export interface WidgetEmbedChangeDialog {
  widgetType: WidgetPickerDialogProps["widgetType"];
  /** Points the node at an existing widget and closes the dialog. */
  onUseExisting: WidgetPickerDialogProps["onUseExisting"];
  /** Creates a widget of the current type, then points the node at it. A failed create alerts the
   *  describable error and leaves the node (and the open dialog) untouched. */
  onCreateNew: WidgetPickerDialogProps["onCreateNew"];
  onCancel: WidgetPickerDialogProps["onCancel"];
}

/** The Style dialog's "Content for this spot" draft — only for media/gallery widgets. */
export interface WidgetEmbedPlacementContent extends PlacementContentDraft {
  widgetType: string;
  setCustom: (custom: boolean) => void;
  setContent: (content: Record<string, unknown>) => void;
}

/** Everything `WidgetEmbedNodeView` renders from. */
export interface WidgetEmbedNodeViewController {
  /** The node's `placementId`, `""` when unset (never the literal `"undefined"`). */
  placementId: string;
  /** `undefined` while loading, `null` when unresolvable (no id, or the fetch failed). */
  widget: AdminWidget | null | undefined;
  /** No id, a failed fetch, or a resolved widget that is not `active`. */
  isBroken: boolean;
  /** The node wrapper's class, with the `--broken` modifier when {@link isBroken}. */
  nodeClassName: string;
  /** The Change button: opens the dialog (which renders only once a widget has resolved). */
  openChange: () => void;
  /** The Remove button: deletes this node from the document. */
  remove: () => void;
  /** Non-`null` exactly when the Change dialog should render — see {@link WidgetEmbedChangeDialog}. */
  changeDialog: WidgetEmbedChangeDialog | null;
  /** The node's current `cssClass`/`htmlAttributes`, seeding the Style dialog (D5) — `alt` is
   *  always `null` since {@link MediaEditDialog} renders with `showAlt={false}` here and never
   *  reads it back. */
  styleInitial: MediaEditDialogValue;
  /** Whether the Style dialog should render — unlike {@link changeDialog}, not gated on the widget
   *  having resolved: styling only touches node attrs, not the referenced widget. */
  styling: boolean;
  /** Opens the Style dialog. */
  openStyle: () => void;
  /** Closes the Style dialog without writing anything. */
  closeStyle: () => void;
  /** Writes the dialog's `cssClass`/`htmlAttributes` onto the node (never `alt`, which this dialog
   *  never exposes) and closes it — same shape as `media-embed-extension.hooks.ts`'s `saveEdit`.
   *  For a media/gallery widget it also writes `content` (the override, or `null` for "Use the
   *  widget's content"); for any other type `content` is left exactly as it was. */
  saveStyle: (value: MediaEditDialogValue) => void;
  /** Non-`null` while the Style dialog is open for a media/gallery widget — the per-placement
   *  content override (mediawidget contract) the dialog renders below the style fields. */
  placementContent: WidgetEmbedPlacementContent | null;
}

/**
 * Owns `WidgetEmbedNodeView`'s resolved widget, broken flag and Change-dialog state, and the handlers
 * that write back into the node through `props.updateAttributes`/`props.deleteNode`.
 *
 * @param props - The TipTap node-view props for one `widgetEmbed` node.
 * @returns See {@link WidgetEmbedNodeViewController}.
 * @complexity O(1) per render; one `api.getWidget` call per `widgetEntryId` change.
 */
export function useWidgetEmbedNodeView(props: NodeViewProps): WidgetEmbedNodeViewController {
  const { widgetEntryId, placementId, cssClass, htmlAttributes } = widgetEmbedAttrs(props.node.attrs);
  const { widget, isBroken } = useResolvedWidget(widgetEntryId);
  const [changing, setChanging] = useState(false);
  const [styling, setStyling] = useState(false);
  const [placementDraft, setPlacementDraft] = useState<PlacementContentDraft>({ custom: false, content: {} });

  function changeInstance(newWidgetEntryId: string) {
    props.updateAttributes({ widgetEntryId: newWidgetEntryId });
    setChanging(false);
  }

  const contentEditable = supportsPlacementContent(widget?.widgetType);

  return {
    placementId,
    widget,
    isBroken,
    nodeClassName: `widget-embed-node${isBroken ? " widget-embed-node--broken" : ""}`,
    openChange: () => setChanging(true),
    remove: () => props.deleteNode(),
    styleInitial: { alt: null, cssClass, htmlAttributes },
    styling,
    openStyle: () => {
      // Re-seeded on every open so Cancel discards an edited override, like the style fields.
      setPlacementDraft(initialPlacementDraft({ attrsContent: props.node.attrs.content, widgetConfig: widget?.config }));
      setStyling(true);
    },
    closeStyle: () => setStyling(false),
    saveStyle: (value) => {
      props.updateAttributes({
        cssClass: value.cssClass,
        htmlAttributes: value.htmlAttributes,
        ...(contentEditable ? { content: placementContentAttr({ draft: placementDraft }) } : {}),
      });
      setStyling(false);
    },
    placementContent: styling && contentEditable && widget
      ? placementContentController({ widgetType: widget.widgetType, draft: placementDraft, setDraft: setPlacementDraft })
      : null,
    changeDialog: changing && widget
      ? changeDialogController({ widgetType: widget.widgetType, changeInstance, close: () => setChanging(false) })
      : null,
  };
}

/**
 * Reads one `widgetEmbed` node's attributes, normalising absent ones.
 * @param attrs The node's raw TipTap attributes.
 * @returns Ids as strings (`""` when unset, never `"undefined"`); style attrs as string or `null`.
 */
function widgetEmbedAttrs(attrs: NodeViewProps["node"]["attrs"]) {
  return {
    widgetEntryId: String(attrs.widgetEntryId ?? ""),
    placementId: String(attrs.placementId ?? ""),
    cssClass: (attrs.cssClass as string | null | undefined) ?? null,
    htmlAttributes: (attrs.htmlAttributes as string | null | undefined) ?? null,
  };
}

/**
 * Resolves the widget a node points at, dropping stale settles (see this file's header).
 * @param widgetEntryId The node's widget id; `""` marks the node broken without fetching.
 * @returns `widget` (`undefined` while loading, `null` when unresolvable) and the broken flag.
 * @complexity One `api.getWidget` call per `widgetEntryId` change.
 */
function useResolvedWidget(widgetEntryId: string): { widget: AdminWidget | null | undefined; isBroken: boolean } {
  const [widget, setWidget] = useState<AdminWidget | null | undefined>(undefined);
  const [isBroken, setIsBroken] = useState(false);

  useEffect(() => {
    if (!widgetEntryId) {
      setIsBroken(true);
      setWidget(null);
      return undefined;
    }
    // Cleared by this run's own cleanup, i.e. as soon as `widgetEntryId` changes or the node view
    // unmounts — see this file's header on why a stale settle must not apply.
    let current = true;
    api
      .getWidget(widgetEntryId)
      .then((r) => {
        if (!current) return;
        setWidget(r.widget);
        setIsBroken(r.widget.status !== "active");
      })
      .catch(() => {
        if (!current) return;
        setWidget(null);
        setIsBroken(true);
      });
    return () => {
      current = false;
    };
  }, [widgetEntryId]);

  return { widget, isBroken };
}

/** The Style dialog's per-placement content override for a media/gallery widget. */
function placementContentController(
  { widgetType, draft, setDraft }: {
    widgetType: string;
    draft: PlacementContentDraft;
    setDraft: (update: (draft: PlacementContentDraft) => PlacementContentDraft) => void;
  },
): WidgetEmbedPlacementContent {
  return {
    ...draft,
    widgetType,
    setCustom: (custom) => setDraft((current) => ({ ...current, custom })),
    setContent: (content) => setDraft((current) => ({ ...current, content })),
  };
}

/** The Change dialog's handlers, scoped to the current widget's own `widgetType`. */
function changeDialogController(
  { widgetType, changeInstance, close }: {
    widgetType: AdminWidget["widgetType"];
    changeInstance: (widgetEntryId: string) => void;
    close: () => void;
  },
): WidgetEmbedChangeDialog {
  return {
    widgetType,
    onUseExisting: (id) => changeInstance(id),
    onCreateNew: async (title, config) => {
      try {
        const { widget: created } = await api.createWidget({ widgetType, title, config });
        changeInstance(created.id);
      } catch (e) {
        // eslint-disable-next-line no-alert
        window.alert(describeApiError(e, "failed to create widget"));
      }
    },
    onCancel: close,
  };
}

import { readFileSync, realpathSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import react from "@vitejs/plugin-react";
import { defineConfig } from "vitest/config";
import { parseCLI } from "vitest/node";

/** Full-suite floors cannot judge a deliberately filtered test or coverage report. O(args). */
function fullSuiteCoverageThresholds({ args }: { args: string[] }, _options = {}) {
  const { filter, options } = parseCLI(["vitest", ...args], { allowUnknownOptions: true });
  const coverage = typeof options.coverage === "object" ? options.coverage : undefined;
  const scopes = [filter.length, options.testNamePattern, options.changed, options.related,
    options.shard, options.exclude, options.project, options.dir, coverage?.include, coverage?.exclude];
  if (scopes.some(Boolean)) return undefined;
  return { statements: 98, branches: 98, functions: 98, lines: 98 };
}

/**
 * @file First-ever test harness for `apps/admin` (SPEC-005 REQ-12..17 dispatch). This app had
 * zero test infrastructure before this pass — a pre-existing gap, not introduced by this feature
 * — so this config is minimal, deliberately mirroring `vite.config.ts`'s existing alias/plugin
 * setup rather than inventing a second, divergent build configuration.
 */

/**
 * This package's own version, read at test-run time for `lib/app-version.ts`'s
 * `__TOVU_ADMIN_VERSION__` global. Mirrors `vite.config.ts`'s `adminPackageVersion` derivation
 * exactly (same `package.json` read, same field) rather than hardcoding a version string here,
 * so the two configs cannot drift apart — this was previously undefined under `vitest`, which
 * threw `ReferenceError: __TOVU_ADMIN_VERSION__ is not defined` at import time in any suite that
 * imports `App.tsx` (which imports `SettingsUi.tsx`, which imports `app-version.ts`), and had kept
 * three suites (`app-plugins-route`, `app-agent-page-identity`, `app-route-prototype-keys`) from
 * ever executing.
 */
const adminPackageVersion = (
  JSON.parse(readFileSync(path.resolve(__dirname, "package.json"), "utf8")) as { version: string }
).version;

/**
 * The admin dev server's own port, for `lib/admin-dev-origin.ts`'s `__TOVU_ADMIN_DEV_PORT__` global.
 * Mirrors `vite.config.ts`'s `adminDevPort` derivation exactly, for the same reason
 * `adminPackageVersion` above does: without a define here, every suite that (transitively) imports
 * `admin-dev-origin.ts` — `site-url.ts`, and therefore `api.ts` and every feature that links to the
 * public site — throws `ReferenceError: __TOVU_ADMIN_DEV_PORT__ is not defined` at import time.
 */
const adminDevPort = Number(process.env.TOVU_ADMIN_DEV_PORT ?? 5173);

export default defineConfig({
  define: {
    __TOVU_ADMIN_VERSION__: JSON.stringify(adminPackageVersion),
    __TOVU_ADMIN_DEV_PORT__: JSON.stringify(String(adminDevPort)),
  },
  plugins: [react()],
  server: {
    fs: {
      /**
       * `src/main.tsx` imports `@jini-ai/ui/remixicon.css?inline`. That package is a `file:` link
       * into the sibling Jini checkout, outside this repo, and Vite refuses `?inline`/`?raw` reads
       * outside `server.fs.allow` ("Denied ID"), so the entry module could not load under test.
       * The reviewed chart-bundle tests also import provider-plugins' built payload directly.
       * Allow exactly this repo plus those two packages' real directories.
       */
      allow: [path.resolve(__dirname, "../.."), realpathSync(path.resolve(__dirname, "node_modules/@jini-ai/ui")),
        path.dirname(createRequire(import.meta.url).resolve("@jini-ai/provider-plugins/catalog"))],
    },
  },
  resolve: {
    /**
     * One React, one react-dom, no matter who imports them.
     *
     * `@jini-ai/ui` is a `file:` dependency symlinked into the sibling Jini checkout, which has its
     * own pnpm-installed React. Without this, `ChatPane` resolves Jini's copy while `react-dom`
     * renders with this app's, and the first hook it calls throws
     * `Cannot read properties of null (reading 'useContext')` — the classic two-Reacts symptom,
     * which reads like a bug in the component rather than a resolution problem.
     *
     * It surfaced as an unhandled error rather than a failure (the render is inside React's own
     * work loop, so the test that triggered it still passed), which is why it went unnoticed: any
     * admin test that mounts `App` renders the assistant dock, and therefore `ChatPane`.
     */
    // Match production: Jini's adapter, application probes and Devtools share one context.
    dedupe: ["react", "react-dom", "@jini-ai/ui", "@tanstack/react-query", "@tanstack/query-core"],
    alias: {
      "@": path.resolve(__dirname, "src"),
      "@tovu/headless": path.resolve(__dirname, "../website/src/contracts/headless"),
      // Mirrors `vite.config.ts`'s identical alias — see that file's own comment.
      "@tovu/theme-layout": path.resolve(__dirname, "../website/src/features/theme/theme-layout.ts"),
      // Same again for the Publish Content dialog's shared report semantics. This is a THIRD place
      // the alias has to be declared (tsconfig `paths`, `vite.config.ts`, here) — the three configs
      // are independent, and a missing entry fails in a different way in each: a type error, a
      // build-time resolution failure, and "Failed to resolve import" with no tests run.
      "@tovu/publish-content-ui": path.resolve(__dirname, "../website/src/features/publish-content/ui/index.ts"),
      // Marker consumers import `@jini-ai/cms/widgets/markers` directly, sharing the server owner.
      // Mirrors `vite.config.ts`'s identical alias — see that file's own comment.
      "@tovu/assistant-run-events": path.resolve(__dirname, "../website/src/contracts/core/assistant-run-events.ts"),
    },
  },
  test: {
    // `formatTimestamp` renders the viewer's local wall time (D-06, 2026-10-06), so every suite
    // that asserts a rendered timestamp would otherwise pass or fail depending on the machine's
    // zone. UTC keeps those fixtures (`…Z` in, the same digits out) stable everywhere;
    // `format-timestamp.unit.test.ts` switches to America/Los_Angeles itself to prove conversion.
    env: { TZ: "UTC" },
    environment: "jsdom",
    environmentOptions: {
      // Native fetch (undici) has no concept of "the current document URL" the way a real
      // browser does, so a RELATIVE fetch() call (as every apps/admin/src/lib/api.ts call makes)
      // fails to parse under jsdom's default blank test URL. Pinning an explicit origin here is
      // the standard fix — unrelated to (and does not affect) window.location.hash-based routing,
      // which apps/admin/src/App.tsx already reads directly.
      jsdom: { url: "http://localhost:3000/" },
    },
    globals: false,
    setupFiles: ["./src/__tests__/setup.ts"],
    css: false,
    server: {
      deps: {
        /**
         * `@jini-ai/ui`'s built `InteractiveHtmlEditor.js` does `import
         * 'grapesjs/dist/css/grapes.min.css'`. Vitest externalizes node_modules packages by
         * default (skips Vite's transform, uses Node's native ESM loader for them), and Node's
         * loader has no `.css` handling, so any suite that transitively imports the html editor
         * (`PageEditor.tsx`, `PostEditor.tsx`, and anything that renders `Pages`/`Posts`) fails
         * to even load with `TypeError: Unknown file extension ".css"`. Targeting just
         * `["@jini-ai/ui", "grapesjs"]` (string or regex) was tried first and did NOT clear the
         * error even though both packages match Vitest's own `matchPattern` substring check —
         * inlining everything is the only setting that reliably routed the import through Vite's
         * transform pipeline, where `css: false` above turns the stylesheet import into a no-op
         * instead of a raw Node import.
         */
        inline: true,
      },
    },
    coverage: {
      provider: "v8",
      // Unloaded runtime files remain in the denominator; only tests and declarations are outside it.
      include: ["src/**/*.{ts,tsx}"],
      exclude: ["**/*.{test,spec}.{ts,tsx}", "**/__tests__/**", "**/*.d.ts"],
      // AI Dev Shop's full unit-suite floor applies equally to every axis. Scoped reports still
      // measure the same sources, but cannot be compared with a floor for the whole test suite.
      thresholds: fullSuiteCoverageThresholds({ args: process.argv.slice(2) }),
      reporter: ["text", "lcov"],
      reportsDirectory: "./coverage",
      // Vitest defaults this to `false` — a coverage run with even one failing test then produces
      // ZERO artifacts (no error, no partial report), which reads as broken tooling rather than a
      // failed test. This has already cost real debugging time in this repo (see the 2026-08-15
      // coverage-and-tests-worklist). Owner-approved 2026-08-15.
      reportOnFailure: true,
    },
  },
});
